--
-- Name: activate_ai_prompt(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activate_ai_prompt(p_prompt_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_prompt public.ai_prompts;
BEGIN
  SELECT * INTO v_prompt FROM public.ai_prompts WHERE id = p_prompt_id;
  
  IF NOT FOUND THEN
    RETURN false;
  END IF;
  
  -- Deactivate all prompts with same brand_id and name
  UPDATE public.ai_prompts
  SET is_active = false
  WHERE brand_id = v_prompt.brand_id AND name = v_prompt.name;
  
  -- Activate the target prompt
  UPDATE public.ai_prompts
  SET is_active = true
  WHERE id = p_prompt_id;
  
  -- Update the ai_configs with new active version
  UPDATE public.ai_configs
  SET active_prompt_version = v_prompt.version, updated_at = now()
  WHERE brand_id = v_prompt.brand_id;
  
  RETURN true;
END;
$$;


--
-- Name: add_contact_phone(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_contact_phone(p_contact_id uuid, p_phone_raw text, p_is_primary boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_brand_id uuid;
  v_phone_normalized text;
  v_phone_id uuid;
BEGIN
  v_user_id := get_user_id(auth.uid());
  
  -- Get brand_id from contact
  SELECT brand_id INTO v_brand_id
  FROM contacts
  WHERE id = p_contact_id;
  
  IF v_brand_id IS NULL THEN
    RAISE EXCEPTION 'Contact not found';
  END IF;
  
  -- Check permissions
  IF v_user_id IS NOT NULL AND NOT (
    has_role_for_brand(v_user_id, v_brand_id, 'admin') OR
    has_role_for_brand(v_user_id, v_brand_id, 'callcenter') OR
    has_role(v_user_id, 'ceo')
  ) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;
  
  -- Normalize phone (simple version: digits only)
  v_phone_normalized := regexp_replace(p_phone_raw, '[^0-9+]', '', 'g');
  
  -- Try to insert, on conflict get existing
  INSERT INTO contact_phones (brand_id, contact_id, phone_raw, phone_normalized, is_primary)
  VALUES (v_brand_id, p_contact_id, p_phone_raw, v_phone_normalized, false)
  ON CONFLICT (brand_id, phone_normalized) DO UPDATE SET phone_raw = EXCLUDED.phone_raw
  RETURNING id INTO v_phone_id;
  
  -- Handle primary flag
  IF p_is_primary THEN
    UPDATE contact_phones SET is_primary = false
    WHERE contact_id = p_contact_id AND is_primary = true AND id != v_phone_id;
    
    UPDATE contact_phones SET is_primary = true WHERE id = v_phone_id;
  END IF;
  
  RETURN v_phone_id;
END;
$$;


--
-- Name: add_group_member(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_group_member(p_thread_id uuid, p_new_user_id uuid, p_role text DEFAULT 'member'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_user_id UUID; v_actor_role TEXT; v_brand_id UUID;
BEGIN
  v_user_id := get_user_id(auth.uid());
  SELECT role INTO v_actor_role FROM chat_thread_members WHERE thread_id = p_thread_id AND user_id = v_user_id AND left_at IS NULL;
  IF v_actor_role IS NULL OR v_actor_role = 'member' THEN RAISE EXCEPTION 'Only owners and moderators can add members'; END IF;
  IF p_role = 'moderator' AND v_actor_role != 'owner' THEN RAISE EXCEPTION 'Only owners can add moderators'; END IF;
  SELECT brand_id INTO v_brand_id FROM chat_threads WHERE id = p_thread_id;
  IF NOT user_belongs_to_brand(p_new_user_id, v_brand_id) THEN RAISE EXCEPTION 'User does not belong to this brand'; END IF;
  INSERT INTO chat_thread_members (thread_id, user_id, role) VALUES (p_thread_id, p_new_user_id, p_role)
  ON CONFLICT (thread_id, user_id) DO UPDATE SET left_at = NULL, role = p_role, joined_at = now();
END; $$;


--
-- Name: apply_ai_deal_tags(uuid, uuid[], double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_ai_deal_tags(p_deal_id uuid, p_tag_ids uuid[], p_confidence double precision DEFAULT 0.8) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_brand_id UUID;
  v_tag_id UUID;
  v_count INTEGER := 0;
BEGIN
  -- Get deal's brand
  SELECT brand_id INTO v_brand_id FROM deals WHERE id = p_deal_id;
  
  IF v_brand_id IS NULL THEN
    RAISE EXCEPTION 'Deal not found: %', p_deal_id;
  END IF;
  
  -- Insert each tag assignment
  FOREACH v_tag_id IN ARRAY p_tag_ids LOOP
    INSERT INTO tag_assignments (brand_id, tag_id, deal_id, assigned_by, confidence)
    VALUES (v_brand_id, v_tag_id, p_deal_id, 'ai', p_confidence)
    ON CONFLICT (tag_id, deal_id) WHERE deal_id IS NOT NULL DO NOTHING;
    
    IF FOUND THEN
      v_count := v_count + 1;
    END IF;
  END LOOP;
  
  RETURN v_count;
END;
$$;


--
-- Name: apply_ai_fallback(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_ai_fallback(p_lead_event_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_brand_id UUID;
  v_fallback_tag_id UUID;
BEGIN
  -- Get brand_id
  SELECT brand_id INTO v_brand_id FROM lead_events WHERE id = p_lead_event_id;
  
  -- Update lead_event with fallback values
  UPDATE lead_events SET
    lead_type = 'generic',
    ai_priority = 3,
    ai_confidence = 0.0,
    ai_rationale = 'Fallback: AI processing not available',
    ai_processed = true,
    ai_processed_at = now()
  WHERE id = p_lead_event_id;
  
  -- Try to find or create a "Da Verificare" tag for fallback
  SELECT id INTO v_fallback_tag_id 
  FROM tags 
  WHERE brand_id = v_brand_id AND name = 'Da Verificare' AND parent_id IS NULL
  LIMIT 1;
  
  IF v_fallback_tag_id IS NULL THEN
    INSERT INTO tags (brand_id, name, color, scope, description)
    VALUES (v_brand_id, 'Da Verificare', '#f59e0b', 'mixed', 'Tag automatico per lead non classificati')
    RETURNING id INTO v_fallback_tag_id;
  END IF;
  
  -- Assign fallback tag
  INSERT INTO tag_assignments (brand_id, tag_id, lead_event_id, assigned_by, confidence)
  VALUES (v_brand_id, v_fallback_tag_id, p_lead_event_id, 'ai', 0.0)
  ON CONFLICT DO NOTHING;
END;
$$;


--
-- Name: appointments_recompute_risk_score(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.appointments_recompute_risk_score() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_new_score numeric;
BEGIN
  v_new_score := public.compute_appointment_risk_score(NEW.id);
  IF v_new_score IS DISTINCT FROM NEW.risk_score THEN
    UPDATE public.appointments
    SET risk_score = v_new_score
    WHERE id = NEW.id;
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: appointments_set_risk_score(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.appointments_set_risk_score() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Compute only when relevant fields changed (or new row)
  IF TG_OP = 'INSERT' OR
     NEW.scheduled_at IS DISTINCT FROM OLD.scheduled_at OR
     NEW.status IS DISTINCT FROM OLD.status OR
     NEW.address IS DISTINCT FROM OLD.address OR
     NEW.city IS DISTINCT FROM OLD.city OR
     NEW.assigned_sales_user_id IS DISTINCT FROM OLD.assigned_sales_user_id OR
     NEW.appointment_type IS DISTINCT FROM OLD.appointment_type THEN

    -- Inline compute (avoid double SELECT — use NEW row directly via helper logic)
    -- For simplicity & consistency: call function AFTER row exists (use AFTER trigger pattern)
    NEW.risk_score := NULL; -- will be set by AFTER trigger
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: assert_can_backup_brand(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_can_backup_brand(p_brand_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_allowed BOOLEAN;
BEGIN
  v_user_id := public.get_user_id(auth.uid());
  IF v_user_id IS NULL THEN
    RETURN FALSE;
  END IF;
  SELECT EXISTS (
    SELECT 1 FROM public.user_roles
    WHERE user_id = v_user_id
      AND role IN ('admin','ceo')
      AND is_active = true
      AND (brand_id = p_brand_id OR brand_id = '00000000-0000-0000-0000-000000000000'::uuid)
  ) INTO v_allowed;
  RETURN COALESCE(v_allowed, FALSE);
END;
$$;


--
-- Name: assert_can_restore_brand(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_can_restore_brand(p_brand_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
BEGIN
  v_user_id := public.get_user_id(auth.uid());
  IF v_user_id IS NULL THEN RETURN FALSE; END IF;
  RETURN public.has_role_for_brand(v_user_id, p_brand_id, 'admin'::app_role)
      OR public.has_role(v_user_id, 'ceo'::app_role);
END;
$$;


--
-- Name: assign_appointment_sales(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_appointment_sales(p_appointment_id uuid, p_sales_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_user_role app_role;
  v_brand_id uuid;
  v_sales_role app_role;
  v_old_value jsonb;
BEGIN
  SELECT u.id INTO v_user_id
  FROM public.users u
  WHERE u.supabase_auth_id = auth.uid();

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  SELECT brand_id INTO v_brand_id
  FROM public.appointments
  WHERE id = p_appointment_id;

  IF v_brand_id IS NULL THEN
    RAISE EXCEPTION 'Not found';
  END IF;

  SELECT ur.role INTO v_user_role
  FROM public.user_roles ur
  WHERE ur.user_id = v_user_id AND ur.brand_id = v_brand_id
  LIMIT 1;

  IF v_user_role NOT IN ('admin', 'ceo', 'callcenter') THEN
    RAISE EXCEPTION 'Forbidden';
  END IF;

  -- VALIDATION: Target user must be sales for this brand
  SELECT ur.role INTO v_sales_role
  FROM public.user_roles ur
  WHERE ur.user_id = p_sales_user_id 
    AND ur.brand_id = v_brand_id
    AND ur.role = 'sales'
  LIMIT 1;

  IF v_sales_role IS NULL THEN
    RAISE EXCEPTION 'Forbidden: target user is not a sales for this brand';
  END IF;

  -- Capture old state for audit
  SELECT row_to_json(a.*)::jsonb INTO v_old_value
  FROM public.appointments a WHERE a.id = p_appointment_id;

  UPDATE public.appointments
  SET assigned_sales_user_id = p_sales_user_id
  WHERE id = p_appointment_id;

  -- AUDIT
  INSERT INTO public.audit_log (
    brand_id, entity_type, entity_id, action, actor_user_id, old_value, new_value
  )
  SELECT 
    v_brand_id, 
    'appointment', 
    p_appointment_id, 
    'assign_sales',
    v_user_id,
    v_old_value,
    row_to_json(a.*)::jsonb
  FROM public.appointments a WHERE a.id = p_appointment_id;
END;
$$;


--
-- Name: assign_ticket_round_robin(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_ticket_round_robin(p_ticket_id uuid, p_brand_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_next_user_id uuid;
  v_last_assigned_user_id uuid;
  v_auto_assign_enabled boolean;
BEGIN
  -- Check if auto-assign is enabled for this brand
  SELECT auto_assign_enabled INTO v_auto_assign_enabled
  FROM brands
  WHERE id = p_brand_id;
  
  -- If auto-assign is disabled, return null (no assignment)
  IF v_auto_assign_enabled IS NOT TRUE THEN
    RETURN NULL;
  END IF;

  -- Get last assigned user for this brand
  SELECT last_assigned_user_id INTO v_last_assigned_user_id
  FROM brand_assignment_state
  WHERE brand_id = p_brand_id;

  -- Get next operator in round-robin order
  SELECT ur.user_id INTO v_next_user_id
  FROM user_roles ur
  WHERE ur.brand_id = p_brand_id
    AND ur.role IN ('callcenter', 'admin')
    AND (v_last_assigned_user_id IS NULL OR ur.user_id > v_last_assigned_user_id)
  ORDER BY ur.user_id
  LIMIT 1;

  -- If no user found after last assigned, wrap around to first
  IF v_next_user_id IS NULL THEN
    SELECT ur.user_id INTO v_next_user_id
    FROM user_roles ur
    WHERE ur.brand_id = p_brand_id
      AND ur.role IN ('callcenter', 'admin')
    ORDER BY ur.user_id
    LIMIT 1;
  END IF;

  -- If still no user found, return null
  IF v_next_user_id IS NULL THEN
    RETURN NULL;
  END IF;

  -- Update ticket assignment
  UPDATE tickets
  SET 
    assigned_to_user_id = v_next_user_id,
    assigned_at = now(),
    assigned_by_user_id = NULL  -- NULL indicates auto-assignment
  WHERE id = p_ticket_id;

  -- Update or insert brand assignment state
  INSERT INTO brand_assignment_state (brand_id, last_assigned_user_id, updated_at)
  VALUES (p_brand_id, v_next_user_id, now())
  ON CONFLICT (brand_id)
  DO UPDATE SET 
    last_assigned_user_id = v_next_user_id,
    updated_at = now();

  RETURN v_next_user_id;
END;
$$;


--
-- Name: assign_unassigned_support_tickets(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_unassigned_support_tickets(p_brand_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ticket RECORD;
  v_assigned_count integer := 0;
  v_auto_assign_enabled boolean;
BEGIN
  -- Check if auto-assign is enabled for this brand
  SELECT auto_assign_enabled INTO v_auto_assign_enabled
  FROM brands
  WHERE id = p_brand_id;
  
  -- If auto-assign is disabled, return 0 (no assignments)
  IF v_auto_assign_enabled IS NOT TRUE THEN
    RETURN 0;
  END IF;

  -- Find unassigned support tickets (created by AI with should_create_ticket flag)
  FOR v_ticket IN
    SELECT t.id
    FROM tickets t
    JOIN lead_events le ON le.id = t.source_event_id
    WHERE t.brand_id = p_brand_id
      AND t.assigned_to_user_id IS NULL
      AND t.status IN ('open', 'reopened')
      AND le.should_create_ticket = true
    ORDER BY t.created_at ASC
  LOOP
    -- Assign using round-robin
    IF assign_ticket_round_robin(v_ticket.id, p_brand_id) IS NOT NULL THEN
      v_assigned_count := v_assigned_count + 1;
    END IF;
  END LOOP;

  RETURN v_assigned_count;
END;
$$;


--
-- Name: audit_events_refresh_search_text(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_events_refresh_search_text() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  NEW.search_text := lower(
    coalesce(NEW.entity_type, '') || ' ' ||
    coalesce(NEW.action, '') || ' ' ||
    coalesce(NEW.actor_display_name, '') || ' ' ||
    coalesce(NEW.correlation_id, '') || ' ' ||
    coalesce(array_to_string(NEW.changed_fields, ' '), '') || ' ' ||
    coalesce(NEW.metadata::text, '')
  );
  RETURN NEW;
END;
$$;


--
-- Name: audit_ticket_created(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_ticket_created() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO public.audit_log (
    brand_id,
    entity_type,
