$$;


--
-- Name: audit_trigger_func(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_trigger_func() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_action text;
  v_entity_type text;
  v_entity_id uuid;
  v_brand_id uuid;
  v_old_value jsonb;
  v_new_value jsonb;
  v_changed text[];
BEGIN
  v_entity_type := TG_ARGV[0];
  IF v_entity_type IS NULL THEN
    v_entity_type := TG_TABLE_NAME;
  END IF;

  IF TG_OP = 'INSERT' THEN
    v_action := 'create';
    v_entity_id := NEW.id;
    v_brand_id := NEW.brand_id;
    v_new_value := to_jsonb(NEW);
    v_old_value := NULL;
  ELSIF TG_OP = 'UPDATE' THEN
    v_action := 'update';
    v_entity_id := NEW.id;
    v_brand_id := NEW.brand_id;
    v_old_value := to_jsonb(OLD);
    v_new_value := to_jsonb(NEW);
    v_changed := ARRAY(
      SELECT key FROM jsonb_each(to_jsonb(NEW))
      WHERE to_jsonb(NEW) ->> key IS DISTINCT FROM to_jsonb(OLD) ->> key
        AND key NOT IN ('updated_at', 'created_at')
    );
    IF array_length(v_changed, 1) IS NULL OR array_length(v_changed, 1) = 0 THEN
      RETURN NEW;
    END IF;
    IF 'status' = ANY(v_changed) THEN
      v_action := 'status_change';
    END IF;
  ELSIF TG_OP = 'DELETE' THEN
    v_action := 'delete';
    v_entity_id := OLD.id;
    v_brand_id := OLD.brand_id;
    v_old_value := to_jsonb(OLD);
    v_new_value := NULL;
  END IF;

  BEGIN
    PERFORM write_audit_event(
      p_brand_id := v_brand_id,
      p_entity_type := v_entity_type,
      p_entity_id := v_entity_id,
      p_action := v_action,
      p_old_value := v_old_value,
      p_new_value := v_new_value,
      p_changed_fields := v_changed
    );
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'audit_trigger_func failed for % on %: %', v_action, v_entity_type, SQLERRM;
  END;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: build_contact_search_text(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.build_contact_search_text(p_contact_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_text TEXT := '';
  v_contact RECORD;
BEGIN
  SELECT c.first_name, c.last_name, c.email, c.city, c.cap, 
         c.address, c.notes, b.name as brand_name
  INTO v_contact FROM contacts c 
  LEFT JOIN brands b ON b.id = c.brand_id 
  WHERE c.id = p_contact_id;
  
  IF v_contact IS NULL THEN RETURN ''; END IF;
  
  v_text := COALESCE(v_contact.first_name, '') || ' ' || 
            COALESCE(v_contact.last_name, '') || ' ' ||
            COALESCE(v_contact.email, '') || ' ' || 
            COALESCE(v_contact.city, '') || ' ' ||
            COALESCE(v_contact.cap, '') || ' ' || 
            COALESCE(v_contact.address, '') || ' ' ||
            COALESCE(v_contact.notes, '') || ' ' ||
            COALESCE(v_contact.brand_name, '');
  
  -- Telefoni
  v_text := v_text || ' ' || COALESCE((
    SELECT string_agg(phone_normalized, ' ') 
    FROM contact_phones WHERE contact_id = p_contact_id AND is_active
  ), '');
  
  -- Tag
  v_text := v_text || ' ' || COALESCE((
    SELECT string_agg(t.name, ' ') 
    FROM tag_assignments ta JOIN tags t ON t.id = ta.tag_id 
    WHERE ta.contact_id = p_contact_id
  ), '');
  
  -- Custom fields
  v_text := v_text || ' ' || COALESCE((
    SELECT string_agg(value_text, ' ') 
    FROM contact_field_values WHERE contact_id = p_contact_id AND value_text IS NOT NULL
  ), '');
  
  RETURN lower(regexp_replace(trim(v_text), '\s+', ' ', 'g'));
END;
$$;


--
-- Name: build_contact_snapshot(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.build_contact_snapshot(p_contact_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result JSONB;
BEGIN
  SELECT jsonb_build_object(
    'id', c.id,
    'first_name', c.first_name,
    'last_name', c.last_name,
    'email', c.email,
    'address', c.address,
    'city', c.city,
    'cap', c.cap,
    'province', c.province,
    'country', c.country,
    'status', c.status,
    'notes', c.notes,
    'lead_valid', c.lead_valid,
    'fax', c.fax,
    'vat_number', c.vat_number,
    'fiscal_code', c.fiscal_code,
    'company_name', c.company_name,
    'company_address', c.company_address,
    'company_city', c.company_city,
    'company_province', c.company_province,
    'company_zip', c.company_zip,
    'lead_extra', c.lead_extra,
    'lead_reason_id', c.lead_reason_id,
    'lead_type', c.lead_type,
    'lead_message', c.lead_message,
    'lead_reason', c.lead_reason,
    'lead_cost', c.lead_cost,
    'lead_note', c.lead_note,
    'lead_state_id', c.lead_state_id,
    'lead_validation_ts', c.lead_validation_ts,
    'note1', c.note1,
    'note2', c.note2,
    'note3', c.note3,
    'note4', c.note4,
    'note5', c.note5,
    'note6', c.note6,
    'note7', c.note7,
    'note8', c.note8,
    'note9', c.note9,
    'note10', c.note10,
    'primary_phone', (
      SELECT cp.phone_normalized
      FROM contact_phones cp
      WHERE cp.contact_id = c.id AND cp.is_primary = true
      LIMIT 1
    ),
    'pipeline_stage_name', (
      SELECT ps.name
      FROM deals d
      JOIN pipeline_stages ps ON ps.id = d.current_stage_id
      WHERE d.contact_id = c.id AND d.status = 'open'
      ORDER BY d.created_at DESC
      LIMIT 1
    )
  )
  INTO v_result
  FROM contacts c
  WHERE c.id = p_contact_id;

  RETURN COALESCE(v_result, '{}'::jsonb);
END;
$$;


--
-- Name: build_deal_snapshot(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.build_deal_snapshot(p_deal_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result JSONB;
BEGIN
  IF p_deal_id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT jsonb_build_object(
    'id', d.id,
    'status', d.status,
    'value', d.value,
    'current_stage_id', d.current_stage_id,
    'current_stage_name', ps.name
  )
  INTO v_result
  FROM deals d
  LEFT JOIN pipeline_stages ps ON ps.id = d.current_stage_id
  WHERE d.id = p_deal_id;
  
  RETURN v_result;
END;
$$;


--
-- Name: build_entity_tags(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.build_entity_tags(p_brand_id uuid, p_contact_id uuid DEFAULT NULL::uuid, p_deal_id uuid DEFAULT NULL::uuid, p_lead_event_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN COALESCE((
    SELECT jsonb_agg(jsonb_build_object(
      'id', t.id,
      'name', t.name,
      'color', t.color,
      'scope', t.scope
    ))
    FROM tag_assignments ta
    JOIN tags t ON t.id = ta.tag_id
    WHERE ta.brand_id = p_brand_id
      AND (
        (p_contact_id IS NOT NULL AND ta.contact_id = p_contact_id) OR
        (p_deal_id IS NOT NULL AND ta.deal_id = p_deal_id) OR
        (p_lead_event_id IS NOT NULL AND ta.lead_event_id = p_lead_event_id)
      )
  ), '[]'::jsonb);
END;
$$;


--
-- Name: build_webhook_payload_v1(text, uuid, uuid, timestamp with time zone, jsonb, uuid, uuid, uuid, jsonb, jsonb, jsonb, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.build_webhook_payload_v1(p_event_type text, p_brand_id uuid, p_event_id uuid, p_occurred_at timestamp with time zone, p_refs jsonb DEFAULT '{}'::jsonb, p_contact_id uuid DEFAULT NULL::uuid, p_deal_id uuid DEFAULT NULL::uuid, p_lead_event_id uuid DEFAULT NULL::uuid, p_event_snapshot jsonb DEFAULT NULL::jsonb, p_appointment_snapshot jsonb DEFAULT NULL::jsonb, p_sale_snapshot jsonb DEFAULT NULL::jsonb, p_stage_snapshot jsonb DEFAULT NULL::jsonb, p_old_data jsonb DEFAULT NULL::jsonb, p_new_data jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_payload JSONB;
BEGIN
  v_payload := jsonb_build_object(
    'version', 'v1',
    'type', p_event_type,
    'occurred_at', p_occurred_at,
    'brand_id', p_brand_id,
    'event_id', p_event_id,
    'refs', p_refs
  );
  
  -- Add contact_snapshot if contact_id provided
  IF p_contact_id IS NOT NULL THEN
    v_payload := v_payload || jsonb_build_object(
      'contact_snapshot', build_contact_snapshot(p_contact_id)
    );
  END IF;
  
  -- Add deal_snapshot if deal_id provided
  IF p_deal_id IS NOT NULL THEN
    v_payload := v_payload || jsonb_build_object(
      'deal_snapshot', build_deal_snapshot(p_deal_id)
    );
  END IF;
  
  -- Add tags
  v_payload := v_payload || jsonb_build_object(
    'tags', build_entity_tags(p_brand_id, p_contact_id, p_deal_id, p_lead_event_id)
  );
  
  -- Add optional snapshots
  IF p_event_snapshot IS NOT NULL THEN
    v_payload := v_payload || jsonb_build_object('event_snapshot', p_event_snapshot);
  END IF;
  
  IF p_appointment_snapshot IS NOT NULL THEN
    v_payload := v_payload || jsonb_build_object('appointment', p_appointment_snapshot);
  END IF;
  
  IF p_sale_snapshot IS NOT NULL THEN
    v_payload := v_payload || jsonb_build_object('sale', p_sale_snapshot);
  END IF;
  
  IF p_stage_snapshot IS NOT NULL THEN
    v_payload := v_payload || jsonb_build_object('stage', p_stage_snapshot);
  END IF;
  
  -- Add change tracking
  IF p_old_data IS NOT NULL OR p_new_data IS NOT NULL THEN
    v_payload := v_payload || jsonb_build_object(
      'changes', jsonb_build_object(
        'old', COALESCE(p_old_data, '{}'::jsonb),
        'new', COALESCE(p_new_data, '{}'::jsonb)
      )
    );
  END IF;
  
  RETURN v_payload;
END;
$$;


--
-- Name: calculate_deal_scores(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_deal_scores(p_brand_id uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_deal RECORD;
  v_score INTEGER;
  v_risk_level TEXT;
  v_factors JSONB;
  v_count INTEGER := 0;
  v_avg_days_in_stage NUMERIC;
  v_days_in_current_stage INTEGER;
  v_last_interaction_days INTEGER;
  v_salesperson_win_rate NUMERIC;
  v_avg_deal_value NUMERIC;
  v_stage_progression_score INTEGER;
  v_today DATE := CURRENT_DATE;
BEGIN
  -- Get average days in stage for reference
  SELECT COALESCE(AVG(EXTRACT(EPOCH FROM (COALESCE(d.closed_at, now()) - d.created_at)) / 86400), 30)
  INTO v_avg_days_in_stage
  FROM deals d
  WHERE (p_brand_id IS NULL OR d.brand_id = p_brand_id)
    AND d.status = 'won';

  -- Get average deal value
  SELECT COALESCE(AVG(value), 1000)
  INTO v_avg_deal_value
  FROM deals
  WHERE (p_brand_id IS NULL OR brand_id = p_brand_id)
    AND status = 'won'
    AND value IS NOT NULL;

  -- Process each open deal
  FOR v_deal IN 
    SELECT 
      d.id,
      d.brand_id,
      d.value,
      d.assigned_user_id,
      d.current_stage_id,
      d.created_at,
      d.updated_at,
      ps.order_index as stage_order,
      (SELECT MAX(order_index) FROM pipeline_stages WHERE brand_id = d.brand_id AND is_active = true) as max_stage
    FROM deals d
    LEFT JOIN pipeline_stages ps ON d.current_stage_id = ps.id
    WHERE d.status = 'open'
      AND (p_brand_id IS NULL OR d.brand_id = p_brand_id)
  LOOP
    v_score := 50; -- Base score
    v_factors := '[]'::jsonb;

    -- Factor 1: Days in current stage
    SELECT EXTRACT(DAY FROM (now() - COALESCE(
      (SELECT MAX(changed_at) FROM deal_stage_history WHERE deal_id = v_deal.id),
      v_deal.created_at
    )))::INTEGER INTO v_days_in_current_stage;
    
    IF v_days_in_current_stage > v_avg_days_in_stage THEN
      v_score := v_score - LEAST(20, (v_days_in_current_stage - v_avg_days_in_stage)::INTEGER * 2);
      v_factors := v_factors || jsonb_build_object(
        'factor', 'days_in_stage',
        'impact', -LEAST(20, (v_days_in_current_stage - v_avg_days_in_stage)::INTEGER * 2),
        'detail', format('%s giorni in fase attuale', v_days_in_current_stage)
      );
    ELSE
      v_score := v_score + 5;
      v_factors := v_factors || jsonb_build_object(
        'factor', 'days_in_stage',
        'impact', 5,
        'detail', 'Progressione nella norma'
      );
    END IF;

    -- Factor 2: Last interaction recency
    SELECT COALESCE(
      EXTRACT(DAY FROM (now() - MAX(created_at)))::INTEGER,
      30
    ) INTO v_last_interaction_days
    FROM (
      SELECT created_at FROM call_logs WHERE deal_id = v_deal.id
      UNION ALL
      SELECT created_at FROM chat_messages cm
      JOIN chat_threads ct ON cm.thread_id = ct.id
      WHERE ct.entity_type = 'deal' AND ct.entity_id = v_deal.id
      UNION ALL
      SELECT created_at FROM appointments WHERE deal_id = v_deal.id
    ) interactions;

    IF v_last_interaction_days <= 3 THEN
      v_score := v_score + 15;
      v_factors := v_factors || jsonb_build_object('factor', 'interaction_recency', 'impact', 15, 'detail', 'Interazione recente');
    ELSIF v_last_interaction_days <= 7 THEN
      v_score := v_score + 5;
      v_factors := v_factors || jsonb_build_object('factor', 'interaction_recency', 'impact', 5, 'detail', format('Ultima interazione %s giorni fa', v_last_interaction_days));
    ELSE
      v_score := v_score - 10;
      v_factors := v_factors || jsonb_build_object('factor', 'interaction_recency', 'impact', -10, 'detail', format('Nessuna interazione da %s giorni', v_last_interaction_days));
    END IF;

    -- Factor 3: Salesperson win rate
    IF v_deal.assigned_user_id IS NOT NULL THEN
      SELECT COALESCE(
        (COUNT(*) FILTER (WHERE status = 'won')::NUMERIC / NULLIF(COUNT(*) FILTER (WHERE status IN ('won', 'lost')), 0)) * 100,
        50
      ) INTO v_salesperson_win_rate
      FROM deals
      WHERE assigned_user_id = v_deal.assigned_user_id
        AND brand_id = v_deal.brand_id
        AND closed_at >= now() - INTERVAL '90 days';

      IF v_salesperson_win_rate >= 70 THEN
        v_score := v_score + 10;
        v_factors := v_factors || jsonb_build_object('factor', 'salesperson_performance', 'impact', 10, 'detail', format('Win rate: %.0f%%', v_salesperson_win_rate));
      ELSIF v_salesperson_win_rate >= 50 THEN
        v_score := v_score + 5;
        v_factors := v_factors || jsonb_build_object('factor', 'salesperson_performance', 'impact', 5, 'detail', format('Win rate: %.0f%%', v_salesperson_win_rate));
      ELSE
        v_score := v_score - 5;
        v_factors := v_factors || jsonb_build_object('factor', 'salesperson_performance', 'impact', -5, 'detail', format('Win rate basso: %.0f%%', v_salesperson_win_rate));
      END IF;
    END IF;

    -- Factor 4: Deal value vs average
    IF v_deal.value IS NOT NULL AND v_deal.value > v_avg_deal_value THEN
      v_score := v_score + 8;
      v_factors := v_factors || jsonb_build_object('factor', 'deal_value', 'impact', 8, 'detail', 'Valore sopra la media');
    END IF;

    -- Factor 5: Stage progression
    IF v_deal.stage_order IS NOT NULL AND v_deal.max_stage IS NOT NULL AND v_deal.max_stage > 0 THEN
      v_stage_progression_score := ((v_deal.stage_order::NUMERIC / v_deal.max_stage) * 15)::INTEGER;
      v_score := v_score + v_stage_progression_score;
      v_factors := v_factors || jsonb_build_object('factor', 'stage_progression', 'impact', v_stage_progression_score, 'detail', format('Fase %s di %s', v_deal.stage_order, v_deal.max_stage));
    END IF;

    -- Clamp score
    v_score := GREATEST(0, LEAST(100, v_score));

    -- Risk level
    v_risk_level := CASE
      WHEN v_score >= 70 THEN 'low'
      WHEN v_score >= 50 THEN 'medium'
      WHEN v_score >= 30 THEN 'high'
      ELSE 'critical'
    END;

    -- Update deal
    UPDATE deals SET deal_score = v_score, deal_risk_level = v_risk_level, score_updated_at = now() WHERE id = v_deal.id;

    -- Insert/update score history
    INSERT INTO deal_scores (deal_id, brand_id, score, risk_level, factors, score_date)
    VALUES (v_deal.id, v_deal.brand_id, v_score, v_risk_level, v_factors, v_today)
    ON CONFLICT (deal_id, score_date) DO UPDATE SET score = EXCLUDED.score, risk_level = EXCLUDED.risk_level, factors = EXCLUDED.factors, calculated_at = now();

    v_count := v_count + 1;
  END LOOP;

  RETURN v_count;
END;
$$;


--
-- Name: calculate_lead_score(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_lead_score(p_contact_id uuid, p_trigger_event text DEFAULT 'manual'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_brand_id uuid;
  v_score int := 30;
  v_drivers_pos text[] := '{}';
  v_drivers_neg text[] := '{}';
  v_next_action text;
  v_heat public.heat_class;
  v_contact record;
  v_appt_counts record;
  v_deal_counts record;
  v_call_counts record;
  v_event_count int;
  v_last_activity timestamptz;
  v_days_inactive int;
  v_has_positive_sentiment boolean;
  v_has_negative_sentiment boolean;
BEGIN
  SELECT c.brand_id, c.* INTO v_contact
  FROM contacts c WHERE c.id = p_contact_id;
  
  IF v_contact IS NULL THEN
    RETURN jsonb_build_object('error', 'Contact not found');
  END IF;
  
  v_brand_id := v_contact.brand_id;

  -- A. FORM DATA
  IF v_contact.phone IS NOT NULL AND v_contact.phone != '' THEN
    v_score := v_score + 5;
    v_drivers_pos := array_append(v_drivers_pos, 'Telefono presente');
  ELSE
    v_drivers_neg := array_append(v_drivers_neg, 'Telefono mancante');
  END IF;

  IF v_contact.email IS NOT NULL AND v_contact.email != '' THEN
    v_score := v_score + 3;
    v_drivers_pos := array_append(v_drivers_pos, 'Email presente');
  END IF;

  IF v_contact.quiz_answers IS NOT NULL AND v_contact.quiz_answers::text != '{}' AND v_contact.quiz_answers::text != 'null' THEN
    v_score := v_score + 8;
    v_drivers_pos := array_append(v_drivers_pos, 'Quiz compilato');
  END IF;

  IF v_contact.lead_message IS NOT NULL AND length(trim(v_contact.lead_message)) > 10 THEN
    v_score := v_score + 5;
    v_drivers_pos := array_append(v_drivers_pos, 'Richiesta dettagliata');
  END IF;

  -- B. RECENCY
  IF v_contact.created_at > now() - interval '1 day' THEN
    v_score := v_score + 10;
    v_drivers_pos := array_append(v_drivers_pos, 'Lead recentissimo (oggi)');
  ELSIF v_contact.created_at > now() - interval '3 days' THEN
    v_score := v_score + 5;
    v_drivers_pos := array_append(v_drivers_pos, 'Lead recente (<3 giorni)');
  END IF;

  -- C. APPOINTMENTS
  SELECT
    count(*) FILTER (WHERE a.status = 'scheduled') AS scheduled,
    count(*) FILTER (WHERE a.status = 'confirmed') AS confirmed,
    count(*) FILTER (WHERE a.status = 'visited') AS visited,
    count(*) FILTER (WHERE a.status = 'no_show') AS no_show,
    count(*) FILTER (WHERE a.status = 'cancelled') AS cancelled
  INTO v_appt_counts
  FROM appointments a
  WHERE a.contact_id = p_contact_id AND a.brand_id = v_brand_id;

  IF v_appt_counts.confirmed > 0 THEN
    v_score := v_score + 25;
    v_drivers_pos := array_append(v_drivers_pos, 'Appuntamento confermato');
  ELSIF v_appt_counts.visited > 0 THEN
    v_score := v_score + 20;
    v_drivers_pos := array_append(v_drivers_pos, 'Visita effettuata');
  ELSIF v_appt_counts.scheduled > 0 THEN
    v_score := v_score + 15;
    v_drivers_pos := array_append(v_drivers_pos, 'Appuntamento fissato');
  END IF;

  IF v_appt_counts.no_show > 0 THEN
    v_score := v_score - (v_appt_counts.no_show * 15);
    v_drivers_neg := array_append(v_drivers_neg, v_appt_counts.no_show || ' no-show');
  END IF;

  IF v_appt_counts.cancelled > 0 THEN
    v_score := v_score - (v_appt_counts.cancelled * 10);
    v_drivers_neg := array_append(v_drivers_neg, v_appt_counts.cancelled || ' cancellazione/i');
  END IF;

  -- D. DEALS
  SELECT
    count(*) FILTER (WHERE d.status = 'open') AS open_deals,
    count(*) FILTER (WHERE d.status = 'won') AS won,
    count(*) FILTER (WHERE d.status = 'lost') AS lost
  INTO v_deal_counts
  FROM deals d
  WHERE d.contact_id = p_contact_id AND d.brand_id = v_brand_id;

  IF v_deal_counts.won > 0 THEN
    v_score := v_score + 15;
    v_drivers_pos := array_append(v_drivers_pos, 'Deal vinto in passato');
  ELSIF v_deal_counts.open_deals > 0 THEN
    v_score := v_score + 10;
    v_drivers_pos := array_append(v_drivers_pos, 'Deal attivo in pipeline');
  END IF;

  IF v_deal_counts.lost > 0 THEN
    v_score := v_score - 10;
    v_drivers_neg := array_append(v_drivers_neg, 'Deal perso in passato');
  END IF;

  -- E. CALLS
  SELECT
    count(*) AS total_calls,
    count(*) FILTER (WHERE cl.status = 'completed' AND cl.duration_seconds > 120) AS quality_calls
  INTO v_call_counts
  FROM call_logs cl
  WHERE cl.contact_id = p_contact_id AND cl.brand_id = v_brand_id;

  IF v_call_counts.total_calls > 0 THEN
    v_score := v_score + 8;
    v_drivers_pos := array_append(v_drivers_pos, 'Chiamata effettuata');
  END IF;

  IF v_call_counts.quality_calls > 0 THEN
    v_score := v_score + 5;
    v_drivers_pos := array_append(v_drivers_pos, 'Chiamata di qualità (>2 min)');
  END IF;

  -- F. LEAD EVENTS & SENTIMENT
  SELECT count(*) INTO v_event_count
  FROM lead_events le
  WHERE le.contact_id = p_contact_id AND le.brand_id = v_brand_id;

  IF v_event_count > 1 THEN
    v_score := v_score + LEAST(v_event_count * 3, 15);
    v_drivers_pos := array_append(v_drivers_pos, v_event_count || ' interazioni registrate');
  END IF;

  SELECT
    bool_or(le.customer_sentiment = 'positivo') AS has_pos,
    bool_or(le.customer_sentiment = 'negativo') AS has_neg
  INTO v_has_positive_sentiment, v_has_negative_sentiment
  FROM lead_events le
  WHERE le.contact_id = p_contact_id AND le.brand_id = v_brand_id
    AND le.customer_sentiment IS NOT NULL;

  IF v_has_positive_sentiment THEN
    v_score := v_score + 10;
    v_drivers_pos := array_append(v_drivers_pos, 'Sentiment positivo');
  END IF;

  IF v_has_negative_sentiment THEN
    v_score := v_score - 10;
    v_drivers_neg := array_append(v_drivers_neg, 'Sentiment negativo');
  END IF;

  -- G. INACTIVITY
  SELECT GREATEST(
    max(a.scheduled_at),
    max(cl.started_at),
    max(le.occurred_at),
    v_contact.updated_at
  ) INTO v_last_activity
  FROM contacts c
  LEFT JOIN appointments a ON a.contact_id = c.id
  LEFT JOIN call_logs cl ON cl.contact_id = c.id
  LEFT JOIN lead_events le ON le.contact_id = c.id
  WHERE c.id = p_contact_id;

  v_days_inactive := EXTRACT(DAY FROM now() - COALESCE(v_last_activity, v_contact.created_at));

  IF v_days_inactive >= 14 THEN
    v_score := v_score - 25;
    v_drivers_neg := array_append(v_drivers_neg, 'Inattivo da ' || v_days_inactive || ' giorni');
  ELSIF v_days_inactive >= 7 THEN
    v_score := v_score - 15;
    v_drivers_neg := array_append(v_drivers_neg, 'Inattivo da ' || v_days_inactive || ' giorni');
  END IF;

  -- CLAMP & CLASSIFY
  v_score := GREATEST(0, LEAST(100, v_score));

  IF v_score >= 70 THEN
    v_heat := 'caldo';
    v_next_action := 'Contattare entro 30 minuti con proposta commerciale';
  ELSIF v_score >= 40 THEN
    v_heat := 'tiepido';
    v_next_action := 'Programmare follow-up entro 24 ore';
  ELSE
    v_heat := 'freddo';
    v_next_action := 'Inserire in sequenza nurturing automatica';
  END IF;

  v_drivers_pos := v_drivers_pos[1:3];
  v_drivers_neg := v_drivers_neg[1:3];

  -- PERSIST
  INSERT INTO lead_scores (contact_id, brand_id, score, heat_class, positive_drivers, negative_drivers, next_best_action, computed_at)
  VALUES (p_contact_id, v_brand_id, v_score, v_heat, v_drivers_pos, v_drivers_neg, v_next_action, now())
  ON CONFLICT (contact_id) DO UPDATE SET
    score = EXCLUDED.score,
    heat_class = EXCLUDED.heat_class,
    positive_drivers = EXCLUDED.positive_drivers,
    negative_drivers = EXCLUDED.negative_drivers,
    next_best_action = EXCLUDED.next_best_action,
    computed_at = EXCLUDED.computed_at,
    updated_at = now();

  INSERT INTO lead_score_history (contact_id, brand_id, score, heat_class, trigger_event, positive_drivers, negative_drivers)
  VALUES (p_contact_id, v_brand_id, v_score, v_heat, p_trigger_event, v_drivers_pos, v_drivers_neg);

  UPDATE contacts SET
    lead_score = v_score,
    lead_heat_class = v_heat,
    lead_score_updated_at = now()
  WHERE id = p_contact_id;

  RETURN jsonb_build_object(
    'contact_id', p_contact_id,
    'score', v_score,
    'heat_class', v_heat::text,
    'positive_drivers', to_jsonb(v_drivers_pos),
    'negative_drivers', to_jsonb(v_drivers_neg),
    'next_best_action', v_next_action,
    'computed_at', now()
  );
END;
$$;


--
-- Name: calculate_slo_burn_rate(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_slo_burn_rate(p_slo_id uuid) RETURNS TABLE(current_sli numeric, error_budget_remaining numeric, burn_rate_1h numeric, burn_rate_6h numeric, burn_rate_24h numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_def RECORD;
  v_total_good BIGINT;
  v_total_all BIGINT;
  v_window_good BIGINT;
  v_window_all BIGINT;
  v_target NUMERIC;
  v_sli NUMERIC;
  v_budget NUMERIC;
  v_burn_1h NUMERIC;
  v_burn_6h NUMERIC;
  v_burn_24h NUMERIC;
BEGIN
  SELECT * INTO v_def FROM public.slo_definitions WHERE id = p_slo_id AND is_active = true;
  IF NOT FOUND THEN
    RETURN;
  END IF;

  v_target := v_def.target_percentage / 100.0;

  -- Full window SLI
  SELECT COALESCE(SUM(good_events), 0), COALESCE(SUM(total_events), 0)
  INTO v_total_good, v_total_all
  FROM public.slo_measurements
  WHERE slo_id = p_slo_id
    AND measured_at >= now() - (v_def.window_days || ' days')::interval;

  v_sli := CASE WHEN v_total_all > 0 THEN v_total_good::numeric / v_total_all ELSE 1 END;
  v_budget := CASE WHEN (1 - v_target) > 0 THEN ((v_sli - v_target) / (1 - v_target)) * 100 ELSE 100 END;

  -- Burn rates (errors per period / allowed errors)
  SELECT COALESCE(SUM(good_events), 0), COALESCE(SUM(total_events), 0)
  INTO v_window_good, v_window_all
  FROM public.slo_measurements
  WHERE slo_id = p_slo_id AND measured_at >= now() - interval '1 hour';
  v_burn_1h := CASE WHEN v_window_all > 0 AND (1 - v_target) > 0
    THEN ((v_window_all - v_window_good)::numeric / v_window_all) / (1 - v_target)
    ELSE 0 END;

  SELECT COALESCE(SUM(good_events), 0), COALESCE(SUM(total_events), 0)
  INTO v_window_good, v_window_all
  FROM public.slo_measurements
  WHERE slo_id = p_slo_id AND measured_at >= now() - interval '6 hours';
  v_burn_6h := CASE WHEN v_window_all > 0 AND (1 - v_target) > 0
    THEN ((v_window_all - v_window_good)::numeric / v_window_all) / (1 - v_target)
    ELSE 0 END;

  SELECT COALESCE(SUM(good_events), 0), COALESCE(SUM(total_events), 0)
  INTO v_window_good, v_window_all
  FROM public.slo_measurements
  WHERE slo_id = p_slo_id AND measured_at >= now() - interval '24 hours';
  v_burn_24h := CASE WHEN v_window_all > 0 AND (1 - v_target) > 0
    THEN ((v_window_all - v_window_good)::numeric / v_window_all) / (1 - v_target)
    ELSE 0 END;

  RETURN QUERY SELECT v_sli, v_budget, v_burn_1h, v_burn_6h, v_burn_24h;
END;
$$;


--
-- Name: can_manage_role(public.app_role, public.app_role); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_manage_role(manager_role public.app_role, target_role public.app_role) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN manager_role = 'admin' THEN true
    WHEN manager_role = 'ceo' AND target_role != 'admin' THEN true
    WHEN manager_role = 'responsabile_venditori' 
      AND target_role IN ('venditore', 'sales') THEN true
    WHEN manager_role = 'responsabile_callcenter' 
      AND target_role IN ('operatore_callcenter', 'callcenter') THEN true
    ELSE false
  END;
$$;


--
-- Name: can_manage_role_in_brand(uuid, public.app_role); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_manage_role_in_brand(p_brand_id uuid, target_role public.app_role) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM user_roles
    WHERE user_id = get_user_id(auth.uid())
      AND brand_id = p_brand_id
      AND is_active = true
      AND can_manage_role(role, target_role)
  );
$$;


--
-- Name: can_view_audit(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_view_audit(_supabase_auth_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.user_roles ur
    JOIN public.users u ON u.id = ur.user_id
    WHERE u.supabase_auth_id = _supabase_auth_id
      AND ur.role IN ('admin'::app_role, 'ceo'::app_role, 'amministrazione'::app_role, 'responsabile_venditori'::app_role, 'responsabile_callcenter'::app_role)
  );
$$;


--
-- Name: cap_to_provincia(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cap_to_provincia(p_cap text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'public'
    AS $$
SELECT CASE substring(p_cap, 1, 2)
  WHEN '00' THEN 'RM' WHEN '01' THEN 'VT' WHEN '02' THEN 'RI' WHEN '03' THEN 'FR' WHEN '04' THEN 'LT'
  WHEN '05' THEN 'TR' WHEN '06' THEN 'PG'
  WHEN '07' THEN 'SS' WHEN '08' THEN 'CA' WHEN '09' THEN 'CA'
  WHEN '10' THEN 'TO' WHEN '11' THEN 'AO' WHEN '12' THEN 'CN' WHEN '13' THEN 'VC' WHEN '14' THEN 'AT' WHEN '15' THEN 'AL'
  WHEN '16' THEN 'GE' WHEN '17' THEN 'SV' WHEN '18' THEN 'IM' WHEN '19' THEN 'SP'
  WHEN '20' THEN 'MI' WHEN '21' THEN 'VA' WHEN '22' THEN 'CO' WHEN '23' THEN 'SO' WHEN '24' THEN 'BG' WHEN '25' THEN 'BS'
  WHEN '26' THEN 'CR' WHEN '27' THEN 'PV' WHEN '28' THEN 'NO' WHEN '29' THEN 'PC'
  WHEN '30' THEN 'VE' WHEN '31' THEN 'TV' WHEN '32' THEN 'BL' WHEN '33' THEN 'UD' WHEN '34' THEN 'TS'
  WHEN '35' THEN 'PD' WHEN '36' THEN 'VI' WHEN '37' THEN 'VR' WHEN '38' THEN 'TN' WHEN '39' THEN 'BZ'
  WHEN '40' THEN 'BO' WHEN '41' THEN 'MO' WHEN '42' THEN 'RE' WHEN '43' THEN 'PR' WHEN '44' THEN 'FE'
  WHEN '45' THEN 'RO' WHEN '46' THEN 'MN' WHEN '47' THEN 'FC' WHEN '48' THEN 'RA'
  WHEN '50' THEN 'FI' WHEN '51' THEN 'PT' WHEN '52' THEN 'AR' WHEN '53' THEN 'SI' WHEN '54' THEN 'MS'
  WHEN '55' THEN 'LU' WHEN '56' THEN 'PI' WHEN '57' THEN 'LI' WHEN '58' THEN 'GR' WHEN '59' THEN 'PO'
  WHEN '60' THEN 'AN' WHEN '61' THEN 'PU' WHEN '62' THEN 'MC' WHEN '63' THEN 'AP'
  WHEN '64' THEN 'TE' WHEN '65' THEN 'PE' WHEN '66' THEN 'CH' WHEN '67' THEN 'AQ'
  WHEN '70' THEN 'BA' WHEN '71' THEN 'FG' WHEN '72' THEN 'BR' WHEN '73' THEN 'LE' WHEN '74' THEN 'TA' WHEN '76' THEN 'BT'
  WHEN '75' THEN 'MT' WHEN '85' THEN 'PZ'
  WHEN '80' THEN 'NA' WHEN '81' THEN 'CE' WHEN '82' THEN 'BN' WHEN '83' THEN 'AV' WHEN '84' THEN 'SA'
  WHEN '86' THEN 'CB'
  WHEN '87' THEN 'CS' WHEN '88' THEN 'CZ' WHEN '89' THEN 'RC'
  WHEN '90' THEN 'PA' WHEN '91' THEN 'TP' WHEN '92' THEN 'AG' WHEN '93' THEN 'CL' WHEN '94' THEN 'EN'
  WHEN '95' THEN 'CT' WHEN '96' THEN 'SR' WHEN '97' THEN 'RG' WHEN '98' THEN 'ME'
  ELSE NULL
END
$$;


--
-- Name: cap_to_regione(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cap_to_regione(p_cap text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'public'
    AS $$
  SELECT public.provincia_to_regione(public.cap_to_provincia(p_cap))
$$;


--
-- Name: capi_events_summary(uuid[], timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.capi_events_summary(p_brand_ids uuid[], p_from timestamp with time zone DEFAULT (now() - '7 days'::interval), p_to timestamp with time zone DEFAULT now()) RETURNS TABLE(total_events bigint, pending_count bigint, sent_count bigint, failed_count bigint, skipped_count bigint, processing_count bigint, avg_attempts numeric, lead_events bigint, purchase_events bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    COUNT(*)::bigint AS total_events,
    COUNT(*) FILTER (WHERE status::text = 'pending')::bigint AS pending_count,
    COUNT(*) FILTER (WHERE status::text = 'sent')::bigint AS sent_count,
    COUNT(*) FILTER (WHERE status::text = 'failed')::bigint AS failed_count,
    COUNT(*) FILTER (WHERE status::text = 'skipped')::bigint AS skipped_count,
    COUNT(*) FILTER (WHERE status::text = 'processing')::bigint AS processing_count,
    ROUND(AVG(attempts)::numeric, 1) AS avg_attempts,
    COUNT(*) FILTER (WHERE event_name = 'Lead')::bigint AS lead_events,
    COUNT(*) FILTER (WHERE event_name = 'Purchase')::bigint AS purchase_events
  FROM meta_capi_event_queue
  WHERE brand_id = ANY(p_brand_ids)
    AND created_at >= p_from
    AND created_at <= p_to;
$$;


--
-- Name: capture_capacity_snapshot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.capture_capacity_snapshot() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_db_size_mb numeric;
  v_contacts_count bigint;
  v_webhooks_today bigint;
  v_audit_today bigint;
  v_failed_jobs bigint;
BEGIN
  SELECT pg_database_size(current_database())::numeric / 1024 / 1024 INTO v_db_size_mb;
  SELECT count(*) INTO v_contacts_count FROM public.contacts;
  SELECT count(*) INTO v_webhooks_today FROM public.incoming_requests WHERE received_at > now() - interval '24 hours';
  SELECT count(*) INTO v_audit_today FROM public.audit_events WHERE occurred_at > now() - interval '24 hours';
  SELECT count(*) INTO v_failed_jobs FROM public.incoming_requests WHERE status = 'failed';

  INSERT INTO public.capacity_snapshots (metric_name, metric_value, unit) VALUES
    ('db_size_mb', v_db_size_mb, 'MB'),
    ('contacts_count', v_contacts_count, 'rows'),
    ('webhooks_per_day', v_webhooks_today, 'count'),
    ('audit_events_per_day', v_audit_today, 'count'),
    ('failed_jobs_count', v_failed_jobs, 'count');

  RETURN jsonb_build_object(
    'db_size_mb', v_db_size_mb,
    'contacts_count', v_contacts_count,
    'webhooks_per_day', v_webhooks_today,
    'audit_events_per_day', v_audit_today,
    'failed_jobs_count', v_failed_jobs,
    'captured_at', now()
  );
END;
$$;


--
-- Name: check_all_brands_sla_breaches(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_all_brands_sla_breaches() RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_brand RECORD;
  v_total_breached integer := 0;
  v_brand_results jsonb := '[]'::jsonb;
  v_count integer;
BEGIN
  FOR v_brand IN SELECT id, name FROM brands
  LOOP
    SELECT check_and_mark_sla_breaches(v_brand.id) INTO v_count;
    
    IF v_count > 0 THEN
      v_total_breached := v_total_breached + v_count;
      v_brand_results := v_brand_results || jsonb_build_object(
        'brand_id', v_brand.id,
        'brand_name', v_brand.name,
        'breached_count', v_count
      );
    END IF;
  END LOOP;
  
  RETURN json_build_object(
    'total_breached', v_total_breached,
    'brands', v_brand_results,
    'checked_at', now()
  );
END;
$$;


--
-- Name: check_and_mark_sla_breaches(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_and_mark_sla_breaches(p_brand_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_sla_thresholds jsonb;
  v_breached_count integer := 0;
  v_ticket RECORD;
BEGIN
  -- Get SLA thresholds for this brand
  SELECT sla_thresholds_minutes INTO v_sla_thresholds
  FROM brands
  WHERE id = p_brand_id;
  
  IF v_sla_thresholds IS NULL THEN
    RETURN 0;
  END IF;
  
  -- Find and mark tickets that have breached SLA but not yet marked
  FOR v_ticket IN
    SELECT t.id, t.priority, t.opened_at
    FROM tickets t
    WHERE t.brand_id = p_brand_id
      AND t.status IN ('open', 'in_progress', 'reopened')
      AND t.sla_breached_at IS NULL
      AND (
        EXTRACT(EPOCH FROM (now() - t.opened_at)) / 60 > 
        COALESCE((v_sla_thresholds->>t.priority::text)::numeric, 1440)
      )
  LOOP
    -- Mark the ticket as breached
    UPDATE tickets
    SET sla_breached_at = now()
    WHERE id = v_ticket.id;
    
    -- Log to audit trail
    INSERT INTO ticket_audit_logs (brand_id, ticket_id, action_type, new_value, metadata)
    VALUES (
      p_brand_id,
      v_ticket.id,
      'sla_breach',
      jsonb_build_object('priority', v_ticket.priority, 'age_minutes', 
        ROUND(EXTRACT(EPOCH FROM (now() - v_ticket.opened_at)) / 60)),
      jsonb_build_object(
        'threshold_minutes', (v_sla_thresholds->>v_ticket.priority::text)::integer,
        'detected_at', now()
      )
    );
    
    v_breached_count := v_breached_count + 1;
  END LOOP;
  
  RETURN v_breached_count;
END;
$$;


--
-- Name: check_appointment_conflict(uuid, uuid, timestamp with time zone, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_appointment_conflict(p_brand_id uuid, p_assigned_sales_user_id uuid, p_scheduled_at timestamp with time zone, p_duration_minutes integer, p_exclude_appointment_id uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, scheduled_at timestamp with time zone, duration_minutes integer, contact_id uuid, status public.appointment_status)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    a.id,
    a.scheduled_at,
    a.duration_minutes,
    a.contact_id,
    a.status
  FROM public.appointments a
  WHERE a.brand_id = p_brand_id
    AND a.assigned_sales_user_id = p_assigned_sales_user_id
    AND p_assigned_sales_user_id IS NOT NULL
    AND a.status NOT IN ('cancelled', 'no_show', 'completed')
    AND (p_exclude_appointment_id IS NULL OR a.id <> p_exclude_appointment_id)
    AND tstzrange(a.scheduled_at, a.scheduled_at + (a.duration_minutes || ' minutes')::interval, '[)')
        && tstzrange(p_scheduled_at, p_scheduled_at + (p_duration_minutes || ' minutes')::interval, '[)')
  ORDER BY a.scheduled_at
  LIMIT 50;
$$;


--
-- Name: check_phone_duplicate(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_phone_duplicate(p_brand_id uuid, p_phone_normalized text) RETURNS TABLE(contact_id uuid, first_name text, last_name text, email text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT c.id, c.first_name, c.last_name, c.email
  FROM contact_phones cp
  JOIN contacts c ON c.id = cp.contact_id
  WHERE cp.brand_id = p_brand_id
    AND cp.phone_normalized = p_phone_normalized
    AND cp.is_active = true
  LIMIT 1;
$$;


--
-- Name: check_report_rate_limit(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_report_rate_limit(p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COUNT(*) < 20
  FROM sync_runs
  WHERE triggered_by = p_user_id
    AND created_at > now() - interval '1 hour';
$$;


