--
-- Name: automation_jobs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.automation_jobs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    brand_id uuid NOT NULL,
    source_event_id uuid,
    contact_id uuid,
    job_type text DEFAULT 'keplero.callback'::text NOT NULL,
    run_at timestamp with time zone NOT NULL,
    endpoint text NOT NULL,
    method text DEFAULT 'POST'::text NOT NULL,
    headers jsonb DEFAULT '{}'::jsonb NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    status text DEFAULT 'scheduled'::text NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    max_attempts integer DEFAULT 3 NOT NULL,
    last_error text,
    sent_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT automation_jobs_status_check CHECK ((status = ANY (ARRAY['scheduled'::text, 'running'::text, 'sent'::text, 'failed'::text, 'canceled'::text])))
);


--
-- Name: claim_automation_jobs(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_automation_jobs(p_limit integer DEFAULT 50) RETURNS SETOF public.automation_jobs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  UPDATE automation_jobs
  SET status = 'running', updated_at = now()
  WHERE id IN (
    SELECT id FROM automation_jobs
    WHERE status = 'scheduled'
      AND run_at <= now()
    ORDER BY run_at ASC
    LIMIT p_limit
    FOR UPDATE SKIP LOCKED
  )
  RETURNING *;
END;
$$;


