--
-- Name: claim_capi_events(integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_capi_events(p_limit integer, p_processing_by text DEFAULT NULL::text) RETURNS SETOF public.meta_capi_event_queue
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  UPDATE public.meta_capi_event_queue
  SET 
    status = 'processing',
    processing_at = NOW(),
    processing_by = COALESCE(p_processing_by, gen_random_uuid()::text)
  WHERE id IN (
    SELECT id FROM public.meta_capi_event_queue
    WHERE (
      (status = 'pending')
      OR (status = 'processing' AND processing_at < NOW() - INTERVAL '5 minutes')
    )
      AND attempts < max_attempts
      AND consent_snapshot = true
    ORDER BY created_at
    LIMIT p_limit
    FOR UPDATE SKIP LOCKED
  )
  RETURNING *;
END;
$$;


