--
-- Name: claim_inbound_events(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_inbound_events(p_limit integer DEFAULT 50) RETURNS SETOF public.webhook_inbound_events
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  UPDATE public.webhook_inbound_events
  SET status = 'processing'
  WHERE id IN (
    SELECT id FROM public.webhook_inbound_events
    WHERE status = 'pending'
      AND (attempts < 5 OR attempts IS NULL)
    ORDER BY received_at ASC
    LIMIT p_limit
    FOR UPDATE SKIP LOCKED
  )
  RETURNING *;
END;
$$;


--
-- Name: claim_pending_notification_webhooks(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_pending_notification_webhooks(p_limit integer DEFAULT 50) RETURNS TABLE(outbox_id uuid, destination_id uuid, endpoint_url text, hmac_secret text, preset text, payload jsonb, attempts integer, retry_max integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH claimed AS (
    SELECT o.id
    FROM public.notification_webhook_outbox o
    JOIN public.notification_webhook_destinations d ON d.id = o.destination_id
    WHERE o.status = 'pending'
      AND o.next_retry_at <= now()
      AND d.is_active = true
    ORDER BY o.next_retry_at ASC
    LIMIT LEAST(GREATEST(p_limit, 1), 200)
    FOR UPDATE OF o SKIP LOCKED
  )
  UPDATE public.notification_webhook_outbox o
  SET attempts = o.attempts + 1,
      last_attempt_at = now()
  FROM claimed c, public.notification_webhook_destinations d
  WHERE o.id = c.id AND d.id = o.destination_id
  RETURNING
    o.id,
    o.destination_id,
    d.endpoint_url,
    d.hmac_secret,
    d.preset,
    o.payload,
    o.attempts,
    d.retry_max;
END;
$$;


--
-- Name: claim_pending_siem_exports(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_pending_siem_exports(_destination_id uuid) RETURNS TABLE(event_id uuid, brand_id uuid, entity_type text, entity_id uuid, action text, actor_user_id uuid, actor_type text, actor_display_name text, source text, old_value jsonb, new_value jsonb, changed_fields text[], metadata jsonb, correlation_id text, occurred_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _dest public.siem_destinations%ROWTYPE;
BEGIN
  SELECT * INTO _dest FROM public.siem_destinations
  WHERE id = _destination_id AND is_active = true
  FOR UPDATE SKIP LOCKED;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    ae.id,
    ae.brand_id,
    ae.entity_type,
    ae.entity_id,
    ae.action,
    ae.actor_user_id,
    ae.actor_type,
    ae.actor_display_name,
    ae.source,
    ae.old_value,
    ae.new_value,
    ae.changed_fields,
    ae.metadata,
    ae.correlation_id,
    ae.occurred_at
  FROM public.audit_events ae
  WHERE ae.brand_id = _dest.brand_id
    AND ae.occurred_at > _dest.last_exported_at
    AND (_dest.entity_types_filter IS NULL OR ae.entity_type = ANY(_dest.entity_types_filter))
    AND (_dest.actions_filter IS NULL OR ae.action = ANY(_dest.actions_filter))
  ORDER BY ae.occurred_at ASC
  LIMIT _dest.batch_size;
END;
$$;


