CREATE FUNCTION public.claim_webhook_deliveries(p_batch_size integer DEFAULT 10) RETURNS SETOF public.outbound_webhook_deliveries
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  UPDATE outbound_webhook_deliveries
  SET 
    status = 'sending',
    updated_at = now()
  WHERE id IN (
    SELECT id
    FROM outbound_webhook_deliveries
    WHERE status IN ('pending', 'failed')
      AND next_attempt_at <= now()
      AND attempt_count < max_attempts
    ORDER BY next_attempt_at ASC
    LIMIT p_batch_size
    FOR UPDATE SKIP LOCKED
  )
  RETURNING *;
END;
$$;


--
-- Name: cleanup_old_traces(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_old_traces() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_deleted INTEGER;
BEGIN
  DELETE FROM public.trace_events WHERE created_at < now() - interval '14 days';
  GET DIAGNOSTICS v_deleted = ROW_COUNT;

  DELETE FROM public.slo_measurements WHERE measured_at < now() - interval '90 days';
  RETURN v_deleted;
END;
$$;


--
-- Name: cleanup_outbound_webhook_deliveries(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_outbound_webhook_deliveries(p_limit integer DEFAULT 10000) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_deleted int := 0;
BEGIN
  WITH doomed AS (
    SELECT id
    FROM public.outbound_webhook_deliveries
    WHERE created_at < now() - interval '7 days'
    ORDER BY created_at ASC
    LIMIT p_limit
  )
  DELETE FROM public.outbound_webhook_deliveries d
  USING doomed
  WHERE d.id = doomed.id;

  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN v_deleted;
END;
$$;


