-- Name: cleanup_webhook_dedup(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_webhook_dedup() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  deleted_count INTEGER;
BEGIN
  DELETE FROM public.webhook_request_dedup
  WHERE expires_at < now();
  GET DIAGNOSTICS deleted_count = ROW_COUNT;
  RETURN deleted_count;
END;
$$;


--
-- Name: complete_ai_tag_job(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_ai_tag_job(p_job_id uuid, p_error text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_error IS NULL THEN
    UPDATE ai_tag_deal_jobs 
    SET status = 'completed', completed_at = now()
    WHERE id = p_job_id;
  ELSE
    UPDATE ai_tag_deal_jobs 
    SET status = CASE WHEN attempts >= max_attempts THEN 'failed' ELSE 'pending' END,
        last_error = p_error,
        started_at = NULL
    WHERE id = p_job_id;
  END IF;
END;
$$;


--
-- Name: compute_appointment_risk_score(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compute_appointment_risk_score(p_appointment_id uuid) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_score numeric := 0;
  v_appt RECORD;
  v_no_show_count int := 0;
  v_reschedule_count int := 0;
  v_has_phone boolean := false;
  v_hours_until numeric;
BEGIN
  SELECT id, contact_id, scheduled_at, status, address, city,
         assigned_sales_user_id, appointment_type
  INTO v_appt
  FROM public.appointments
  WHERE id = p_appointment_id;

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  -- Skip terminal statuses
  IF v_appt.status IN ('cancelled', 'visited', 'completed', 'no_show') THEN
    RETURN 0;
  END IF;

  v_hours_until := EXTRACT(EPOCH FROM (v_appt.scheduled_at - now())) / 3600;

  -- +25: draft entro 24h
  IF v_appt.status = 'draft' AND v_hours_until BETWEEN 0 AND 24 THEN
    v_score := v_score + 25;
  END IF;

  -- +20: contatto con storico no-show
  SELECT COUNT(*) INTO v_no_show_count
  FROM public.appointment_outcomes ao
  JOIN public.appointments a ON a.id = ao.appointment_id
  WHERE a.contact_id = v_appt.contact_id
    AND ao.outcome_code IN ('no_show_client', 'no_show_operator');
  IF v_no_show_count > 0 THEN
    v_score := v_score + 20;
  END IF;

  -- +15: contatto con >2 riprogrammazioni
  SELECT COUNT(*) INTO v_reschedule_count
  FROM public.appointment_outcomes ao
  JOIN public.appointments a ON a.id = ao.appointment_id
  WHERE a.contact_id = v_appt.contact_id
    AND ao.outcome_code = 'rescheduled';
  IF v_reschedule_count > 2 THEN
    v_score := v_score + 15;
  END IF;

  -- +15: manca telefono primario
  SELECT EXISTS (
    SELECT 1 FROM public.contact_phones
    WHERE contact_id = v_appt.contact_id
      AND is_primary = true
      AND is_active = true
  ) INTO v_has_phone;
  IF NOT v_has_phone THEN
    v_score := v_score + 15;
  END IF;

  -- +10: manca indirizzo o città
  IF v_appt.address IS NULL OR v_appt.city IS NULL THEN
    v_score := v_score + 10;
  END IF;

  -- +10: nessun sales assegnato a <48h
  IF v_appt.assigned_sales_user_id IS NULL AND v_hours_until BETWEEN 0 AND 48 THEN
    v_score := v_score + 10;
  END IF;

  -- +5: follow_up
  IF v_appt.appointment_type = 'follow_up' THEN
    v_score := v_score + 5;
  END IF;

  -- Cap at 100
  IF v_score > 100 THEN
    v_score := 100;
  END IF;

  RETURN v_score;
END;
$$;


--
-- Name: consume_ai_quota(uuid, uuid, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.consume_ai_quota(p_user_id uuid, p_brand_id uuid, p_endpoint text, p_input_chars integer, p_daily_limit integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_current_count integer;
  v_today date := (now() AT TIME ZONE 'UTC')::date;
BEGIN
  INSERT INTO public.ai_request_quota (user_id, brand_id, endpoint, day, request_count, total_input_chars, last_request_at, updated_at)
  VALUES (p_user_id, p_brand_id, p_endpoint, v_today, 1, COALESCE(p_input_chars, 0), now(), now())
  ON CONFLICT (user_id, endpoint, day) DO UPDATE
    SET request_count     = ai_request_quota.request_count + 1,
        total_input_chars = ai_request_quota.total_input_chars + COALESCE(EXCLUDED.total_input_chars, 0),
        last_request_at   = now(),
        updated_at        = now()
  RETURNING request_count INTO v_current_count;

  IF v_current_count > p_daily_limit THEN
    UPDATE public.ai_request_quota
       SET request_count     = request_count - 1,
           total_input_chars = total_input_chars - COALESCE(p_input_chars, 0),
           updated_at        = now()
     WHERE user_id = p_user_id AND endpoint = p_endpoint AND day = v_today;

    RETURN jsonb_build_object(
      'allowed', false,
      'remaining', 0,
      'daily_limit', p_daily_limit,
      'used', p_daily_limit
    );
  END IF;

  RETURN jsonb_build_object(
    'allowed', true,
    'remaining', GREATEST(0, p_daily_limit - v_current_count),
    'daily_limit', p_daily_limit,
    'used', v_current_count
  );
END;
$$;


--
-- Name: consume_rate_limit_token(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.consume_rate_limit_token(p_source_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_bucket RECORD;
  v_elapsed_minutes NUMERIC;
  v_tokens_to_add INT;
  v_new_tokens INT;
BEGIN
  -- 1. Upsert: crea bucket se non esiste
  INSERT INTO public.rate_limit_buckets (source_id, tokens, max_tokens, refill_rate)
  SELECT 
    p_source_id,
    ws.rate_limit_per_min,
    ws.rate_limit_per_min,
    ws.rate_limit_per_min
  FROM public.webhook_sources ws
  WHERE ws.id = p_source_id
  ON CONFLICT (source_id) DO NOTHING;

  -- 2. Lock e fetch
  SELECT tokens, max_tokens, refill_rate, last_refill_at
  INTO v_bucket
  FROM public.rate_limit_buckets
  WHERE source_id = p_source_id
  FOR UPDATE;

  -- 3. Source non esiste
  IF v_bucket IS NULL THEN
    RETURN FALSE;
  END IF;

  -- 4. Calcola refill
  v_elapsed_minutes := EXTRACT(EPOCH FROM (now() - v_bucket.last_refill_at)) / 60.0;
  v_tokens_to_add := FLOOR(v_elapsed_minutes * v_bucket.refill_rate);
  v_new_tokens := LEAST(v_bucket.tokens + v_tokens_to_add, v_bucket.max_tokens);

  -- 5. Consuma token
  IF v_new_tokens > 0 THEN
    UPDATE public.rate_limit_buckets
    SET 
      tokens = v_new_tokens - 1,
      last_refill_at = CASE 
        WHEN v_tokens_to_add > 0 THEN now() 
        ELSE last_refill_at 
      END
    WHERE source_id = p_source_id;
    
    RETURN TRUE;
  END IF;

  RETURN FALSE;
END;
$$;


--
-- Name: correct_contact_phone(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.correct_contact_phone(p_contact_id uuid, p_old_phone text, p_new_phone text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_brand_id uuid;
  v_phone_record contact_phones%ROWTYPE;
  v_old_normalized text;
  v_new_normalized text;
  v_new_country_code text := 'IT';
  v_new_assumed_country boolean := true;
  v_existing_phone contact_phones%ROWTYPE;
  v_result jsonb;
BEGIN
  -- Get user id
  v_user_id := get_user_id(auth.uid());
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Get brand from contact and validate access
  SELECT brand_id INTO v_brand_id
  FROM contacts
  WHERE id = p_contact_id;

  IF v_brand_id IS NULL THEN
    RAISE EXCEPTION 'Contact not found';
  END IF;

  IF NOT user_belongs_to_brand(v_user_id, v_brand_id) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  -- Normalize phones (digits only)
  v_old_normalized := regexp_replace(p_old_phone, '\D', '', 'g');
  v_new_normalized := regexp_replace(p_new_phone, '\D', '', 'g');

  -- Detect country code from new phone
  IF length(v_new_normalized) > 10 THEN
    IF v_new_normalized LIKE '39%' THEN
      v_new_normalized := substring(v_new_normalized FROM 3);
      v_new_country_code := 'IT';
      v_new_assumed_country := false;
    ELSIF v_new_normalized LIKE '44%' THEN
      v_new_normalized := substring(v_new_normalized FROM 3);
      v_new_country_code := 'GB';
      v_new_assumed_country := false;
    ELSIF v_new_normalized LIKE '49%' THEN
      v_new_normalized := substring(v_new_normalized FROM 3);
      v_new_country_code := 'DE';
      v_new_assumed_country := false;
    ELSIF v_new_normalized LIKE '33%' THEN
      v_new_normalized := substring(v_new_normalized FROM 3);
      v_new_country_code := 'FR';
      v_new_assumed_country := false;
    ELSIF v_new_normalized LIKE '1%' AND length(v_new_normalized) = 11 THEN
      v_new_normalized := substring(v_new_normalized FROM 2);
      v_new_country_code := 'US';
      v_new_assumed_country := false;
    END IF;
  END IF;

  -- Find the phone record to update
  SELECT * INTO v_phone_record
  FROM contact_phones
  WHERE contact_id = p_contact_id
    AND brand_id = v_brand_id
    AND phone_normalized = v_old_normalized
  FOR UPDATE;

  IF v_phone_record.id IS NULL THEN
    RAISE EXCEPTION 'Phone number % not found for this contact', p_old_phone;
  END IF;

  -- Check if new phone already exists for another contact in same brand
  SELECT * INTO v_existing_phone
  FROM contact_phones
  WHERE brand_id = v_brand_id
    AND phone_normalized = v_new_normalized
    AND contact_id != p_contact_id;

  IF v_existing_phone.id IS NOT NULL THEN
    -- Phone exists on another contact - return conflict info for merge decision
    v_result := jsonb_build_object(
      'success', false,
      'error', 'phone_exists_other_contact',
      'conflicting_contact_id', v_existing_phone.contact_id,
      'message', 'Il numero ' || p_new_phone || ' è già associato ad un altro contatto'
    );
    RETURN v_result;
  END IF;

  -- Check if new phone already exists for THIS contact (same brand, same contact)
  SELECT * INTO v_existing_phone
  FROM contact_phones
  WHERE brand_id = v_brand_id
    AND phone_normalized = v_new_normalized
    AND contact_id = p_contact_id
    AND id != v_phone_record.id;

  IF v_existing_phone.id IS NOT NULL THEN
    -- New phone already exists on same contact - just deactivate old one
    UPDATE contact_phones
    SET is_active = false
    WHERE id = v_phone_record.id;

    -- If old was primary, transfer to existing
    IF v_phone_record.is_primary THEN
      UPDATE contact_phones
      SET is_primary = true
      WHERE id = v_existing_phone.id;
    END IF;

    -- Audit log
    INSERT INTO audit_log (brand_id, entity_type, entity_id, action, actor_user_id, old_value, new_value, metadata)
    VALUES (
      v_brand_id,
      'contact_phone',
      v_phone_record.id,
      'phone_corrected_merged',
      v_user_id,
      jsonb_build_object('phone_raw', v_phone_record.phone_raw, 'phone_normalized', v_phone_record.phone_normalized),
      jsonb_build_object('phone_raw', p_new_phone, 'phone_normalized', v_new_normalized, 'merged_with', v_existing_phone.id),
      jsonb_build_object('contact_id', p_contact_id, 'was_primary', v_phone_record.is_primary)
    );

    v_result := jsonb_build_object(
      'success', true,
      'action', 'merged',
      'phone_id', v_existing_phone.id,
      'message', 'Numero corretto e unito con record esistente'
    );
    RETURN v_result;
  END IF;

  -- Standard case: update the phone record
  UPDATE contact_phones
  SET 
    phone_raw = p_new_phone,
    phone_normalized = v_new_normalized,
    country_code = v_new_country_code,
    assumed_country = v_new_assumed_country
  WHERE id = v_phone_record.id;

  -- Audit log
  INSERT INTO audit_log (brand_id, entity_type, entity_id, action, actor_user_id, old_value, new_value, metadata)
  VALUES (
    v_brand_id,
    'contact_phone',
    v_phone_record.id,
    'phone_corrected',
    v_user_id,
    jsonb_build_object(
      'phone_raw', v_phone_record.phone_raw, 
      'phone_normalized', v_phone_record.phone_normalized,
      'country_code', v_phone_record.country_code
    ),
    jsonb_build_object(
      'phone_raw', p_new_phone, 
      'phone_normalized', v_new_normalized,
      'country_code', v_new_country_code
    ),
    jsonb_build_object('contact_id', p_contact_id, 'is_primary', v_phone_record.is_primary)
  );

  v_result := jsonb_build_object(
    'success', true,
    'action', 'updated',
    'phone_id', v_phone_record.id,
    'old_normalized', v_phone_record.phone_normalized,
    'new_normalized', v_new_normalized,
    'message', 'Numero corretto con successo'
  );

  RETURN v_result;
END;
$$;


--
-- Name: count_new_leads_by_day(uuid[], timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.count_new_leads_by_day(p_brand_ids uuid[], p_from timestamp with time zone, p_to timestamp with time zone) RETURNS TABLE(day date, new_leads bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH first_events AS (
    SELECT le.contact_id, (le.received_at AT TIME ZONE 'Europe/Rome')::date AS event_day
    FROM lead_events le
    WHERE le.brand_id = ANY(p_brand_ids)
      AND le.contact_id IS NOT NULL
      AND le.received_at >= p_from
      AND le.received_at <= p_to
      AND NOT EXISTS (
        SELECT 1 FROM webhook_sources ws
        WHERE ws.name = le.source_name
          AND ws.brand_id = le.brand_id
          AND ws.counts_as_new_lead = false
      )
      AND NOT EXISTS (
        SELECT 1 FROM lead_events older
        WHERE older.contact_id = le.contact_id
          AND older.brand_id = le.brand_id
          AND older.received_at < p_from
          AND NOT EXISTS (
            SELECT 1 FROM webhook_sources ws2
            WHERE ws2.name = older.source_name
              AND ws2.brand_id = older.brand_id
              AND ws2.counts_as_new_lead = false
          )
      )
  )
  SELECT fe.event_day AS day, count(DISTINCT fe.contact_id) AS new_leads
  FROM first_events fe
  GROUP BY fe.event_day
  ORDER BY fe.event_day;
$$;


--
-- Name: count_new_leads_in_range(uuid[], timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.count_new_leads_in_range(p_brand_ids uuid[], p_from timestamp with time zone, p_to timestamp with time zone) RETURNS bigint
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT count(DISTINCT le.contact_id)
  FROM lead_events le
  WHERE le.brand_id = ANY(p_brand_ids)
    AND le.contact_id IS NOT NULL
    AND le.received_at >= p_from
    AND le.received_at <= p_to
    AND NOT EXISTS (
      SELECT 1 FROM webhook_sources ws
      WHERE ws.name = le.source_name
        AND ws.brand_id = le.brand_id
        AND ws.counts_as_new_lead = false
    )
    AND NOT EXISTS (
      SELECT 1 FROM lead_events older
      WHERE older.contact_id = le.contact_id
        AND older.brand_id = le.brand_id
        AND older.received_at < p_from
        AND NOT EXISTS (
          SELECT 1 FROM webhook_sources ws2
          WHERE ws2.name = older.source_name
            AND ws2.brand_id = older.brand_id
            AND ws2.counts_as_new_lead = false
        )
    );
$$;


--
-- Name: create_appointment(uuid, uuid, uuid, timestamp with time zone, integer, text, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_appointment(p_brand_id uuid, p_contact_id uuid, p_deal_id uuid DEFAULT NULL::uuid, p_scheduled_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_duration_minutes integer DEFAULT 60, p_address text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_cap text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_assigned_sales_user_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_user_role app_role;
  v_appointment_id uuid;
  v_contact_brand uuid;
  v_deal_contact uuid;
  v_sales_role app_role;
BEGIN
  -- Get current user
  SELECT u.id INTO v_user_id
  FROM public.users u
  WHERE u.supabase_auth_id = auth.uid();

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  -- Check brand access
  IF NOT user_belongs_to_brand(v_user_id, p_brand_id) THEN
    RAISE EXCEPTION 'Forbidden: no access to this brand';
  END IF;

  -- Get role
  SELECT ur.role INTO v_user_role
  FROM public.user_roles ur
  WHERE ur.user_id = v_user_id AND ur.brand_id = p_brand_id
  LIMIT 1;

  -- Only admin/ceo/callcenter can create appointments
  IF v_user_role NOT IN ('admin', 'ceo', 'callcenter') THEN
    RAISE EXCEPTION 'Forbidden: creating appointments requires admin, ceo, or callcenter role';
  END IF;

  -- VALIDATION: Contact must belong to brand
  SELECT brand_id INTO v_contact_brand
  FROM public.contacts
  WHERE id = p_contact_id;

  IF v_contact_brand IS NULL THEN
    RAISE EXCEPTION 'Not found: contact does not exist';
  END IF;

  IF v_contact_brand != p_brand_id THEN
    RAISE EXCEPTION 'Forbidden: contact does not belong to this brand';
  END IF;

  -- VALIDATION: If deal provided, must belong to same brand and same contact
  IF p_deal_id IS NOT NULL THEN
    SELECT contact_id INTO v_deal_contact
    FROM public.deals
    WHERE id = p_deal_id AND brand_id = p_brand_id;

    IF v_deal_contact IS NULL THEN
      RAISE EXCEPTION 'Forbidden: deal does not exist or does not belong to this brand';
    END IF;

    IF v_deal_contact != p_contact_id THEN
      RAISE EXCEPTION 'Forbidden: deal contact mismatch';
    END IF;
  END IF;

  -- VALIDATION: If sales user assigned, must have sales role for this brand
  IF p_assigned_sales_user_id IS NOT NULL THEN
    SELECT ur.role INTO v_sales_role
    FROM public.user_roles ur
    WHERE ur.user_id = p_assigned_sales_user_id 
      AND ur.brand_id = p_brand_id
      AND ur.role = 'sales'
    LIMIT 1;

    IF v_sales_role IS NULL THEN
      RAISE EXCEPTION 'Forbidden: assigned user is not a sales for this brand';
    END IF;
  END IF;

  -- Insert appointment
  INSERT INTO public.appointments (
    brand_id,
    contact_id,
    deal_id,
    scheduled_at,
    duration_minutes,
    address,
    city,
    cap,
    notes,
    assigned_sales_user_id,
    created_by_user_id
  ) VALUES (
    p_brand_id,
    p_contact_id,
    p_deal_id,
    COALESCE(p_scheduled_at, now() + interval '1 day'),
    p_duration_minutes,
    p_address,
    p_city,
    p_cap,
    p_notes,
    p_assigned_sales_user_id,
    v_user_id
  )
  RETURNING id INTO v_appointment_id;

  -- AUDIT: Log creation
  INSERT INTO public.audit_log (
    brand_id, entity_type, entity_id, action, actor_user_id, new_value
  )
  SELECT 
    p_brand_id, 
    'appointment', 
    v_appointment_id, 
    'create',
    v_user_id,
    row_to_json(a.*)::jsonb
  FROM public.appointments a WHERE a.id = v_appointment_id;

  RETURN v_appointment_id;
END;
$$;


--
-- Name: create_brand_notifications(uuid, public.notification_type, text, text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_brand_notifications(p_brand_id uuid, p_type public.notification_type, p_title text, p_body text DEFAULT NULL::text, p_entity_type text DEFAULT NULL::text, p_entity_id uuid DEFAULT NULL::uuid, p_exclude_user_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO notifications (brand_id, user_id, type, title, body, entity_type, entity_id)
  SELECT p_brand_id, ur.user_id, p_type, p_title, p_body, p_entity_type, p_entity_id
  FROM user_roles ur
  WHERE ur.brand_id = p_brand_id
    AND ur.is_active = true
    AND (p_exclude_user_id IS NULL OR ur.user_id != p_exclude_user_id);
END;
$$;


--
-- Name: create_group_chat(uuid, text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_group_chat(p_brand_id uuid, p_title text, p_member_ids uuid[]) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_thread_id uuid; v_user_id uuid; v_member_id uuid;
BEGIN
  v_user_id := get_user_id(auth.uid());
  IF NOT user_belongs_to_brand(v_user_id, p_brand_id) THEN RAISE EXCEPTION 'User does not belong to this brand'; END IF;
  INSERT INTO chat_threads (brand_id, type, title, created_by) VALUES (p_brand_id, 'group', p_title, v_user_id) RETURNING id INTO v_thread_id;
  INSERT INTO chat_thread_members (thread_id, user_id, role) VALUES (v_thread_id, v_user_id, 'owner');
  FOREACH v_member_id IN ARRAY p_member_ids LOOP
    IF v_member_id != v_user_id AND user_belongs_to_brand(v_member_id, p_brand_id) THEN
      INSERT INTO chat_thread_members (thread_id, user_id, role) VALUES (v_thread_id, v_member_id, 'member') ON CONFLICT DO NOTHING;
    END IF;
  END LOOP;
  RETURN v_thread_id;
END; $$;


--
-- Name: create_manual_lead_event(uuid, uuid, text, public.lead_source_channel, public.contact_channel, public.pacemaker_status, public.customer_sentiment, public.decision_status, public.objection_type, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_manual_lead_event(p_brand_id uuid, p_contact_id uuid, p_source_name text DEFAULT 'Creazione manuale'::text, p_lead_source_channel public.lead_source_channel DEFAULT NULL::public.lead_source_channel, p_contact_channel public.contact_channel DEFAULT NULL::public.contact_channel, p_pacemaker_status public.pacemaker_status DEFAULT NULL::public.pacemaker_status, p_customer_sentiment public.customer_sentiment DEFAULT NULL::public.customer_sentiment, p_decision_status public.decision_status DEFAULT NULL::public.decision_status, p_objection_type public.objection_type DEFAULT NULL::public.objection_type, p_booking_notes text DEFAULT NULL::text, p_logistics_notes text DEFAULT NULL::text, p_ai_conversation_summary text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_event_id uuid;
BEGIN
  -- Resolve app user
  v_user_id := get_user_id(auth.uid());
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  -- Brand access check
  IF NOT user_belongs_to_brand(v_user_id, p_brand_id) THEN
    RAISE EXCEPTION 'Forbidden: no access to brand';
  END IF;

  -- Verify contact belongs to brand
  IF NOT EXISTS (
    SELECT 1 FROM public.contacts 
    WHERE id = p_contact_id AND brand_id = p_brand_id
  ) THEN
    RAISE EXCEPTION 'Contact not found or does not belong to brand';
  END IF;

  -- Insert the manual lead_event
  INSERT INTO public.lead_events (
    brand_id,
    contact_id,
    source,
    source_name,
    raw_payload,
    occurred_at,
    received_at,
    lead_source_channel,
    contact_channel,
    pacemaker_status,
    customer_sentiment,
    decision_status,
    objection_type,
    booking_notes,
    logistics_notes,
    ai_conversation_summary
  ) VALUES (
    p_brand_id,
    p_contact_id,
    'manual'::lead_source_type,
    COALESCE(p_source_name, 'Creazione manuale'),
    jsonb_build_object('created_by_user_id', v_user_id::text, 'created_at', now()::text),
    now(),
    now(),
    p_lead_source_channel,
    p_contact_channel,
    p_pacemaker_status,
    p_customer_sentiment,
    p_decision_status,
    p_objection_type,
    p_booking_notes,
    p_logistics_notes,
    p_ai_conversation_summary
  )
  RETURNING id INTO v_event_id;

  -- Audit log
  INSERT INTO public.audit_log (
    brand_id,
    entity_type,
    entity_id,
    action,
    actor_user_id,
    new_value
  ) VALUES (
    p_brand_id,
    'lead_event',
    v_event_id,
    'create_manual',
    v_user_id,
    jsonb_build_object('contact_id', p_contact_id, 'source', 'manual')
  );

  RETURN v_event_id;
END;
$$;


--
-- Name: create_marketing_lead(uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_marketing_lead(p_brand_id uuid, p_contact_id uuid, p_marketing_campaign_id uuid DEFAULT NULL::uuid, p_source_name text DEFAULT 'Lead manuale marketing'::text, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_event_id UUID;
BEGIN
  v_user_id := current_app_user_id();
  
  IF NOT user_belongs_to_brand(v_user_id, p_brand_id) THEN
    RAISE EXCEPTION 'Accesso negato al brand';
  END IF;

  INSERT INTO lead_events (
    brand_id, contact_id, source, source_name,
    marketing_campaign_id, occurred_at, received_at,
    raw_payload
  ) VALUES (
    p_brand_id, p_contact_id, 'manual', p_source_name,
    p_marketing_campaign_id, now(), now(),
    jsonb_build_object('notes', p_notes, 'created_by', v_user_id::text)
  )
  RETURNING id INTO v_event_id;

  RETURN v_event_id;
END;
$$;


--
-- Name: create_outbound_webhook(uuid, text, text, text, text[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_outbound_webhook(p_brand_id uuid, p_name text, p_url text, p_secret text, p_event_types text[], p_is_active boolean DEFAULT true) RETURNS TABLE(webhook_id uuid, secret text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_webhook_id uuid;
  v_valid_events text[] := ARRAY[
    'ticket.created', 'ticket.updated', 'ticket.assigned', 
    'ticket.status_changed', 'ticket.priority_changed', 
    'ticket.sla_breached', 'ticket.resolved', 'ticket.closed',
    'contact.created', 'contact.updated',
    'deal.created', 'deal.stage_changed', 'deal.closed',
    'webhook.test'
  ];
BEGIN
  -- Admin check
  IF NOT has_role_for_brand(get_user_id(auth.uid()), p_brand_id, 'admin') THEN
    RAISE EXCEPTION 'Admin access required';
  END IF;
  
  -- Validate URL: HTTPS required, no exceptions
  IF NOT (p_url LIKE 'https://%') THEN
    RAISE EXCEPTION 'URL must use HTTPS';
  END IF;
  
  -- Validate secret length
  IF length(p_secret) < 32 THEN
    RAISE EXCEPTION 'Secret must be at least 32 characters';
  END IF;
  
  -- Validate event types
  IF NOT (p_event_types <@ v_valid_events) THEN
    RAISE EXCEPTION 'Invalid event type(s) specified';
  END IF;
  
  -- Insert webhook
  INSERT INTO outbound_webhooks (brand_id, name, url, secret, event_types, is_active)
  VALUES (p_brand_id, p_name, p_url, p_secret, p_event_types::webhook_event_type[], p_is_active)
  RETURNING id INTO v_webhook_id;
  
  RETURN QUERY SELECT v_webhook_id, p_secret;
END;
$$;


--
-- Name: create_outbound_webhook(uuid, text, text, text, text[], boolean, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_outbound_webhook(p_brand_id uuid, p_name text, p_url text, p_secret text, p_event_types text[], p_is_active boolean DEFAULT true, p_payload_format text DEFAULT 'json'::text, p_payload_mapping jsonb DEFAULT NULL::jsonb, p_custom_url_params jsonb DEFAULT NULL::jsonb) RETURNS TABLE(webhook_id uuid, secret text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_webhook_id uuid;
  v_user_id uuid;
BEGIN
  -- Get the internal user_id from the supabase_auth_id
  SELECT u.id INTO v_user_id 
  FROM users u 
  WHERE u.supabase_auth_id = auth.uid();

  -- Verify user has admin or ceo role for this brand
  IF NOT EXISTS (
    SELECT 1 FROM user_roles
    WHERE user_id = v_user_id
    AND brand_id = p_brand_id
    AND role IN ('admin', 'ceo')
  ) THEN
    RAISE EXCEPTION 'Access denied: admin or ceo role required';
  END IF;

  -- Insert the webhook
  INSERT INTO outbound_webhooks (
    brand_id, name, url, secret_encrypted, event_types, is_active,
    payload_format, payload_mapping, custom_url_params
  )
  VALUES (
    p_brand_id, p_name, p_url,
    extensions.crypt(p_secret, extensions.gen_salt('bf')),
    p_event_types, p_is_active,
    p_payload_format, p_payload_mapping, p_custom_url_params
  )
  RETURNING id INTO v_webhook_id;

  RETURN QUERY SELECT v_webhook_id, p_secret;
END;
$$;


--
-- Name: create_outbound_webhook(uuid, text, text, text, public.webhook_event_type[], boolean, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_outbound_webhook(p_brand_id uuid, p_name text, p_url text, p_secret text, p_event_types public.webhook_event_type[], p_is_active boolean DEFAULT true, p_payload_format text DEFAULT 'json'::text, p_payload_mapping jsonb DEFAULT NULL::jsonb, p_custom_url_params jsonb DEFAULT NULL::jsonb) RETURNS TABLE(webhook_id uuid, secret text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_webhook_id UUID;
BEGIN
  -- Verify user has admin role for this brand
  IF NOT EXISTS (
    SELECT 1 FROM user_brand_roles
    WHERE user_id = auth.uid()
    AND brand_id = p_brand_id
    AND role = 'admin'
  ) THEN
    RAISE EXCEPTION 'Access denied: admin role required';
  END IF;

  -- Validate payload_format
  IF p_payload_format NOT IN ('json', 'form_urlencoded') THEN
    RAISE EXCEPTION 'Invalid payload_format. Must be json or form_urlencoded';
  END IF;

  -- Insert webhook
  INSERT INTO outbound_webhooks (
    brand_id, name, url, secret, event_types, is_active,
    payload_format, payload_mapping, custom_url_params
  )
  VALUES (
    p_brand_id, p_name, p_url, p_secret, p_event_types, p_is_active,
    p_payload_format, p_payload_mapping, p_custom_url_params
  )
  RETURNING id INTO v_webhook_id;

  RETURN QUERY SELECT v_webhook_id, p_secret;
END;
$$;


--
-- Name: create_pipeline_stage(text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_pipeline_stage(p_name text, p_color text DEFAULT '#6366f1'::text, p_brand_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_new_id UUID;
  v_max_order INT;
  v_user_id UUID;
BEGIN
  -- Get user_id from auth
  v_user_id := get_user_id(auth.uid());
  
  -- Check if user is admin or CEO
  IF NOT (has_role(v_user_id, 'admin'::app_role) OR has_role(v_user_id, 'ceo'::app_role)) THEN
    RAISE EXCEPTION 'Solo admin e CEO possono creare fasi pipeline';
  END IF;
  
  -- Get max order_index for global stages
  SELECT COALESCE(MAX(order_index), -1) INTO v_max_order
  FROM pipeline_stages
  WHERE is_active = true;
  
  -- Insert new stage (global, no brand_id)
  INSERT INTO pipeline_stages (name, color, order_index, brand_id)
  VALUES (p_name, p_color, v_max_order + 1, NULL)
  RETURNING id INTO v_new_id;
  
  RETURN v_new_id;
END;
$$;


--
-- Name: create_pipeline_stage(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_pipeline_stage(p_brand_id uuid, p_name text, p_color text DEFAULT '#6366f1'::text, p_description text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_max_order int;
  v_new_id uuid;
BEGIN
  -- Get user ID
  v_user_id := get_user_id(auth.uid());
  
  -- Check admin permission
  IF NOT has_role_for_brand(v_user_id, p_brand_id, 'admin') THEN
    RAISE EXCEPTION 'Permission denied: admin role required';
  END IF;
  
  -- Validate name
  IF p_name IS NULL OR trim(p_name) = '' THEN
    RAISE EXCEPTION 'Stage name cannot be empty';
  END IF;
  
  -- Get max order_index
  SELECT COALESCE(MAX(order_index), -1) INTO v_max_order
  FROM pipeline_stages
  WHERE brand_id = p_brand_id AND is_active = true;
  
  -- Insert new stage
  INSERT INTO pipeline_stages (brand_id, name, color, description, order_index, is_active)
  VALUES (p_brand_id, trim(p_name), p_color, p_description, v_max_order + 1, true)
  RETURNING id INTO v_new_id;
  
  -- Audit log
  INSERT INTO audit_log (brand_id, actor_user_id, entity_type, entity_id, action, new_value)
  VALUES (p_brand_id, v_user_id, 'pipeline_stage', v_new_id, 'created', 
          jsonb_build_object('name', trim(p_name), 'color', p_color));
  
  RETURN v_new_id;
END;
$$;


--
-- Name: create_sales_order_from_deal(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_sales_order_from_deal(p_deal_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_deal RECORD;
  v_order_id UUID;
  v_user_id UUID;
BEGIN
  v_user_id := get_user_id(auth.uid());
  
  -- Get deal info
  SELECT d.*, c.id as cid
  INTO v_deal
  FROM deals d
  JOIN contacts c ON c.id = d.contact_id
  WHERE d.id = p_deal_id;
  
  IF v_deal IS NULL THEN
    RAISE EXCEPTION 'Deal not found';
  END IF;
  
  -- Check if order already exists
  IF EXISTS (SELECT 1 FROM sales_orders WHERE deal_id = p_deal_id) THEN
    RAISE EXCEPTION 'Order already exists for this deal';
  END IF;
  
  -- Check permissions
  IF NOT (
    user_belongs_to_brand(v_user_id, v_deal.brand_id) AND (
      has_role_for_brand(v_user_id, v_deal.brand_id, 'admin') OR
      has_role(v_user_id, 'ceo') OR
      has_role_for_brand(v_user_id, v_deal.brand_id, 'responsabile_venditori') OR
      (has_role_for_brand(v_user_id, v_deal.brand_id, 'venditore') AND 
       v_deal.assigned_user_id = v_user_id)
    )
  ) THEN
    RAISE EXCEPTION 'Permission denied';
  END IF;
  
  -- Create order
  INSERT INTO sales_orders (
    brand_id,
    deal_id,
    contact_id,
    assigned_user_id,
    order_number,
    status
  ) VALUES (
    v_deal.brand_id,
    p_deal_id,
    v_deal.contact_id,
    COALESCE(v_deal.assigned_user_id, v_user_id),
    '' -- Will be auto-generated by trigger
  )
  RETURNING id INTO v_order_id;
  
  -- Log to audit
  INSERT INTO sales_order_history (order_id, action, new_status, changed_by_user_id)
  VALUES (v_order_id, 'created', 'draft', v_user_id);
  
  RETURN v_order_id;
END;
$$;


