--
-- Name: delete_notifications(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_notifications(p_notification_ids uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_count INTEGER;
BEGIN
  SELECT u.id INTO v_user_id FROM public.users u WHERE u.supabase_auth_id = auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  DELETE FROM notifications
  WHERE id = ANY(p_notification_ids)
    AND user_id = v_user_id;

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


--
-- Name: delete_outbound_webhook(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_outbound_webhook(p_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_brand_id uuid;
BEGIN
  -- Get brand_id
  SELECT brand_id INTO v_brand_id FROM outbound_webhooks WHERE id = p_id;
  
  IF v_brand_id IS NULL THEN
    RETURN false;
  END IF;
  
  -- Admin check
  IF NOT has_role_for_brand(get_user_id(auth.uid()), v_brand_id, 'admin') THEN
    RAISE EXCEPTION 'Admin access required';
  END IF;
  
  -- First deactivate
  UPDATE outbound_webhooks SET is_active = false WHERE id = p_id;
  
  -- Delete old deliveries (keep last 7 days)
  DELETE FROM outbound_webhook_deliveries 
  WHERE webhook_id = p_id 
    AND created_at < now() - interval '7 days';
  
  -- Delete webhook
  DELETE FROM outbound_webhooks WHERE id = p_id;
  
  RETURN FOUND;
END;
$$;


--
-- Name: delete_pipeline_stage_permanently(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_pipeline_stage_permanently(p_stage_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_stage_name TEXT;
  v_deal_count INT;
  v_history_count INT;
BEGIN
  v_user_id := get_user_id(auth.uid());
  
  -- Check if user is admin or CEO
  IF NOT (has_role(v_user_id, 'admin'::app_role) OR has_role(v_user_id, 'ceo'::app_role)) THEN
    RAISE EXCEPTION 'Solo admin e CEO possono eliminare fasi pipeline';
  END IF;
  
  -- Get stage name
  SELECT name INTO v_stage_name FROM pipeline_stages WHERE id = p_stage_id;
  
  IF v_stage_name IS NULL THEN
    RAISE EXCEPTION 'Fase non trovata';
  END IF;
  
  -- Check for deals in this stage
  SELECT COUNT(*) INTO v_deal_count
  FROM deals
  WHERE current_stage_id = p_stage_id;
  
  IF v_deal_count > 0 THEN
    RAISE EXCEPTION 'Impossibile eliminare: % deal ancora in questa fase', v_deal_count;
  END IF;
  
  -- Check for stage history
  SELECT COUNT(*) INTO v_history_count
  FROM deal_stage_history
  WHERE from_stage_id = p_stage_id OR to_stage_id = p_stage_id;
  
  IF v_history_count > 0 THEN
    RAISE EXCEPTION 'Impossibile eliminare: % record storici associati a questa fase', v_history_count;
  END IF;
  
  -- Delete the stage
  DELETE FROM pipeline_stages WHERE id = p_stage_id;
  
  RETURN jsonb_build_object(
    'success', true,
    'stage_name', v_stage_name
  );
END;
$$;


--
-- Name: delete_read_notifications(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_read_notifications(p_brand_id uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_count INTEGER;
BEGIN
  SELECT u.id INTO v_user_id FROM public.users u WHERE u.supabase_auth_id = auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  DELETE FROM notifications
  WHERE user_id = v_user_id
    AND read_at IS NOT NULL
    AND (p_brand_id IS NULL OR brand_id = p_brand_id);

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


--
-- Name: detect_anomalies(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.detect_anomalies(p_lookback_hours integer DEFAULT 1) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_metric record;
  v_observed numeric;
  v_z numeric;
  v_severity text;
  v_direction text;
  v_count int := 0;
BEGIN
  FOR v_metric IN
    SELECT b.metric_name, b.mean_value, b.stddev_value
    FROM public.anomaly_baselines b
    WHERE b.stddev_value > 0
  LOOP
    SELECT avg(metric_value) INTO v_observed
    FROM public.capacity_snapshots
    WHERE metric_name = v_metric.metric_name
      AND captured_at > now() - (p_lookback_hours || ' hours')::interval;

    IF v_observed IS NULL THEN CONTINUE; END IF;

    v_z := (v_observed - v_metric.mean_value) / NULLIF(v_metric.stddev_value, 0);
    IF abs(v_z) < 2 THEN CONTINUE; END IF;

    v_severity := CASE WHEN abs(v_z) >= 4 THEN 'critical' WHEN abs(v_z) >= 3 THEN 'warning' ELSE 'info' END;
    v_direction := CASE WHEN v_z > 0 THEN 'spike' ELSE 'drop' END;

    INSERT INTO public.anomaly_detections (metric_name, observed_value, expected_value, z_score, severity, direction)
    VALUES (v_metric.metric_name, v_observed, v_metric.mean_value, v_z, v_severity, v_direction);
    v_count := v_count + 1;
  END LOOP;

  RETURN jsonb_build_object('anomalies_detected', v_count, 'checked_at', now());
END;
$$;


--
-- Name: detect_audit_anomalies(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.detect_audit_anomalies(p_brand_id uuid, p_lookback_hours integer DEFAULT 24) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_since timestamptz;
  v_mass_export jsonb;
  v_mass_delete jsonb;
  v_off_hours jsonb;
BEGIN
  IF NOT public.can_view_audit(auth.uid()) THEN
    RAISE EXCEPTION 'Insufficient permissions';
  END IF;

  v_since := now() - (p_lookback_hours || ' hours')::interval;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'accessed_by', accessed_by,
    'accessed_by_display_name', accessed_by_display_name,
    'result_count', result_count,
    'accessed_at', accessed_at,
    'access_type', access_type
  ) ORDER BY accessed_at DESC), '[]'::jsonb)
  INTO v_mass_export
  FROM (
    SELECT * FROM public.audit_access_log
    WHERE (brand_id = p_brand_id OR brand_id IS NULL)
      AND accessed_at >= v_since
      AND access_type = 'export'
      AND COALESCE(result_count, 0) > 500
    LIMIT 50
  ) s;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'actor_user_id', actor_user_id,
    'actor_display_name', actor_display_name,
    'delete_count', cnt,
    'window_start', window_start
  ) ORDER BY cnt DESC), '[]'::jsonb)
  INTO v_mass_delete
  FROM (
    SELECT
      actor_user_id,
      max(actor_display_name) AS actor_display_name,
      date_trunc('hour', occurred_at) AS window_start,
      count(*)::bigint AS cnt
    FROM public.audit_events
    WHERE brand_id = p_brand_id
      AND occurred_at >= v_since
      AND action = 'delete'
      AND actor_user_id IS NOT NULL
    GROUP BY actor_user_id, date_trunc('hour', occurred_at)
    HAVING count(*) > 20
    LIMIT 50
  ) s;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'actor_user_id', actor_user_id,
    'actor_display_name', actor_display_name,
    'action_count', cnt,
    'sample_at', sample_at
  ) ORDER BY cnt DESC), '[]'::jsonb)
  INTO v_off_hours
  FROM (
    SELECT
      actor_user_id,
      max(actor_display_name) AS actor_display_name,
      count(*)::bigint AS cnt,
      max(occurred_at) AS sample_at
    FROM public.audit_events
    WHERE brand_id = p_brand_id
      AND occurred_at >= v_since
      AND extract(hour from occurred_at) BETWEEN 0 AND 5
      AND actor_user_id IS NOT NULL
      AND actor_type = 'user'
    GROUP BY actor_user_id
    HAVING count(*) >= 5
    LIMIT 50
  ) s;

  RETURN jsonb_build_object(
    'lookback_hours', p_lookback_hours,
    'generated_at', now(),
    'mass_export', v_mass_export,
    'mass_delete', v_mass_delete,
    'off_hours', v_off_hours
  );
END;
$$;


--
-- Name: dynamic_analytics_query(text, text, uuid, timestamp with time zone, timestamp with time zone, text, jsonb, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dynamic_analytics_query(p_dataset text, p_metric text DEFAULT 'count'::text, p_brand_id uuid DEFAULT NULL::uuid, p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_group_by text DEFAULT NULL::text, p_filters jsonb DEFAULT '{}'::jsonb, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result jsonb;
  v_query text;
  v_table text;
  v_date_col text;
  v_select_metric text;
  v_select_group text := '';
  v_join text := '';
  v_where text;
  v_group_clause text := '';
  v_order_clause text := '';
  v_key text;
  v_val jsonb;
  v_allowed_filters text[] := ARRAY[
    'status','priority','source_name','lead_type','outcome',
    'appointment_type','call_type','assigned_user_id','created_by_user_id',
    'contact_id','deal_id','assigned_sales_user_id','lead_valid',
    'category_id','cost_center_id','payment_status','campaign_id',
    'periodicity','is_deductible','is_active','vendor_name',
    'from_stage_label','to_stage_label','channel_id'
  ];
  v_allowed_group_bys text[] := ARRAY[
    'status','priority','source_name','lead_type','outcome',
    'appointment_type','call_type','date','week','month',
    'regione','provincia','city',
    'payment_status','category','campaign_name','product_name',
    'from_stage_label','to_stage_label','vendor_name',
    'periodicity','cost_center','channel'
  ];
BEGIN
  CASE p_dataset
    WHEN 'leads' THEN v_table := 'lead_events'; v_date_col := 'received_at';
    WHEN 'contacts' THEN v_table := 'contacts'; v_date_col := 'created_at';
    WHEN 'deals' THEN v_table := 'deals'; v_date_col := 'created_at';
    WHEN 'tickets' THEN v_table := 'tickets'; v_date_col := 'created_at';
    WHEN 'appointments' THEN v_table := 'appointments'; v_date_col := 'scheduled_at';
    WHEN 'calls' THEN v_table := 'call_logs'; v_date_col := 'started_at';
    WHEN 'expenses' THEN v_table := 'expenses'; v_date_col := 'expense_date';
    WHEN 'budgets' THEN v_table := 'budgets'; v_date_col := 'created_at';
    WHEN 'sales_orders' THEN v_table := 'sales_orders'; v_date_col := 'created_at';
    WHEN 'products' THEN v_table := 'products'; v_date_col := 'created_at';
    WHEN 'marketing_campaigns' THEN v_table := 'marketing_campaigns'; v_date_col := 'created_at';
    WHEN 'deal_transitions' THEN v_table := 'deal_stage_transitions'; v_date_col := 'occurred_at';
    ELSE RAISE EXCEPTION 'Invalid dataset: %', p_dataset;
  END CASE;

  CASE p_metric
    WHEN 'count' THEN v_select_metric := 'count(*)::int as metric_value';
    WHEN 'count_distinct_contacts' THEN v_select_metric := 'count(DISTINCT t.contact_id)::int as metric_value';
    WHEN 'sum_value' THEN v_select_metric := 'coalesce(sum(t.value),0)::numeric as metric_value';
    WHEN 'avg_value' THEN v_select_metric := 'coalesce(round(avg(t.value),2),0)::numeric as metric_value';
    WHEN 'sum_lead_cost' THEN v_select_metric := 'coalesce(sum(c.lead_cost),0)::numeric as metric_value';
    WHEN 'sum_amount' THEN v_select_metric := 'coalesce(sum(t.amount),0)::numeric as metric_value';
    WHEN 'sum_planned_amount' THEN v_select_metric := 'coalesce(sum(t.planned_amount),0)::numeric as metric_value';
    WHEN 'sum_total_amount' THEN v_select_metric := 'coalesce(sum(t.total_amount),0)::numeric as metric_value';
    WHEN 'sum_paid_amount' THEN v_select_metric := 'coalesce(sum(t.paid_amount),0)::numeric as metric_value';
    WHEN 'sum_default_price' THEN v_select_metric := 'coalesce(sum(t.default_price),0)::numeric as metric_value';
    WHEN 'avg_amount' THEN v_select_metric := 'coalesce(round(avg(t.amount),2),0)::numeric as metric_value';
    WHEN 'sum_planned_budget' THEN v_select_metric := 'coalesce(sum(t.planned_budget),0)::numeric as metric_value';
    WHEN 'sum_gross_amount' THEN v_select_metric := 'coalesce(sum(t.gross_amount),0)::numeric as metric_value';
    WHEN 'sum_discount_amount' THEN v_select_metric := 'coalesce(sum(t.discount_amount),0)::numeric as metric_value';
    WHEN 'sum_tax_amount' THEN v_select_metric := 'coalesce(sum(t.tax_amount),0)::numeric as metric_value';
    ELSE RAISE EXCEPTION 'Invalid metric: %', p_metric;
  END CASE;

  -- Build WHERE: if system brand (all-brands mode), skip brand filter
  IF p_brand_id = '00000000-0000-0000-0000-000000000000'::uuid THEN
    v_where := 'true';
  ELSE
    v_where := format('t.brand_id = %L', p_brand_id);
  END IF;

  IF p_date_from IS NOT NULL THEN
    v_where := v_where || format(' AND t.%I >= %L', v_date_col, p_date_from);
  END IF;
  IF p_date_to IS NOT NULL THEN
    v_where := v_where || format(' AND t.%I <= %L', v_date_col, p_date_to);
  END IF;

  FOR v_key, v_val IN SELECT * FROM jsonb_each(p_filters) LOOP
    IF NOT (v_key = ANY(v_allowed_filters)) THEN
      RAISE EXCEPTION 'Invalid filter: %', v_key;
    END IF;
    IF jsonb_typeof(v_val) = 'array' THEN
      v_where := v_where || format(' AND t.%I::text = ANY(ARRAY(SELECT jsonb_array_elements_text(%L)))', v_key, v_val);
    ELSE
      v_where := v_where || format(' AND t.%I::text = %L', v_key, v_val #>> '{}');
    END IF;
  END LOOP;

  IF p_group_by IS NOT NULL THEN
    IF NOT (p_group_by = ANY(v_allowed_group_bys)) THEN
      RAISE EXCEPTION 'Invalid group_by: %', p_group_by;
    END IF;

    CASE p_group_by
      WHEN 'date' THEN
        v_select_group := format('t.%I::date as group_key', v_date_col);
        v_group_clause := format('GROUP BY t.%I::date', v_date_col);
        v_order_clause := format('ORDER BY t.%I::date', v_date_col);
      WHEN 'week' THEN
        v_select_group := format('date_trunc(''week'', t.%I)::date as group_key', v_date_col);
        v_group_clause := format('GROUP BY date_trunc(''week'', t.%I)', v_date_col);
        v_order_clause := format('ORDER BY date_trunc(''week'', t.%I)', v_date_col);
      WHEN 'month' THEN
        v_select_group := format('to_char(t.%I, ''YYYY-MM'') as group_key', v_date_col);
        v_group_clause := format('GROUP BY to_char(t.%I, ''YYYY-MM'')', v_date_col);
        v_order_clause := format('ORDER BY to_char(t.%I, ''YYYY-MM'')', v_date_col);
      WHEN 'regione' THEN
        v_join := 'LEFT JOIN contacts c ON c.id = t.contact_id';
        v_select_group := 'COALESCE(c.province, ''N/D'') as group_key';
        v_group_clause := 'GROUP BY c.province';
        v_order_clause := 'ORDER BY metric_value DESC';
      WHEN 'provincia' THEN
        v_join := 'LEFT JOIN contacts c ON c.id = t.contact_id';
        v_select_group := 'COALESCE(c.province, ''N/D'') as group_key';
        v_group_clause := 'GROUP BY c.province';
        v_order_clause := 'ORDER BY metric_value DESC';
      WHEN 'city' THEN
        v_join := 'LEFT JOIN contacts c ON c.id = t.contact_id';
        v_select_group := 'COALESCE(c.city, ''N/D'') as group_key';
        v_group_clause := 'GROUP BY c.city';
        v_order_clause := 'ORDER BY metric_value DESC';
      WHEN 'category' THEN
        v_join := 'LEFT JOIN expense_categories ec ON ec.id = t.category_id';
        v_select_group := 'COALESCE(ec.name, ''Non categorizzata'') as group_key';
        v_group_clause := 'GROUP BY ec.name';
        v_order_clause := 'ORDER BY metric_value DESC';
      WHEN 'cost_center' THEN
        v_join := 'LEFT JOIN cost_centers cc ON cc.id = t.cost_center_id';
        v_select_group := 'COALESCE(cc.name, ''Non assegnato'') as group_key';
        v_group_clause := 'GROUP BY cc.name';
        v_order_clause := 'ORDER BY metric_value DESC';
      WHEN 'campaign_name' THEN
        -- For leads dataset, use source_name instead of campaign_id join (lead_events has no campaign_id)
        IF p_dataset = 'leads' THEN
          v_select_group := 'COALESCE(t.source_name, ''Sorgente sconosciuta'') as group_key';
          v_group_clause := 'GROUP BY t.source_name';
        ELSE
          v_join := 'LEFT JOIN marketing_campaigns mc ON mc.id = t.campaign_id';
          v_select_group := 'COALESCE(mc.name, ''Nessuna campagna'') as group_key';
          v_group_clause := 'GROUP BY mc.name';
        END IF;
        v_order_clause := 'ORDER BY metric_value DESC';
      WHEN 'product_name' THEN
        v_join := 'LEFT JOIN products p ON p.id = t.product_id';
        v_select_group := 'COALESCE(p.name, ''Nessun prodotto'') as group_key';
        v_group_clause := 'GROUP BY p.name';
        v_order_clause := 'ORDER BY metric_value DESC';
      WHEN 'channel' THEN
        v_join := 'LEFT JOIN marketing_channels mch ON mch.id = t.channel_id';
        v_select_group := 'COALESCE(mch.name, ''Nessun canale'') as group_key';
        v_group_clause := 'GROUP BY mch.name';
        v_order_clause := 'ORDER BY metric_value DESC';
      ELSE
        v_select_group := format('t.%I::text as group_key', p_group_by);
        v_group_clause := format('GROUP BY t.%I', p_group_by);
        v_order_clause := 'ORDER BY metric_value DESC';
    END CASE;
  END IF;

  IF p_group_by IS NOT NULL THEN
    v_query := format(
      'SELECT %s, %s FROM %I t %s WHERE %s %s %s LIMIT %s',
      v_select_group, v_select_metric, v_table, v_join, v_where,
      v_group_clause, v_order_clause, p_limit
    );
  ELSE
    v_query := format(
      'SELECT %s FROM %I t %s WHERE %s',
      v_select_metric, v_table, v_join, v_where
    );
  END IF;

  EXECUTE format('SELECT jsonb_agg(row_to_json(sub)) FROM (%s) sub', v_query) INTO v_result;
  RETURN COALESCE(v_result, '[]'::jsonb);
END;
$$;


--
-- Name: e2e_revenue_snapshot(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.e2e_revenue_snapshot(p_phone text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_contact_id UUID;
  v_contact_count INT;
  v_lead_event_count INT;
  v_phone_count INT;
  v_normalized TEXT;
  v_deal_count INT;
  v_appointment_count INT;
  v_recent_stage_transitions INT;
  v_latest_deal_stage TEXT;
  v_recent_outcomes INT;
BEGIN
  v_normalized := regexp_replace(p_phone, '\D', '', 'g');

  SELECT contact_id INTO v_contact_id
  FROM contact_phones
  WHERE regexp_replace(phone, '\D', '', 'g') = v_normalized
     OR regexp_replace(phone, '\D', '', 'g') = right(v_normalized, 10)
  ORDER BY created_at DESC
  LIMIT 1;

  SELECT COUNT(*) INTO v_phone_count
  FROM contact_phones
  WHERE regexp_replace(phone, '\D', '', 'g') = v_normalized
     OR regexp_replace(phone, '\D', '', 'g') = right(v_normalized, 10);

  v_contact_count := CASE WHEN v_contact_id IS NOT NULL THEN 1 ELSE 0 END;

  SELECT COUNT(*) INTO v_lead_event_count
  FROM lead_events
  WHERE contact_id = v_contact_id
    AND created_at > now() - interval '5 minutes';

  IF v_contact_id IS NOT NULL THEN
    SELECT COUNT(*) INTO v_deal_count
    FROM deals
    WHERE contact_id = v_contact_id;

    SELECT ps.name INTO v_latest_deal_stage
    FROM deals d
    LEFT JOIN pipeline_stages ps ON ps.id = d.stage_id
    WHERE d.contact_id = v_contact_id
    ORDER BY d.updated_at DESC NULLS LAST
    LIMIT 1;

    SELECT COUNT(*) INTO v_recent_stage_transitions
    FROM deal_stage_transitions dst
    WHERE dst.deal_id IN (SELECT id FROM deals WHERE contact_id = v_contact_id)
      AND dst.created_at > now() - interval '10 minutes';

    SELECT COUNT(*) INTO v_appointment_count
    FROM appointments
    WHERE contact_id = v_contact_id;

    SELECT COUNT(*) INTO v_recent_outcomes
    FROM appointment_outcomes ao
    WHERE ao.appointment_id IN (
      SELECT id FROM appointments WHERE contact_id = v_contact_id
    )
    AND ao.recorded_at > now() - interval '10 minutes';
  ELSE
    v_deal_count := 0;
    v_appointment_count := 0;
    v_recent_stage_transitions := 0;
    v_recent_outcomes := 0;
  END IF;

  RETURN jsonb_build_object(
    'phone_normalized', v_normalized,
    'contact_id', v_contact_id,
    'contact_found', v_contact_count > 0,
    'phone_rows', v_phone_count,
    'recent_lead_events', v_lead_event_count,
    'deals', jsonb_build_object(
      'total', v_deal_count,
      'latest_stage_name', v_latest_deal_stage,
      'recent_stage_transitions_10min', v_recent_stage_transitions
    ),
    'appointments', jsonb_build_object(
      'total', v_appointment_count,
      'recent_outcomes_10min', v_recent_outcomes
    ),
    'snapshot_at', now()
  );
END;
$$;


--
-- Name: emit_appointment_webhook(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.emit_appointment_webhook() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_payload JSONB;
  v_event_type TEXT;
  v_appointment_snapshot JSONB;
  v_sales_user_name TEXT;
BEGIN
  -- Get sales user name
  IF NEW.assigned_sales_user_id IS NOT NULL THEN
    SELECT full_name INTO v_sales_user_name FROM users WHERE id = NEW.assigned_sales_user_id;
  END IF;
  
  v_appointment_snapshot := jsonb_build_object(
    'id', NEW.id,
    'scheduled_at', NEW.scheduled_at,
    'duration_minutes', NEW.duration_minutes,
    'status', NEW.status,
    'appointment_type', NEW.appointment_type,
    'appointment_order', NEW.appointment_order,
    'address', NEW.address,
    'city', NEW.city,
    'cap', NEW.cap,
    'notes', NEW.notes,
    'assigned_sales_user_id', NEW.assigned_sales_user_id,
    'assigned_sales_user_name', v_sales_user_name,
    'parent_appointment_id', NEW.parent_appointment_id
  );
  
  IF TG_OP = 'INSERT' THEN
    v_event_type := 'appointment.created';
  ELSE
    v_event_type := 'appointment.updated';
  END IF;
  
  v_payload := build_webhook_payload_v1(
    p_event_type := v_event_type,
    p_brand_id := NEW.brand_id,
    p_event_id := NEW.id,
    p_occurred_at := CASE WHEN TG_OP = 'INSERT' THEN NEW.created_at ELSE NEW.updated_at END,
    p_refs := jsonb_build_object(
      'appointment_id', NEW.id,
      'contact_id', NEW.contact_id,
      'deal_id', NEW.deal_id
    ),
    p_contact_id := NEW.contact_id,
    p_deal_id := NEW.deal_id,
    p_appointment_snapshot := v_appointment_snapshot,
    p_old_data := CASE WHEN TG_OP = 'UPDATE' THEN jsonb_build_object(
      'status', OLD.status,
      'scheduled_at', OLD.scheduled_at,
      'assigned_sales_user_id', OLD.assigned_sales_user_id
    ) ELSE NULL END,
    p_new_data := CASE WHEN TG_OP = 'UPDATE' THEN jsonb_build_object(
      'status', NEW.status,
      'scheduled_at', NEW.scheduled_at,
      'assigned_sales_user_id', NEW.assigned_sales_user_id
    ) ELSE NULL END
  );
  
  PERFORM enqueue_webhook_delivery(
    NEW.brand_id,
    v_event_type::webhook_event_type,
    NEW.id,
    v_payload
  );
  
  RETURN NEW;
END;
$$;


--
-- Name: emit_lead_event_created(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.emit_lead_event_created() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_payload JSONB;
  v_event_snapshot JSONB;
BEGIN
  -- Skip duplicates and opted-out contacts
  IF NEW.archived THEN
    RETURN NEW;
  END IF;

  -- Build event snapshot with ALL relevant fields
  v_event_snapshot := jsonb_build_object(
    'id', NEW.id,
    'source', NEW.source,
    'source_name', NEW.source_name,
    'occurred_at', NEW.occurred_at,
    'received_at', NEW.received_at,
    'ai_priority', NEW.ai_priority,
    'lead_type', NEW.lead_type,
    'lead_source_channel', NEW.lead_source_channel,
    'contact_channel', NEW.contact_channel,
    'pacemaker_status', NEW.pacemaker_status,
    'customer_sentiment', NEW.customer_sentiment,
    'decision_status', NEW.decision_status,
    'objection_type', NEW.objection_type,
    'booking_notes', NEW.booking_notes,
    'logistics_notes', NEW.logistics_notes,
    'ai_conversation_summary', NEW.ai_conversation_summary,
    'raw_payload', NEW.raw_payload,
    'archived', NEW.archived
  );
  
  -- Build v1 payload
  v_payload := build_webhook_payload_v1(
    p_event_type := 'lead_event.created',
    p_brand_id := NEW.brand_id,
    p_event_id := NEW.id,
    p_occurred_at := NEW.occurred_at,
    p_refs := jsonb_build_object(
      'lead_event_id', NEW.id,
      'contact_id', NEW.contact_id,
      'deal_id', NEW.deal_id
    ),
    p_contact_id := NEW.contact_id,
    p_deal_id := NEW.deal_id,
    p_lead_event_id := NEW.id,
    p_event_snapshot := v_event_snapshot
  );
  
  -- Enqueue delivery
  PERFORM enqueue_webhook_delivery(
    NEW.brand_id,
    'lead_event.created'::webhook_event_type,
    NEW.id,
    v_payload
  );
  
  RETURN NEW;
END;
$$;


--
-- Name: emit_pipeline_stage_changed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.emit_pipeline_stage_changed() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_deal deals%ROWTYPE;
  v_from_stage pipeline_stages%ROWTYPE;
  v_to_stage pipeline_stages%ROWTYPE;
  v_payload JSONB;
  v_stage_snapshot JSONB;
BEGIN
  -- Get deal info
  SELECT * INTO v_deal FROM deals WHERE id = NEW.deal_id;
  IF NOT FOUND THEN
    RETURN NEW;
  END IF;
  
  -- Get stage names
  IF NEW.from_stage_id IS NOT NULL THEN
    SELECT * INTO v_from_stage FROM pipeline_stages WHERE id = NEW.from_stage_id;
  END IF;
  SELECT * INTO v_to_stage FROM pipeline_stages WHERE id = NEW.to_stage_id;
  
  v_stage_snapshot := jsonb_build_object(
    'from_stage_id', NEW.from_stage_id,
    'from_stage_name', v_from_stage.name,
    'to_stage_id', NEW.to_stage_id,
    'to_stage_name', v_to_stage.name,
    'changed_by_user_id', NEW.changed_by,
    'changed_at', NEW.changed_at,
    'notes', NEW.notes
  );
  
  v_payload := build_webhook_payload_v1(
    p_event_type := 'pipeline.stage_changed',
    p_brand_id := v_deal.brand_id,
    p_event_id := NEW.id,
    p_occurred_at := NEW.changed_at,
    p_refs := jsonb_build_object(
      'deal_id', NEW.deal_id,
      'contact_id', v_deal.contact_id,
      'history_id', NEW.id
    ),
    p_contact_id := v_deal.contact_id,
    p_deal_id := NEW.deal_id,
    p_stage_snapshot := v_stage_snapshot
  );
  
  PERFORM enqueue_webhook_delivery(
    v_deal.brand_id,
    'pipeline.stage_changed'::webhook_event_type,
    NEW.id,
    v_payload
  );
  
  RETURN NEW;
END;
$$;


--
-- Name: emit_sale_recorded(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.emit_sale_recorded() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_payload JSONB;
  v_sale_snapshot JSONB;
  v_stage_name TEXT;
BEGIN
  -- Only emit when status changes to 'won'
  IF TG_OP = 'UPDATE' AND NEW.status = 'won' AND OLD.status != 'won' THEN
    IF NEW.current_stage_id IS NOT NULL THEN
      SELECT name INTO v_stage_name FROM pipeline_stages WHERE id = NEW.current_stage_id;
    END IF;
    
    v_sale_snapshot := jsonb_build_object(
      'deal_id', NEW.id,
      'value', NEW.value,
      'closed_at', NEW.closed_at,
      'final_stage_id', NEW.current_stage_id,
      'final_stage_name', v_stage_name,
      'notes', NEW.notes
    );
    
    v_payload := build_webhook_payload_v1(
      p_event_type := 'sale.recorded',
      p_brand_id := NEW.brand_id,
      p_event_id := NEW.id,
      p_occurred_at := COALESCE(NEW.closed_at, now()),
      p_refs := jsonb_build_object(
        'deal_id', NEW.id,
        'contact_id', NEW.contact_id
      ),
      p_contact_id := NEW.contact_id,
      p_deal_id := NEW.id,
      p_sale_snapshot := v_sale_snapshot
    );
    
    PERFORM enqueue_webhook_delivery(
      NEW.brand_id,
      'sale.recorded'::webhook_event_type,
      NEW.id,
      v_payload
    );
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: emit_tags_updated(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.emit_tags_updated() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_payload JSONB;
  v_entity_type TEXT;
  v_entity_id UUID;
  v_contact_id UUID;
  v_deal_id UUID;
BEGIN
  -- Determine entity type and ID
  IF TG_OP = 'DELETE' THEN
    v_entity_id := COALESCE(OLD.contact_id, OLD.deal_id, OLD.lead_event_id);
    v_contact_id := OLD.contact_id;
    v_deal_id := OLD.deal_id;
    
    IF OLD.contact_id IS NOT NULL THEN v_entity_type := 'contact';
    ELSIF OLD.deal_id IS NOT NULL THEN v_entity_type := 'deal';
    ELSIF OLD.lead_event_id IS NOT NULL THEN v_entity_type := 'lead_event';
    END IF;
    
    v_payload := build_webhook_payload_v1(
      p_event_type := 'tags.updated',
      p_brand_id := OLD.brand_id,
      p_event_id := OLD.id,
      p_occurred_at := now(),
      p_refs := jsonb_build_object(
        'entity_type', v_entity_type,
        'entity_id', v_entity_id,
        'tag_id', OLD.tag_id,
        'action', 'removed'
      ),
      p_contact_id := v_contact_id,
      p_deal_id := v_deal_id
    );
    
    PERFORM enqueue_webhook_delivery(
      OLD.brand_id,
      'tags.updated'::webhook_event_type,
      OLD.id,
      v_payload
    );
    
    RETURN OLD;
  ELSE
    v_entity_id := COALESCE(NEW.contact_id, NEW.deal_id, NEW.lead_event_id);
    v_contact_id := NEW.contact_id;
    v_deal_id := NEW.deal_id;
    
    IF NEW.contact_id IS NOT NULL THEN v_entity_type := 'contact';
    ELSIF NEW.deal_id IS NOT NULL THEN v_entity_type := 'deal';
    ELSIF NEW.lead_event_id IS NOT NULL THEN v_entity_type := 'lead_event';
    END IF;
    
    v_payload := build_webhook_payload_v1(
      p_event_type := 'tags.updated',
      p_brand_id := NEW.brand_id,
      p_event_id := NEW.id,
      p_occurred_at := NEW.assigned_at,
      p_refs := jsonb_build_object(
        'entity_type', v_entity_type,
        'entity_id', v_entity_id,
        'tag_id', NEW.tag_id,
        'action', 'added'
      ),
      p_contact_id := v_contact_id,
      p_deal_id := v_deal_id
    );
    
    PERFORM enqueue_webhook_delivery(
      NEW.brand_id,
      'tags.updated'::webhook_event_type,
      NEW.id,
      v_payload
    );
    
    RETURN NEW;
  END IF;
END;
$$;


--
-- Name: emit_ticket_webhook_from_audit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.emit_ticket_webhook_from_audit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_event_type webhook_event_type;
  v_payload jsonb;
  v_enqueued int;
BEGIN
  -- Map audit action_type to webhook event_type
  CASE NEW.action_type
    WHEN 'created' THEN v_event_type := 'ticket.created';
    WHEN 'status_change' THEN v_event_type := 'ticket.status_changed';
    WHEN 'assignment_change' THEN v_event_type := 'ticket.assigned';
    WHEN 'priority_change' THEN v_event_type := 'ticket.priority_changed';
    WHEN 'category_change' THEN v_event_type := 'ticket.updated';
    WHEN 'sla_breach' THEN v_event_type := 'ticket.sla_breached';
    ELSE 
      -- Ignore unmapped events (e.g., comment_added)
      RETURN NEW;
  END CASE;

  -- Build standardized payload (schema v1)
  v_payload := jsonb_build_object(
    'schema_version', 1,
    'event_type', v_event_type::text,
    'event_id', NEW.id,
    'occurred_at', NEW.created_at,
    'brand_id', NEW.brand_id,
    'ticket_id', NEW.ticket_id,
    'actor_user_id', NEW.user_id,
    'data', jsonb_build_object(
      'old', COALESCE(NEW.old_value, '{}'::jsonb),
      'new', COALESCE(NEW.new_value, '{}'::jsonb),
      'metadata', COALESCE(NEW.metadata, '{}'::jsonb)
    )
  );

  -- Enqueue to all matching webhooks (fan-out)
  SELECT enqueue_webhook_delivery(
    NEW.brand_id,
    v_event_type,
    NEW.id,  -- event_id = audit log id (idempotency key)
    v_payload
  ) INTO v_enqueued;

  RETURN NEW;
END;
$$;


--
-- Name: enqueue_ai_classification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_ai_classification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Skip duplicates and opted-out contacts
  IF NEW.archived THEN
    RETURN NEW;
  END IF;

  -- Create a job for AI classification
  INSERT INTO public.ai_jobs (brand_id, lead_event_id)
  VALUES (NEW.brand_id, NEW.id)
  ON CONFLICT (lead_event_id) DO NOTHING;
  
  RETURN NEW;
END;
$$;


--
-- Name: enqueue_audit_alert_deliveries(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_audit_alert_deliveries() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _channel RECORD;
BEGIN
  FOR _channel IN
    SELECT id, brand_id, anomaly_types
    FROM public.audit_alert_channels
    WHERE is_active = true
      AND (brand_id = NEW.brand_id OR brand_id = '00000000-0000-0000-0000-000000000000'::uuid)
      AND public.severity_meets_threshold(NEW.severity, min_severity)
      AND (cardinality(anomaly_types) = 0 OR NEW.anomaly_type = ANY(anomaly_types))
  LOOP
    INSERT INTO public.audit_alert_deliveries (channel_id, anomaly_id, brand_id, status)
    VALUES (_channel.id, NEW.id, NEW.brand_id, 'pending');
  END LOOP;

  PERFORM pg_notify('audit_alert_dispatch', NEW.id::text);
  RETURN NEW;
END;
$$;


--
-- Name: enqueue_email(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_email(queue_name text, payload jsonb) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN pgmq.send(queue_name, payload);
EXCEPTION WHEN undefined_table THEN
  PERFORM pgmq.create(queue_name);
  RETURN pgmq.send(queue_name, payload);
END;
$$;


--
-- Name: enqueue_payment_overdue_notifications(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_payment_overdue_notifications(p_brand_id uuid DEFAULT NULL::uuid) RETURNS TABLE(notifications_created integer, brands_processed integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_created integer := 0;
  v_brands integer := 0;
  v_brand record;
  v_row record;
  v_recipient uuid;
BEGIN
  FOR v_brand IN
    SELECT id FROM public.brands
    WHERE (p_brand_id IS NULL OR id = p_brand_id)
  LOOP
    v_brands := v_brands + 1;

    FOR v_row IN
      SELECT * FROM public.get_overdue_installments(v_brand.id, 0)
      WHERE status = 'overdue' AND days_overdue >= 1
    LOOP
      -- destinatario: assigned_user, fallback admin del brand
      v_recipient := v_row.assigned_user_id;
      IF v_recipient IS NULL THEN
        SELECT ur.user_id INTO v_recipient
        FROM public.user_roles ur
        WHERE ur.brand_id = v_brand.id
          AND ur.role IN ('admin', 'responsabile_venditori')
        LIMIT 1;
      END IF;

      IF v_recipient IS NULL THEN CONTINUE; END IF;

      -- Dedup: niente notifica se ne esiste già una nelle ultime 24h per la stessa rata
      IF EXISTS (
        SELECT 1 FROM public.notifications n
        WHERE n.user_id = v_recipient
          AND n.type = 'payment_overdue'
          AND n.entity_id = v_row.order_id
          AND n.body LIKE '%rata #' || (v_row.installment_index + 1) || '%'
          AND n.created_at > NOW() - INTERVAL '24 hours'
      ) THEN
        CONTINUE;
      END IF;

      INSERT INTO public.notifications (
        brand_id, user_id, type, title, body, entity_type, entity_id
      ) VALUES (
        v_brand.id,
        v_recipient,
        'payment_overdue',
        'Rata in ritardo: ' || v_row.contact_name,
        'Ordine ' || v_row.order_number || ' • rata #' || (v_row.installment_index + 1)
          || ' di ' || to_char(v_row.installment_amount, 'FM999G999D00') || '€'
          || ' scaduta il ' || to_char(v_row.due_date, 'DD/MM/YYYY')
          || ' (' || v_row.days_overdue || ' giorni di ritardo)',
        'sales_order',
        v_row.order_id
      );
      v_created := v_created + 1;
    END LOOP;
  END LOOP;

  RETURN QUERY SELECT v_created, v_brands;
END;
$$;


--
-- Name: enqueue_webhook_delivery(uuid, public.webhook_event_type, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_webhook_delivery(p_brand_id uuid, p_event_type public.webhook_event_type, p_event_id uuid, p_payload jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_webhook RECORD;
  v_count INTEGER := 0;
BEGIN
  -- Find all active webhooks for this brand that subscribe to this event type
  FOR v_webhook IN
    SELECT id, brand_id
    FROM outbound_webhooks
    WHERE brand_id = p_brand_id
      AND is_active = true
      AND p_event_type = ANY(event_types)
  LOOP
    -- Insert delivery (idempotency handled by unique index)
    INSERT INTO outbound_webhook_deliveries (
      webhook_id, brand_id, event_type, event_id, payload, status, next_attempt_at
    ) VALUES (
      v_webhook.id, p_brand_id, p_event_type, p_event_id, p_payload, 'pending', now()
    )
    ON CONFLICT (webhook_id, event_id) DO NOTHING;
    
    IF FOUND THEN
      v_count := v_count + 1;
    END IF;
  END LOOP;
  
  RETURN v_count;
END;
$$;


--
-- Name: escalate_all_brands_breached_tickets(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.escalate_all_brands_breached_tickets() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_brand RECORD;
  v_brand_result jsonb;
  v_total integer := 0;
  v_results jsonb := '[]'::jsonb;
BEGIN
  FOR v_brand IN
    SELECT id, name FROM brands LIMIT 500
  LOOP
    v_brand_result := escalate_breached_tickets(v_brand.id);
    IF (v_brand_result->>'escalated_count')::int > 0 THEN
      v_total := v_total + (v_brand_result->>'escalated_count')::int;
      v_results := v_results || jsonb_build_object(
        'brand_id', v_brand.id,
        'brand_name', v_brand.name,
        'escalated_count', v_brand_result->>'escalated_count'
      );
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'total_escalated', v_total,
    'brands', v_results,
    'checked_at', now()
  );
END;
$$;


--
-- Name: escalate_breached_tickets(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.escalate_breached_tickets(p_brand_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ticket RECORD;
  v_target_level integer;
  v_minutes_since_breach numeric;
  v_escalated_count integer := 0;
  v_manager_user_id uuid;
  v_target_roles app_role[];
  v_results jsonb := '[]'::jsonb;
  v_policy public.ticket_escalation_policies;
BEGIN
  -- Resolve policy once per brand
  SELECT * INTO v_policy FROM public.get_ticket_escalation_policy(p_brand_id);

  -- Hard fallback if no policy at all (shouldn't happen, default seeded)
  IF v_policy.id IS NULL THEN
    v_policy.level_1_minutes := 30;
    v_policy.level_2_minutes := 120;
    v_policy.level_3_minutes := 480;
    v_policy.level_1_roles := ARRAY['responsabile_callcenter','admin']::app_role[];
    v_policy.level_2_roles := ARRAY['responsabile_callcenter','responsabile_venditori','admin']::app_role[];
    v_policy.level_3_roles := ARRAY['admin','ceo']::app_role[];
  END IF;

  FOR v_ticket IN
    SELECT t.id, t.priority, t.opened_at, t.sla_breached_at,
           t.escalation_level, t.assigned_to_user_id
    FROM tickets t
    WHERE t.brand_id = p_brand_id
      AND t.status IN ('open', 'in_progress', 'reopened')
      AND t.sla_breached_at IS NOT NULL
    LIMIT 500
  LOOP
    v_minutes_since_breach := EXTRACT(EPOCH FROM (now() - v_ticket.sla_breached_at)) / 60;

    v_target_level := CASE
      WHEN v_minutes_since_breach >= v_policy.level_3_minutes THEN 3
      WHEN v_minutes_since_breach >= v_policy.level_2_minutes THEN 2
      WHEN v_minutes_since_breach >= v_policy.level_1_minutes THEN 1
      ELSE 0
    END;

    IF v_target_level <= v_ticket.escalation_level THEN
      CONTINUE;
    END IF;

    -- Roles for this level
    v_target_roles := CASE v_target_level
      WHEN 1 THEN v_policy.level_1_roles
      WHEN 2 THEN v_policy.level_2_roles
      WHEN 3 THEN v_policy.level_3_roles
    END;

    -- Find a recipient honouring the role priority order in the array
    SELECT ur.user_id INTO v_manager_user_id
    FROM user_roles ur
    JOIN users u ON u.id = ur.user_id AND u.is_active = true
    WHERE ur.brand_id = p_brand_id
      AND ur.role = ANY(v_target_roles)
    ORDER BY array_position(v_target_roles, ur.role) NULLS LAST,
             ur.created_at ASC
    LIMIT 1;

    -- Fallback: cross-brand admin/ceo if nothing found in this brand
    IF v_manager_user_id IS NULL THEN
      SELECT ur.user_id INTO v_manager_user_id
      FROM user_roles ur
      JOIN users u ON u.id = ur.user_id AND u.is_active = true
      WHERE ur.role IN ('admin','ceo')
      ORDER BY CASE ur.role WHEN 'admin' THEN 1 WHEN 'ceo' THEN 2 END
      LIMIT 1;
    END IF;

    UPDATE tickets
    SET escalation_level = v_target_level,
        escalated_at = now(),
        escalated_to_user_id = v_manager_user_id
    WHERE id = v_ticket.id;

    INSERT INTO ticket_audit_logs (brand_id, ticket_id, action_type, new_value, metadata)
    VALUES (
      p_brand_id,
      v_ticket.id,
      'sla_escalation',
      jsonb_build_object('escalation_level', v_target_level),
      jsonb_build_object(
        'previous_level', v_ticket.escalation_level,
        'minutes_since_breach', ROUND(v_minutes_since_breach),
        'escalated_to_user_id', v_manager_user_id,
        'priority', v_ticket.priority,
        'policy_id', v_policy.id,
        'target_roles', to_jsonb(v_target_roles)
      )
    );

    IF v_manager_user_id IS NOT NULL THEN
      INSERT INTO notifications (brand_id, user_id, type, title, body, entity_type, entity_id)
      VALUES (
        p_brand_id,
        v_manager_user_id,
        'ticket_escalated',
        format('Escalation L%s ticket SLA breached', v_target_level),
        format('Ticket in breach SLA da %s minuti — richiede intervento immediato',
               ROUND(v_minutes_since_breach)),
        'ticket',
        v_ticket.id
      );

      INSERT INTO action_suggestions (
        brand_id, user_id, entity_type, entity_id,
        suggestion_type, title, description, priority, confidence,
        metadata, expires_at
      )
      VALUES (
        p_brand_id,
        v_manager_user_id,
        'ticket',
        v_ticket.id,
        'escalate',
        format('Escalation ticket L%s', v_target_level),
        format('SLA breach da %s minuti. Riassegna o intervieni.',
               ROUND(v_minutes_since_breach)),
        CASE v_target_level WHEN 3 THEN 1 WHEN 2 THEN 2 ELSE 3 END,
        0.95,
        jsonb_build_object(
          'escalation_level', v_target_level,
          'minutes_since_breach', ROUND(v_minutes_since_breach),
          'policy_id', v_policy.id
        ),
        now() + interval '24 hours'
      );
    END IF;

    v_escalated_count := v_escalated_count + 1;
    v_results := v_results || jsonb_build_object(
      'ticket_id', v_ticket.id,
      'level', v_target_level,
      'minutes_since_breach', ROUND(v_minutes_since_breach),
      'recipient_user_id', v_manager_user_id
    );
  END LOOP;

  RETURN jsonb_build_object(
    'brand_id', p_brand_id,
    'policy_id', v_policy.id,
    'escalated_count', v_escalated_count,
    'tickets', v_results,
    'checked_at', now()
  );
END;
$$;


--
-- Name: find_meta_app_by_slug(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.find_meta_app_by_slug(p_brand_slug text) RETURNS TABLE(id uuid, brand_id uuid, brand_slug text, verify_token text, app_secret text, page_id text, access_token text, is_active boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT 
    ma.id,
    ma.brand_id,
    ma.brand_slug,
    ma.verify_token,
    ma.app_secret,
    ma.page_id,
    ma.access_token,
    ma.is_active
  FROM public.meta_apps ma
  WHERE ma.brand_slug = p_brand_slug
  LIMIT 1;
$$;


--
-- Name: find_meta_lead_source(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.find_meta_lead_source(p_page_id text, p_form_id text DEFAULT NULL::text) RETURNS TABLE(source_id uuid, brand_id uuid, access_token text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    mls.id AS source_id,
    mls.brand_id,
    mls.access_token
  FROM meta_lead_sources mls
  WHERE mls.page_id = p_page_id
    AND mls.is_active = true
    AND (
      -- Match specific form_id if provided
      (p_form_id IS NOT NULL AND mls.form_id = p_form_id)
      OR
      -- Or match source with no form_id filter (catches all forms)
      (mls.form_id IS NULL)
    )
  ORDER BY 
    -- Prefer specific form_id match over catch-all
    CASE WHEN mls.form_id IS NOT NULL THEN 0 ELSE 1 END
  LIMIT 1;
END;
$$;


--
-- Name: find_or_create_contact(uuid, text, text, text, boolean, text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.find_or_create_contact(p_brand_id uuid, p_phone_normalized text, p_phone_raw text, p_country_code text, p_assumed_country boolean, p_first_name text DEFAULT NULL::text, p_last_name text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_cap text DEFAULT NULL::text, p_lead_message text DEFAULT NULL::text, p_address text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_contact_id uuid;
BEGIN
  -- Try to find existing contact by normalized phone in contact_phones table
  SELECT cp.contact_id INTO v_contact_id
  FROM public.contact_phones cp
  WHERE cp.brand_id = p_brand_id
    AND cp.phone_normalized = p_phone_normalized
    AND cp.is_active = true
  LIMIT 1;
  
  IF v_contact_id IS NOT NULL THEN
    -- Update existing contact with new data if provided (don't overwrite with nulls)
    UPDATE public.contacts
    SET
      first_name = COALESCE(NULLIF(p_first_name, ''), first_name),
      last_name = COALESCE(NULLIF(p_last_name, ''), last_name),
      email = COALESCE(NULLIF(p_email, ''), email),
      city = COALESCE(NULLIF(p_city, ''), city),
      cap = COALESCE(NULLIF(p_cap, ''), cap),
      address = COALESCE(NULLIF(p_address, ''), address),
      lead_message = COALESCE(NULLIF(p_lead_message, ''), lead_message),
      updated_at = now()
    WHERE id = v_contact_id;
    
    RETURN v_contact_id;
  END IF;
  
  -- Create new contact
  INSERT INTO public.contacts (
    brand_id,
    first_name,
    last_name,
    email,
    city,
    cap,
    address,
    lead_message
  ) VALUES (
    p_brand_id,
    p_first_name,
    p_last_name,
    p_email,
    p_city,
    p_cap,
    p_address,
    p_lead_message
  )
  RETURNING id INTO v_contact_id;
  
  -- Create phone record in contact_phones table
  INSERT INTO public.contact_phones (
    brand_id,
    contact_id,
    phone_raw,
    phone_normalized,
    country_code,
    assumed_country,
    is_primary,
    is_active
  ) VALUES (
    p_brand_id,
    v_contact_id,
    p_phone_raw,
    p_phone_normalized,
    p_country_code,
    p_assumed_country,
    true,
    true
  );
  
  RETURN v_contact_id;
END;
$$;


--
-- Name: find_or_create_deal(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.find_or_create_deal(p_brand_id uuid, p_contact_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_deal_id UUID;
  v_initial_stage_id UUID;
BEGIN
  -- 1. Trova lo stage iniziale GLOBALE (brand_id IS NULL)
  SELECT id INTO v_initial_stage_id
  FROM public.pipeline_stages
  WHERE brand_id IS NULL 
    AND is_active = true
  ORDER BY order_index ASC
  LIMIT 1;

  -- 2. Prova INSERT con ON CONFLICT (sfrutta indice parziale)
  INSERT INTO public.deals (brand_id, contact_id, current_stage_id, status)
  VALUES (p_brand_id, p_contact_id, v_initial_stage_id, 'open')
  ON CONFLICT (brand_id, contact_id) WHERE status IN ('open', 'reopened_for_support')
  DO NOTHING
  RETURNING id INTO v_deal_id;

  -- 3. Se INSERT ha funzionato (nuovo deal), registra history
  IF v_deal_id IS NOT NULL THEN
    INSERT INTO public.deal_stage_history (deal_id, from_stage_id, to_stage_id, notes)
    VALUES (v_deal_id, NULL, v_initial_stage_id, 'Deal creato automaticamente');
    
    RETURN v_deal_id;
  END IF;

  -- 4. Deal già esistente, recupera ID
  SELECT id INTO v_deal_id
  FROM public.deals
  WHERE brand_id = p_brand_id 
    AND contact_id = p_contact_id
    AND status IN ('open', 'reopened_for_support')
  LIMIT 1;

  RETURN v_deal_id;
END;
$$;


--
-- Name: find_or_create_deal(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.find_or_create_deal(p_brand_id uuid, p_contact_id uuid, p_stage_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_deal_id UUID;
  v_initial_stage_id UUID;
  v_current_stage_id UUID;
  v_current_order INT;
  v_requested_order INT;
BEGIN
  -- Use provided stage_id or fall back to first global stage
  IF p_stage_id IS NOT NULL THEN
    v_initial_stage_id := p_stage_id;
  ELSE
    SELECT id INTO v_initial_stage_id
    FROM public.pipeline_stages
    WHERE brand_id IS NULL 
      AND is_active = true
    ORDER BY order_index ASC
    LIMIT 1;
  END IF;

  -- Prova INSERT con ON CONFLICT (sfrutta indice parziale)
  INSERT INTO public.deals (brand_id, contact_id, current_stage_id, status)
  VALUES (p_brand_id, p_contact_id, v_initial_stage_id, 'open')
  ON CONFLICT (brand_id, contact_id) WHERE status IN ('open', 'reopened_for_support')
  DO NOTHING
  RETURNING id INTO v_deal_id;

  -- Se INSERT ha funzionato (nuovo deal), registra history
  IF v_deal_id IS NOT NULL THEN
    INSERT INTO public.deal_stage_history (deal_id, from_stage_id, to_stage_id, notes)
    VALUES (v_deal_id, NULL, v_initial_stage_id, 'Deal creato automaticamente');
    
    RETURN v_deal_id;
  END IF;

  -- Deal già esistente, recupera ID e fase corrente
  SELECT id, current_stage_id INTO v_deal_id, v_current_stage_id
  FROM public.deals
  WHERE brand_id = p_brand_id 
    AND contact_id = p_contact_id
    AND status IN ('open', 'reopened_for_support')
  LIMIT 1;

  -- Se è stata richiesta una fase specifica e il deal esiste, avanza se necessario
  IF v_deal_id IS NOT NULL AND p_stage_id IS NOT NULL AND v_current_stage_id IS DISTINCT FROM p_stage_id THEN
    -- Controlla se la fase del deal è bloccata dall'utente
    IF NOT COALESCE((SELECT stage_locked_by_user FROM public.deals WHERE id = v_deal_id), false) THEN
      -- Recupera order_index della fase corrente e di quella richiesta
      SELECT order_index INTO v_current_order FROM public.pipeline_stages WHERE id = v_current_stage_id;
      SELECT order_index INTO v_requested_order FROM public.pipeline_stages WHERE id = p_stage_id;

      -- Avanza solo se la fase richiesta è più avanzata (order_index maggiore)
      IF v_requested_order IS NOT NULL AND v_current_order IS NOT NULL AND v_requested_order > v_current_order THEN
        UPDATE public.deals
        SET current_stage_id = p_stage_id, updated_at = now()
        WHERE id = v_deal_id;

        INSERT INTO public.deal_stage_history (deal_id, from_stage_id, to_stage_id, notes)
        VALUES (v_deal_id, v_current_stage_id, p_stage_id, 'Avanzamento automatico da webhook');
      END IF;
    END IF;
  END IF;

  RETURN v_deal_id;
END;
$$;


--
-- Name: find_or_create_ticket(uuid, uuid, uuid, uuid, text, text, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.find_or_create_ticket(p_brand_id uuid, p_contact_id uuid, p_deal_id uuid, p_lead_event_id uuid, p_title text, p_description text, p_priority integer, p_category_tag_id uuid DEFAULT NULL::uuid) RETURNS TABLE(ticket_id uuid, is_new boolean, ticket_event_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ticket_id UUID;
  v_is_new BOOLEAN := false;
  v_ticket_event_id UUID;
  v_reopen_threshold INTERVAL := '30 days';
BEGIN
  -- 1. Look for existing open/in_progress/reopened ticket for same contact+category
  SELECT t.id INTO v_ticket_id
  FROM tickets t
  WHERE t.brand_id = p_brand_id
    AND t.contact_id = p_contact_id
    AND t.status IN ('open', 'in_progress', 'reopened')
    AND (
      (p_category_tag_id IS NULL AND t.category_tag_id IS NULL)
      OR t.category_tag_id = p_category_tag_id
    )
  ORDER BY t.created_at DESC
  LIMIT 1;

  -- 2. If not found, check for recently closed ticket to reopen
  IF v_ticket_id IS NULL THEN
    SELECT t.id INTO v_ticket_id
    FROM tickets t
    WHERE t.brand_id = p_brand_id
      AND t.contact_id = p_contact_id
      AND t.status IN ('resolved', 'closed')
      AND t.closed_at > (now() - v_reopen_threshold)
      AND (
        (p_category_tag_id IS NULL AND t.category_tag_id IS NULL)
        OR t.category_tag_id = p_category_tag_id
      )
    ORDER BY t.closed_at DESC
    LIMIT 1;

    -- Reopen the ticket
    IF v_ticket_id IS NOT NULL THEN
      UPDATE tickets
      SET status = 'reopened',
          resolved_at = NULL,
          closed_at = NULL,
          updated_at = now()
      WHERE id = v_ticket_id;
    END IF;
  END IF;

  -- 3. If still not found, create new ticket
  IF v_ticket_id IS NULL THEN
    INSERT INTO tickets (
      brand_id, contact_id, deal_id, title, description,
      priority, category_tag_id, created_by, source_event_id
    )
    VALUES (
      p_brand_id, p_contact_id, p_deal_id, p_title, p_description,
      COALESCE(p_priority, 3), p_category_tag_id, 'ai', p_lead_event_id
    )
    RETURNING id INTO v_ticket_id;
    
    v_is_new := true;
  END IF;

  -- 4. Always create ticket_event to link lead_event
  INSERT INTO ticket_events (brand_id, ticket_id, lead_event_id, note)
  VALUES (
    p_brand_id, 
    v_ticket_id, 
    p_lead_event_id,
    CASE WHEN v_is_new THEN 'Ticket creato automaticamente' ELSE 'Nuova richiesta collegata' END
  )
  RETURNING id INTO v_ticket_event_id;

  RETURN QUERY SELECT v_ticket_id, v_is_new, v_ticket_event_id;
END;
$$;


--
-- Name: find_or_link_household_person(uuid, uuid, public.household_person_role, text, text, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.find_or_link_household_person(p_contact_id uuid, p_brand_id uuid, p_role public.household_person_role, p_phone_raw text, p_phone_normalized text, p_first_name text DEFAULT NULL::text, p_last_name text DEFAULT NULL::text, p_pacemaker_status text DEFAULT NULL::text, p_has_device boolean DEFAULT NULL::boolean) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_person_id UUID;
BEGIN
  IF p_phone_normalized IS NOT NULL AND p_phone_normalized != '' THEN
    SELECT id INTO v_person_id
    FROM public.household_people
    WHERE contact_id = p_contact_id
      AND phone_normalized = p_phone_normalized
    LIMIT 1;
  END IF;
  
  IF v_person_id IS NOT NULL THEN
    UPDATE public.household_people
    SET
      role = p_role,
      first_name = COALESCE(NULLIF(p_first_name, ''), first_name),
      last_name = COALESCE(NULLIF(p_last_name, ''), last_name),
      pacemaker_status = COALESCE(NULLIF(p_pacemaker_status, ''), pacemaker_status),
      has_device = COALESCE(p_has_device, has_device),
      updated_at = now()
    WHERE id = v_person_id;
    RETURN v_person_id;
  END IF;
  
  INSERT INTO public.household_people (
    contact_id, brand_id, role, first_name, last_name,
    phone_raw, phone_normalized, pacemaker_status, has_device
  ) VALUES (
    p_contact_id, p_brand_id, p_role, p_first_name, p_last_name,
    p_phone_raw, p_phone_normalized, p_pacemaker_status, p_has_device
  )
  RETURNING id INTO v_person_id;
  
  RETURN v_person_id;
END;
$$;


--
-- Name: generate_access_review(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_access_review(p_period text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_review_id uuid;
  v_total int;
BEGIN
  IF NOT has_role(get_user_id(auth.uid()), 'admin'::app_role) THEN
    RAISE EXCEPTION 'Only admins can generate access reviews';
  END IF;

  INSERT INTO public.access_reviews (review_period, reviewer_user_id, status, started_at)
  VALUES (p_period, get_user_id(auth.uid()), 'in_progress', now())
  ON CONFLICT (brand_id, review_period) DO UPDATE
    SET status = 'in_progress', started_at = now()
  RETURNING id INTO v_review_id;

  INSERT INTO public.access_review_items (review_id, user_id, user_email, current_role_label, decision)
  SELECT v_review_id, u.id, u.email, string_agg(DISTINCT ur.role::text, ', '), 'pending'
  FROM public.users u
  LEFT JOIN public.user_roles ur ON ur.user_id = u.id
  WHERE u.is_active = true
  GROUP BY u.id, u.email;

  GET DIAGNOSTICS v_total = ROW_COUNT;
  UPDATE public.access_reviews SET total_users = v_total WHERE id = v_review_id;

  RETURN v_review_id;
END;
$$;


--
-- Name: generate_compliance_report(uuid, text, timestamp with time zone, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_compliance_report(p_brand_id uuid, p_report_type text, p_period_start timestamp with time zone, p_period_end timestamp with time zone, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_summary JSONB;
  v_total INT;
  v_by_action JSONB;
  v_by_entity JSONB;
  v_top_users JSONB;
  v_exports INT;
  v_deletions INT;
  v_permission_changes INT;
  v_pii_access INT;
  v_anomalies INT;
  v_checksum TEXT;
  v_report_id UUID;
BEGIN
  IF NOT public.is_audit_admin(auth.uid()) THEN
    RAISE EXCEPTION 'access denied';
  END IF;

  IF p_report_type NOT IN ('gdpr', 'sox', 'custom') THEN
    RAISE EXCEPTION 'invalid report_type';
  END IF;

  SELECT id INTO v_user_id FROM public.users WHERE supabase_auth_id = auth.uid() LIMIT 1;

  -- Total events
  SELECT count(*) INTO v_total
  FROM public.audit_events
  WHERE brand_id = p_brand_id
    AND occurred_at >= p_period_start
    AND occurred_at < p_period_end;

  -- By action
  SELECT COALESCE(jsonb_object_agg(action, cnt), '{}'::jsonb) INTO v_by_action
  FROM (
    SELECT action, count(*) AS cnt
    FROM public.audit_events
    WHERE brand_id = p_brand_id
      AND occurred_at >= p_period_start
      AND occurred_at < p_period_end
    GROUP BY action
    ORDER BY cnt DESC
    LIMIT 50
  ) a;

  -- By entity type
  SELECT COALESCE(jsonb_object_agg(entity_type, cnt), '{}'::jsonb) INTO v_by_entity
  FROM (
    SELECT entity_type, count(*) AS cnt
    FROM public.audit_events
    WHERE brand_id = p_brand_id
      AND occurred_at >= p_period_start
      AND occurred_at < p_period_end
    GROUP BY entity_type
    ORDER BY cnt DESC
    LIMIT 50
  ) e;

  -- Top users
  SELECT COALESCE(jsonb_agg(jsonb_build_object('user_id', actor_user_id, 'count', cnt) ORDER BY cnt DESC), '[]'::jsonb)
  INTO v_top_users
  FROM (
    SELECT actor_user_id, count(*) AS cnt
    FROM public.audit_events
    WHERE brand_id = p_brand_id
      AND occurred_at >= p_period_start
      AND occurred_at < p_period_end
      AND actor_user_id IS NOT NULL
    GROUP BY actor_user_id
    ORDER BY cnt DESC
    LIMIT 20
  ) u;

  -- SOX/GDPR critical events
  SELECT count(*) INTO v_exports
  FROM public.audit_events
  WHERE brand_id = p_brand_id
    AND occurred_at >= p_period_start
    AND occurred_at < p_period_end
    AND action IN ('export', 'data_export', 'csv_export');

  SELECT count(*) INTO v_deletions
  FROM public.audit_events
  WHERE brand_id = p_brand_id
    AND occurred_at >= p_period_start
    AND occurred_at < p_period_end
    AND action IN ('delete', 'hard_delete');

  SELECT count(*) INTO v_permission_changes
  FROM public.audit_events
  WHERE brand_id = p_brand_id
    AND occurred_at >= p_period_start
    AND occurred_at < p_period_end
    AND (action ILIKE '%role%' OR action ILIKE '%permission%' OR entity_type IN ('user_roles', 'user_module_access'));

  -- PII access (from audit_access_log if exists)
  v_pii_access := 0;
  BEGIN
    SELECT count(*) INTO v_pii_access
    FROM public.audit_access_log
    WHERE brand_id = p_brand_id
      AND accessed_at >= p_period_start
      AND accessed_at < p_period_end;
  EXCEPTION WHEN OTHERS THEN
    v_pii_access := 0;
  END;

  -- Anomalies count
  v_anomalies := 0;
  BEGIN
    SELECT count(*) INTO v_anomalies
    FROM public.audit_anomalies
    WHERE brand_id = p_brand_id
      AND detected_at >= p_period_start
      AND detected_at < p_period_end;
  EXCEPTION WHEN OTHERS THEN
    v_anomalies := 0;
  END;

  v_summary := jsonb_build_object(
    'total_events', v_total,
    'by_action', v_by_action,
    'by_entity_type', v_by_entity,
    'top_users', v_top_users,
    'critical', jsonb_build_object(
      'exports', v_exports,
      'deletions', v_deletions,
      'permission_changes', v_permission_changes,
      'pii_access', v_pii_access,
      'anomalies', v_anomalies
    ),
    'meta', jsonb_build_object(
      'report_type', p_report_type,
      'period_start', p_period_start,
      'period_end', p_period_end,
      'generated_at', now()
    )
  );

  -- Checksum (deterministic hash of summary)
  v_checksum := encode(digest(v_summary::text || p_brand_id::text || p_period_start::text || p_period_end::text, 'sha256'), 'hex');

  INSERT INTO public.audit_compliance_reports (
    brand_id, report_type, period_start, period_end,
    generated_by, summary, checksum, notes
  ) VALUES (
    p_brand_id, p_report_type, p_period_start, p_period_end,
    v_user_id, v_summary, v_checksum, p_notes
  ) RETURNING id INTO v_report_id;

  RETURN jsonb_build_object(
    'id', v_report_id,
    'checksum', v_checksum,
    'summary', v_summary
  );
END;
$$;


--
-- Name: generate_order_number(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_order_number(p_brand_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_brand_slug TEXT;
  v_year TEXT;
  v_count INTEGER;
BEGIN
  SELECT slug INTO v_brand_slug FROM brands WHERE id = p_brand_id;
  v_year := to_char(now(), 'YY');
  
  SELECT COUNT(*) + 1 INTO v_count
  FROM sales_orders
  WHERE brand_id = p_brand_id
    AND created_at >= date_trunc('year', now());
  
  RETURN UPPER(v_brand_slug) || '-' || v_year || '-' || LPAD(v_count::TEXT, 5, '0');
END;
$$;


--
-- Name: get_accessible_brand_ids(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_accessible_brand_ids(p_user_id uuid) RETURNS uuid[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_direct_brands UUID[];
  v_child_brands UUID[];
  v_parent_brands_with_children UUID[];
BEGIN
  -- Get directly assigned brands
  SELECT array_agg(ur.brand_id) INTO v_direct_brands
  FROM user_roles ur
  WHERE ur.user_id = p_user_id;
  
  IF v_direct_brands IS NULL THEN
    RETURN ARRAY[]::UUID[];
  END IF;
  
  -- Get parent brands where user has can_access_children = true
  SELECT array_agg(ur.brand_id) INTO v_parent_brands_with_children
  FROM user_roles ur
  WHERE ur.user_id = p_user_id AND ur.can_access_children = true;
  
  -- Get child brands of those parents
  IF v_parent_brands_with_children IS NOT NULL THEN
    SELECT array_agg(b.id) INTO v_child_brands
    FROM brands b
    WHERE b.parent_brand_id = ANY(v_parent_brands_with_children);
  END IF;
  
  -- Combine and return unique brand IDs
  RETURN ARRAY(
    SELECT DISTINCT unnest(
      array_cat(
        COALESCE(v_direct_brands, ARRAY[]::UUID[]),
        COALESCE(v_child_brands, ARRAY[]::UUID[])
      )
    )
  );
END;
$$;


--
-- Name: get_ad_creative_stats(uuid[], date, date, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_ad_creative_stats(p_brand_ids uuid[], p_from_date date, p_to_date date, p_platform text DEFAULT NULL::text, p_campaign_id text DEFAULT NULL::text) RETURNS TABLE(external_ad_id text, external_ad_name text, external_campaign_id text, external_campaign_name text, thumbnail_url text, platform text, brand_id uuid, total_spend numeric, total_impressions bigint, total_clicks bigint, total_reach bigint, avg_frequency numeric, ctr numeric, cpc numeric, cpm numeric, days_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    s.external_ad_id,
    MAX(s.external_ad_name) AS external_ad_name,
    s.external_campaign_id,
    MAX(s.external_campaign_name) AS external_campaign_name,
    MAX(s.thumbnail_url) AS thumbnail_url,
    s.platform::TEXT,
    s.brand_id,
    SUM(s.spend) AS total_spend,
    SUM(s.impressions)::BIGINT AS total_impressions,
    SUM(s.clicks)::BIGINT AS total_clicks,
    SUM(COALESCE(s.reach, 0))::BIGINT AS total_reach,
    AVG(s.frequency) AS avg_frequency,
    CASE WHEN SUM(s.impressions) > 0
      THEN ROUND(SUM(s.clicks)::NUMERIC / SUM(s.impressions) * 100, 2) END AS ctr,
    CASE WHEN SUM(s.clicks) > 0
      THEN ROUND(SUM(s.spend) / SUM(s.clicks), 2) END AS cpc,
    CASE WHEN SUM(s.impressions) > 0
      THEN ROUND(SUM(s.spend) / SUM(s.impressions) * 1000, 2) END AS cpm,
    COUNT(DISTINCT s.stat_date) AS days_count
  FROM ad_creative_stats s
  WHERE s.brand_id = ANY(p_brand_ids)
    AND s.stat_date BETWEEN p_from_date AND p_to_date
    AND (p_platform IS NULL OR s.platform::TEXT = p_platform)
    AND (p_campaign_id IS NULL OR s.external_campaign_id = p_campaign_id)
  GROUP BY s.external_ad_id, s.external_campaign_id, s.platform, s.brand_id
  ORDER BY SUM(s.spend) DESC;
$$;


--
-- Name: get_ad_demographics(uuid[], date, date, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_ad_demographics(p_brand_ids uuid[], p_from_date date, p_to_date date, p_platform text DEFAULT NULL::text, p_campaign_id text DEFAULT NULL::text) RETURNS TABLE(age_range text, gender text, total_spend numeric, total_impressions bigint, total_clicks bigint, total_reach bigint, ctr numeric, cpc numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    d.age_range,
    d.gender,
    SUM(d.spend) AS total_spend,
    SUM(d.impressions)::BIGINT AS total_impressions,
    SUM(d.clicks)::BIGINT AS total_clicks,
    SUM(COALESCE(d.reach, 0))::BIGINT AS total_reach,
    CASE WHEN SUM(d.impressions) > 0
      THEN ROUND(SUM(d.clicks)::NUMERIC / SUM(d.impressions) * 100, 2) END AS ctr,
    CASE WHEN SUM(d.clicks) > 0
      THEN ROUND(SUM(d.spend) / SUM(d.clicks), 2) END AS cpc
  FROM ad_demographic_stats d
  WHERE d.brand_id = ANY(p_brand_ids)
    AND d.stat_date BETWEEN p_from_date AND p_to_date
    AND (p_platform IS NULL OR d.platform::TEXT = p_platform)
    AND (p_campaign_id IS NULL OR d.external_campaign_id = p_campaign_id)
  GROUP BY d.age_range, d.gender
  ORDER BY d.age_range, d.gender;
$$;


--
-- Name: get_ad_platform_stats(uuid, date, date, public.ad_platform, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_ad_platform_stats(p_brand_id uuid, p_from date, p_to date, p_platform public.ad_platform DEFAULT NULL::public.ad_platform, p_campaign_id uuid DEFAULT NULL::uuid) RETURNS TABLE(external_campaign_id text, external_campaign_name text, campaign_id uuid, campaign_name text, platform public.ad_platform, brand_id uuid, total_spend numeric, total_impressions bigint, total_clicks bigint, total_conversions numeric, total_reach bigint, avg_frequency numeric, ctr numeric, cpm numeric, cpc numeric, days_count integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_brand_ids uuid[];
BEGIN
  IF p_brand_id = '00000000-0000-0000-0000-000000000000' THEN
    SELECT array_agg(DISTINCT ur.brand_id)
    INTO v_brand_ids
    FROM user_roles ur
    WHERE ur.user_id = get_user_id(auth.uid())
      AND ur.is_active = true
      AND ur.brand_id <> '00000000-0000-0000-0000-000000000000';
  ELSE
    IF NOT has_marketing_access(get_user_id(auth.uid()), p_brand_id) THEN
      RAISE EXCEPTION 'Access denied' USING ERRCODE = '42501';
    END IF;
    v_brand_ids := ARRAY[p_brand_id];
  END IF;

  RETURN QUERY
  SELECT 
    s.external_campaign_id,
    MAX(s.external_campaign_name)::text AS external_campaign_name,
    s.campaign_id,
    MAX(mc.name)::text AS campaign_name,
    s.platform,
    s.brand_id,
    SUM(s.spend) AS total_spend,
    SUM(s.impressions)::BIGINT AS total_impressions,
    SUM(s.clicks)::BIGINT AS total_clicks,
    SUM(COALESCE(s.conversions, 0)) AS total_conversions,
    SUM(COALESCE(s.reach, 0))::BIGINT AS total_reach,
    CASE WHEN SUM(COALESCE(s.reach, 0)) > 0
      THEN ROUND(SUM(s.impressions)::NUMERIC / SUM(s.reach), 2)
      ELSE NULL
    END AS avg_frequency,
    CASE WHEN SUM(s.impressions) > 0 THEN ROUND((SUM(s.clicks)::NUMERIC / SUM(s.impressions)) * 100, 2) ELSE NULL END AS ctr,
    CASE WHEN SUM(s.impressions) > 0 THEN ROUND((SUM(s.spend) / SUM(s.impressions)) * 1000, 2) ELSE NULL END AS cpm,
    CASE WHEN SUM(s.clicks) > 0 THEN ROUND(SUM(s.spend) / SUM(s.clicks), 2) ELSE NULL END AS cpc,
    COUNT(DISTINCT s.stat_date)::INTEGER AS days_count
  FROM ad_platform_stats s
  LEFT JOIN marketing_campaigns mc ON mc.id = s.campaign_id
  WHERE s.brand_id = ANY(v_brand_ids)
    AND s.stat_date >= p_from
    AND s.stat_date <= p_to
    AND (p_platform IS NULL OR s.platform = p_platform)
    AND (p_campaign_id IS NULL OR s.campaign_id = p_campaign_id)
  GROUP BY s.external_campaign_id, s.campaign_id, s.platform, s.brand_id
  ORDER BY total_spend DESC NULLS LAST;
END;
$$;


--
-- Name: get_ad_platform_stats_summary(uuid, date, date, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_ad_platform_stats_summary(p_brand_id uuid, p_from date, p_to date, p_platform text DEFAULT NULL::text, p_campaign_id text DEFAULT NULL::text) RETURNS TABLE(total_spend numeric, total_impressions bigint, total_clicks bigint, total_conversions bigint, total_reach bigint, total_leads bigint, avg_frequency numeric, avg_ctr numeric, avg_cpm numeric, avg_cpc numeric, avg_cpl numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_company_brand_id uuid := '00000000-0000-0000-0000-000000000000';
  v_is_company_brand boolean;
BEGIN
  IF NOT has_marketing_access(get_user_id(auth.uid()), p_brand_id) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  v_is_company_brand := (p_brand_id = v_company_brand_id);

  RETURN QUERY
  WITH ad_data AS (
    SELECT
      COALESCE(SUM(aps.spend), 0)::numeric AS t_spend,
      COALESCE(SUM(aps.impressions), 0)::bigint AS t_impressions,
      COALESCE(SUM(aps.clicks), 0)::bigint AS t_clicks,
      COALESCE(SUM(aps.conversions), 0)::bigint AS t_conversions,
      COALESCE(SUM(aps.reach), 0)::bigint AS t_reach,
      CASE WHEN SUM(aps.reach) > 0
           THEN ROUND(SUM(aps.impressions)::numeric / NULLIF(SUM(aps.reach), 0), 2)
           ELSE NULL END AS t_frequency
    FROM ad_platform_stats aps
    WHERE (v_is_company_brand OR aps.brand_id = p_brand_id)
      AND aps.stat_date BETWEEN p_from AND p_to
      AND (p_platform IS NULL OR aps.platform::text = p_platform)
      AND (p_campaign_id IS NULL OR aps.campaign_id::text = p_campaign_id)
  ),
  lead_data AS (
    SELECT COUNT(DISTINCT le.contact_id)::bigint AS t_leads
    FROM lead_events le
    WHERE (v_is_company_brand OR le.brand_id = p_brand_id)
      AND le.contact_id IS NOT NULL
      AND le.received_at >= p_from::timestamptz
      AND le.received_at < (p_to + 1)::timestamptz
      AND (le.archived = false OR le.archived IS NULL)
      -- Exclude sources marked as not counting as new lead
      AND NOT EXISTS (
        SELECT 1 FROM webhook_sources ws
        WHERE ws.name = le.source_name
          AND ws.brand_id = le.brand_id
          AND ws.counts_as_new_lead = false
      )
      -- First-touch: exclude contacts that had events before the range
      AND NOT EXISTS (
        SELECT 1 FROM lead_events older
        WHERE older.contact_id = le.contact_id
          AND older.brand_id = le.brand_id
          AND older.received_at < p_from::timestamptz
          AND NOT EXISTS (
            SELECT 1 FROM webhook_sources ws2
            WHERE ws2.name = older.source_name
              AND ws2.brand_id = older.brand_id
              AND ws2.counts_as_new_lead = false
          )
      )
  )
  SELECT
    ad.t_spend,
    ad.t_impressions,
    ad.t_clicks,
    ad.t_conversions,
    ad.t_reach,
    ld.t_leads,
    ad.t_frequency,
    CASE WHEN ad.t_impressions > 0 THEN ROUND((ad.t_clicks::numeric / ad.t_impressions) * 100, 2) ELSE NULL END,
    CASE WHEN ad.t_impressions > 0 THEN ROUND((ad.t_spend / ad.t_impressions) * 1000, 2) ELSE NULL END,
    CASE WHEN ad.t_clicks > 0 THEN ROUND(ad.t_spend / ad.t_clicks, 2) ELSE NULL END,
    CASE WHEN ld.t_leads > 0 AND ad.t_spend > 0
         THEN ROUND(ad.t_spend / ld.t_leads, 2)
         ELSE NULL END
  FROM ad_data ad, lead_data ld;
END;
$$;


--
-- Name: get_ad_platform_stats_trend(uuid, date, date, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_ad_platform_stats_trend(p_brand_id uuid, p_from date, p_to date, p_platform text DEFAULT NULL::text, p_campaign_id text DEFAULT NULL::text) RETURNS TABLE(stat_date date, total_spend numeric, total_impressions bigint, total_clicks bigint, total_conversions bigint, total_leads bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_is_system boolean := (p_brand_id = '00000000-0000-0000-0000-000000000000');
BEGIN
  RETURN QUERY
  WITH ad_data AS (
    SELECT
      aps.stat_date AS day,
      COALESCE(SUM(aps.spend), 0)::numeric AS total_spend,
      COALESCE(SUM(aps.impressions), 0)::bigint AS total_impressions,
      COALESCE(SUM(aps.clicks), 0)::bigint AS total_clicks,
      COALESCE(SUM(aps.conversions), 0)::bigint AS total_conversions
    FROM ad_platform_stats aps
    WHERE (v_is_system OR aps.brand_id = p_brand_id)
      AND aps.stat_date BETWEEN p_from AND p_to
      AND (p_platform IS NULL OR aps.platform::text = p_platform)
      AND (p_campaign_id IS NULL OR aps.campaign_id::text = p_campaign_id)
    GROUP BY aps.stat_date
  ),
  lead_data AS (
    SELECT
      (le.created_at AT TIME ZONE 'Europe/Rome')::date AS day,
      COUNT(DISTINCT le.contact_id)::bigint AS total_leads
    FROM lead_events le
    JOIN contacts c ON c.id = le.contact_id
    WHERE (v_is_system OR c.brand_id = p_brand_id)
      AND le.created_at::date BETWEEN p_from AND p_to
      AND (le.archived = false OR le.archived IS NULL)
    GROUP BY (le.created_at AT TIME ZONE 'Europe/Rome')::date
  ),
  date_series AS (
    SELECT generate_series(p_from, p_to, '1 day'::interval)::date AS day
  )
  SELECT
    ds.day AS stat_date,
    COALESCE(ad.total_spend, 0)::numeric,
    COALESCE(ad.total_impressions, 0)::bigint,
    COALESCE(ad.total_clicks, 0)::bigint,
    COALESCE(ad.total_conversions, 0)::bigint,
    COALESCE(ld.total_leads, 0)::bigint
  FROM date_series ds
  LEFT JOIN ad_data ad ON ad.day = ds.day
  LEFT JOIN lead_data ld ON ld.day = ds.day
  WHERE COALESCE(ad.total_spend, 0) > 0 OR COALESCE(ld.total_leads, 0) > 0
  ORDER BY ds.day;
END;
$$;


--
-- Name: get_admin_finance_kpis(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_admin_finance_kpis(p_brand_id uuid, p_from date, p_to date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_total_expenses numeric(12,2);
  v_budget_total numeric(12,2);
  v_sales_total numeric(12,2);
  v_expenses_by_category jsonb;
  v_budget_by_category jsonb;
  v_is_system_brand boolean;
BEGIN
  -- Get current user id
  v_user_id := get_user_id(auth.uid());
  
  -- Check if user has finance access
  IF NOT has_finance_access(v_user_id, p_brand_id) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;
  
  -- Check if this is the system brand (azienda intera)
  SELECT COALESCE(is_system, false) INTO v_is_system_brand FROM brands WHERE id = p_brand_id;
  
  -- Calculate total expenses
  SELECT COALESCE(SUM(amount), 0) INTO v_total_expenses
  FROM expenses
  WHERE brand_id = p_brand_id
    AND expense_date BETWEEN p_from AND p_to;
  
  -- Calculate expenses by category
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'category_id', sub.category_id,
    'category_name', COALESCE(ec.name, 'Senza categoria'),
    'amount', sub.cat_total
  )), '[]'::jsonb)
  INTO v_expenses_by_category
  FROM (
    SELECT e.category_id, SUM(e.amount) as cat_total
    FROM expenses e
    WHERE e.brand_id = p_brand_id
      AND e.expense_date BETWEEN p_from AND p_to
    GROUP BY e.category_id
  ) sub
  LEFT JOIN expense_categories ec ON ec.id = sub.category_id;
  
  -- Calculate budget total for the period
  SELECT COALESCE(SUM(planned_amount), 0) INTO v_budget_total
  FROM budgets
  WHERE brand_id = p_brand_id
    AND period_month >= date_trunc('month', p_from)::date
    AND period_month <= date_trunc('month', p_to)::date;
  
  -- Calculate budget by category
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'category_id', sub.category_id,
    'category_name', COALESCE(ec.name, 'Budget Totale'),
    'planned_amount', sub.budget_total
  )), '[]'::jsonb)
  INTO v_budget_by_category
  FROM (
    SELECT b.category_id, SUM(b.planned_amount) as budget_total
    FROM budgets b
    WHERE b.brand_id = p_brand_id
      AND b.period_month >= date_trunc('month', p_from)::date
      AND b.period_month <= date_trunc('month', p_to)::date
    GROUP BY b.category_id
  ) sub
  LEFT JOIN expense_categories ec ON ec.id = sub.category_id;
  
  -- Calculate sales total from won deals
  -- If system brand, aggregate from ALL operational brands
  IF v_is_system_brand THEN
    SELECT COALESCE(SUM(value), 0) INTO v_sales_total
    FROM deals d
    JOIN brands b ON b.id = d.brand_id
    WHERE d.status = 'won'
      AND COALESCE(b.is_system, false) = false
      AND d.closed_at::date BETWEEN p_from AND p_to;
  ELSE
    SELECT COALESCE(SUM(value), 0) INTO v_sales_total
    FROM deals
    WHERE brand_id = p_brand_id
      AND status = 'won'
      AND closed_at::date BETWEEN p_from AND p_to;
  END IF;
  
  RETURN jsonb_build_object(
    'total_expenses', v_total_expenses,
    'expenses_by_category', v_expenses_by_category,
    'budget_total', v_budget_total,
    'budget_by_category', v_budget_by_category,
    'sales_total', v_sales_total,
    'margin', v_sales_total - v_total_expenses,
    'period_from', p_from,
    'period_to', p_to
  );
END;
$$;


--
-- Name: get_ai_decisions_drilldown(uuid, integer, text, text, uuid, boolean, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_ai_decisions_drilldown(p_brand_id uuid DEFAULT NULL::uuid, p_days integer DEFAULT 30, p_model_version text DEFAULT NULL::text, p_initial_stage text DEFAULT NULL::text, p_overridden_by_user_id uuid DEFAULT NULL::uuid, p_only_overridden boolean DEFAULT NULL::boolean, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_total integer := 0;
  v_rows jsonb;
  v_lim integer;
  v_off integer;
BEGIN
  v_user_id := get_user_id(auth.uid());
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'unauthenticated';
  END IF;

  -- Reuse the same permission shape as get_ai_override_summary
  IF p_brand_id IS NOT NULL THEN
    IF NOT (
      has_role(v_user_id, 'ceo'::app_role)
      OR has_role_for_brand(v_user_id, p_brand_id, 'admin'::app_role)
      OR has_role_for_brand(v_user_id, p_brand_id, 'responsabile_venditori'::app_role)
      OR has_role_for_brand(v_user_id, p_brand_id, 'responsabile_callcenter'::app_role)
    ) THEN
      RAISE EXCEPTION 'forbidden';
    END IF;
  ELSE
    IF NOT has_role(v_user_id, 'ceo'::app_role) AND NOT has_role(v_user_id, 'admin'::app_role) THEN
      RAISE EXCEPTION 'forbidden';
    END IF;
  END IF;

  v_lim := LEAST(GREATEST(p_limit, 1), 200);
  v_off := GREATEST(p_offset, 0);

  -- Total matching count (for pagination)
  SELECT COUNT(*)
  INTO v_total
  FROM ai_decision_logs l
  WHERE l.created_at >= now() - (p_days || ' days')::interval
    AND (p_brand_id IS NULL OR l.brand_id = p_brand_id)
    AND (p_model_version IS NULL OR l.model_version = p_model_version)
    AND (p_initial_stage IS NULL OR l.initial_stage_name = p_initial_stage)
    AND (p_overridden_by_user_id IS NULL OR l.overridden_by_user_id = p_overridden_by_user_id)
    AND (p_only_overridden IS NULL OR l.was_overridden = p_only_overridden);

  -- Page of rows with denormalized labels
  SELECT COALESCE(jsonb_agg(row_to_jsonb(r) ORDER BY r.created_at DESC), '[]'::jsonb)
  INTO v_rows
  FROM (
    SELECT
      l.id,
      l.brand_id,
      b.name AS brand_name,
      l.lead_event_id,
      l.lead_type,
      l.priority,
      l.initial_stage_name,
      l.model_version,
      l.prompt_version,
      l.confidence,
      l.was_overridden,
      l.override_reason,
      l.override_reason_category::text AS override_reason_category,
      l.overridden_at,
      l.overridden_by_user_id,
      u.full_name AS overridden_by_name,
      l.tags_to_apply,
      l.should_create_ticket,
      l.should_create_or_update_appointment,
      l.appointment_action,
      l.rationale,
      l.created_at
    FROM ai_decision_logs l
    LEFT JOIN brands b ON b.id = l.brand_id
    LEFT JOIN users u ON u.id = l.overridden_by_user_id
    WHERE l.created_at >= now() - (p_days || ' days')::interval
      AND (p_brand_id IS NULL OR l.brand_id = p_brand_id)
      AND (p_model_version IS NULL OR l.model_version = p_model_version)
      AND (p_initial_stage IS NULL OR l.initial_stage_name = p_initial_stage)
      AND (p_overridden_by_user_id IS NULL OR l.overridden_by_user_id = p_overridden_by_user_id)
      AND (p_only_overridden IS NULL OR l.was_overridden = p_only_overridden)
    ORDER BY l.created_at DESC
    LIMIT v_lim OFFSET v_off
  ) r;

  RETURN jsonb_build_object(
    'total', v_total,
    'limit', v_lim,
    'offset', v_off,
    'rows', v_rows,
    'generated_at', now()
  );
END;
$$;


--
-- Name: get_ai_decisions_filter_options(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_ai_decisions_filter_options(p_brand_id uuid DEFAULT NULL::uuid, p_days integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_models jsonb;
  v_stages jsonb;
  v_users jsonb;
BEGIN
  v_user_id := get_user_id(auth.uid());
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'unauthenticated'; END IF;

  IF p_brand_id IS NOT NULL THEN
    IF NOT (
      has_role(v_user_id, 'ceo'::app_role)
      OR has_role_for_brand(v_user_id, p_brand_id, 'admin'::app_role)
      OR has_role_for_brand(v_user_id, p_brand_id, 'responsabile_venditori'::app_role)
      OR has_role_for_brand(v_user_id, p_brand_id, 'responsabile_callcenter'::app_role)
    ) THEN RAISE EXCEPTION 'forbidden'; END IF;
  ELSE
    IF NOT has_role(v_user_id, 'ceo'::app_role) AND NOT has_role(v_user_id, 'admin'::app_role) THEN
      RAISE EXCEPTION 'forbidden';
    END IF;
  END IF;

  SELECT COALESCE(jsonb_agg(DISTINCT model_version), '[]'::jsonb)
  INTO v_models
  FROM ai_decision_logs
  WHERE created_at >= now() - (p_days || ' days')::interval
    AND (p_brand_id IS NULL OR brand_id = p_brand_id);

  SELECT COALESCE(jsonb_agg(DISTINCT initial_stage_name) FILTER (WHERE initial_stage_name IS NOT NULL), '[]'::jsonb)
  INTO v_stages
  FROM ai_decision_logs
  WHERE created_at >= now() - (p_days || ' days')::interval
    AND (p_brand_id IS NULL OR brand_id = p_brand_id);

  SELECT COALESCE(jsonb_agg(jsonb_build_object('id', u.id, 'name', u.full_name) ORDER BY u.full_name), '[]'::jsonb)
  INTO v_users
  FROM (
    SELECT DISTINCT u.id, u.full_name
    FROM ai_decision_logs l
    JOIN users u ON u.id = l.overridden_by_user_id
    WHERE l.was_overridden = true
      AND l.created_at >= now() - (p_days || ' days')::interval
      AND (p_brand_id IS NULL OR l.brand_id = p_brand_id)
    LIMIT 200
  ) u;

  RETURN jsonb_build_object('models', v_models, 'stages', v_stages, 'users', v_users);
END;
$$;


--
-- Name: get_ai_metrics_errors(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_ai_metrics_errors(p_brand_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN (
    SELECT COALESCE(json_agg(json_build_object(
      'error', COALESCE(
        CASE 
          WHEN last_error LIKE '%timeout%' THEN 'Timeout'
          WHEN last_error LIKE '%rate limit%' THEN 'Rate Limit'
          WHEN last_error LIKE '%network%' THEN 'Network Error'
          WHEN last_error LIKE '%parse%' OR last_error LIKE '%JSON%' THEN 'Parse Error'
          ELSE SUBSTRING(last_error FROM 1 FOR 50)
        END,
        'Unknown'
      ),
      'count', cnt,
      'last_occurrence', last_at
    ) ORDER BY cnt DESC), '[]'::json)
    FROM (
      SELECT 
        last_error,
        COUNT(*) as cnt,
        MAX(created_at) as last_at
      FROM ai_jobs
      WHERE brand_id = p_brand_id
        AND status = 'failed'
        AND created_at >= p_from
        AND created_at < p_to
      GROUP BY last_error
      LIMIT 10
    ) t
  );
END;
$$;


--
-- Name: get_ai_metrics_overview(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_ai_metrics_overview(p_brand_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result JSON;
BEGIN
  SELECT json_build_object(
    'job_counts', (
      SELECT json_build_object(
        'pending', COUNT(*) FILTER (WHERE status = 'pending'),
        'processing', COUNT(*) FILTER (WHERE status = 'processing'),
        'completed', COUNT(*) FILTER (WHERE status = 'completed'),
        'failed', COUNT(*) FILTER (WHERE status = 'failed'),
        'total', COUNT(*)
      )
      FROM ai_jobs
      WHERE brand_id = p_brand_id
        AND created_at >= p_from
        AND created_at < p_to
    ),
    'latency', (
      SELECT json_build_object(
        'avg_ms', COALESCE(
          ROUND(AVG(EXTRACT(EPOCH FROM (completed_at - created_at)) * 1000)::numeric, 0),
          0
        ),
        'p95_ms', COALESCE(
          ROUND((percentile_cont(0.95) WITHIN GROUP (ORDER BY EXTRACT(EPOCH FROM (completed_at - created_at)) * 1000))::numeric, 0),
          0
        ),
        'avg_attempts', COALESCE(ROUND(AVG(attempts)::numeric, 2), 0)
      )
      FROM ai_jobs
      WHERE brand_id = p_brand_id
        AND status = 'completed'
        AND created_at >= p_from
        AND created_at < p_to
    ),
    'fallback_count', (
      SELECT COUNT(*)
      FROM lead_events
      WHERE brand_id = p_brand_id
        AND ai_processed = true
        AND ai_confidence = 0
        AND created_at >= p_from
        AND created_at < p_to
    ),
    'lead_type_distribution', (
      SELECT COALESCE(json_agg(json_build_object('type', lead_type, 'count', cnt)), '[]'::json)
      FROM (
        SELECT lead_type, COUNT(*) as cnt
        FROM lead_events
        WHERE brand_id = p_brand_id
          AND ai_processed = true
          AND created_at >= p_from
          AND created_at < p_to
        GROUP BY lead_type
      ) t
    ),
    'priority_distribution', (
      SELECT COALESCE(json_agg(json_build_object('priority', ai_priority, 'count', cnt)), '[]'::json)
      FROM (
        SELECT ai_priority, COUNT(*) as cnt
        FROM lead_events
        WHERE brand_id = p_brand_id
          AND ai_processed = true
          AND ai_priority IS NOT NULL
          AND created_at >= p_from
          AND created_at < p_to
        GROUP BY ai_priority
        ORDER BY ai_priority
      ) t
    ),
    'ticket_stats', (
      SELECT json_build_object(
        'support_count', COUNT(*) FILTER (WHERE lead_type = 'support'),
        'tickets_created', COUNT(*) FILTER (WHERE should_create_ticket = true)
      )
      FROM lead_events
      WHERE brand_id = p_brand_id
        AND ai_processed = true
        AND created_at >= p_from
        AND created_at < p_to
    ),
    'daily_trend', (
      SELECT COALESCE(json_agg(json_build_object(
        'date', day::date,
        'completed', completed_cnt,
        'failed', failed_cnt
      ) ORDER BY day), '[]'::json)
      FROM (
        SELECT 
          date_trunc('day', created_at) as day,
          COUNT(*) FILTER (WHERE status = 'completed') as completed_cnt,
          COUNT(*) FILTER (WHERE status = 'failed') as failed_cnt
        FROM ai_jobs
        WHERE brand_id = p_brand_id
          AND created_at >= p_from
          AND created_at < p_to
        GROUP BY date_trunc('day', created_at)
      ) t
    )
  ) INTO v_result;
  
  RETURN v_result;
END;
$$;


--
-- Name: get_ai_override_summary(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_ai_override_summary(p_brand_id uuid DEFAULT NULL::uuid, p_days integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_total integer := 0;
  v_overridden integer := 0;
  v_avg_conf numeric;
  v_avg_conf_overridden numeric;
  v_top_categories jsonb;
  v_proposals_total integer := 0;
  v_proposals_approved integer := 0;
  v_proposals_rejected integer := 0;
  v_proposals_edited integer := 0;
BEGIN
  v_user_id := get_user_id(auth.uid());
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'unauthenticated';
  END IF;

  -- Permission check: must be admin or CEO or responsabile_venditori for this brand
  IF p_brand_id IS NOT NULL THEN
    IF NOT (
      has_role(v_user_id, 'ceo'::app_role)
      OR has_role_for_brand(v_user_id, p_brand_id, 'admin'::app_role)
      OR has_role_for_brand(v_user_id, p_brand_id, 'responsabile_venditori'::app_role)
      OR has_role_for_brand(v_user_id, p_brand_id, 'responsabile_callcenter'::app_role)
    ) THEN
      RAISE EXCEPTION 'forbidden';
    END IF;
  ELSE
    IF NOT has_role(v_user_id, 'ceo'::app_role) AND NOT has_role(v_user_id, 'admin'::app_role) THEN
      RAISE EXCEPTION 'forbidden';
    END IF;
  END IF;

  -- AI decision logs aggregation
  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE was_overridden),
    ROUND(AVG(confidence)::numeric, 3),
    ROUND(AVG(confidence) FILTER (WHERE was_overridden)::numeric, 3)
  INTO v_total, v_overridden, v_avg_conf, v_avg_conf_overridden
  FROM ai_decision_logs
  WHERE created_at >= now() - (p_days || ' days')::interval
    AND (p_brand_id IS NULL OR brand_id = p_brand_id);

  -- Top override categories
  SELECT COALESCE(jsonb_agg(c ORDER BY c.cnt DESC), '[]'::jsonb)
  INTO v_top_categories
  FROM (
    SELECT override_reason_category::text AS category, COUNT(*) AS cnt
    FROM ai_decision_logs
    WHERE was_overridden = true
      AND override_reason_category IS NOT NULL
      AND created_at >= now() - (p_days || ' days')::interval
      AND (p_brand_id IS NULL OR brand_id = p_brand_id)
    GROUP BY override_reason_category
    ORDER BY COUNT(*) DESC
    LIMIT 10
  ) c;

  -- AI call-action proposal outcomes
  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE decision::text = 'approved'),
    COUNT(*) FILTER (WHERE decision::text = 'rejected'),
    COUNT(*) FILTER (WHERE decision::text = 'edited')
  INTO v_proposals_total, v_proposals_approved, v_proposals_rejected, v_proposals_edited
  FROM ai_call_action_decisions
  WHERE decided_at >= now() - (p_days || ' days')::interval
    AND (p_brand_id IS NULL OR brand_id = p_brand_id);

  RETURN jsonb_build_object(
    'period_days', p_days,
    'brand_id', p_brand_id,
    'decisions', jsonb_build_object(
      'total', v_total,
      'overridden', v_overridden,
      'override_rate_pct', ROUND(100.0 * v_overridden / NULLIF(v_total, 0), 2),
      'avg_confidence', v_avg_conf,
      'avg_confidence_when_overridden', v_avg_conf_overridden,
      'top_override_categories', v_top_categories
    ),
    'proposals', jsonb_build_object(
      'total', v_proposals_total,
      'approved', v_proposals_approved,
      'rejected', v_proposals_rejected,
      'edited', v_proposals_edited,
      'approval_rate_pct', ROUND(100.0 * v_proposals_approved / NULLIF(v_proposals_total, 0), 2)
    ),
    'generated_at', now()
  );
END;
$$;


--
-- Name: get_ai_quality_detailed(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_ai_quality_detailed(p_brand_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'override_by_category', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'category', cat,
        'count', cnt
      )), '[]'::jsonb)
      FROM (
        SELECT
          COALESCE(override_reason_category::text, 'unspecified') AS cat,
          COUNT(*) AS cnt
        FROM ai_decision_logs
        WHERE brand_id = p_brand_id
          AND created_at BETWEEN p_from AND p_to
          AND was_overridden = true
        GROUP BY override_reason_category
        ORDER BY cnt DESC
      ) sub
    ),
    'confidence_distribution', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'bucket', bucket,
        'count', cnt,
        'override_count', ov_cnt
      )), '[]'::jsonb)
      FROM (
        SELECT
          CASE
            WHEN confidence IS NULL THEN 'N/A'
            WHEN confidence < 0.3 THEN '0-30%'
            WHEN confidence < 0.6 THEN '30-60%'
            WHEN confidence < 0.8 THEN '60-80%'
            ELSE '80-100%'
          END AS bucket,
          COUNT(*) AS cnt,
          COUNT(*) FILTER (WHERE was_overridden = true) AS ov_cnt
        FROM ai_decision_logs
        WHERE brand_id = p_brand_id
          AND created_at BETWEEN p_from AND p_to
        GROUP BY bucket
        ORDER BY bucket
      ) sub
    ),
    'avg_triage_time_minutes', (
      SELECT COALESCE(
        ROUND(AVG(EXTRACT(EPOCH FROM (overridden_at - created_at)) / 60)::numeric, 1),
        0
      )
      FROM ai_decision_logs
      WHERE brand_id = p_brand_id
        AND created_at BETWEEN p_from AND p_to
        AND was_overridden = true
        AND overridden_at IS NOT NULL
    ),
    'low_confidence_count', (
      SELECT COUNT(*)
      FROM ai_decision_logs d
      JOIN ai_configs c ON c.brand_id = d.brand_id
      WHERE d.brand_id = p_brand_id
        AND d.created_at BETWEEN p_from AND p_to
        AND d.confidence IS NOT NULL
        AND d.confidence < c.confidence_threshold
    ),
    'precision_proxy', (
      SELECT CASE
        WHEN COUNT(*) = 0 THEN NULL
        ELSE ROUND(
          (COUNT(*) FILTER (WHERE was_overridden = false))::numeric / COUNT(*) * 100, 1
        )
      END
      FROM ai_decision_logs
      WHERE brand_id = p_brand_id
        AND created_at BETWEEN p_from AND p_to
    ),
    'weekly_override_trend', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'week', week_start,
        'total', total,
        'overridden', overridden,
        'rate', CASE WHEN total > 0 THEN ROUND(overridden::numeric / total * 100, 1) ELSE 0 END
      ) ORDER BY week_start), '[]'::jsonb)
      FROM (
        SELECT
          date_trunc('week', created_at)::date AS week_start,
          COUNT(*) AS total,
          COUNT(*) FILTER (WHERE was_overridden = true) AS overridden
        FROM ai_decision_logs
        WHERE brand_id = p_brand_id
          AND created_at BETWEEN p_from AND p_to
        GROUP BY week_start
      ) sub
    )
  ) INTO result;

  RETURN result;
END;
$$;


--
-- Name: get_ai_quality_metrics(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_ai_quality_metrics(p_brand_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result JSONB;
  v_total_decisions INTEGER;
  v_overridden_count INTEGER;
  v_feedback_correct INTEGER;
  v_feedback_incorrect INTEGER;
BEGIN
  -- Count total decisions
  SELECT COUNT(*) INTO v_total_decisions
  FROM public.ai_decision_logs
  WHERE brand_id = p_brand_id
    AND created_at BETWEEN p_from AND p_to;

  -- Count overrides
  SELECT COUNT(*) INTO v_overridden_count
  FROM public.ai_decision_logs
  WHERE brand_id = p_brand_id
    AND created_at BETWEEN p_from AND p_to
    AND was_overridden = true;

  -- Count feedback
  SELECT 
    COALESCE(SUM(CASE WHEN label = 'correct' THEN 1 ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN label = 'incorrect' THEN 1 ELSE 0 END), 0)
  INTO v_feedback_correct, v_feedback_incorrect
  FROM public.ai_feedback
  WHERE brand_id = p_brand_id
    AND created_at BETWEEN p_from AND p_to;

  v_result := jsonb_build_object(
    'total_decisions', v_total_decisions,
    'override_count', v_overridden_count,
    'override_rate', CASE WHEN v_total_decisions > 0 
      THEN ROUND((v_overridden_count::numeric / v_total_decisions) * 100, 2)
      ELSE 0 END,
    'feedback_correct', v_feedback_correct,
    'feedback_incorrect', v_feedback_incorrect,
    'feedback_accuracy', CASE WHEN (v_feedback_correct + v_feedback_incorrect) > 0
      THEN ROUND((v_feedback_correct::numeric / (v_feedback_correct + v_feedback_incorrect)) * 100, 2)
      ELSE NULL END
  );

  RETURN v_result;
END;
$$;


--
-- Name: get_appointment_campaign_attribution(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_appointment_campaign_attribution(p_appointment_id uuid) RETURNS TABLE(appointment_id uuid, contact_id uuid, lead_event_id uuid, lead_event_at timestamp with time zone, campaign_id uuid, campaign_name text, campaign_external_id text, group_id uuid, match_type text, channel_id uuid, matched_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_internal_user_id uuid;
  v_brand_id uuid;
  v_authorized boolean := false;
BEGIN
  v_internal_user_id := public.get_user_id(auth.uid());
  IF v_internal_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  SELECT a.brand_id INTO v_brand_id
  FROM public.appointments a
  WHERE a.id = p_appointment_id;

  IF v_brand_id IS NULL THEN
    RETURN;
  END IF;

  -- Re-use existing helper for brand membership check
  SELECT public.user_belongs_to_brand(v_internal_user_id, v_brand_id) INTO v_authorized;
  IF NOT v_authorized THEN
    RAISE EXCEPTION 'Insufficient privileges' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH appt AS (
    SELECT id, contact_id, scheduled_at, created_at
    FROM public.appointments
    WHERE id = p_appointment_id
  ),
  -- last lead_event for the contact created BEFORE the appointment was scheduled (or created)
  picked_event AS (
    SELECT le.id, le.created_at
    FROM public.lead_events le
    JOIN appt a ON a.contact_id = le.contact_id
    WHERE le.created_at <= COALESCE(a.scheduled_at, a.created_at)
    ORDER BY le.created_at DESC
    LIMIT 1
  )
  SELECT
    appt.id,
    appt.contact_id,
    pe.id,
    pe.created_at,
    mc.id,
    mc.name,
    mc.external_id,
    lca.group_id,
    lca.match_type,
    mc.channel_id,
    lca.matched_at
  FROM appt
  LEFT JOIN picked_event pe ON true
  LEFT JOIN public.lead_campaign_attribution lca ON lca.lead_event_id = pe.id
  LEFT JOIN public.marketing_campaigns mc ON mc.id = lca.campaign_id
  LIMIT 1;
END;
$$;


--
-- Name: get_appointments_by_campaign(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_appointments_by_campaign(p_brand_id uuid, p_from_date date, p_to_date date) RETURNS TABLE(campaign_id uuid, campaign_name text, channel_id uuid, external_id text, total_appointments bigint, scheduled_count bigint, completed_count bigint, cancelled_count bigint, no_show_count bigint, unique_contacts bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_internal_user_id uuid;
  v_authorized boolean := false;
BEGIN
  IF p_from_date > p_to_date THEN
    RAISE EXCEPTION 'from_date must be <= to_date' USING ERRCODE = '22023';
  END IF;
  IF (p_to_date - p_from_date) > 366 THEN
    RAISE EXCEPTION 'Date range cannot exceed 366 days' USING ERRCODE = '22023';
  END IF;

  v_internal_user_id := public.get_user_id(auth.uid());
  IF v_internal_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.user_roles ur
    WHERE ur.user_id = v_internal_user_id
      AND ur.is_active = true
      AND ur.role IN ('admin', 'ceo', 'responsabile_venditori')
      AND (
        ur.brand_id = p_brand_id
        OR ur.brand_id = '00000000-0000-0000-0000-000000000000'::uuid
      )
  ) INTO v_authorized;

  IF NOT v_authorized THEN
    RAISE EXCEPTION 'Insufficient privileges' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH appt_window AS (
    SELECT a.id, a.contact_id, a.status, a.last_outcome_code, a.scheduled_at, a.created_at
    FROM public.appointments a
    WHERE a.brand_id = p_brand_id
      AND a.created_at::date >= p_from_date
      AND a.created_at::date <= p_to_date
  ),
  resolved AS (
    SELECT
      aw.id AS appointment_id,
      aw.contact_id,
      aw.status,
      (
        SELECT lca.campaign_id
        FROM public.lead_events le
        JOIN public.lead_campaign_attribution lca ON lca.lead_event_id = le.id
        WHERE le.contact_id = aw.contact_id
          AND le.created_at <= COALESCE(aw.scheduled_at, aw.created_at)
          AND lca.brand_id = p_brand_id
        ORDER BY le.created_at DESC
        LIMIT 1
      ) AS campaign_id
    FROM appt_window aw
  )
  SELECT
    mc.id,
    mc.name,
    mc.channel_id,
    mc.external_id,
    COUNT(*)::bigint,
    COUNT(*) FILTER (WHERE r.status = 'scheduled')::bigint,
    COUNT(*) FILTER (WHERE r.status = 'completed')::bigint,
    COUNT(*) FILTER (WHERE r.status = 'cancelled')::bigint,
    COUNT(*) FILTER (WHERE r.status = 'no_show')::bigint,
    COUNT(DISTINCT r.contact_id)::bigint
  FROM resolved r
  LEFT JOIN public.marketing_campaigns mc ON mc.id = r.campaign_id
  WHERE mc.id IS NOT NULL
  GROUP BY mc.id, mc.name, mc.channel_id, mc.external_id
  ORDER BY COUNT(*) DESC
  LIMIT 500;
END;
$$;


--
-- Name: get_appointments_ops_kpi(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_appointments_ops_kpi(p_brand_id uuid, p_date_from timestamp with time zone, p_date_to timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_total int;
  v_status_breakdown jsonb;
  v_outcome_breakdown jsonb;
  v_executed int;
  v_no_show int;
  v_at_risk int;
  v_follow_up int;
  v_avg_risk_score numeric;
BEGIN
  -- Totale appuntamenti nella finestra
  SELECT COUNT(*) INTO v_total
  FROM public.appointments
  WHERE brand_id = p_brand_id
    AND scheduled_at >= p_date_from
    AND scheduled_at < p_date_to;

  -- Distribuzione per status
  SELECT COALESCE(jsonb_object_agg(status, cnt), '{}'::jsonb) INTO v_status_breakdown
  FROM (
    SELECT status::text AS status, COUNT(*)::int AS cnt
    FROM public.appointments
    WHERE brand_id = p_brand_id
      AND scheduled_at >= p_date_from
      AND scheduled_at < p_date_to
    GROUP BY status
    LIMIT 1000
  ) s;

  -- Distribuzione outcomes
  SELECT COALESCE(jsonb_object_agg(outcome_code, cnt), '{}'::jsonb) INTO v_outcome_breakdown
  FROM (
    SELECT outcome_code::text AS outcome_code, COUNT(*)::int AS cnt
    FROM public.appointment_outcomes ao
    JOIN public.appointments a ON a.id = ao.appointment_id
    WHERE ao.brand_id = p_brand_id
      AND a.scheduled_at >= p_date_from
      AND a.scheduled_at < p_date_to
    GROUP BY outcome_code
    LIMIT 1000
  ) o;

  v_executed := COALESCE((v_outcome_breakdown->>'executed')::int, 0);
  v_no_show := COALESCE((v_outcome_breakdown->>'no_show_client')::int, 0)
             + COALESCE((v_outcome_breakdown->>'no_show_operator')::int, 0);

  -- A rischio: appuntamenti nelle prossime 48h ancora non confermati
  SELECT COUNT(*) INTO v_at_risk
  FROM public.appointments
  WHERE brand_id = p_brand_id
    AND scheduled_at >= now()
    AND scheduled_at < now() + interval '48 hours'
    AND status IN ('scheduled', 'draft');

  -- Follow-up: outcomes registrati ultimi 7gg con next_action presente
  SELECT COUNT(*) INTO v_follow_up
  FROM public.appointment_outcomes
  WHERE brand_id = p_brand_id
    AND recorded_at >= now() - interval '7 days'
    AND next_action IS NOT NULL
    AND length(trim(next_action)) > 0;

  -- Risk score medio (se popolato)
  SELECT AVG(risk_score) INTO v_avg_risk_score
  FROM public.appointments
  WHERE brand_id = p_brand_id
    AND scheduled_at >= p_date_from
    AND scheduled_at < p_date_to
    AND risk_score IS NOT NULL;

  RETURN jsonb_build_object(
    'total', v_total,
    'status_breakdown', v_status_breakdown,
    'outcome_breakdown', v_outcome_breakdown,
    'executed_count', v_executed,
    'no_show_count', v_no_show,
    'execution_rate', CASE WHEN v_total > 0 THEN ROUND((v_executed::numeric / v_total) * 100, 1) ELSE 0 END,
    'no_show_rate', CASE WHEN v_total > 0 THEN ROUND((v_no_show::numeric / v_total) * 100, 1) ELSE 0 END,
    'at_risk_next_48h', v_at_risk,
    'pending_follow_up', v_follow_up,
    'avg_risk_score', COALESCE(ROUND(v_avg_risk_score, 2), 0)
  );
END;
$$;


--
-- Name: get_assignable_roles(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_assignable_roles(p_brand_id uuid) RETURNS TABLE(role_value public.app_role, role_label text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller_role app_role;
BEGIN
  SELECT ur.role INTO v_caller_role
  FROM user_roles ur
  WHERE ur.user_id = get_user_id(auth.uid())
    AND ur.brand_id = p_brand_id
    AND ur.is_active = true
  ORDER BY get_role_level(ur.role) DESC
  LIMIT 1;

  RETURN QUERY
  SELECT r.role_value, r.role_label
  FROM (VALUES 
    ('ceo'::app_role, 'CEO'),
    ('responsabile_venditori'::app_role, 'Responsabile Venditori'),
    ('responsabile_callcenter'::app_role, 'Responsabile Call Center'),
    ('venditore'::app_role, 'Venditore'),
    ('operatore_callcenter'::app_role, 'Operatore Call Center')
  ) AS r(role_value, role_label)
  WHERE can_manage_role(v_caller_role, r.role_value);
END;
$$;


--
-- Name: get_attribution_summary(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_attribution_summary(p_brand_id uuid, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(total_leads bigint, exact_count bigint, group_count bigint, unmapped_count bigint, match_rate numeric, overall_cpl numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    COUNT(*)::BIGINT AS total_leads,
    COUNT(*) FILTER (WHERE lca.match_type = 'exact')::BIGINT,
    COUNT(*) FILTER (WHERE lca.match_type = 'group')::BIGINT,
    COUNT(*) FILTER (WHERE lca.match_type = 'unmapped')::BIGINT,
    CASE WHEN COUNT(*) > 0
         THEN ROUND(100.0 * COUNT(*) FILTER (WHERE lca.match_type != 'unmapped') / COUNT(*), 1)
         ELSE 0
    END,
    CASE WHEN COUNT(*) FILTER (WHERE lca.match_type != 'unmapped') > 0
         THEN ROUND(
           COALESCE((
             SELECT SUM(mco.amount)
             FROM marketing_costs mco
             WHERE mco.brand_id = p_brand_id
               AND (p_from IS NULL OR mco.cost_date >= p_from::date)
               AND (p_to IS NULL OR mco.cost_date <= p_to::date)
           ), 0) / COUNT(*) FILTER (WHERE lca.match_type != 'unmapped'), 2)
         ELSE 0
    END
  FROM lead_campaign_attribution lca
  WHERE lca.brand_id = p_brand_id
    AND (p_from IS NULL OR lca.matched_at >= p_from)
    AND (p_to IS NULL OR lca.matched_at <= p_to);
END;
$$;


--
-- Name: get_audit_access_log(uuid, timestamp with time zone, timestamp with time zone, text, uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_audit_access_log(p_brand_id uuid, p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_access_type text DEFAULT NULL::text, p_user_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_from timestamptz := COALESCE(p_date_from, now() - interval '30 days');
  v_to   timestamptz := COALESCE(p_date_to, now());
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 100), 1), 500);
  v_offset integer := GREATEST(COALESCE(p_offset, 0), 0);
  v_total integer;
  v_events jsonb;
  v_by_type jsonb;
  v_by_user jsonb;
BEGIN
  -- Admin-only
  IF NOT public.is_audit_admin(auth.uid()) THEN
    RAISE EXCEPTION 'access denied: audit admin required';
  END IF;

  -- Total
  SELECT COUNT(*) INTO v_total
  FROM public.audit_access_log al
  WHERE (p_brand_id IS NULL OR al.brand_id = p_brand_id)
    AND al.accessed_at >= v_from
    AND al.accessed_at <= v_to
    AND (p_access_type IS NULL OR al.access_type = p_access_type)
    AND (p_user_id IS NULL OR al.accessed_by = p_user_id);

  -- Page of events
  SELECT COALESCE(jsonb_agg(row_to_json(t) ORDER BY t.accessed_at DESC), '[]'::jsonb)
  INTO v_events
  FROM (
    SELECT al.id, al.brand_id, al.accessed_by, al.accessed_by_display_name,
           al.access_type, al.filters, al.result_count, al.reason,
           al.user_agent, al.accessed_at
    FROM public.audit_access_log al
    WHERE (p_brand_id IS NULL OR al.brand_id = p_brand_id)
      AND al.accessed_at >= v_from
      AND al.accessed_at <= v_to
      AND (p_access_type IS NULL OR al.access_type = p_access_type)
      AND (p_user_id IS NULL OR al.accessed_by = p_user_id)
    ORDER BY al.accessed_at DESC
    LIMIT v_limit OFFSET v_offset
  ) t;

  -- Aggregate: by access_type
  SELECT COALESCE(jsonb_agg(row_to_json(t) ORDER BY t.count DESC), '[]'::jsonb)
  INTO v_by_type
  FROM (
    SELECT al.access_type, COUNT(*)::int AS count
    FROM public.audit_access_log al
    WHERE (p_brand_id IS NULL OR al.brand_id = p_brand_id)
      AND al.accessed_at >= v_from
      AND al.accessed_at <= v_to
    GROUP BY al.access_type
  ) t;

  -- Aggregate: top users (max 10)
  SELECT COALESCE(jsonb_agg(row_to_json(t) ORDER BY t.count DESC), '[]'::jsonb)
  INTO v_by_user
  FROM (
    SELECT al.accessed_by AS user_id,
           MAX(al.accessed_by_display_name) AS display_name,
           COUNT(*)::int AS count,
           MAX(al.accessed_at) AS last_access_at
    FROM public.audit_access_log al
    WHERE (p_brand_id IS NULL OR al.brand_id = p_brand_id)
      AND al.accessed_at >= v_from
      AND al.accessed_at <= v_to
    GROUP BY al.accessed_by
    ORDER BY count DESC
    LIMIT 10
  ) t;

  RETURN jsonb_build_object(
    'total', v_total,
    'limit', v_limit,
    'offset', v_offset,
    'events', v_events,
    'by_access_type', v_by_type,
    'top_users', v_by_user,
    'date_from', v_from,
    'date_to', v_to
  );
END;
$$;


--
-- Name: get_audit_dashboard_stats(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_audit_dashboard_stats(p_brand_id uuid, p_date_from timestamp with time zone DEFAULT (now() - '30 days'::interval), p_date_to timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_total bigint;
  v_by_action jsonb;
  v_by_entity jsonb;
  v_by_actor jsonb;
  v_by_day jsonb;
BEGIN
  IF NOT public.can_view_audit(auth.uid()) THEN
    RAISE EXCEPTION 'Insufficient permissions';
  END IF;

  SELECT count(*) INTO v_total
  FROM public.audit_events
  WHERE brand_id = p_brand_id
    AND occurred_at BETWEEN p_date_from AND p_date_to;

  SELECT COALESCE(jsonb_agg(jsonb_build_object('action', action, 'count', cnt) ORDER BY cnt DESC), '[]'::jsonb)
  INTO v_by_action
  FROM (
    SELECT action, count(*)::bigint as cnt
    FROM public.audit_events
    WHERE brand_id = p_brand_id AND occurred_at BETWEEN p_date_from AND p_date_to
    GROUP BY action
    ORDER BY cnt DESC LIMIT 15
  ) s;

  SELECT COALESCE(jsonb_agg(jsonb_build_object('entity_type', entity_type, 'count', cnt) ORDER BY cnt DESC), '[]'::jsonb)
  INTO v_by_entity
  FROM (
    SELECT entity_type, count(*)::bigint as cnt
    FROM public.audit_events
    WHERE brand_id = p_brand_id AND occurred_at BETWEEN p_date_from AND p_date_to
    GROUP BY entity_type
    ORDER BY cnt DESC
  ) s;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'actor_user_id', actor_user_id,
    'actor_display_name', actor_display_name,
    'count', cnt
  ) ORDER BY cnt DESC), '[]'::jsonb)
  INTO v_by_actor
  FROM (
    SELECT actor_user_id, actor_display_name, count(*)::bigint as cnt
    FROM public.audit_events
    WHERE brand_id = p_brand_id AND occurred_at BETWEEN p_date_from AND p_date_to
      AND actor_user_id IS NOT NULL
    GROUP BY actor_user_id, actor_display_name
    ORDER BY cnt DESC LIMIT 20
  ) s;

  SELECT COALESCE(jsonb_agg(jsonb_build_object('day', day, 'count', cnt) ORDER BY day), '[]'::jsonb)
  INTO v_by_day
  FROM (
    SELECT date_trunc('day', occurred_at)::date as day, count(*)::bigint as cnt
    FROM public.audit_events
    WHERE brand_id = p_brand_id AND occurred_at BETWEEN p_date_from AND p_date_to
    GROUP BY day
    ORDER BY day
  ) s;

  RETURN jsonb_build_object(
    'total', v_total,
    'by_action', v_by_action,
    'by_entity', v_by_entity,
    'by_actor', v_by_actor,
    'by_day', v_by_day
  );
END;
$$;


--
-- Name: get_audit_pii_policies_for_role(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_audit_pii_policies_for_role() RETURNS TABLE(field_pattern text, strategy text, description text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid;
  v_user_id uuid;
  v_roles text[];
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RETURN;
  END IF;

  -- Audit viewers only (mirrors can_view_audit gate)
  IF NOT public.can_view_audit(v_uid) THEN
    RETURN;
  END IF;

  v_user_id := public.get_user_id(v_uid);

  SELECT array_agg(DISTINCT ur.role::text)
    INTO v_roles
  FROM public.user_roles ur
  WHERE ur.user_id = v_user_id;

  v_roles := COALESCE(v_roles, ARRAY[]::text[]);

  RETURN QUERY
  SELECT
    p.field_pattern,
    CASE
      WHEN v_roles && p.exempt_roles THEN 'none'
      ELSE p.strategy
    END AS strategy,
    p.description
  FROM public.audit_pii_policies p
  WHERE p.is_active = true
    AND (
      v_roles && p.exempt_roles
      OR p.strategy <> 'none'
    );
END;
$$;


--
-- Name: get_auth_user_id_by_email(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_auth_user_id_by_email(p_email text) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
  SELECT id
  FROM auth.users
  WHERE lower(email) = lower(p_email)
  LIMIT 1;
$$;


--
-- Name: get_backup_schedules(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_backup_schedules() RETURNS TABLE(id uuid, brand_id uuid, brand_name text, scope text, frequency text, hour_utc integer, day_of_week integer, retention_days integer, enabled boolean, last_run_at timestamp with time zone, last_run_status text, next_run_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT (
    public.has_role(public.get_user_id(auth.uid()), 'admin'::app_role)
    OR public.has_role(public.get_user_id(auth.uid()), 'ceo'::app_role)
  ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY
  SELECT s.id, s.brand_id, b.name AS brand_name, s.scope, s.frequency,
         s.hour_utc, s.day_of_week, s.retention_days, s.enabled,
         s.last_run_at, s.last_run_status, s.next_run_at,
         s.created_at, s.updated_at
  FROM public.backup_schedules s
  LEFT JOIN public.brands b ON b.id = s.brand_id
  ORDER BY b.name NULLS LAST
  LIMIT 500;
END;
$$;


--
-- Name: get_board_slo_metrics(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_board_slo_metrics(p_brand_id uuid DEFAULT NULL::uuid, p_month_start timestamp with time zone DEFAULT date_trunc('month'::text, now())) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_month_end timestamptz := p_month_start + interval '1 month';
  v_result jsonb;
  v_ingest_total bigint;
  v_ingest_success bigint;
  v_ingest_availability numeric;
  v_tickets_total bigint;
  v_tickets_within_sla bigint;
  v_sla_compliance numeric;
  v_mttr_avg_hours numeric;
  v_ai_total bigint;
  v_ai_completed bigint;
  v_ai_success_rate numeric;
  v_ai_override_count bigint;
  v_ai_total_decisions bigint;
  v_ai_override_rate numeric;
  v_wh_total bigint;
  v_wh_success bigint;
  v_wh_delivery_rate numeric;
  v_wh_dlq bigint;
  v_wh_dlq_rate numeric;
  v_deal_avg_days numeric;
  v_deal_median_days numeric;
  v_deals_closed bigint;
  v_total_leads bigint;
  v_total_deals bigint;
  v_conversion_rate numeric;
BEGIN
  -- 1. Ingest Availability (exclude rejected/duplicates — intentional behavior)
  SELECT
    COUNT(*) FILTER (WHERE status != 'rejected'),
    COUNT(*) FILTER (WHERE status = 'success')
  INTO v_ingest_total, v_ingest_success
  FROM incoming_requests
  WHERE created_at >= p_month_start AND created_at < v_month_end
    AND (p_brand_id IS NULL OR brand_id = p_brand_id);

  v_ingest_availability := CASE WHEN v_ingest_total > 0
    THEN ROUND(v_ingest_success::numeric / v_ingest_total * 100, 2)
    ELSE 100 END;

  -- 2. Ticket SLA Compliance
  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE sla_breached_at IS NULL OR resolved_at < sla_breached_at)
  INTO v_tickets_total, v_tickets_within_sla
  FROM tickets
  WHERE created_at >= p_month_start AND created_at < v_month_end
    AND (p_brand_id IS NULL OR brand_id = p_brand_id);

  v_sla_compliance := CASE WHEN v_tickets_total > 0
    THEN ROUND(v_tickets_within_sla::numeric / v_tickets_total * 100, 1)
    ELSE 100 END;

  SELECT
    ROUND(AVG(EXTRACT(EPOCH FROM (resolved_at - created_at)) / 3600)::numeric, 1)
  INTO v_mttr_avg_hours
  FROM tickets
  WHERE resolved_at IS NOT NULL
    AND created_at >= p_month_start AND created_at < v_month_end
    AND (p_brand_id IS NULL OR brand_id = p_brand_id);

  -- 3. AI Success Rate
  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE status = 'completed')
  INTO v_ai_total, v_ai_completed
  FROM ai_jobs
  WHERE created_at >= p_month_start AND created_at < v_month_end
    AND (p_brand_id IS NULL OR brand_id = p_brand_id);

  v_ai_success_rate := CASE WHEN v_ai_total > 0
    THEN ROUND(v_ai_completed::numeric / v_ai_total * 100, 1)
    ELSE 100 END;

  SELECT
    COUNT(*) FILTER (WHERE was_overridden = true),
    COUNT(*)
  INTO v_ai_override_count, v_ai_total_decisions
  FROM ai_decision_logs
  WHERE created_at >= p_month_start AND created_at < v_month_end
    AND (p_brand_id IS NULL OR brand_id = p_brand_id);

  v_ai_override_rate := CASE WHEN v_ai_total_decisions > 0
    THEN ROUND(v_ai_override_count::numeric / v_ai_total_decisions * 100, 1)
    ELSE 0 END;

  -- 4. Webhook Delivery Rate
  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE status = 'success'),
    COUNT(*) FILTER (WHERE dead_at IS NOT NULL)
  INTO v_wh_total, v_wh_success, v_wh_dlq
  FROM outbound_webhook_deliveries
  WHERE created_at >= p_month_start AND created_at < v_month_end
    AND (p_brand_id IS NULL OR brand_id = p_brand_id);

  v_wh_delivery_rate := CASE WHEN v_wh_total > 0
    THEN ROUND(v_wh_success::numeric / v_wh_total * 100, 1)
    ELSE 100 END;

  v_wh_dlq_rate := CASE WHEN v_wh_total > 0
    THEN ROUND(v_wh_dlq::numeric / v_wh_total * 100, 1)
    ELSE 0 END;

  -- 5. Deal Velocity
  SELECT
    COUNT(*),
    ROUND(AVG(EXTRACT(EPOCH FROM (closed_at - created_at)) / 86400)::numeric, 1),
    ROUND(PERCENTILE_CONT(0.5) WITHIN GROUP (
      ORDER BY EXTRACT(EPOCH FROM (closed_at - created_at)) / 86400
    )::numeric, 1)
  INTO v_deals_closed, v_deal_avg_days, v_deal_median_days
  FROM deals
  WHERE closed_at IS NOT NULL AND status = 'won'
    AND created_at >= p_month_start AND created_at < v_month_end
    AND (p_brand_id IS NULL OR brand_id = p_brand_id);

  -- 6. Lead → Deal Conversion
  SELECT COUNT(DISTINCT id) INTO v_total_leads
  FROM contacts
  WHERE created_at >= p_month_start AND created_at < v_month_end
    AND (p_brand_id IS NULL OR brand_id = p_brand_id);

  SELECT COUNT(DISTINCT d.contact_id) INTO v_total_deals
  FROM deals d
  JOIN contacts c ON d.contact_id = c.id
  WHERE c.created_at >= p_month_start AND c.created_at < v_month_end
    AND d.status NOT IN ('lost')
    AND (p_brand_id IS NULL OR d.brand_id = p_brand_id);

  v_conversion_rate := CASE WHEN v_total_leads > 0
    THEN ROUND(v_total_deals::numeric / v_total_leads * 100, 1)
    ELSE 0 END;

  v_result := jsonb_build_object(
    'period', jsonb_build_object('start', p_month_start, 'end', v_month_end),
    'engineering', jsonb_build_object(
      'ingest_availability', jsonb_build_object(
        'value', v_ingest_availability, 'target', 99.5, 'unit', '%',
        'total', v_ingest_total, 'success', v_ingest_success
      ),
      'ai_success_rate', jsonb_build_object(
        'value', v_ai_success_rate, 'target', 95, 'unit', '%',
        'total', v_ai_total, 'completed', v_ai_completed
      ),
      'webhook_delivery_rate', jsonb_build_object(
        'value', v_wh_delivery_rate, 'target', 95, 'unit', '%',
        'total', v_wh_total, 'success', v_wh_success, 'dlq', v_wh_dlq,
        'dlq_rate', v_wh_dlq_rate
      )
    ),
    'cx_ops', jsonb_build_object(
      'sla_compliance', jsonb_build_object(
        'value', v_sla_compliance, 'target', 90, 'unit', '%',
        'total', v_tickets_total, 'within_sla', v_tickets_within_sla
      ),
      'mttr_hours', jsonb_build_object(
        'value', COALESCE(v_mttr_avg_hours, 0), 'target', 4, 'unit', 'h',
        'direction', 'lower_is_better'
      ),
      'ai_override_rate', jsonb_build_object(
        'value', v_ai_override_rate, 'target', 15, 'unit', '%',
        'direction', 'lower_is_better',
        'overrides', v_ai_override_count, 'total', v_ai_total_decisions
      )
    ),
    'sales_ops', jsonb_build_object(
      'lead_conversion', jsonb_build_object(
        'value', v_conversion_rate, 'target', 15, 'unit', '%',
        'total_leads', v_total_leads, 'converted', v_total_deals
      ),
      'deal_velocity', jsonb_build_object(
        'value', COALESCE(v_deal_avg_days, 0), 'target', 30, 'unit', 'gg',
        'direction', 'lower_is_better',
        'median', COALESCE(v_deal_median_days, 0), 'closed', v_deals_closed
      )
    )
  );

  RETURN v_result;
END;
$$;


--
-- Name: get_brand_operators(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_brand_operators(p_brand_id uuid) RETURNS TABLE(user_id uuid, supabase_auth_id uuid, full_name text, email text, role text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT 
    u.id as user_id,
    u.supabase_auth_id,
    u.full_name,
    u.email,
    ur.role::text
  FROM users u
  JOIN user_roles ur ON ur.user_id = u.id
  WHERE ur.brand_id = p_brand_id
    AND ur.role IN ('callcenter', 'sales', 'admin')
  ORDER BY u.full_name;
$$;


--
-- Name: get_brands_with_hierarchy(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_brands_with_hierarchy(p_user_id uuid) RETURNS TABLE(id uuid, name text, slug text, parent_brand_id uuid, parent_brand_name text, is_parent boolean, child_count integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH accessible AS (
    SELECT unnest(public.get_accessible_brand_ids(p_user_id)) AS brand_id
  ),
  child_counts AS (
    SELECT parent_brand_id, COUNT(*) as cnt
    FROM brands
    WHERE parent_brand_id IS NOT NULL
    GROUP BY parent_brand_id
  )
  SELECT 
    b.id,
    b.name,
    b.slug,
    b.parent_brand_id,
    pb.name as parent_brand_name,
    COALESCE(cc.cnt, 0) > 0 as is_parent,
    COALESCE(cc.cnt, 0)::integer as child_count
  FROM brands b
  JOIN accessible a ON a.brand_id = b.id
  LEFT JOIN brands pb ON pb.id = b.parent_brand_id
  LEFT JOIN child_counts cc ON cc.parent_brand_id = b.id
  ORDER BY b.name;
$$;


--
-- Name: get_call_center_telephony_kpis(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_call_center_telephony_kpis(p_brand_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  result json;
BEGIN
  SELECT json_build_object(
    'total_calls', COUNT(*),
    'answered_calls', COUNT(*) FILTER (WHERE status = 'completed' OR status = 'answered'),
    'missed_calls', COUNT(*) FILTER (WHERE status = 'no_answer' OR outcome = 'missed'),
    'failed_calls', COUNT(*) FILTER (WHERE status = 'failed'),
    'busy_calls', COUNT(*) FILTER (WHERE status = 'busy'),
    'answered_rate', CASE WHEN COUNT(*) > 0
      THEN ROUND((COUNT(*) FILTER (WHERE status = 'completed' OR status = 'answered'))::numeric / COUNT(*)::numeric * 100, 1)
      ELSE 0 END,
    'avg_duration_seconds', ROUND(AVG(duration_seconds) FILTER (WHERE duration_seconds IS NOT NULL AND duration_seconds > 0)),
    'p90_duration_seconds', PERCENTILE_CONT(0.9) WITHIN GROUP (ORDER BY duration_seconds) FILTER (WHERE duration_seconds IS NOT NULL AND duration_seconds > 0),
    'avg_response_time_seconds', ROUND(AVG(response_time_seconds) FILTER (WHERE response_time_seconds IS NOT NULL AND response_time_seconds > 0)),
    'p90_response_time_seconds', PERCENTILE_CONT(0.9) WITHIN GROUP (ORDER BY response_time_seconds) FILTER (WHERE response_time_seconds IS NOT NULL AND response_time_seconds > 0),
    'by_operator', (
      SELECT COALESCE(json_agg(op_row), '[]'::json)
      FROM (
        SELECT
          cl2.user_id,
          u.full_name,
          COUNT(*) as total,
          COUNT(*) FILTER (WHERE cl2.status = 'completed' OR cl2.status = 'answered') as answered,
          ROUND(AVG(cl2.duration_seconds) FILTER (WHERE cl2.duration_seconds IS NOT NULL AND cl2.duration_seconds > 0)) as avg_duration,
          ROUND(AVG(cl2.response_time_seconds) FILTER (WHERE cl2.response_time_seconds IS NOT NULL AND cl2.response_time_seconds > 0)) as avg_response_time
        FROM call_logs cl2
        JOIN users u ON u.id = cl2.user_id
        WHERE cl2.brand_id = p_brand_id
          AND cl2.started_at >= p_from
          AND cl2.started_at <= p_to
        GROUP BY cl2.user_id, u.full_name
        ORDER BY total DESC
      ) op_row
    ),
    'daily_trend', (
      SELECT COALESCE(json_agg(dt_row ORDER BY dt_row.call_date), '[]'::json)
      FROM (
        SELECT
          DATE(cl3.started_at) as call_date,
          COUNT(*) as total,
          COUNT(*) FILTER (WHERE cl3.status = 'completed' OR cl3.status = 'answered') as answered,
          COUNT(*) FILTER (WHERE cl3.status = 'no_answer' OR cl3.outcome = 'missed') as missed
        FROM call_logs cl3
        WHERE cl3.brand_id = p_brand_id
          AND cl3.started_at >= p_from
          AND cl3.started_at <= p_to
        GROUP BY DATE(cl3.started_at)
      ) dt_row
    )
  ) INTO result
  FROM call_logs cl
  WHERE cl.brand_id = p_brand_id
    AND cl.started_at >= p_from
    AND cl.started_at <= p_to;

  RETURN result;
END;
$$;


--
-- Name: get_callcenter_kpis_by_operator(uuid[], timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_callcenter_kpis_by_operator(p_brand_ids uuid[], p_from timestamp with time zone, p_to timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  result jsonb;
BEGIN
  SELECT COALESCE(jsonb_agg(row_data), '[]'::jsonb)
  INTO result
  FROM (
    SELECT jsonb_build_object(
      'user_id', u.id,
      'full_name', u.full_name,
      'email', u.email,
      'role', u.role,
      'tickets_assigned', COALESCE((
        SELECT count(*) FROM tickets t
        WHERE t.assigned_to_user_id = u.id
          AND t.brand_id = ANY(p_brand_ids)
          AND t.assigned_at >= p_from AND t.assigned_at <= p_to
      ), 0),
      'tickets_resolved', COALESCE((
        SELECT count(*) FROM tickets t
        WHERE t.assigned_to_user_id = u.id
          AND t.brand_id = ANY(p_brand_ids)
          AND t.resolved_at >= p_from AND t.resolved_at <= p_to
      ), 0),
      'tickets_closed', COALESCE((
        SELECT count(*) FROM tickets t
        WHERE t.assigned_to_user_id = u.id
          AND t.brand_id = ANY(p_brand_ids)
          AND t.status = 'closed'
          AND t.updated_at >= p_from AND t.updated_at <= p_to
      ), 0),
      'avg_time_to_assign_minutes', COALESCE((
        SELECT round(avg(EXTRACT(EPOCH FROM (t.assigned_at - t.opened_at)) / 60)::numeric, 1)
        FROM tickets t
        WHERE t.assigned_to_user_id = u.id
          AND t.brand_id = ANY(p_brand_ids)
          AND t.assigned_at IS NOT NULL
          AND t.opened_at >= p_from AND t.opened_at <= p_to
      ), 0),
      'avg_time_to_resolve_minutes', COALESCE((
        SELECT round(avg(EXTRACT(EPOCH FROM (t.resolved_at - t.opened_at)) / 60)::numeric, 1)
        FROM tickets t
        WHERE t.assigned_to_user_id = u.id
          AND t.brand_id = ANY(p_brand_ids)
          AND t.resolved_at IS NOT NULL
          AND t.opened_at >= p_from AND t.opened_at <= p_to
      ), 0),
      'backlog_current', COALESCE((
        SELECT count(*) FROM tickets t
        WHERE t.assigned_to_user_id = u.id
          AND t.brand_id = ANY(p_brand_ids)
          AND t.status IN ('open', 'in_progress', 'reopened')
      ), 0)
    ) as row_data
    FROM users u
    WHERE u.role IN ('operatore_callcenter', 'responsabile_callcenter', 'callcenter', 'admin')
      AND EXISTS (
        SELECT 1 FROM user_brand_assignments uba
        WHERE uba.user_id = u.id
          AND uba.brand_id = ANY(p_brand_ids)
      )
    ORDER BY u.full_name NULLS LAST
  ) sub;

  RETURN result;
END;
$$;


--
-- Name: get_callcenter_kpis_overview(uuid[], timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_callcenter_kpis_overview(p_brand_ids uuid[], p_from timestamp with time zone, p_to timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'tickets_created', COALESCE((
      SELECT count(*) FROM tickets
      WHERE brand_id = ANY(p_brand_ids)
        AND opened_at >= p_from AND opened_at <= p_to
    ), 0),
    'tickets_assigned', COALESCE((
      SELECT count(*) FROM tickets
      WHERE brand_id = ANY(p_brand_ids)
        AND assigned_at >= p_from AND assigned_at <= p_to
    ), 0),
    'tickets_resolved', COALESCE((
      SELECT count(*) FROM tickets
      WHERE brand_id = ANY(p_brand_ids)
        AND resolved_at >= p_from AND resolved_at <= p_to
    ), 0),
    'tickets_closed', COALESCE((
      SELECT count(*) FROM tickets
      WHERE brand_id = ANY(p_brand_ids)
        AND status = 'closed'
        AND updated_at >= p_from AND updated_at <= p_to
    ), 0),
    'avg_time_to_assign_minutes', COALESCE((
      SELECT round(avg(EXTRACT(EPOCH FROM (assigned_at - opened_at)) / 60)::numeric, 1)
      FROM tickets
      WHERE brand_id = ANY(p_brand_ids)
        AND assigned_at IS NOT NULL
        AND opened_at >= p_from AND opened_at <= p_to
    ), 0),
    'avg_time_to_resolve_minutes', COALESCE((
      SELECT round(avg(EXTRACT(EPOCH FROM (resolved_at - opened_at)) / 60)::numeric, 1)
      FROM tickets
      WHERE brand_id = ANY(p_brand_ids)
        AND resolved_at IS NOT NULL
        AND opened_at >= p_from AND opened_at <= p_to
    ), 0),
    'backlog_total', COALESCE((
      SELECT count(*) FROM tickets
      WHERE brand_id = ANY(p_brand_ids)
        AND status IN ('open', 'in_progress', 'reopened')
    ), 0),
    'unassigned_now', COALESCE((
      SELECT count(*) FROM tickets
      WHERE brand_id = ANY(p_brand_ids)
        AND status IN ('open', 'in_progress', 'reopened')
        AND assigned_to_user_id IS NULL
    ), 0),
    'priority_distribution', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('priority', priority, 'count', cnt))
      FROM (
        SELECT priority, count(*)::int as cnt
        FROM tickets
        WHERE brand_id = ANY(p_brand_ids)
          AND status IN ('open', 'in_progress', 'reopened')
        GROUP BY priority
        ORDER BY priority
      ) sub
    ), '[]'::jsonb),
    'status_distribution', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('status', status::text, 'count', cnt))
      FROM (
        SELECT status, count(*)::int as cnt
        FROM tickets
        WHERE brand_id = ANY(p_brand_ids)
          AND opened_at >= p_from AND opened_at <= p_to
        GROUP BY status
        ORDER BY status
      ) sub
    ), '[]'::jsonb),
    'daily_trend', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('date', d, 'created', created_cnt, 'resolved', resolved_cnt))
      FROM (
        SELECT
          d::date::text as d,
          COALESCE((SELECT count(*) FROM tickets WHERE brand_id = ANY(p_brand_ids) AND opened_at::date = d::date), 0)::int as created_cnt,
          COALESCE((SELECT count(*) FROM tickets WHERE brand_id = ANY(p_brand_ids) AND resolved_at::date = d::date), 0)::int as resolved_cnt
        FROM generate_series(p_from::date, p_to::date, '1 day'::interval) d
        ORDER BY d
      ) sub
    ), '[]'::jsonb)
  ) INTO result;

  RETURN result;
END;
$$;


--
-- Name: get_ceo_dashboard_kpis(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_ceo_dashboard_kpis(p_brand_id uuid, p_from date, p_to date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_is_system_brand boolean;
  v_brand_ids uuid[];
  
  -- Revenue
  v_revenue_total numeric := 0;
  v_revenue_won_deals numeric := 0;
  v_prev_revenue numeric := 0;
  
  -- Costs
  v_costs_total numeric := 0;
  v_costs_direct numeric := 0;
  v_costs_indirect numeric := 0;
  v_costs_personnel numeric := 0;
  v_costs_marketing numeric := 0;
  v_prev_costs numeric := 0;
  v_costs_by_center jsonb := '[]'::jsonb;
  v_costs_by_category jsonb := '[]'::jsonb;
  
  -- Margins
  v_gross_margin numeric := 0;
  v_operating_margin numeric := 0;
  v_gross_margin_percent numeric := 0;
  
  -- Tax settings
  v_tax_settings jsonb := '{}'::jsonb;
  v_corporate_rate numeric := 24.0;
  v_regional_rate numeric := 3.9;
  v_vat_rate numeric := 22.0;
  
  -- Estimated taxes
  v_estimated_vat numeric := 0;
  v_estimated_corporate_tax numeric := 0;
  v_estimated_net_profit numeric := 0;
  
  -- Marketing
  v_marketing_spend numeric := 0;
  v_marketing_roi numeric := 0;
  
  -- Confidence calculation
  v_total_expenses_count integer := 0;
  v_recurring_expenses_count integer := 0;
  v_recurring_ratio numeric := 0;
  v_won_deals_count integer := 0;
  v_confirmed_deals_count integer := 0;
  v_confirmed_ratio numeric := 1;
  v_days_with_data integer := 0;
  v_total_days integer := 0;
  v_period_coverage numeric := 0;
  v_confidence_overall numeric := 0;
  v_confidence_factors jsonb := '[]'::jsonb;
  
  -- Budget baseline
  v_budget_total numeric := 0;
  v_budget_spent numeric := 0;
  v_budget_variance numeric := 0;
  v_budget_variance_pct numeric := 0;
  v_categories_over_budget jsonb := '[]'::jsonb;
  
  -- Alerts
  v_alerts jsonb := '[]'::jsonb;
  v_margin_change numeric := 0;
  v_prev_margin numeric := 0;
  v_avg_margin_3m numeric := 0;
  
  -- Period calculations
  v_period_days integer;
  v_prev_from date;
  v_prev_to date;
BEGIN
  -- Get user ID and validate access
  v_user_id := get_user_id(auth.uid());
  
  IF NOT has_finance_access(v_user_id, p_brand_id) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;
  
  -- Check if system brand (aggregate all brands)
  v_is_system_brand := (p_brand_id = '00000000-0000-0000-0000-000000000000'::uuid);
  
  IF v_is_system_brand THEN
    SELECT array_agg(id) INTO v_brand_ids
    FROM brands
    WHERE is_system IS NOT TRUE;
  ELSE
    v_brand_ids := ARRAY[p_brand_id];
  END IF;
  
  -- Calculate period info
  v_period_days := p_to - p_from + 1;
  v_prev_from := p_from - v_period_days;
  v_prev_to := p_from - 1;
  v_total_days := v_period_days;
  
  -- =====================================================
  -- REVENUE CALCULATION
  -- =====================================================
  
  -- Revenue from won deals in period
  SELECT COALESCE(SUM(value), 0), COUNT(*)
  INTO v_revenue_won_deals, v_won_deals_count
  FROM deals
  WHERE brand_id = ANY(v_brand_ids)
    AND status = 'won'
    AND closed_at::date BETWEEN p_from AND p_to;
  
  v_revenue_total := v_revenue_won_deals;
  
  -- Confirmed deals (with value set) for confidence
  SELECT COUNT(*)
  INTO v_confirmed_deals_count
  FROM deals
  WHERE brand_id = ANY(v_brand_ids)
    AND status = 'won'
    AND closed_at::date BETWEEN p_from AND p_to
    AND value IS NOT NULL AND value > 0;
  
  v_confirmed_ratio := CASE 
    WHEN v_won_deals_count > 0 THEN v_confirmed_deals_count::numeric / v_won_deals_count 
    ELSE 1 
  END;
  
  -- Previous period revenue
  SELECT COALESCE(SUM(value), 0)
  INTO v_prev_revenue
  FROM deals
  WHERE brand_id = ANY(v_brand_ids)
    AND status = 'won'
    AND closed_at::date BETWEEN v_prev_from AND v_prev_to;
  
  -- =====================================================
  -- COSTS CALCULATION
  -- =====================================================
  
  -- Total costs
  SELECT COALESCE(SUM(amount), 0), COUNT(*)
  INTO v_costs_total, v_total_expenses_count
  FROM expenses
  WHERE brand_id = ANY(v_brand_ids)
    AND expense_date BETWEEN p_from AND p_to;
  
  -- Recurring expenses count
  SELECT COUNT(*)
  INTO v_recurring_expenses_count
  FROM expenses
  WHERE brand_id = ANY(v_brand_ids)
    AND expense_date BETWEEN p_from AND p_to
    AND periodicity IS NOT NULL AND periodicity != 'one_off';
  
  v_recurring_ratio := CASE 
    WHEN v_total_expenses_count > 0 THEN v_recurring_expenses_count::numeric / v_total_expenses_count 
    ELSE 0 
  END;
  
  -- Costs by category type
  SELECT 
    COALESCE(SUM(CASE WHEN ec.category_type = 'direct' THEN e.amount ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN ec.category_type = 'indirect' THEN e.amount ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN ec.category_type = 'personnel' THEN e.amount ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN ec.category_type = 'marketing' THEN e.amount ELSE 0 END), 0)
  INTO v_costs_direct, v_costs_indirect, v_costs_personnel, v_costs_marketing
  FROM expenses e
  LEFT JOIN expense_categories ec ON e.category_id = ec.id
  WHERE e.brand_id = ANY(v_brand_ids)
    AND e.expense_date BETWEEN p_from AND p_to;
  
  v_marketing_spend := v_costs_marketing;
  
  -- Costs by center
  SELECT jsonb_agg(jsonb_build_object(
    'center_name', COALESCE(cc.name, 'Non assegnato'),
    'amount', sub.total
  ))
  INTO v_costs_by_center
  FROM (
    SELECT cost_center_id, SUM(amount) as total
    FROM expenses
    WHERE brand_id = ANY(v_brand_ids)
      AND expense_date BETWEEN p_from AND p_to
    GROUP BY cost_center_id
  ) sub
  LEFT JOIN cost_centers cc ON sub.cost_center_id = cc.id;
  
  v_costs_by_center := COALESCE(v_costs_by_center, '[]'::jsonb);
  
  -- Costs by category
  SELECT jsonb_agg(jsonb_build_object(
    'category_name', COALESCE(ec.name, 'Non categorizzato'),
    'type', COALESCE(ec.category_type, 'direct'),
    'amount', sub.total
  ))
  INTO v_costs_by_category
  FROM (
    SELECT category_id, SUM(amount) as total
    FROM expenses
    WHERE brand_id = ANY(v_brand_ids)
      AND expense_date BETWEEN p_from AND p_to
    GROUP BY category_id
  ) sub
  LEFT JOIN expense_categories ec ON sub.category_id = ec.id;
  
  v_costs_by_category := COALESCE(v_costs_by_category, '[]'::jsonb);
  
  -- Previous period costs
  SELECT COALESCE(SUM(amount), 0)
  INTO v_prev_costs
  FROM expenses
  WHERE brand_id = ANY(v_brand_ids)
    AND expense_date BETWEEN v_prev_from AND v_prev_to;
  
  -- Days with data (for confidence)
  SELECT COUNT(DISTINCT expense_date)
  INTO v_days_with_data
  FROM expenses
  WHERE brand_id = ANY(v_brand_ids)
    AND expense_date BETWEEN p_from AND p_to;
  
  v_period_coverage := CASE 
    WHEN v_total_days > 0 THEN LEAST(v_days_with_data::numeric / v_total_days, 1) 
    ELSE 0 
  END;
  
  -- =====================================================
  -- MARGINS CALCULATION
  -- =====================================================
  
  v_gross_margin := v_revenue_total - v_costs_direct;
  v_operating_margin := v_gross_margin - v_costs_indirect - v_costs_personnel;
  v_gross_margin_percent := CASE 
    WHEN v_revenue_total > 0 THEN (v_gross_margin / v_revenue_total) * 100 
    ELSE 0 
  END;
  
  -- Previous margin for comparison
  v_prev_margin := v_prev_revenue - v_prev_costs;
  v_margin_change := CASE 
    WHEN v_prev_margin != 0 THEN ((v_operating_margin - v_prev_margin) / ABS(v_prev_margin)) * 100 
    ELSE 0 
  END;
  
  -- =====================================================
  -- TAX SETTINGS & ESTIMATION
  -- =====================================================
  
  -- Get tax settings (use first brand if system brand)
  SELECT 
    corporate_tax_rate,
    regional_tax_rate,
    vat_rate_default
  INTO v_corporate_rate, v_regional_rate, v_vat_rate
  FROM brand_tax_settings
  WHERE brand_id = CASE WHEN v_is_system_brand THEN v_brand_ids[1] ELSE p_brand_id END;
  
  -- Use defaults if not found
  v_corporate_rate := COALESCE(v_corporate_rate, 24.0);
  v_regional_rate := COALESCE(v_regional_rate, 3.9);
  v_vat_rate := COALESCE(v_vat_rate, 22.0);
  
  v_tax_settings := jsonb_build_object(
    'corporate_rate', v_corporate_rate,
    'regional_rate', v_regional_rate,
    'vat_rate', v_vat_rate
  );
  
  -- Estimated VAT (simplified: revenue VAT - deductible expenses VAT)
  v_estimated_vat := (v_revenue_total * v_vat_rate / 100) - 
    (SELECT COALESCE(SUM(
      CASE WHEN COALESCE(e.is_deductible, ec.is_deductible, true) 
        THEN e.amount * COALESCE(e.tax_rate, v_vat_rate) / 100 
        ELSE 0 
      END
    ), 0)
    FROM expenses e
    LEFT JOIN expense_categories ec ON e.category_id = ec.id
    WHERE e.brand_id = ANY(v_brand_ids)
      AND e.expense_date BETWEEN p_from AND p_to);
  
  -- Estimated corporate + regional tax
  v_estimated_corporate_tax := GREATEST(0, v_operating_margin * (v_corporate_rate + v_regional_rate) / 100);
  
  -- Estimated net profit
  v_estimated_net_profit := v_operating_margin - v_estimated_corporate_tax;
  
  -- =====================================================
  -- MARKETING ROI
  -- =====================================================
  
  v_marketing_roi := CASE 
    WHEN v_marketing_spend > 0 THEN ((v_revenue_total - v_marketing_spend) / v_marketing_spend) * 100 
    ELSE 0 
  END;
  
  -- =====================================================
  -- CONFIDENCE LEVEL CALCULATION
  -- =====================================================
  
  v_confidence_overall := (
    v_recurring_ratio * 0.30 +
    v_confirmed_ratio * 0.30 +
    v_period_coverage * 0.20 +
    0.80 * 0.20  -- historical_accuracy placeholder
  );
  
  v_confidence_factors := jsonb_build_array(
    jsonb_build_object(
      'factor', 'recurring_costs_known',
      'contribution', 0.30,
      'value', ROUND(v_recurring_ratio::numeric, 2),
      'detail', format('%s/%s costi ricorrenti', v_recurring_expenses_count, v_total_expenses_count)
    ),
    jsonb_build_object(
      'factor', 'confirmed_sales_ratio',
      'contribution', 0.30,
      'value', ROUND(v_confirmed_ratio::numeric, 2),
      'detail', format('%s/%s vendite confermate', v_confirmed_deals_count, v_won_deals_count)
    ),
    jsonb_build_object(
      'factor', 'period_coverage',
      'contribution', 0.20,
      'value', ROUND(v_period_coverage::numeric, 2),
      'detail', format('%s/%s giorni con dati', v_days_with_data, v_total_days)
    ),
    jsonb_build_object(
      'factor', 'historical_accuracy',
      'contribution', 0.20,
      'value', 0.80,
      'detail', 'Placeholder per M14'
    )
  );
  
  -- =====================================================
  -- BUDGET BASELINE
  -- =====================================================
  
  -- Get budget for period month
  SELECT COALESCE(SUM(planned_amount), 0)
  INTO v_budget_total
  FROM budgets
  WHERE brand_id = ANY(v_brand_ids)
    AND period_month >= p_from
    AND period_month <= p_to;
  
  v_budget_spent := v_costs_total;
  v_budget_variance := v_budget_total - v_budget_spent;
  v_budget_variance_pct := CASE 
    WHEN v_budget_total > 0 THEN (v_budget_variance / v_budget_total) * 100 
    ELSE 0 
  END;
  
  -- Categories over budget
  SELECT jsonb_agg(jsonb_build_object(
    'category_name', sub.category_name,
    'planned', sub.planned,
    'actual', sub.actual,
    'overage', sub.actual - sub.planned
  ))
  INTO v_categories_over_budget
  FROM (
    SELECT 
      COALESCE(ec.name, 'Non categorizzato') as category_name,
      COALESCE(b.planned_amount, 0) as planned,
      COALESCE(e.total_spent, 0) as actual
    FROM expense_categories ec
    LEFT JOIN (
      SELECT category_id, SUM(planned_amount) as planned_amount
      FROM budgets
      WHERE brand_id = ANY(v_brand_ids)
        AND period_month >= p_from AND period_month <= p_to
      GROUP BY category_id
    ) b ON ec.id = b.category_id
    LEFT JOIN (
      SELECT category_id, SUM(amount) as total_spent
      FROM expenses
      WHERE brand_id = ANY(v_brand_ids)
        AND expense_date BETWEEN p_from AND p_to
      GROUP BY category_id
    ) e ON ec.id = e.category_id
    WHERE ec.brand_id = ANY(v_brand_ids)
      AND COALESCE(e.total_spent, 0) > COALESCE(b.planned_amount, 0)
      AND COALESCE(b.planned_amount, 0) > 0
  ) sub;
  
  v_categories_over_budget := COALESCE(v_categories_over_budget, '[]'::jsonb);
  
  -- =====================================================
  -- ALERTS GENERATION
  -- =====================================================
  
  -- Alert: MARGIN_DECLINING (margin < prev - 10%)
  IF v_margin_change < -10 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'type', 'MARGIN_DECLINING',
      'severity', 'warning',
      'message', format('Margine in calo del %.1f%% rispetto al periodo precedente', ABS(v_margin_change)),
      'root_causes', jsonb_build_array(
        CASE WHEN v_revenue_total < v_prev_revenue 
          THEN format('Revenue: %.1f%% rispetto al periodo precedente', 
            CASE WHEN v_prev_revenue > 0 THEN ((v_revenue_total - v_prev_revenue) / v_prev_revenue) * 100 ELSE 0 END)
          ELSE NULL 
        END,
        CASE WHEN v_costs_total > v_prev_costs 
          THEN format('Costi: +%.1f%% rispetto al periodo precedente', 
            CASE WHEN v_prev_costs > 0 THEN ((v_costs_total - v_prev_costs) / v_prev_costs) * 100 ELSE 0 END)
          ELSE NULL 
        END
      ),
      'suggested_action', 'Analizzare categorie con maggiore incremento. Valutare ottimizzazione budget.',
      'metric_value', v_margin_change,
      'threshold_value', -10.0
    ));
  END IF;
  
  -- Alert: REVENUE_DROP (revenue < prev - 20%)
  IF v_prev_revenue > 0 AND ((v_revenue_total - v_prev_revenue) / v_prev_revenue) * 100 < -20 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'type', 'REVENUE_DROP',
      'severity', 'error',
      'message', format('Fatturato in calo del %.1f%% rispetto al periodo precedente', 
        ABS(((v_revenue_total - v_prev_revenue) / v_prev_revenue) * 100)),
      'root_causes', jsonb_build_array('Analisi vendite richiesta'),
      'suggested_action', 'Verificare pipeline e conversioni. Contattare venditori per feedback.',
      'metric_value', ((v_revenue_total - v_prev_revenue) / v_prev_revenue) * 100,
      'threshold_value', -20.0
    ));
  END IF;
  
  -- Alert: BUDGET_EXCEEDED
  IF jsonb_array_length(v_categories_over_budget) > 0 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'type', 'BUDGET_EXCEEDED',
      'severity', 'error',
      'message', format('%s categorie hanno superato il budget', jsonb_array_length(v_categories_over_budget)),
      'root_causes', (SELECT jsonb_agg(elem->>'category_name') FROM jsonb_array_elements(v_categories_over_budget) elem),
      'suggested_action', 'Rivedere allocazione budget o autorizzare spese extra.',
      'metric_value', v_budget_variance,
      'threshold_value', 0
    ));
  END IF;
  
  -- Alert: MARKETING_ROI_LOW (ROI < 100%)
  IF v_marketing_spend > 0 AND v_marketing_roi < 100 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'type', 'MARKETING_ROI_LOW',
      'severity', 'warning',
      'message', format('ROI Marketing al %.1f%% (sotto il 100%%)', v_marketing_roi),
      'root_causes', jsonb_build_array(
        format('Spesa marketing: €%.2f', v_marketing_spend),
        format('Revenue attribuibile: €%.2f', v_revenue_total)
      ),
      'suggested_action', 'Analizzare efficacia campagne. Considerare riallocazione budget.',
      'metric_value', v_marketing_roi,
      'threshold_value', 100.0
    ));
  END IF;
  
  -- Alert: POSITIVE_TREND (margin > prev + 15%)
  IF v_margin_change > 15 THEN
    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object(
      'type', 'POSITIVE_TREND',
      'severity', 'success',
      'message', format('Margine in crescita del %.1f%% rispetto al periodo precedente', v_margin_change),
      'root_causes', jsonb_build_array('Trend positivo'),
      'suggested_action', 'Consolidare pratiche attuali. Valutare espansione.',
      'metric_value', v_margin_change,
      'threshold_value', 15.0
    ));
  END IF;
  
  -- =====================================================
  -- RETURN RESULT
  -- =====================================================
  
  RETURN jsonb_build_object(
    -- Revenue
    'revenue_total', v_revenue_total,
    'revenue_from_won_deals', v_revenue_won_deals,
    
    -- Costs
    'costs_total', v_costs_total,
    'costs_direct', v_costs_direct,
    'costs_indirect', v_costs_indirect,
    'costs_personnel', v_costs_personnel,
    'costs_marketing', v_costs_marketing,
    'costs_by_center', v_costs_by_center,
    'costs_by_category', v_costs_by_category,
    
    -- Margins
    'gross_margin', v_gross_margin,
    'operating_margin', v_operating_margin,
    'gross_margin_percent', ROUND(v_gross_margin_percent, 1),
    
    -- Tax settings & estimation
    'tax_settings', v_tax_settings,
    'estimated_vat_payable', ROUND(v_estimated_vat, 2),
    'estimated_corporate_tax', ROUND(v_estimated_corporate_tax, 2),
    'estimated_net_profit', ROUND(v_estimated_net_profit, 2),
    
    -- Comparisons
    'prev_period_revenue', v_prev_revenue,
    'prev_period_costs', v_prev_costs,
    'revenue_change_percent', ROUND(
      CASE WHEN v_prev_revenue > 0 THEN ((v_revenue_total - v_prev_revenue) / v_prev_revenue) * 100 ELSE 0 END, 1
    ),
    'costs_change_percent', ROUND(
      CASE WHEN v_prev_costs > 0 THEN ((v_costs_total - v_prev_costs) / v_prev_costs) * 100 ELSE 0 END, 1
    ),
    
    -- Marketing
    'marketing_spend', v_marketing_spend,
    'marketing_roi', ROUND(v_marketing_roi, 1),
    
    -- Confidence
    'confidence', jsonb_build_object(
      'overall', ROUND(v_confidence_overall, 2),
      'estimated_net_profit', ROUND(v_confidence_overall, 2),
      'marketing_roi', ROUND(LEAST(v_confirmed_ratio, v_period_coverage), 2),
      'factors', v_confidence_factors
    ),
    
    -- Alerts
    'alerts', v_alerts,
    
    -- Budget baseline
    'budget_baseline', jsonb_build_object(
      'total_planned', v_budget_total,
      'total_spent', v_budget_spent,
      'variance', v_budget_variance,
      'variance_percent', ROUND(v_budget_variance_pct, 1),
      'categories_over_budget', v_categories_over_budget,
      'remaining_allocable', GREATEST(0, v_budget_variance)
    )
  );
END;
$$;


--
-- Name: get_ceo_operational_kpis(uuid, uuid[], date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_ceo_operational_kpis(p_brand_id uuid, p_brand_ids uuid[] DEFAULT NULL::uuid[], p_from date DEFAULT CURRENT_DATE, p_to date DEFAULT CURRENT_DATE) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_result JSON;
  v_total_contacts BIGINT;
  v_new_contacts BIGINT;
  v_open_tickets BIGINT;
  v_tickets_created BIGINT;
  v_appointments_period BIGINT;
  v_deals_by_stage JSON;
  v_total_open_deals BIGINT;
  v_total_open_value NUMERIC;
  v_won_deals BIGINT;
  v_won_revenue NUMERIC;
BEGIN
  -- Resolve current user
  v_user_id := current_app_user_id();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Validate brand access
  IF p_brand_ids IS NOT NULL THEN
    -- Multi-brand: validate all brands are accessible
    IF NOT (p_brand_ids <@ (SELECT ARRAY_AGG(ur.brand_id) FROM user_roles ur WHERE ur.user_id = v_user_id)) THEN
      RAISE EXCEPTION 'Unauthorized brand access';
    END IF;
  ELSE
    -- Single brand
    IF NOT user_belongs_to_brand(v_user_id, p_brand_id) THEN
      RAISE EXCEPTION 'Unauthorized brand access';
    END IF;
  END IF;

  -- Total contacts
  SELECT COUNT(*) INTO v_total_contacts
  FROM contacts
  WHERE CASE WHEN p_brand_ids IS NOT NULL THEN brand_id = ANY(p_brand_ids) ELSE brand_id = p_brand_id END;

  -- New contacts in period
  SELECT COUNT(*) INTO v_new_contacts
  FROM contacts
  WHERE CASE WHEN p_brand_ids IS NOT NULL THEN brand_id = ANY(p_brand_ids) ELSE brand_id = p_brand_id END
    AND created_at::date BETWEEN p_from AND p_to;

  -- Open tickets
  SELECT COUNT(*) INTO v_open_tickets
  FROM tickets
  WHERE CASE WHEN p_brand_ids IS NOT NULL THEN brand_id = ANY(p_brand_ids) ELSE brand_id = p_brand_id END
    AND status::text IN ('open', 'in_progress', 'reopened_for_support');

  -- Tickets created in period
  SELECT COUNT(*) INTO v_tickets_created
  FROM tickets
  WHERE CASE WHEN p_brand_ids IS NOT NULL THEN brand_id = ANY(p_brand_ids) ELSE brand_id = p_brand_id END
    AND created_at::date BETWEEN p_from AND p_to;

  -- Appointments in period (only valid statuses)
  SELECT COUNT(*) INTO v_appointments_period
  FROM appointments
  WHERE CASE WHEN p_brand_ids IS NOT NULL THEN brand_id = ANY(p_brand_ids) ELSE brand_id = p_brand_id END
    AND status::text IN ('scheduled', 'confirmed', 'visited')
    AND scheduled_at::date BETWEEN p_from AND p_to;

  -- Deals by stage (open deals)
  SELECT COALESCE(json_agg(row_to_json(stage_data) ORDER BY stage_data.stage_order), '[]'::json)
  INTO v_deals_by_stage
  FROM (
    SELECT
      ps.name AS stage_name,
      ps.order_index AS stage_order,
      COUNT(d.id) AS count,
      COALESCE(SUM(d.value), 0) AS total_value
    FROM pipeline_stages ps
    LEFT JOIN deals d ON d.current_stage_id = ps.id
      AND d.status::text = 'open'
      AND CASE WHEN p_brand_ids IS NOT NULL THEN d.brand_id = ANY(p_brand_ids) ELSE d.brand_id = p_brand_id END
    GROUP BY ps.id, ps.name, ps.order_index
    ORDER BY ps.order_index
  ) stage_data;

  -- Total open deals
  SELECT COUNT(*), COALESCE(SUM(value), 0)
  INTO v_total_open_deals, v_total_open_value
  FROM deals
  WHERE CASE WHEN p_brand_ids IS NOT NULL THEN brand_id = ANY(p_brand_ids) ELSE brand_id = p_brand_id END
    AND status::text = 'open';

  -- Won deals in period
  SELECT COUNT(*), COALESCE(SUM(value), 0)
  INTO v_won_deals, v_won_revenue
  FROM deals
  WHERE CASE WHEN p_brand_ids IS NOT NULL THEN brand_id = ANY(p_brand_ids) ELSE brand_id = p_brand_id END
    AND status::text = 'won'
    AND closed_at::date BETWEEN p_from AND p_to;

  -- Build result
  v_result := json_build_object(
    'total_contacts', v_total_contacts,
    'new_contacts_period', v_new_contacts,
    'open_tickets', v_open_tickets,
    'tickets_created', v_tickets_created,
    'appointments_period', v_appointments_period,
    'deals_by_stage', v_deals_by_stage,
    'total_open_deals', v_total_open_deals,
    'total_open_value', v_total_open_value,
    'won_deals_period', v_won_deals,
    'won_deals_revenue', v_won_revenue
  );

  RETURN v_result;
END;
$$;


--
-- Name: get_compliance_report(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_compliance_report(p_report_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_report public.audit_compliance_reports;
BEGIN
  IF NOT public.is_audit_admin(auth.uid()) THEN
    RAISE EXCEPTION 'access denied';
  END IF;

  SELECT * INTO v_report FROM public.audit_compliance_reports WHERE id = p_report_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'report not found';
  END IF;

  RETURN to_jsonb(v_report);
END;
$$;


--
-- Name: get_contact_field_definitions(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_contact_field_definitions(p_brand_id uuid) RETURNS TABLE(id uuid, scope public.custom_field_scope, brand_id uuid, key text, label text, description text, field_type public.custom_field_type, options jsonb, is_required boolean, display_order integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT 
    cfd.id,
    cfd.scope,
    cfd.brand_id,
    cfd.key,
    cfd.label,
    cfd.description,
    cfd.field_type,
    cfd.options,
    cfd.is_required,
    cfd.display_order
  FROM contact_field_definitions cfd
  WHERE cfd.is_active = true
    AND (cfd.scope = 'global' OR cfd.brand_id = p_brand_id)
  ORDER BY cfd.scope DESC, cfd.display_order, cfd.label;
$$;


--
-- Name: get_contacts_with_sales_totals(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_contacts_with_sales_totals(p_brand_id uuid) RETURNS TABLE(contact_id uuid, sales_count bigint, sales_total numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    SELECT 
        so.contact_id,
        COUNT(*)::BIGINT as sales_count,
        COALESCE(SUM(so.total_amount), 0) as sales_total
    FROM sales_orders so
    WHERE so.brand_id = p_brand_id
      AND so.status NOT IN ('cancelled')
    GROUP BY so.contact_id;
$$;


--
-- Name: get_cpl_analytics(uuid, timestamp with time zone, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_cpl_analytics(p_brand_id uuid, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_group_by text DEFAULT 'campaign'::text) RETURNS TABLE(entity_id uuid, entity_name text, match_type text, leads_count bigint, total_spend numeric, cpl numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_group_by = 'group' THEN
    RETURN QUERY
    SELECT
      lca.group_id AS entity_id,
      COALESCE(mcg.name, 'Unmapped') AS entity_name,
      lca.match_type,
      COUNT(DISTINCT lca.lead_event_id) AS leads_count,
      COALESCE(SUM(mc_agg.spend), 0) AS total_spend,
      CASE WHEN COUNT(DISTINCT lca.lead_event_id) > 0
           THEN ROUND(COALESCE(SUM(mc_agg.spend), 0) / COUNT(DISTINCT lca.lead_event_id), 2)
           ELSE 0
      END AS cpl
    FROM lead_campaign_attribution lca
    LEFT JOIN marketing_campaign_groups mcg ON mcg.id = lca.group_id
    LEFT JOIN LATERAL (
      SELECT COALESCE(SUM(mco.amount), 0) AS spend
      FROM marketing_costs mco
      WHERE mco.campaign_id = lca.campaign_id
        AND (p_from IS NULL OR mco.cost_date >= p_from::date)
        AND (p_to IS NULL OR mco.cost_date <= p_to::date)
    ) mc_agg ON true
    WHERE lca.brand_id = p_brand_id
      AND (p_from IS NULL OR lca.matched_at >= p_from)
      AND (p_to IS NULL OR lca.matched_at <= p_to)
    GROUP BY lca.group_id, mcg.name, lca.match_type
    ORDER BY leads_count DESC;
  ELSE
    RETURN QUERY
    SELECT
      lca.campaign_id AS entity_id,
      COALESCE(mcamp.name, 'Unmapped') AS entity_name,
      lca.match_type,
      COUNT(DISTINCT lca.lead_event_id) AS leads_count,
      COALESCE(mc_agg.spend, 0) AS total_spend,
      CASE WHEN COUNT(DISTINCT lca.lead_event_id) > 0
           THEN ROUND(COALESCE(mc_agg.spend, 0) / COUNT(DISTINCT lca.lead_event_id), 2)
           ELSE 0
      END AS cpl
    FROM lead_campaign_attribution lca
    LEFT JOIN marketing_campaigns mcamp ON mcamp.id = lca.campaign_id
    LEFT JOIN LATERAL (
      SELECT COALESCE(SUM(mco.amount), 0) AS spend
      FROM marketing_costs mco
      WHERE mco.campaign_id = lca.campaign_id
        AND (p_from IS NULL OR mco.cost_date >= p_from::date)
        AND (p_to IS NULL OR mco.cost_date <= p_to::date)
    ) mc_agg ON true
    WHERE lca.brand_id = p_brand_id
      AND (p_from IS NULL OR lca.matched_at >= p_from)
      AND (p_to IS NULL OR lca.matched_at <= p_to)
    GROUP BY lca.campaign_id, mcamp.name, lca.match_type, mc_agg.spend
    ORDER BY leads_count DESC;
  END IF;
END;
$$;


--
-- Name: get_cron_secret(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_cron_secret() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_secret text;
BEGIN
  SELECT decrypted_secret INTO v_secret
  FROM vault.decrypted_secrets
  WHERE name = 'CRON_SECRET'
  LIMIT 1;
  
  RETURN v_secret;
END;
$$;


--
-- Name: get_deal_velocity_metrics(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_deal_velocity_metrics(p_brand_id uuid, p_from timestamp with time zone DEFAULT (now() - '30 days'::interval), p_to timestamp with time zone DEFAULT now()) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id UUID := get_user_id(auth.uid());
  v_result JSON;
BEGIN
  -- Validate brand access
  IF NOT user_belongs_to_brand(v_user_id, p_brand_id) THEN
    RAISE EXCEPTION 'Access denied to brand';
  END IF;

  WITH velocity_data AS (
    SELECT
      -- Average time to close (won deals)
      AVG(
        EXTRACT(EPOCH FROM (closed_at - created_at)) / 86400
      ) FILTER (WHERE status = 'won' AND closed_at BETWEEN p_from AND p_to) AS avg_days_to_win,
      -- Average time to lose
      AVG(
        EXTRACT(EPOCH FROM (closed_at - created_at)) / 86400
      ) FILTER (WHERE status = 'lost' AND closed_at BETWEEN p_from AND p_to) AS avg_days_to_lose,
      -- Deals closed in period
      COUNT(*) FILTER (WHERE status = 'won' AND closed_at BETWEEN p_from AND p_to) AS deals_won_count,
      COUNT(*) FILTER (WHERE status = 'lost' AND closed_at BETWEEN p_from AND p_to) AS deals_lost_count,
      -- New deals in period
      COUNT(*) FILTER (WHERE created_at BETWEEN p_from AND p_to) AS new_deals_count,
      -- Average deal value
      AVG(value) FILTER (WHERE status = 'won' AND closed_at BETWEEN p_from AND p_to) AS avg_won_value,
      -- Total value won
      SUM(value) FILTER (WHERE status = 'won' AND closed_at BETWEEN p_from AND p_to) AS total_won_value
    FROM deals
    WHERE brand_id = p_brand_id
  ),
  weekly_trend AS (
    SELECT 
      date_trunc('week', created_at) AS week_start,
      COUNT(*) AS deals_created,
      COUNT(*) FILTER (WHERE status = 'won') AS deals_won
    FROM deals
    WHERE brand_id = p_brand_id
      AND created_at BETWEEN p_from AND p_to
    GROUP BY date_trunc('week', created_at)
    ORDER BY week_start
  )
  SELECT json_build_object(
    'avg_days_to_win', COALESCE((SELECT ROUND(avg_days_to_win::NUMERIC, 1) FROM velocity_data), 0),
    'avg_days_to_lose', COALESCE((SELECT ROUND(avg_days_to_lose::NUMERIC, 1) FROM velocity_data), 0),
    'deals_won_count', COALESCE((SELECT deals_won_count FROM velocity_data), 0),
    'deals_lost_count', COALESCE((SELECT deals_lost_count FROM velocity_data), 0),
    'new_deals_count', COALESCE((SELECT new_deals_count FROM velocity_data), 0),
    'avg_won_value', COALESCE((SELECT ROUND(avg_won_value::NUMERIC, 2) FROM velocity_data), 0),
    'total_won_value', COALESCE((SELECT total_won_value FROM velocity_data), 0),
    'weekly_trend', COALESCE((
      SELECT json_agg(json_build_object(
        'week_start', week_start,
        'deals_created', deals_created,
        'deals_won', deals_won
      ) ORDER BY week_start)
      FROM weekly_trend
    ), '[]'::json)
  ) INTO v_result;

  RETURN v_result;
END;
$$;


--
-- Name: get_funnel_breakdown(uuid, uuid, text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_funnel_breakdown(p_brand_id uuid, p_user_id uuid DEFAULT NULL::uuid, p_role text DEFAULT NULL::text, p_from timestamp with time zone DEFAULT (now() - '30 days'::interval), p_to timestamp with time zone DEFAULT now()) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_brand_ids uuid[];
  v_result json;
BEGIN
  IF p_brand_id = '00000000-0000-0000-0000-000000000000' THEN
    SELECT array_agg(ur.brand_id)
    INTO v_brand_ids
    FROM user_roles ur
    WHERE ur.user_id = (SELECT u.id FROM users u WHERE u.supabase_auth_id = auth.uid())
      AND ur.is_active = true
      AND ur.brand_id != '00000000-0000-0000-0000-000000000000';
  ELSE
    v_brand_ids := ARRAY[p_brand_id];
  END IF;

  IF v_brand_ids IS NULL OR array_length(v_brand_ids, 1) IS NULL THEN
    RETURN json_build_object('by_campaign', '[]'::json);
  END IF;

  -- Group by lead_events source_name (the actual source of leads)
  -- and join to campaigns where possible, but also show uncampaigned sources
  SELECT json_build_object(
    'by_campaign', COALESCE(json_agg(row_data ORDER BY leads DESC), '[]'::json)
  )
  INTO v_result
  FROM (
    SELECT json_build_object(
      'campaign_id', COALESCE(source_key, 'unknown'),
      'campaign_name', COALESCE(source_label, 'Non attribuito'),
      'impressions', impressions,
      'clicks', clicks,
      'leads', leads,
      'appointments', appointments,
      'sales', sales,
      'revenue', revenue
    ) AS row_data,
    leads
    FROM (
      SELECT
        le.source_name AS source_key,
        le.source_name AS source_label,
        -- Try to match ad_platform_stats via campaign name similarity
        COALESCE((
          SELECT SUM(aps.impressions)
          FROM ad_platform_stats aps
          WHERE aps.brand_id = ANY(v_brand_ids)
            AND aps.stat_date >= p_from::date AND aps.stat_date <= p_to::date
            AND aps.external_campaign_name = le.source_name
        ), 0)::bigint AS impressions,
        COALESCE((
          SELECT SUM(aps.clicks)
          FROM ad_platform_stats aps
          WHERE aps.brand_id = ANY(v_brand_ids)
            AND aps.stat_date >= p_from::date AND aps.stat_date <= p_to::date
            AND aps.external_campaign_name = le.source_name
        ), 0)::bigint AS clicks,
        COUNT(DISTINCT le.contact_id) AS leads,
        (SELECT COUNT(DISTINCT a.contact_id)
         FROM appointments a
         WHERE a.brand_id = ANY(v_brand_ids)
           AND a.contact_id IN (
             SELECT le2.contact_id FROM lead_events le2
             WHERE le2.source_name = le.source_name
               AND le2.brand_id = ANY(v_brand_ids)
           )
           AND a.scheduled_at >= p_from AND a.scheduled_at <= p_to
           AND a.status != 'cancelled'
        ) AS appointments,
        (SELECT COUNT(DISTINCT d.contact_id)
         FROM deals d
         WHERE d.brand_id = ANY(v_brand_ids)
           AND d.contact_id IN (
             SELECT le2.contact_id FROM lead_events le2
             WHERE le2.source_name = le.source_name
               AND le2.brand_id = ANY(v_brand_ids)
           )
           AND d.status::text = 'won'
           AND d.closed_at >= p_from AND d.closed_at <= p_to
        ) AS sales,
        COALESCE((
          SELECT SUM(d.value)
          FROM deals d
          WHERE d.brand_id = ANY(v_brand_ids)
            AND d.contact_id IN (
              SELECT le2.contact_id FROM lead_events le2
              WHERE le2.source_name = le.source_name
                AND le2.brand_id = ANY(v_brand_ids)
            )
            AND d.status::text = 'won'
            AND d.closed_at >= p_from AND d.closed_at <= p_to
        ), 0) AS revenue
      FROM lead_events le
      WHERE le.brand_id = ANY(v_brand_ids)
        AND le.created_at >= p_from AND le.created_at <= p_to
        AND le.source_name IS NOT NULL
      GROUP BY le.source_name
      ORDER BY COUNT(DISTINCT le.contact_id) DESC
      LIMIT 20
    ) sub
  ) wrapped;

  RETURN v_result;
END;
$$;


--
-- Name: get_funnel_losses(uuid, uuid, text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_funnel_losses(p_brand_id uuid, p_user_id uuid DEFAULT NULL::uuid, p_role text DEFAULT NULL::text, p_from timestamp with time zone DEFAULT (now() - '30 days'::interval), p_to timestamp with time zone DEFAULT now()) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_brand_ids uuid[];
  v_threshold integer;
  v_result json;
BEGIN
  -- Resolve brand IDs
  IF p_brand_id = '00000000-0000-0000-0000-000000000000' THEN
    SELECT array_agg(ur.brand_id)
    INTO v_brand_ids
    FROM user_roles ur
    WHERE ur.user_id = (SELECT u.id FROM users u WHERE u.supabase_auth_id = auth.uid())
      AND ur.is_active = true
      AND ur.brand_id != '00000000-0000-0000-0000-000000000000';
  ELSE
    v_brand_ids := ARRAY[p_brand_id];
  END IF;

  IF v_brand_ids IS NULL OR array_length(v_brand_ids, 1) IS NULL THEN
    RETURN json_build_object('losses', '[]'::json, 'total_lost', 0, 'by_reason', '[]'::json);
  END IF;

  SELECT COALESCE(b.funnel_lost_threshold_days, 30) INTO v_threshold FROM brands b WHERE b.id = v_brand_ids[1];

  SELECT json_build_object(
    'total_lost', COALESCE(SUM(lost_count), 0),
    'by_stage', COALESCE(json_agg(json_build_object(
      'stage', stage_label,
      'count', lost_count
    )), '[]'::json),
    'by_reason', (
      SELECT COALESCE(json_agg(json_build_object('reason', reason, 'count', cnt)), '[]'::json)
      FROM (
        -- Deals explicitly lost
        SELECT COALESCE(d.notes, 'Non specificato') AS reason, COUNT(*) AS cnt
        FROM deals d
        WHERE d.brand_id = ANY(v_brand_ids)
          AND d.status = 'lost'
          AND d.closed_at >= p_from AND d.closed_at <= p_to
          AND (p_user_id IS NULL OR p_role NOT IN ('venditore') OR d.assigned_user_id = p_user_id)
        GROUP BY COALESCE(d.notes, 'Non specificato')
        ORDER BY cnt DESC
        LIMIT 10
      ) reasons
    )
  )
  INTO v_result
  FROM (
    -- Lead senza chiamata
    SELECT 'Lead senza chiamata' AS stage_label, COUNT(DISTINCT le.contact_id) AS lost_count
    FROM lead_events le
    WHERE le.brand_id = ANY(v_brand_ids)
      AND le.created_at >= p_from AND le.created_at <= p_to
      AND le.contact_id NOT IN (
        SELECT cl.contact_id FROM call_logs cl
        WHERE cl.brand_id = ANY(v_brand_ids) AND cl.started_at >= p_from
      )
      AND le.created_at < now() - (v_threshold || ' days')::interval

    UNION ALL

    -- Chiamati ma non risposto
    SELECT 'Chiamati non risposti', COUNT(DISTINCT cl.contact_id)
    FROM call_logs cl
    WHERE cl.brand_id = ANY(v_brand_ids)
      AND cl.started_at >= p_from AND cl.started_at <= p_to
      AND cl.contact_id NOT IN (
        SELECT cl2.contact_id FROM call_logs cl2
        WHERE cl2.brand_id = ANY(v_brand_ids)
          AND cl2.started_at >= p_from
          AND cl2.status IN ('completed','answered','connected')
      )

    UNION ALL

    -- Risposti ma senza appuntamento
    SELECT 'Risposti senza appuntamento', COUNT(DISTINCT cl.contact_id)
    FROM call_logs cl
    WHERE cl.brand_id = ANY(v_brand_ids)
      AND cl.started_at >= p_from AND cl.started_at <= p_to
      AND cl.status IN ('completed','answered','connected')
      AND cl.contact_id NOT IN (
        SELECT a.contact_id FROM appointments a
        WHERE a.brand_id = ANY(v_brand_ids)
          AND a.scheduled_at >= p_from
          AND a.status != 'cancelled'
      )

    UNION ALL

    -- Appuntamenti senza vendita
    SELECT 'Appuntamenti senza vendita', COUNT(DISTINCT a.contact_id)
    FROM appointments a
    WHERE a.brand_id = ANY(v_brand_ids)
      AND a.scheduled_at >= p_from AND a.scheduled_at <= p_to
      AND a.status != 'cancelled'
      AND a.contact_id NOT IN (
        SELECT d.contact_id FROM deals d
        WHERE d.brand_id = ANY(v_brand_ids) AND d.status = 'won'
          AND d.closed_at >= p_from
      )

    UNION ALL

    -- Deal esplicitamente persi
    SELECT 'Deal persi', COUNT(DISTINCT d.contact_id)
    FROM deals d
    WHERE d.brand_id = ANY(v_brand_ids)
      AND d.status = 'lost'
      AND d.closed_at >= p_from AND d.closed_at <= p_to
      AND (p_user_id IS NULL OR p_role NOT IN ('venditore') OR d.assigned_user_id = p_user_id)
  ) stages;

  RETURN v_result;
END;
$$;


--
-- Name: get_funnel_metrics(uuid, uuid, text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_funnel_metrics(p_brand_id uuid, p_user_id uuid DEFAULT NULL::uuid, p_role text DEFAULT NULL::text, p_from timestamp with time zone DEFAULT (now() - '30 days'::interval), p_to timestamp with time zone DEFAULT now()) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_brand_ids uuid[];
  v_impressions bigint;
  v_clicks bigint;
  v_leads bigint;
  v_called bigint;
  v_answered bigint;
  v_appointments bigint;
  v_sales bigint;
  v_sales_revenue numeric;
  v_lost_threshold integer;
  v_result json;
BEGIN
  -- Resolve brand IDs (system brand = all user brands)
  IF p_brand_id = '00000000-0000-0000-0000-000000000000' THEN
    SELECT array_agg(ur.brand_id)
    INTO v_brand_ids
    FROM user_roles ur
    WHERE ur.user_id = (SELECT u.id FROM users u WHERE u.supabase_auth_id = auth.uid())
      AND ur.is_active = true
      AND ur.brand_id != '00000000-0000-0000-0000-000000000000';
  ELSE
    v_brand_ids := ARRAY[p_brand_id];
  END IF;

  IF v_brand_ids IS NULL OR array_length(v_brand_ids, 1) IS NULL THEN
    RETURN json_build_object(
      'impressions', 0, 'clicks', 0, 'leads', 0,
      'called_contacts', 0, 'answered_contacts', 0,
      'appointments', 0, 'sales', 0, 'sales_revenue', 0,
      'lost_threshold_days', 30,
      'conversions', json_build_object()
    );
  END IF;

  -- Get lost threshold from first brand
  SELECT COALESCE(b.funnel_lost_threshold_days, 30)
  INTO v_lost_threshold
  FROM brands b WHERE b.id = v_brand_ids[1];

  -- Phase 1: Impressions (from ad_platform_stats)
  SELECT COALESCE(SUM(aps.impressions), 0)
  INTO v_impressions
  FROM ad_platform_stats aps
  WHERE aps.brand_id = ANY(v_brand_ids)
    AND aps.stat_date >= p_from::date
    AND aps.stat_date <= p_to::date;

  -- Phase 2: Clicks (from ad_platform_stats)
  SELECT COALESCE(SUM(aps.clicks), 0)
  INTO v_clicks
  FROM ad_platform_stats aps
  WHERE aps.brand_id = ANY(v_brand_ids)
    AND aps.stat_date >= p_from::date
    AND aps.stat_date <= p_to::date;

  -- Phase 3: Leads — unique contacts, excluding archived events (suppressed duplicates)
  SELECT COUNT(DISTINCT le.contact_id)
  INTO v_leads
  FROM lead_events le
  WHERE le.brand_id = ANY(v_brand_ids)
    AND le.created_at >= p_from
    AND le.created_at <= p_to
    AND (le.archived = false OR le.archived IS NULL)  -- FIX: esclude duplicati soppressi
    AND (p_user_id IS NULL OR p_role NOT IN ('operatore_callcenter','venditore')
         OR le.contact_id IN (
           SELECT d.contact_id FROM deals d
           WHERE d.assigned_user_id = p_user_id AND d.brand_id = ANY(v_brand_ids)
         ));

  -- Phase 4: Called contacts (unique contacts with at least one call)
  SELECT COUNT(DISTINCT cl.contact_id)
  INTO v_called
  FROM call_logs cl
  WHERE cl.brand_id = ANY(v_brand_ids)
    AND cl.started_at >= p_from
    AND cl.started_at <= p_to
    AND (p_user_id IS NULL OR p_role NOT IN ('operatore_callcenter')
         OR cl.user_id = p_user_id);

  -- Phase 5: Answered contacts (unique contacts with answered call)
  SELECT COUNT(DISTINCT cl.contact_id)
  INTO v_answered
  FROM call_logs cl
  WHERE cl.brand_id = ANY(v_brand_ids)
    AND cl.started_at >= p_from
    AND cl.started_at <= p_to
    AND cl.status IN ('completed','answered','connected')
    AND (cl.duration_seconds IS NULL OR cl.duration_seconds > 0)
    AND (p_user_id IS NULL OR p_role NOT IN ('operatore_callcenter')
         OR cl.user_id = p_user_id);

  -- Phase 6: Appointments (unique contacts with appointment)
  SELECT COUNT(DISTINCT a.contact_id)
  INTO v_appointments
  FROM appointments a
  WHERE a.brand_id = ANY(v_brand_ids)
    AND a.scheduled_at >= p_from
    AND a.scheduled_at <= p_to
    AND a.status NOT IN ('cancelled')
    AND (p_user_id IS NULL OR p_role NOT IN ('venditore')
         OR a.assigned_sales_user_id = p_user_id);

  -- Phase 7: Sales (deals won)
  SELECT COUNT(DISTINCT d.contact_id), COALESCE(SUM(d.value), 0)
  INTO v_sales, v_sales_revenue
  FROM deals d
  WHERE d.brand_id = ANY(v_brand_ids)
    AND d.status = 'won'
    AND d.closed_at >= p_from
    AND d.closed_at <= p_to
    AND (p_user_id IS NULL OR p_role NOT IN ('venditore')
         OR d.assigned_user_id = p_user_id);

  -- Build result with conversions
  v_result := json_build_object(
    'impressions', v_impressions,
    'clicks', v_clicks,
    'leads', v_leads,
    'called_contacts', v_called,
    'answered_contacts', v_answered,
    'appointments', v_appointments,
    'sales', v_sales,
    'sales_revenue', v_sales_revenue,
    'lost_threshold_days', v_lost_threshold,
    'conversions', json_build_object(
      'impression_to_click', CASE WHEN v_impressions > 0 THEN ROUND(v_clicks::numeric / v_impressions * 100, 2) ELSE 0 END,
      'click_to_lead', CASE WHEN v_clicks > 0 THEN ROUND(v_leads::numeric / v_clicks * 100, 2) ELSE 0 END,
      'lead_to_called', CASE WHEN v_leads > 0 THEN ROUND(v_called::numeric / v_leads * 100, 2) ELSE 0 END,
      'called_to_answered', CASE WHEN v_called > 0 THEN ROUND(v_answered::numeric / v_called * 100, 2) ELSE 0 END,
      'answered_to_appointment', CASE WHEN v_answered > 0 THEN ROUND(v_appointments::numeric / v_answered * 100, 2) ELSE 0 END,
      'appointment_to_sale', CASE WHEN v_appointments > 0 THEN ROUND(v_sales::numeric / v_appointments * 100, 2) ELSE 0 END,
      'overall', CASE WHEN v_leads > 0 THEN ROUND(v_sales::numeric / v_leads * 100, 2) ELSE 0 END
    )
  );

  RETURN v_result;
END;
$$;


--
-- Name: get_lead_source_analytics(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_lead_source_analytics(p_brand_id uuid, p_from timestamp with time zone DEFAULT (now() - '30 days'::interval), p_to timestamp with time zone DEFAULT now()) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id UUID := get_user_id(auth.uid());
  v_result JSON;
BEGIN
  -- Validate brand access
  IF NOT user_belongs_to_brand(v_user_id, p_brand_id) THEN
    RAISE EXCEPTION 'Access denied to brand';
  END IF;

  WITH source_data AS (
    SELECT 
      le.source,
      COALESCE(le.source_name, le.source::TEXT) AS source_name,
      COUNT(DISTINCT le.id) AS leads_count,
      COUNT(DISTINCT le.deal_id) AS deals_created,
      COUNT(DISTINCT CASE WHEN d.status = 'won' THEN d.id END) AS deals_won,
      COALESCE(SUM(CASE WHEN d.status = 'won' THEN d.value ELSE 0 END), 0) AS total_value_won,
      COUNT(DISTINCT le.contact_id) AS unique_contacts
    FROM lead_events le
    LEFT JOIN deals d ON d.id = le.deal_id
    WHERE le.brand_id = p_brand_id
      AND le.created_at BETWEEN p_from AND p_to
    GROUP BY le.source, COALESCE(le.source_name, le.source::TEXT)
  )
  SELECT json_build_object(
    'sources', COALESCE((
      SELECT json_agg(json_build_object(
        'source', source,
        'source_name', source_name,
        'leads_count', leads_count,
        'deals_created', deals_created,
        'deals_won', deals_won,
        'total_value_won', total_value_won,
        'unique_contacts', unique_contacts,
        'conversion_rate', CASE 
          WHEN leads_count > 0 
          THEN ROUND((deals_won::NUMERIC / leads_count) * 100, 1)
          ELSE 0 
        END,
        'avg_deal_value', CASE 
          WHEN deals_won > 0 
          THEN ROUND(total_value_won / deals_won, 2)
          ELSE 0 
        END
      ) ORDER BY leads_count DESC)
      FROM source_data
    ), '[]'::json),
    'total_leads', COALESCE((SELECT SUM(leads_count) FROM source_data), 0),
    'total_deals_won', COALESCE((SELECT SUM(deals_won) FROM source_data), 0),
    'total_revenue', COALESCE((SELECT SUM(total_value_won) FROM source_data), 0)
  ) INTO v_result;

  RETURN v_result;
END;
$$;


--
-- Name: get_marketing_campaign_kpis(uuid, date, date, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_marketing_campaign_kpis(p_brand_id uuid, p_from date, p_to date, p_channel_id uuid DEFAULT NULL::uuid, p_campaign_id uuid DEFAULT NULL::uuid) RETURNS TABLE(campaign_id uuid, campaign_name text, channel_name text, leads_count bigint, deals_count bigint, deals_won bigint, revenue numeric, marketing_cost numeric, cpl numeric, cac numeric, roi numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_is_company_brand boolean;
  v_company_brand_id uuid := '00000000-0000-0000-0000-000000000000';
BEGIN
  IF NOT has_marketing_access(get_user_id(auth.uid()), p_brand_id) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;
  v_is_company_brand := (p_brand_id = v_company_brand_id);

  RETURN QUERY
  WITH
  -- Collect all ADV campaign names linked to each marketing campaign
  adv_names AS (
    SELECT mcp.id as cid, array_agg(DISTINCT aps.external_campaign_name) as names
    FROM marketing_campaigns mcp
    JOIN ad_platform_stats aps ON (
      aps.campaign_id = mcp.id
      OR (mcp.external_id IS NOT NULL AND mcp.external_id != '' AND aps.external_campaign_id = mcp.external_id)
      -- Also match by similar name (fuzzy)
      OR aps.external_campaign_name ILIKE '%' || mcp.name || '%'
      OR mcp.name ILIKE '%' || aps.external_campaign_name || '%'
    )
    AND aps.stat_date >= p_from AND aps.stat_date <= p_to
    AND (v_is_company_brand OR aps.brand_id = p_brand_id)
    WHERE (v_is_company_brand OR mcp.brand_id = p_brand_id)
      AND (p_channel_id IS NULL OR mcp.channel_id = p_channel_id)
      AND (p_campaign_id IS NULL OR mcp.id = p_campaign_id)
    GROUP BY mcp.id
  ),
  campaign_leads AS (
    SELECT mcp.id as cid,
      COUNT(DISTINCT le.contact_id) as leads_total
    FROM marketing_campaigns mcp
    LEFT JOIN adv_names an ON an.cid = mcp.id
    LEFT JOIN lead_events le ON (
      -- Match by campaign name or external_id
      (mcp.external_id IS NOT NULL AND mcp.external_id != '' AND le.source_name ILIKE '%' || mcp.external_id || '%')
      OR le.source_name ILIKE '%' || mcp.name || '%'
      -- NEW: match by ADV campaign names
      OR EXISTS (
        SELECT 1 FROM unnest(an.names) aname
        WHERE le.source_name ILIKE '%' || aname || '%'
          OR aname ILIKE '%' || le.source_name || '%'
      )
    )
      AND le.received_at >= p_from::timestamptz AND le.received_at <= (p_to + 1)::timestamptz
      AND (v_is_company_brand OR le.brand_id = p_brand_id)
      AND (le.archived = false OR le.archived IS NULL)
    WHERE (v_is_company_brand OR mcp.brand_id = p_brand_id)
      AND (p_channel_id IS NULL OR mcp.channel_id = p_channel_id)
      AND (p_campaign_id IS NULL OR mcp.id = p_campaign_id)
    GROUP BY mcp.id
  ),
  campaign_revenue AS (
    SELECT mcp.id as cid,
      COUNT(DISTINCT d.id) as deals_total,
      COUNT(DISTINCT d.id) FILTER (WHERE d.status = 'won') as deals_won_count,
      COALESCE(SUM(DISTINCT d.value) FILTER (WHERE d.status = 'won'), 0) as total_revenue
    FROM marketing_campaigns mcp
    LEFT JOIN adv_names an ON an.cid = mcp.id
    JOIN lead_events le ON (
      (mcp.external_id IS NOT NULL AND mcp.external_id != '' AND le.source_name ILIKE '%' || mcp.external_id || '%')
      OR le.source_name ILIKE '%' || mcp.name || '%'
      OR EXISTS (
        SELECT 1 FROM unnest(an.names) aname
        WHERE le.source_name ILIKE '%' || aname || '%'
          OR aname ILIKE '%' || le.source_name || '%'
      )
    )
    JOIN contacts c ON le.contact_id = c.id
    JOIN deals d ON d.contact_id = c.id
      AND d.closed_at >= p_from::timestamptz AND d.closed_at <= (p_to + 1)::timestamptz
    WHERE (v_is_company_brand OR mcp.brand_id = p_brand_id)
      AND (v_is_company_brand OR le.brand_id = p_brand_id)
      AND (p_channel_id IS NULL OR mcp.channel_id = p_channel_id)
      AND (p_campaign_id IS NULL OR mcp.id = p_campaign_id)
    GROUP BY mcp.id
  ),
  campaign_adv_spend AS (
    SELECT mcp.id as cid,
      COALESCE(SUM(aps.spend), 0) as total_spend
    FROM marketing_campaigns mcp
    JOIN ad_platform_stats aps ON (
      aps.campaign_id = mcp.id
      OR (mcp.external_id IS NOT NULL AND mcp.external_id != '' AND aps.external_campaign_id = mcp.external_id)
      OR aps.external_campaign_name ILIKE '%' || mcp.name || '%'
      OR mcp.name ILIKE '%' || aps.external_campaign_name || '%'
    )
      AND aps.stat_date >= p_from AND aps.stat_date <= p_to
      AND (v_is_company_brand OR aps.brand_id = p_brand_id)
    WHERE (v_is_company_brand OR mcp.brand_id = p_brand_id)
      AND (p_channel_id IS NULL OR mcp.channel_id = p_channel_id)
      AND (p_campaign_id IS NULL OR mcp.id = p_campaign_id)
    GROUP BY mcp.id
  )
  SELECT
    mcp.id, mcp.name,
    COALESCE(ch.name, 'Non specificato'),
    COALESCE(cl.leads_total, 0)::bigint,
    COALESCE(cr.deals_total, 0)::bigint,
    COALESCE(cr.deals_won_count, 0)::bigint,
    COALESCE(cr.total_revenue, 0)::numeric,
    COALESCE(cas.total_spend, 0)::numeric,
    ROUND(COALESCE(cas.total_spend, 0) / NULLIF(cl.leads_total, 0), 2),
    ROUND(COALESCE(cas.total_spend, 0) / NULLIF(cr.deals_won_count, 0), 2),
    ROUND((COALESCE(cr.total_revenue, 0) - COALESCE(cas.total_spend, 0)) / NULLIF(cas.total_spend, 0) * 100, 2)
  FROM marketing_campaigns mcp
  LEFT JOIN marketing_channels ch ON ch.id = mcp.channel_id
  LEFT JOIN campaign_leads cl ON cl.cid = mcp.id
  LEFT JOIN campaign_revenue cr ON cr.cid = mcp.id
  LEFT JOIN campaign_adv_spend cas ON cas.cid = mcp.id
  WHERE (v_is_company_brand OR mcp.brand_id = p_brand_id)
    AND (p_channel_id IS NULL OR mcp.channel_id = p_channel_id)
    AND (p_campaign_id IS NULL OR mcp.id = p_campaign_id)
  ORDER BY COALESCE(cr.total_revenue, 0) DESC;
END;
$$;


--
-- Name: get_marketing_channel_kpis(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_marketing_channel_kpis(p_brand_id uuid, p_from date, p_to date) RETURNS TABLE(channel_id uuid, channel_name text, channel_type text, campaigns_count bigint, leads_count bigint, deals_won bigint, revenue numeric, marketing_cost numeric, avg_roi numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_is_company_brand boolean;
  v_company_brand_id uuid := '00000000-0000-0000-0000-000000000000';
BEGIN
  IF NOT has_marketing_access(get_user_id(auth.uid()), p_brand_id) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;
  v_is_company_brand := (p_brand_id = v_company_brand_id);

  RETURN QUERY
  WITH channel_adv_spend AS (
    SELECT ch.id as channel_id,
      COALESCE(SUM(aps.spend), 0) as total_spend
    FROM marketing_channels ch
    JOIN ad_platform_stats aps ON aps.platform::text = ch.platform::text
      AND aps.stat_date >= p_from AND aps.stat_date <= p_to
      AND (v_is_company_brand OR aps.brand_id = p_brand_id)
    WHERE (v_is_company_brand OR ch.brand_id = p_brand_id)
      AND ch.is_active = true AND ch.platform IS NOT NULL
    GROUP BY ch.id
    HAVING SUM(aps.spend) > 0
  ),
  -- Collect ADV campaign names per channel for lead matching
  channel_adv_names AS (
    SELECT ch.id as channel_id, array_agg(DISTINCT aps.external_campaign_name) as names
    FROM marketing_channels ch
    JOIN ad_platform_stats aps ON aps.platform::text = ch.platform::text
      AND aps.stat_date >= p_from AND aps.stat_date <= p_to
      AND (v_is_company_brand OR aps.brand_id = p_brand_id)
    WHERE (v_is_company_brand OR ch.brand_id = p_brand_id)
      AND ch.is_active = true AND ch.platform IS NOT NULL
    GROUP BY ch.id
  ),
  active_channels AS (
    SELECT cas.channel_id FROM channel_adv_spend cas
  ),
  channel_leads AS (
    SELECT mcp.channel_id,
      COUNT(DISTINCT le.contact_id) as leads_total
    FROM marketing_campaigns mcp
    LEFT JOIN channel_adv_names can ON can.channel_id = mcp.channel_id
    LEFT JOIN lead_events le ON (
      (mcp.external_id IS NOT NULL AND mcp.external_id != '' AND le.source_name ILIKE '%' || mcp.external_id || '%')
      OR le.source_name ILIKE '%' || mcp.name || '%'
      -- NEW: match via ADV campaign names
      OR EXISTS (
        SELECT 1 FROM unnest(can.names) aname
        WHERE le.source_name ILIKE '%' || aname || '%'
          OR aname ILIKE '%' || le.source_name || '%'
      )
    )
      AND le.received_at >= p_from::timestamptz AND le.received_at <= (p_to + 1)::timestamptz
      AND (v_is_company_brand OR le.brand_id = p_brand_id)
      AND (le.archived = false OR le.archived IS NULL)
    WHERE (v_is_company_brand OR mcp.brand_id = p_brand_id)
      AND mcp.channel_id IN (SELECT ac.channel_id FROM active_channels ac)
    GROUP BY mcp.channel_id
  ),
  channel_revenue AS (
    SELECT ch.id as channel_id,
      COUNT(DISTINCT d.id) FILTER (WHERE d.status = 'won') as deals_won_count,
      COALESCE(SUM(DISTINCT d.value) FILTER (WHERE d.status = 'won'), 0) as total_revenue
    FROM marketing_channels ch
    LEFT JOIN channel_adv_names can ON can.channel_id = ch.id
    JOIN lead_events le ON (
      le.source_name ILIKE '%' || ch.name || '%'
      OR le.source_name ILIKE '%' || REPLACE(ch.name, ' Ads', '') || '%'
      -- NEW: match via ADV campaign names
      OR EXISTS (
        SELECT 1 FROM unnest(can.names) aname
        WHERE le.source_name ILIKE '%' || aname || '%'
          OR aname ILIKE '%' || le.source_name || '%'
      )
    )
    JOIN contacts c ON le.contact_id = c.id
    JOIN deals d ON d.contact_id = c.id
      AND d.closed_at >= p_from::timestamptz AND d.closed_at <= (p_to + 1)::timestamptz
    WHERE (v_is_company_brand OR ch.brand_id = p_brand_id)
      AND (v_is_company_brand OR le.brand_id = p_brand_id)
      AND ch.id IN (SELECT ac.channel_id FROM active_channels ac)
    GROUP BY ch.id
  )
  SELECT 
    ch.id, ch.name, ch.type,
    COUNT(DISTINCT mcp.id)::bigint,
    COALESCE(cl.leads_total, 0)::bigint,
    COALESCE(cr.deals_won_count, 0)::bigint,
    COALESCE(cr.total_revenue, 0)::numeric,
    COALESCE(cas.total_spend, 0)::numeric,
    ROUND(
      (COALESCE(cr.total_revenue, 0) - COALESCE(cas.total_spend, 0)) 
      / NULLIF(cas.total_spend, 0) * 100, 2
    )
  FROM marketing_channels ch
  INNER JOIN channel_adv_spend cas ON cas.channel_id = ch.id
  LEFT JOIN marketing_campaigns mcp ON mcp.channel_id = ch.id
    AND (v_is_company_brand OR mcp.brand_id = p_brand_id)
  LEFT JOIN channel_leads cl ON cl.channel_id = ch.id
  LEFT JOIN channel_revenue cr ON cr.channel_id = ch.id
  WHERE ch.is_active = true
  GROUP BY ch.id, ch.name, ch.type, cl.leads_total, cr.deals_won_count, cr.total_revenue, cas.total_spend
  ORDER BY COALESCE(cr.total_revenue, 0) DESC;
END;
$$;


--
-- Name: get_marketing_leads_by_campaign(uuid[], date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_marketing_leads_by_campaign(p_brand_ids uuid[], p_from_date date, p_to_date date) RETURNS TABLE(campaign_id uuid, campaign_name text, channel_name text, total_leads bigint, manual_leads bigint, meta_leads bigint, webhook_leads bigint, meta_matched bigint, meta_unmatched bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH lead_counts AS (
    SELECT
      le.marketing_campaign_id,
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE le.source::text = 'manual') AS manual_ct,
      COUNT(*) FILTER (WHERE le.source::text = 'meta') AS meta_ct,
      COUNT(*) FILTER (WHERE le.source::text = 'webhook') AS webhook_ct
    FROM lead_events le
    WHERE le.brand_id = ANY(p_brand_ids)
      AND le.occurred_at::date BETWEEN p_from_date AND p_to_date
      AND le.archived = false
    GROUP BY le.marketing_campaign_id
  ),
  meta_reconciliation AS (
    SELECT
      mc2.id AS campaign_id,
      COUNT(mle.id) FILTER (WHERE mle.contact_id IS NOT NULL) AS matched,
      COUNT(mle.id) FILTER (WHERE mle.contact_id IS NULL AND mle.status != 'error') AS unmatched
    FROM meta_lead_events mle
    JOIN marketing_campaigns mc2 ON mc2.external_id = 'meta:' || mle.campaign_id
    WHERE mle.brand_id = ANY(p_brand_ids)
      AND mle.received_at::date BETWEEN p_from_date AND p_to_date
    GROUP BY mc2.id
  )
  SELECT
    mc.id AS campaign_id,
    mc.name AS campaign_name,
    COALESCE(ch.name, 'Non assegnato') AS channel_name,
    COALESCE(lc.total, 0) AS total_leads,
    COALESCE(lc.manual_ct, 0) AS manual_leads,
    COALESCE(lc.meta_ct, 0) AS meta_leads,
    COALESCE(lc.webhook_ct, 0) AS webhook_leads,
    COALESCE(mr.matched, 0) AS meta_matched,
    COALESCE(mr.unmatched, 0) AS meta_unmatched
  FROM marketing_campaigns mc
  LEFT JOIN marketing_channels ch ON ch.id = mc.channel_id
  LEFT JOIN lead_counts lc ON lc.marketing_campaign_id = mc.id
  LEFT JOIN meta_reconciliation mr ON mr.campaign_id = mc.id
  WHERE mc.brand_id = ANY(p_brand_ids)
    AND (mc.start_date <= p_to_date AND (mc.end_date IS NULL OR mc.end_date >= p_from_date))
  ORDER BY COALESCE(lc.total, 0) DESC;
$$;


--
-- Name: get_marketing_monthly_trend(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_marketing_monthly_trend(p_brand_id uuid, p_months_back integer DEFAULT 6) RETURNS TABLE(month date, revenue numeric, cost numeric, leads_count bigint, deals_won bigint, roi numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_is_system_brand boolean;
BEGIN
  -- Get the internal user id
  v_user_id := get_user_id(auth.uid());
  
  -- Check if this is the system brand (Azienda Intera)
  v_is_system_brand := (p_brand_id = '00000000-0000-0000-0000-000000000000');
  
  -- Validate brand access
  IF NOT v_is_system_brand AND NOT user_belongs_to_brand(v_user_id, p_brand_id) THEN
    RAISE EXCEPTION 'Access denied to brand';
  END IF;

  RETURN QUERY
  WITH months AS (
    -- Generate series of months
    SELECT date_trunc('month', d)::date AS month_start
    FROM generate_series(
      date_trunc('month', now()) - (p_months_back - 1 || ' months')::interval,
      date_trunc('month', now()),
      '1 month'::interval
    ) d
  ),
  monthly_costs AS (
    -- Aggregate marketing costs per month
    SELECT 
      date_trunc('month', mc.cost_date)::date AS month_start,
      COALESCE(SUM(mc.amount), 0) AS total_cost
    FROM marketing_costs mc
    JOIN marketing_campaigns camp ON mc.campaign_id = camp.id
    WHERE (v_is_system_brand OR camp.brand_id = p_brand_id)
      AND mc.cost_date >= date_trunc('month', now()) - (p_months_back || ' months')::interval
    GROUP BY 1
  ),
  monthly_deals AS (
    -- Aggregate won deals and revenue per month (attributed to campaigns)
    SELECT 
      date_trunc('month', d.closed_at)::date AS month_start,
      COUNT(*) AS won_count,
      COALESCE(SUM(d.value), 0) AS total_revenue
    FROM deals d
    WHERE d.status = 'won'
      AND d.closed_at IS NOT NULL
      AND d.marketing_campaign_id IS NOT NULL
      AND (v_is_system_brand OR d.brand_id = p_brand_id)
      AND d.closed_at >= date_trunc('month', now()) - (p_months_back || ' months')::interval
    GROUP BY 1
  ),
  monthly_leads AS (
    -- Count leads (lead_events) per month attributed to marketing
    SELECT 
      date_trunc('month', le.created_at)::date AS month_start,
      COUNT(*) AS lead_count
    FROM lead_events le
    JOIN deals d ON le.deal_id = d.id
    WHERE d.marketing_campaign_id IS NOT NULL
      AND (v_is_system_brand OR le.brand_id = p_brand_id)
      AND le.created_at >= date_trunc('month', now()) - (p_months_back || ' months')::interval
    GROUP BY 1
  )
  SELECT 
    m.month_start AS month,
    COALESCE(md.total_revenue, 0) AS revenue,
    COALESCE(mc.total_cost, 0) AS cost,
    COALESCE(ml.lead_count, 0) AS leads_count,
    COALESCE(md.won_count, 0) AS deals_won,
    CASE 
      WHEN COALESCE(mc.total_cost, 0) = 0 THEN 0
      ELSE ROUND(((COALESCE(md.total_revenue, 0) - COALESCE(mc.total_cost, 0)) / mc.total_cost) * 100, 1)
    END AS roi
  FROM months m
  LEFT JOIN monthly_costs mc ON mc.month_start = m.month_start
  LEFT JOIN monthly_deals md ON md.month_start = m.month_start
  LEFT JOIN monthly_leads ml ON ml.month_start = m.month_start
  ORDER BY m.month_start;
END;
$$;


--
-- Name: get_marketing_summary_kpis(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_marketing_summary_kpis(p_brand_id uuid, p_from date, p_to date) RETURNS TABLE(total_leads bigint, total_deals bigint, total_deals_won bigint, total_revenue numeric, total_marketing_cost numeric, avg_cpl numeric, avg_cac numeric, overall_roi numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT has_marketing_access(get_user_id(auth.uid()), p_brand_id) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  RETURN QUERY
  WITH channel_agg AS (
    SELECT
      COALESCE(SUM(ch.leads_count), 0)::bigint AS total_leads,
      COALESCE(SUM(ch.deals_won), 0)::bigint AS total_deals_won,
      COALESCE(SUM(ch.revenue), 0)::numeric AS total_revenue,
      COALESCE(SUM(ch.marketing_cost), 0)::numeric AS total_cost
    FROM get_marketing_channel_kpis(p_brand_id, p_from, p_to) ch
  ),
  deal_count AS (
    SELECT COUNT(DISTINCT d.id)::bigint AS total_deals
    FROM deals d
    WHERE d.created_at >= p_from::timestamptz
      AND d.created_at < (p_to + 1)::timestamptz
      AND (
        p_brand_id = '00000000-0000-0000-0000-000000000000'
        OR d.brand_id = p_brand_id
      )
  )
  SELECT
    ca.total_leads,
    dc.total_deals,
    ca.total_deals_won,
    ca.total_revenue,
    ca.total_cost,
    ROUND(ca.total_cost / NULLIF(ca.total_leads, 0), 2) AS avg_cpl,
    ROUND(ca.total_cost / NULLIF(ca.total_deals_won, 0), 2) AS avg_cac,
    ROUND((ca.total_revenue - ca.total_cost) / NULLIF(ca.total_cost, 0) * 100, 2) AS overall_roi
  FROM channel_agg ca
  CROSS JOIN deal_count dc;
END;
$$;


--
-- Name: get_module_adoption_stats(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_module_adoption_stats(p_brand_id uuid, p_days integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  result jsonb;
  v_since timestamptz := now() - (p_days || ' days')::interval;
BEGIN
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'module_key', module_key,
    'total_events', total_events,
    'unique_users', unique_users,
    'last_used', last_used,
    'avg_daily', ROUND(total_events::numeric / GREATEST(p_days, 1), 1)
  ) ORDER BY total_events DESC), '[]'::jsonb)
  INTO result
  FROM (
    SELECT
      module_key,
      COUNT(*) AS total_events,
      COUNT(DISTINCT user_id) AS unique_users,
      MAX(created_at) AS last_used
    FROM module_usage_events
    WHERE brand_id = p_brand_id
      AND created_at >= v_since
    GROUP BY module_key
  ) sub;

  RETURN result;
END;
$$;


--
-- Name: get_my_permissions(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_permissions(p_brand_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_user_role app_role;
  v_pages jsonb;
  v_hidden_columns jsonb;
BEGIN
  -- Get internal user ID
  SELECT u.id INTO v_user_id
  FROM users u
  WHERE u.supabase_auth_id = auth.uid();
  
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('pages', '[]'::jsonb, 'hidden_columns', '[]'::jsonb);
  END IF;
  
  -- Get user's role
  SELECT role INTO v_user_role
  FROM user_roles
  WHERE user_id = v_user_id
  AND brand_id = p_brand_id
  LIMIT 1;
  
  -- Build pages permissions
  SELECT jsonb_agg(jsonb_build_object(
    'page', p.page::text,
    'can_access', COALESCE(
      up.can_access,
      rp.can_access,
      CASE WHEN v_user_role IN ('admin'::app_role, 'ceo'::app_role) THEN true ELSE true END
    )
  ))
  INTO v_pages
  FROM unnest(enum_range(NULL::app_page)) AS p(page)
  LEFT JOIN user_page_permissions up ON up.user_id = v_user_id AND up.brand_id = p_brand_id AND up.page = p.page
  LEFT JOIN role_page_permissions rp ON rp.brand_id = p_brand_id AND rp.role = v_user_role::text AND rp.page = p.page;
  
  -- Build hidden columns
  SELECT jsonb_agg(jsonb_build_object(
    'table_name', COALESCE(uh.table_name, rh.table_name),
    'column_key', COALESCE(uh.column_key, rh.column_key),
    'is_hidden', COALESCE(uh.is_hidden, rh.is_hidden)
  ))
  INTO v_hidden_columns
  FROM (
    SELECT table_name, column_key, is_hidden FROM user_hidden_columns WHERE user_id = v_user_id AND brand_id = p_brand_id
    UNION
    SELECT table_name, column_key, is_hidden FROM role_hidden_columns WHERE brand_id = p_brand_id AND role = v_user_role::text
    AND NOT EXISTS (
      SELECT 1 FROM user_hidden_columns 
      WHERE user_id = v_user_id AND brand_id = p_brand_id 
      AND table_name = role_hidden_columns.table_name 
      AND column_key = role_hidden_columns.column_key
    )
  ) combined
  LEFT JOIN user_hidden_columns uh ON uh.user_id = v_user_id AND uh.brand_id = p_brand_id AND uh.table_name = combined.table_name AND uh.column_key = combined.column_key
  LEFT JOIN role_hidden_columns rh ON rh.brand_id = p_brand_id AND rh.role = v_user_role::text AND rh.table_name = combined.table_name AND rh.column_key = combined.column_key;
  
  RETURN jsonb_build_object(
    'user_id', v_user_id,
    'role', v_user_role::text,
    'pages', COALESCE(v_pages, '[]'::jsonb),
    'hidden_columns', COALESCE(v_hidden_columns, '[]'::jsonb)
  );
END;
$$;


--
-- Name: get_notification_preferences(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_notification_preferences(p_brand_id uuid) RETURNS TABLE(id uuid, user_id uuid, brand_id uuid, notification_type text, enabled boolean, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
BEGIN
  SELECT u.id INTO v_user_id FROM public.users u WHERE u.supabase_auth_id = auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  IF NOT user_belongs_to_brand(v_user_id, p_brand_id) THEN
    RAISE EXCEPTION 'Forbidden: no access to brand';
  END IF;

  RETURN QUERY
  SELECT 
    np.id,
    np.user_id,
    np.brand_id,
    np.notification_type::text,
    np.enabled,
    np.created_at
  FROM notification_preferences np
  WHERE np.user_id = v_user_id
    AND np.brand_id = p_brand_id;
END;
$$;


--
-- Name: ai_configs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ai_configs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    brand_id uuid NOT NULL,
    mode public.ai_mode DEFAULT 'off'::public.ai_mode NOT NULL,
    active_prompt_version text,
    rules_json jsonb DEFAULT '{}'::jsonb NOT NULL,
    updated_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    confidence_threshold numeric DEFAULT 0.6,
    CONSTRAINT ai_configs_confidence_threshold_check CHECK (((confidence_threshold >= (0)::numeric) AND (confidence_threshold <= (1)::numeric)))
);


--
-- Name: get_or_create_ai_config(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_or_create_ai_config(p_brand_id uuid) RETURNS public.ai_configs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_config public.ai_configs;
BEGIN
  SELECT * INTO v_config FROM public.ai_configs WHERE brand_id = p_brand_id;
  
  IF NOT FOUND THEN
    INSERT INTO public.ai_configs (brand_id)
    VALUES (p_brand_id)
    RETURNING * INTO v_config;
  END IF;
  
  RETURN v_config;
END;
$$;


--
-- Name: get_or_create_entity_thread(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_or_create_entity_thread(p_brand_id uuid, p_entity_type text, p_entity_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_thread_id uuid;
BEGIN
  v_user_id := get_user_id(auth.uid());
  
  -- Check brand access
  IF NOT user_belongs_to_brand(v_user_id, p_brand_id) THEN
    RAISE EXCEPTION 'Access denied to this brand';
  END IF;
  
  -- Try to find existing thread
  SELECT id INTO v_thread_id
  FROM chat_threads
  WHERE brand_id = p_brand_id 
    AND entity_type = p_entity_type 
    AND entity_id = p_entity_id
    AND type = 'entity';
  
  -- Create if not exists
  IF v_thread_id IS NULL THEN
    INSERT INTO chat_threads (brand_id, type, entity_type, entity_id, created_by)
    VALUES (p_brand_id, 'entity', p_entity_type, p_entity_id, v_user_id)
    RETURNING id INTO v_thread_id;
    
    -- Add creator as member (use 'owner' instead of invalid 'admin')
    INSERT INTO chat_thread_members (thread_id, user_id, role)
    VALUES (v_thread_id, v_user_id, 'owner');
  END IF;
  
  -- Ensure current user is member
  INSERT INTO chat_thread_members (thread_id, user_id)
  VALUES (v_thread_id, v_user_id)
  ON CONFLICT (thread_id, user_id) DO NOTHING;
  
  RETURN v_thread_id;
END;
$$;


--
-- Name: get_or_create_executive_thread(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_or_create_executive_thread(p_brand_id uuid, p_user_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_thread_id uuid;
  v_crm_user_id uuid;
BEGIN
  -- Get CRM user id
  SELECT id INTO v_crm_user_id FROM public.users WHERE supabase_auth_id = p_user_id;
  IF v_crm_user_id IS NULL THEN
    RAISE EXCEPTION 'User not found';
  END IF;

  -- Find existing executive thread for this user+brand
  SELECT ct.id INTO v_thread_id
  FROM public.chat_threads ct
  JOIN public.chat_thread_members ctm ON ctm.thread_id = ct.id
  WHERE ct.brand_id = p_brand_id
    AND ct.type = 'executive'
    AND ctm.user_id = v_crm_user_id
    AND ctm.left_at IS NULL
  LIMIT 1;

  IF v_thread_id IS NOT NULL THEN
    RETURN v_thread_id;
  END IF;

  -- Create new executive thread
  INSERT INTO public.chat_threads (brand_id, type, title, created_by)
  VALUES (p_brand_id, 'executive', 'Agente Executive', v_crm_user_id)
  RETURNING id INTO v_thread_id;

  -- Add user as owner
  INSERT INTO public.chat_thread_members (thread_id, user_id, role)
  VALUES (v_thread_id, v_crm_user_id, 'owner');

  RETURN v_thread_id;
END;
$$;


--
-- Name: get_overdue_installments(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_overdue_installments(p_brand_id uuid, p_days_ahead integer DEFAULT 7) RETURNS TABLE(payment_id uuid, order_id uuid, brand_id uuid, contact_id uuid, contact_name text, order_number text, total_amount numeric, paid_amount numeric, remaining_amount numeric, installment_index integer, installment_amount numeric, due_date date, days_overdue integer, status text, assigned_user_id uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH series AS (
    SELECT
      p.id AS payment_id,
      p.order_id,
      p.brand_id,
      so.contact_id,
      COALESCE(NULLIF(TRIM(CONCAT_WS(' ', c.first_name, c.last_name)), ''), c.email, 'Cliente')::text AS contact_name,
      so.order_number,
      so.total_amount,
      so.paid_amount,
      (so.total_amount - so.paid_amount)::numeric AS remaining_amount,
      so.assigned_user_id,
      gs.idx AS installment_index,
      COALESCE((p.plan_details->>'installment_amount')::numeric, 0) AS installment_amount,
      (
        COALESCE((p.plan_details->>'first_due_date')::date, p.created_at::date)
        + (gs.idx * COALESCE((p.plan_details->>'frequency_months')::integer, 1) || ' month')::interval
      )::date AS due_date,
      COALESCE((p.plan_details->>'num_installments')::integer, 0) AS num_installments
    FROM public.payments p
    JOIN public.sales_orders so ON so.id = p.order_id
    LEFT JOIN public.contacts c ON c.id = so.contact_id
    CROSS JOIN LATERAL generate_series(0, GREATEST(COALESCE((p.plan_details->>'num_installments')::integer, 1) - 1, 0)) AS gs(idx)
    WHERE p.brand_id = p_brand_id
      AND p.plan_details IS NOT NULL
      AND p.plan_details ? 'num_installments'
      AND so.status NOT IN ('cancelled', 'refunded', 'paid')
  )
  SELECT
    s.payment_id,
    s.order_id,
    s.brand_id,
    s.contact_id,
    s.contact_name,
    s.order_number,
    s.total_amount,
    s.paid_amount,
    s.remaining_amount,
    s.installment_index,
    s.installment_amount,
    s.due_date,
    GREATEST(0, (CURRENT_DATE - s.due_date))::integer AS days_overdue,
    CASE
      WHEN s.due_date < CURRENT_DATE THEN 'overdue'
      WHEN s.due_date <= CURRENT_DATE + p_days_ahead THEN 'upcoming'
      ELSE 'future'
    END AS status,
    s.assigned_user_id
  FROM series s
  WHERE s.due_date <= CURRENT_DATE + p_days_ahead
  ORDER BY s.due_date ASC
  LIMIT 500;
END;
$$;


--
-- Name: get_paginated_notifications(uuid, text, boolean, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_paginated_notifications(p_brand_id uuid DEFAULT NULL::uuid, p_type_filter text DEFAULT NULL::text, p_unread_only boolean DEFAULT false, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_result json;
BEGIN
  SELECT u.id INTO v_user_id FROM public.users u WHERE u.supabase_auth_id = auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  p_limit := LEAST(p_limit, 200);
  p_offset := GREATEST(p_offset, 0);

  WITH filtered AS (
    SELECT 
      n.id,
      n.brand_id,
      n.type::text as type,
      n.title,
      n.body,
      n.entity_type,
      n.entity_id,
      n.read_at,
      n.created_at
    FROM notifications n
    WHERE n.user_id = v_user_id
      AND (p_brand_id IS NULL OR n.brand_id = p_brand_id)
      AND (p_type_filter IS NULL OR n.type::text = p_type_filter)
      AND (NOT p_unread_only OR n.read_at IS NULL)
    ORDER BY n.created_at DESC
    LIMIT p_limit
    OFFSET p_offset
  ),
  total AS (
    SELECT COUNT(*) as cnt
    FROM notifications n
    WHERE n.user_id = v_user_id
      AND (p_brand_id IS NULL OR n.brand_id = p_brand_id)
      AND (p_type_filter IS NULL OR n.type::text = p_type_filter)
      AND (NOT p_unread_only OR n.read_at IS NULL)
  )
  SELECT json_build_object(
    'data', COALESCE((SELECT json_agg(row_to_json(f)) FROM filtered f), '[]'::json),
    'total', (SELECT cnt FROM total),
    'limit', p_limit,
    'offset', p_offset
  ) INTO v_result;

  RETURN v_result;
END;
$$;


--
-- Name: get_pending_ai_tag_jobs(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_pending_ai_tag_jobs(p_limit integer DEFAULT 10) RETURNS TABLE(job_id uuid, brand_id uuid, deal_id uuid, trigger_reason text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  UPDATE ai_tag_deal_jobs
  SET status = 'processing', 
      started_at = now(), 
      attempts = attempts + 1
  WHERE id IN (
    SELECT j.id FROM ai_tag_deal_jobs j
    WHERE j.status = 'pending'
    ORDER BY j.created_at ASC
    LIMIT p_limit
    FOR UPDATE SKIP LOCKED
  )
  RETURNING ai_tag_deal_jobs.id, ai_tag_deal_jobs.brand_id, ai_tag_deal_jobs.deal_id, ai_tag_deal_jobs.trigger_reason;
END;
$$;


--
-- Name: get_pending_alert_deliveries(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_pending_alert_deliveries(_limit integer DEFAULT 50) RETURNS TABLE(delivery_id uuid, channel_id uuid, anomaly_id uuid, brand_id uuid, channel_type text, destination text, webhook_secret text, mask_pii boolean, attempt_count integer)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    d.id, d.channel_id, d.anomaly_id, d.brand_id,
    c.channel_type, c.destination, c.webhook_secret, c.mask_pii,
    d.attempt_count
  FROM public.audit_alert_deliveries d
  JOIN public.audit_alert_channels c ON c.id = d.channel_id
  WHERE d.status IN ('pending', 'retrying')
    AND d.attempt_count < 5
    AND c.is_active = true
  ORDER BY d.created_at ASC
  LIMIT LEAST(_limit, 200)
  FOR UPDATE SKIP LOCKED;
$$;


--
-- Name: get_pipeline_funnel_analytics(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_pipeline_funnel_analytics(p_brand_id uuid, p_from timestamp with time zone DEFAULT (now() - '30 days'::interval), p_to timestamp with time zone DEFAULT now()) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id UUID := get_user_id(auth.uid());
  v_result JSON;
BEGIN
  IF NOT user_belongs_to_brand(v_user_id, p_brand_id) THEN
    RAISE EXCEPTION 'Access denied to brand';
  END IF;

  WITH stage_data AS (
    SELECT 
      ps.id AS stage_id,
      ps.name AS stage_name,
      ps.color AS stage_color,
      ps.order_index AS stage_position,
      COUNT(DISTINCT CASE 
        WHEN dsh.to_stage_id = ps.id AND dsh.changed_at BETWEEN p_from AND p_to 
        THEN dsh.deal_id 
      END) AS deals_entered,
      COUNT(DISTINCT CASE 
        WHEN dsh.from_stage_id = ps.id 
          AND dsh.changed_at BETWEEN p_from AND p_to
          AND EXISTS (
            SELECT 1 FROM pipeline_stages ps2 
            WHERE ps2.id = dsh.to_stage_id 
              AND ps2.order_index > ps.order_index
          )
        THEN dsh.deal_id 
      END) AS deals_exited_to_next,
      COUNT(DISTINCT CASE 
        WHEN d.status::text = 'won' 
          AND d.current_stage_id = ps.id
          AND d.closed_at BETWEEN p_from AND p_to
        THEN d.id 
      END) AS deals_won,
      COUNT(DISTINCT CASE 
        WHEN d.status::text = 'lost' 
          AND d.current_stage_id = ps.id
          AND d.closed_at BETWEEN p_from AND p_to
        THEN d.id 
      END) AS deals_lost,
      COALESCE(
        AVG(
          CASE 
            WHEN dsh.from_stage_id = ps.id 
            THEN EXTRACT(EPOCH FROM (
              COALESCE(
                (SELECT MIN(dsh2.changed_at) 
                 FROM deal_stage_history dsh2 
                 WHERE dsh2.deal_id = dsh.deal_id 
                   AND dsh2.from_stage_id = ps.id
                   AND dsh2.changed_at > dsh.changed_at),
                NOW()
              ) - dsh.changed_at
            )) / 86400
          END
        ),
        0
      ) AS avg_days_in_stage
    FROM pipeline_stages ps
    LEFT JOIN deal_stage_history dsh ON dsh.to_stage_id = ps.id OR dsh.from_stage_id = ps.id
    LEFT JOIN deals d ON d.current_stage_id = ps.id AND d.brand_id = p_brand_id
    WHERE ps.is_active = true
    GROUP BY ps.id, ps.name, ps.color, ps.order_index
    ORDER BY ps.order_index
  ),
  overall_stats AS (
    SELECT
      COUNT(*) FILTER (WHERE status::text = 'won' AND closed_at BETWEEN p_from AND p_to) AS total_won,
      COUNT(*) FILTER (WHERE status::text = 'lost' AND closed_at BETWEEN p_from AND p_to) AS total_lost,
      COUNT(*) FILTER (WHERE created_at BETWEEN p_from AND p_to) AS total_deals,
      COALESCE(SUM(value) FILTER (WHERE status::text IN ('open', 'reopened_for_support')), 0) AS total_pipeline_value,
      COALESCE(
        AVG(EXTRACT(EPOCH FROM (closed_at - created_at)) / 86400) 
        FILTER (WHERE status::text IN ('won', 'lost') AND closed_at BETWEEN p_from AND p_to),
        0
      ) AS avg_velocity_days
    FROM deals
    WHERE brand_id = p_brand_id
  )
  SELECT json_build_object(
    'stages', COALESCE((
      SELECT json_agg(json_build_object(
        'stage_id', stage_id,
        'stage_name', stage_name,
        'stage_color', stage_color,
        'deals_entered', deals_entered,
        'deals_exited_to_next', deals_exited_to_next,
        'deals_won', deals_won,
        'deals_lost', deals_lost,
        'conversion_rate', CASE 
          WHEN deals_entered > 0 
          THEN ROUND((deals_exited_to_next::NUMERIC / deals_entered) * 100, 1)
          ELSE 0 
        END,
        'avg_days_in_stage', ROUND(avg_days_in_stage::NUMERIC, 1)
      ) ORDER BY stage_position)
      FROM stage_data
    ), '[]'::json),
    'total_deals', COALESCE((SELECT total_deals FROM overall_stats), 0),
    'overall_win_rate', COALESCE((
      SELECT CASE 
        WHEN (total_won + total_lost) > 0 
        THEN ROUND((total_won::NUMERIC / (total_won + total_lost)) * 100, 1)
        ELSE 0 
      END
      FROM overall_stats
    ), 0),
    'avg_deal_velocity_days', COALESCE((SELECT ROUND(avg_velocity_days::NUMERIC, 1) FROM overall_stats), 0),
    'total_pipeline_value', COALESCE((SELECT total_pipeline_value FROM overall_stats), 0)
  ) INTO v_result;

  RETURN v_result;
END;
$$;


--
-- Name: get_revenue_by_payment_method(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_revenue_by_payment_method(p_brand_id uuid, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(method text, total_revenue numeric, order_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT 
    p.method::TEXT,
    COALESCE(SUM(p.amount), 0) AS total_revenue,
    COUNT(DISTINCT p.order_id) AS order_count
  FROM payments p
  WHERE p.brand_id = p_brand_id
    AND p.status = 'completed'
    AND (p_from IS NULL OR p.paid_at >= p_from)
    AND (p_to IS NULL OR p.paid_at <= p_to)
  GROUP BY p.method
  ORDER BY total_revenue DESC;
$$;


--
-- Name: get_revenue_forecast(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_revenue_forecast(p_brand_id uuid, p_period text DEFAULT 'month'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result JSONB;
  v_period_start DATE;
  v_period_end DATE;
  v_predicted_from_deals NUMERIC := 0;
  v_predicted_from_history NUMERIC := 0;
  v_total_predicted NUMERIC;
  v_confidence NUMERIC;
  v_prev_period_revenue NUMERIC;
  v_same_period_last_year NUMERIC;
  v_factors JSONB := '[]';
  v_deal_count INTEGER := 0;
  v_historical_months INTEGER;
  v_stage_contribution NUMERIC;
BEGIN
  IF NOT user_belongs_to_brand(get_user_id(auth.uid()), p_brand_id) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  IF p_period = 'quarter' THEN
    v_period_start := date_trunc('quarter', now())::DATE;
    v_period_end := (date_trunc('quarter', now()) + INTERVAL '3 months - 1 day')::DATE;
    v_historical_months := 12;
  ELSE
    v_period_start := date_trunc('month', now())::DATE;
    v_period_end := (date_trunc('month', now()) + INTERVAL '1 month - 1 day')::DATE;
    v_historical_months := 6;
  END IF;

  -- Calculate from open deals with stage probability
  SELECT COALESCE(SUM(
    d.value * (ps.order_index::NUMERIC / NULLIF(
      (SELECT MAX(order_index) FROM pipeline_stages WHERE brand_id = p_brand_id AND is_active = true), 0
    ) * 0.8)
  ), 0), COUNT(*)
  INTO v_predicted_from_deals, v_deal_count
  FROM deals d
  LEFT JOIN pipeline_stages ps ON d.current_stage_id = ps.id
  WHERE d.brand_id = p_brand_id AND d.status = 'open' AND d.value IS NOT NULL;

  v_factors := v_factors || jsonb_build_object('factor', 'open_deals', 'value', v_predicted_from_deals, 'detail', format('%s deal aperti', v_deal_count));

  -- Historical average
  SELECT COALESCE(AVG(monthly_revenue), 0) INTO v_predicted_from_history
  FROM (
    SELECT date_trunc('month', closed_at) as month, SUM(value) as monthly_revenue
    FROM deals WHERE brand_id = p_brand_id AND status = 'won' AND value IS NOT NULL AND closed_at >= now() - (v_historical_months || ' months')::INTERVAL
    GROUP BY 1
  ) monthly;

  v_factors := v_factors || jsonb_build_object('factor', 'historical_trend', 'value', v_predicted_from_history, 'detail', format('Media %s mesi', v_historical_months));

  v_total_predicted := (v_predicted_from_deals * 0.6) + (v_predicted_from_history * 0.4);
  v_confidence := LEAST(1.0, CASE WHEN v_deal_count > 5 THEN 0.3 ELSE v_deal_count * 0.06 END + CASE WHEN v_predicted_from_history > 0 THEN 0.4 ELSE 0.1 END + 0.3);

  SELECT COALESCE(SUM(value), 0) INTO v_prev_period_revenue FROM deals
  WHERE brand_id = p_brand_id AND status = 'won' AND closed_at >= v_period_start - (v_period_end - v_period_start + 1) AND closed_at < v_period_start;

  SELECT COALESCE(SUM(value), 0) INTO v_same_period_last_year FROM deals
  WHERE brand_id = p_brand_id AND status = 'won' AND closed_at >= v_period_start - INTERVAL '1 year' AND closed_at < v_period_end - INTERVAL '1 year';

  v_result := jsonb_build_object(
    'period', to_char(v_period_start, 'Month YYYY'),
    'period_start', v_period_start,
    'period_end', v_period_end,
    'predicted_revenue', ROUND(v_total_predicted, 2),
    'confidence', ROUND(v_confidence, 3),
    'range', jsonb_build_object('min', ROUND(v_total_predicted * (1 - (1 - v_confidence) * 0.5), 2), 'max', ROUND(v_total_predicted * (1 + (1 - v_confidence) * 0.5), 2)),
    'breakdown', jsonb_build_object('from_open_deals', ROUND(v_predicted_from_deals, 2), 'from_historical_trend', ROUND(v_predicted_from_history, 2)),
    'comparison', jsonb_build_object(
      'vs_last_period', CASE WHEN v_prev_period_revenue > 0 THEN ROUND(((v_total_predicted - v_prev_period_revenue) / v_prev_period_revenue) * 100, 1) ELSE NULL END,
      'vs_same_period_last_year', CASE WHEN v_same_period_last_year > 0 THEN ROUND(((v_total_predicted - v_same_period_last_year) / v_same_period_last_year) * 100, 1) ELSE NULL END
    ),
    'factors', v_factors,
    'generated_at', now()
  );

  INSERT INTO forecasts (brand_id, forecast_type, period_start, period_end, predicted_value, predicted_min, predicted_max, confidence_level, factors)
  VALUES (p_brand_id, 'revenue', v_period_start, v_period_end, v_total_predicted, v_total_predicted * (1 - (1 - v_confidence) * 0.5), v_total_predicted * (1 + (1 - v_confidence) * 0.5), v_confidence, v_factors)
  ON CONFLICT (brand_id, forecast_type, period_start, period_end) DO UPDATE SET predicted_value = EXCLUDED.predicted_value, predicted_min = EXCLUDED.predicted_min, predicted_max = EXCLUDED.predicted_max, confidence_level = EXCLUDED.confidence_level, factors = EXCLUDED.factors, created_at = now();

  RETURN v_result;
END;
$$;


--
-- Name: get_role_level(public.app_role); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_role_level(p_role public.app_role) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE p_role
    WHEN 'admin' THEN 100
    WHEN 'ceo' THEN 90
    WHEN 'responsabile_venditori' THEN 50
    WHEN 'responsabile_callcenter' THEN 50
    WHEN 'venditore' THEN 10
    WHEN 'sales' THEN 10
    WHEN 'operatore_callcenter' THEN 10
    WHEN 'callcenter' THEN 10
    ELSE 0
  END;
$$;


--
-- Name: get_sales_capacity(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_sales_capacity(p_brand_id uuid, p_date_from date, p_date_to date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  IF p_date_to < p_date_from THEN
    RETURN '[]'::jsonb;
  END IF;

  WITH
  -- All sales users for this brand
  sales_users AS (
    SELECT DISTINCT u.id, u.full_name, u.email
    FROM public.users u
    JOIN public.user_roles ur ON ur.user_id = u.id
    WHERE ur.brand_id = p_brand_id
      AND ur.is_active = true
      AND ur.role IN ('venditore', 'responsabile_venditori', 'sales')
    LIMIT 500
  ),
  -- Days in range
  days AS (
    SELECT d::date AS day, EXTRACT(DOW FROM d)::smallint AS weekday
    FROM generate_series(p_date_from, p_date_to, interval '1 day') d
  ),
  -- Available minutes per (sales, day): sum of slot durations matching weekday, minus time off
  avail_per_day AS (
    SELECT
      su.id AS user_id,
      d.day,
      COALESCE(SUM(EXTRACT(EPOCH FROM (sa.end_time - sa.start_time)) / 60)::int, 0) AS available_minutes
    FROM sales_users su
    CROSS JOIN days d
    LEFT JOIN public.sales_availability sa
      ON sa.user_id = su.id
      AND sa.brand_id = p_brand_id
      AND sa.is_active = true
      AND sa.weekday = d.weekday
      AND sa.valid_from <= d.day
      AND (sa.valid_to IS NULL OR sa.valid_to >= d.day)
    LEFT JOIN public.sales_time_off sto
      ON sto.user_id = su.id
      AND sto.brand_id = p_brand_id
      AND d.day BETWEEN sto.start_date AND sto.end_date
    WHERE sto.id IS NULL  -- exclude days off
    GROUP BY su.id, d.day
  ),
  -- Booked minutes per sales in range
  booked AS (
    SELECT
      a.assigned_sales_user_id AS user_id,
      COALESCE(SUM(a.duration_minutes), 0)::int AS booked_minutes,
      COUNT(*)::int AS appointment_count
    FROM public.appointments a
    WHERE a.brand_id = p_brand_id
      AND a.assigned_sales_user_id IS NOT NULL
      AND a.scheduled_at::date BETWEEN p_date_from AND p_date_to
      AND a.status NOT IN ('cancelled', 'no_show')
    GROUP BY a.assigned_sales_user_id
    LIMIT 500
  ),
  -- Aggregated availability per sales
  agg AS (
    SELECT
      user_id,
      SUM(available_minutes)::int AS available_minutes,
      COUNT(*) FILTER (WHERE available_minutes > 0)::int AS working_days
    FROM avail_per_day
    GROUP BY user_id
  )
  SELECT jsonb_agg(
    jsonb_build_object(
      'user_id', su.id,
      'full_name', su.full_name,
      'email', su.email,
      'available_minutes', COALESCE(agg.available_minutes, 0),
      'booked_minutes', COALESCE(b.booked_minutes, 0),
      'appointment_count', COALESCE(b.appointment_count, 0),
      'working_days', COALESCE(agg.working_days, 0),
      'utilization_pct', CASE
        WHEN COALESCE(agg.available_minutes, 0) > 0
          THEN ROUND((COALESCE(b.booked_minutes, 0)::numeric / agg.available_minutes) * 100, 1)
        ELSE NULL
      END
    )
    ORDER BY su.full_name
  )
  INTO v_result
  FROM sales_users su
  LEFT JOIN agg ON agg.user_id = su.id
  LEFT JOIN booked b ON b.user_id = su.id;

  RETURN COALESCE(v_result, '[]'::jsonb);
END;
$$;


--
-- Name: get_sales_kpis(uuid, timestamp with time zone, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_sales_kpis(p_brand_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result JSONB;
  v_user_id UUID;
BEGIN
  v_user_id := get_user_id(auth.uid());
  
  -- Check permissions
  IF NOT user_belongs_to_brand(v_user_id, p_brand_id) THEN
    RAISE EXCEPTION 'Permission denied';
  END IF;
  
  SELECT jsonb_build_object(
    'total_revenue', COALESCE(SUM(CASE WHEN status IN ('paid', 'partially_paid') THEN paid_amount ELSE 0 END), 0),
    'total_orders', COUNT(*),
    'orders_paid', COUNT(*) FILTER (WHERE status = 'paid'),
    'orders_pending', COUNT(*) FILTER (WHERE status IN ('draft', 'confirmed', 'partially_paid')),
    'avg_order_value', COALESCE(AVG(total_amount) FILTER (WHERE status != 'cancelled'), 0),
    'conversion_rate', CASE 
      WHEN COUNT(*) > 0 THEN 
        ROUND((COUNT(*) FILTER (WHERE status = 'paid')::NUMERIC / COUNT(*)::NUMERIC) * 100, 2)
      ELSE 0 
    END
  ) INTO v_result
  FROM sales_orders
  WHERE brand_id = p_brand_id
    AND created_at BETWEEN p_from AND p_to
    AND (p_user_id IS NULL OR assigned_user_id = p_user_id);
  
  RETURN v_result;
END;
$$;


--
-- Name: get_salesperson_kpis(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_salesperson_kpis(p_brand_id uuid, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result JSON;
  v_from TIMESTAMPTZ;
  v_to TIMESTAMPTZ;
BEGIN
  -- Validate brand access
  IF NOT user_belongs_to_brand(get_user_id(auth.uid()), p_brand_id) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;
  
  -- Default to last 30 days if no range
  v_from := COALESCE(p_from, now() - interval '30 days');
  v_to := COALESCE(p_to, now());

  SELECT json_agg(row_to_json(kpi))
  INTO v_result
  FROM (
    SELECT 
      u.id as user_id,
      u.full_name,
      u.email,
      ur.role::text,
      -- Conteggi deal
      COUNT(d.id) FILTER (WHERE d.status = 'open' OR d.status = 'reopened_for_support') as deals_open,
      COUNT(d.id) FILTER (WHERE d.status = 'won' AND d.closed_at >= v_from AND d.closed_at < v_to) as deals_won,
      COUNT(d.id) FILTER (WHERE d.status = 'lost' AND d.closed_at >= v_from AND d.closed_at < v_to) as deals_lost,
      COUNT(d.id) FILTER (WHERE d.status = 'closed' AND d.closed_at >= v_from AND d.closed_at < v_to) as deals_closed,
      -- Valore vinto (won + closed)
      COALESCE(SUM(d.value) FILTER (
        WHERE d.status IN ('won', 'closed') 
        AND d.closed_at >= v_from AND d.closed_at < v_to
      ), 0)::numeric as total_value_won,
      -- Win rate: (won + closed) / totale chiusure con esito
      CASE 
        WHEN COUNT(d.id) FILTER (WHERE d.status IN ('won', 'lost', 'closed') AND d.closed_at >= v_from AND d.closed_at < v_to) = 0 
        THEN 0
        ELSE ROUND(
          COUNT(d.id) FILTER (WHERE d.status IN ('won', 'closed') AND d.closed_at >= v_from AND d.closed_at < v_to)::numeric * 100 
          / COUNT(d.id) FILTER (WHERE d.status IN ('won', 'lost', 'closed') AND d.closed_at >= v_from AND d.closed_at < v_to),
          1
        )
      END as win_rate,
      -- Tempo medio chiusura (giorni)
      COALESCE(
        ROUND(
          AVG(EXTRACT(EPOCH FROM (d.closed_at - d.created_at)) / 86400) 
          FILTER (WHERE d.status IN ('won', 'lost', 'closed') AND d.closed_at >= v_from AND d.closed_at < v_to),
          1
        ),
        0
      ) as avg_days_to_close,
      -- Ultima attività
      MAX(d.updated_at) as last_activity_at
    FROM users u
    INNER JOIN user_roles ur ON ur.user_id = u.id 
      AND ur.brand_id = p_brand_id 
      AND ur.role = 'venditore'
      AND ur.is_active = true
    LEFT JOIN deals d ON d.assigned_user_id = u.id 
      AND d.brand_id = p_brand_id
    GROUP BY u.id, u.full_name, u.email, ur.role
    ORDER BY COALESCE(SUM(d.value) FILTER (
        WHERE d.status IN ('won', 'closed') 
        AND d.closed_at >= v_from AND d.closed_at < v_to
      ), 0) DESC, 
      COUNT(d.id) FILTER (WHERE d.status = 'won' AND d.closed_at >= v_from AND d.closed_at < v_to) DESC
  ) kpi;

  RETURN COALESCE(v_result, '[]'::json);
END;
$$;


--
-- Name: get_tag_assignment_counts(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tag_assignment_counts(p_brand_id uuid) RETURNS TABLE(tag_id uuid, contact_count bigint, event_count bigint, deal_count bigint, total_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT 
    ta.tag_id,
    COUNT(ta.contact_id) AS contact_count,
    COUNT(ta.lead_event_id) AS event_count,
    COUNT(ta.deal_id) AS deal_count,
    COUNT(*) AS total_count
  FROM tag_assignments ta
  WHERE ta.brand_id = p_brand_id
  GROUP BY ta.tag_id;
$$;


--
-- Name: get_tag_tree(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tag_tree(p_brand_id uuid) RETURNS TABLE(id uuid, parent_id uuid, name text, description text, color text, scope public.tag_scope, is_active boolean, order_index integer, depth integer, path text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH RECURSIVE tag_tree AS (
    -- Root tags (no parent)
    SELECT 
      t.id, t.parent_id, t.name, t.description, t.color, t.scope, 
      t.is_active, t.order_index,
      0 AS depth,
      t.name::TEXT AS path
    FROM tags t
    WHERE t.brand_id = p_brand_id AND t.parent_id IS NULL
    
    UNION ALL
    
    -- Child tags
    SELECT 
      t.id, t.parent_id, t.name, t.description, t.color, t.scope,
      t.is_active, t.order_index,
      tt.depth + 1,
      tt.path || ' > ' || t.name
    FROM tags t
    INNER JOIN tag_tree tt ON t.parent_id = tt.id
    WHERE t.brand_id = p_brand_id
  )
  SELECT * FROM tag_tree ORDER BY path, order_index;
$$;


--
-- Name: get_thread_display_titles(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_thread_display_titles(p_thread_ids uuid[]) RETURNS TABLE(thread_id uuid, display_title text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT t.id AS thread_id,
    CASE
      WHEN t.title IS NOT NULL AND t.title <> '' THEN t.title
      WHEN t.type::text = 'executive' THEN
        COALESCE(
          (SELECT LEFT(cm.message_text, 60)
           FROM chat_messages cm
           WHERE cm.thread_id = t.id AND cm.sender_type = 'user' AND cm.deleted_at IS NULL
           ORDER BY cm.created_at ASC LIMIT 1),
          'Agente AI Executive'
        )
      WHEN t.type::text = 'group' THEN COALESCE(t.title, 'Gruppo')
      WHEN t.type::text = 'entity' AND t.entity_type = 'deal' THEN
        COALESCE(
          (SELECT c.first_name || ' ' || c.last_name
           FROM deals d JOIN contacts c ON c.id = d.contact_id
           WHERE d.id = t.entity_id),
          'Deal'
        )
      WHEN t.type::text = 'entity' AND t.entity_type = 'ticket' THEN
        COALESCE(
          (SELECT tk.title FROM tickets tk WHERE tk.id = t.entity_id),
          'Ticket'
        )
      WHEN t.type::text = 'entity' AND t.entity_type = 'contact' THEN
        COALESCE(
          (SELECT c.first_name || ' ' || c.last_name FROM contacts c WHERE c.id = t.entity_id),
          'Contatto'
        )
      WHEN t.type::text = 'entity' AND t.entity_type = 'appointment' THEN
        COALESCE(
          (SELECT c.first_name || ' ' || c.last_name
           FROM appointments a JOIN contacts c ON c.id = a.contact_id
           WHERE a.id = t.entity_id),
          'Appuntamento'
        )
      ELSE
        COALESCE(
          (SELECT LEFT(cm.message_text, 60)
           FROM chat_messages cm
           WHERE cm.thread_id = t.id AND cm.sender_type = 'user' AND cm.deleted_at IS NULL
           ORDER BY cm.created_at ASC LIMIT 1),
          'Conversazione'
        )
    END AS display_title
  FROM chat_threads t
  WHERE t.id = ANY(p_thread_ids);
END;
$$;


--
-- Name: get_ticket_escalation_audit(uuid, integer, timestamp with time zone, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_ticket_escalation_audit(p_brand_id uuid DEFAULT NULL::uuid, p_level integer DEFAULT NULL::integer, p_from timestamp with time zone DEFAULT (now() - '30 days'::interval), p_to timestamp with time zone DEFAULT now(), p_limit integer DEFAULT 200) RETURNS TABLE(audit_id uuid, ticket_id uuid, ticket_title text, ticket_status text, ticket_priority integer, brand_id uuid, escalation_level integer, previous_level integer, minutes_since_breach integer, escalated_at timestamp with time zone, sla_breached_at timestamp with time zone, escalated_to_user_id uuid, escalated_to_name text, notification_id uuid, notification_read_at timestamp with time zone, suggestion_id uuid, suggestion_acted_on_at timestamp with time zone, suggestion_dismissed_at timestamp with time zone, outcome text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH base AS (
    SELECT
      tal.id AS audit_id,
      tal.ticket_id,
      tal.brand_id,
      tal.created_at AS escalated_at,
      COALESCE((tal.new_value->>'escalation_level')::int, 0) AS escalation_level,
      COALESCE((tal.metadata->>'previous_level')::int, 0) AS previous_level,
      COALESCE((tal.metadata->>'minutes_since_breach')::int, 0) AS minutes_since_breach,
      NULLIF(tal.metadata->>'escalated_to_user_id','')::uuid AS escalated_to_user_id
    FROM public.ticket_audit_logs tal
    WHERE tal.action_type = 'sla_escalation'
      AND tal.created_at BETWEEN p_from AND p_to
      AND (p_brand_id IS NULL OR tal.brand_id = p_brand_id)
      AND (
        public.has_role(auth.uid(), 'admin'::app_role)
        OR public.has_role(auth.uid(), 'ceo'::app_role)
        OR public.user_belongs_to_brand(public.get_user_id(auth.uid()), tal.brand_id)
      )
  )
  SELECT
    b.audit_id,
    b.ticket_id,
    t.title AS ticket_title,
    t.status::text AS ticket_status,
    t.priority AS ticket_priority,
    b.brand_id,
    b.escalation_level,
    b.previous_level,
    b.minutes_since_breach,
    b.escalated_at,
    t.sla_breached_at,
    b.escalated_to_user_id,
    u.full_name AS escalated_to_name,
    n.id AS notification_id,
    n.read_at AS notification_read_at,
    s.id AS suggestion_id,
    s.acted_on_at AS suggestion_acted_on_at,
    s.dismissed_at AS suggestion_dismissed_at,
    CASE
      WHEN s.acted_on_at IS NOT NULL THEN 'risolto'
      WHEN s.dismissed_at IS NOT NULL THEN 'ignorato'
      WHEN n.read_at IS NOT NULL THEN 'visto'
      WHEN b.escalated_to_user_id IS NULL THEN 'no_manager'
      ELSE 'pending'
    END AS outcome
  FROM base b
  LEFT JOIN public.tickets t ON t.id = b.ticket_id
  LEFT JOIN public.users u ON u.id = b.escalated_to_user_id
  LEFT JOIN LATERAL (
    SELECT n.id, n.read_at
    FROM public.notifications n
    WHERE n.entity_type = 'ticket'
      AND n.entity_id = b.ticket_id
      AND n.type = 'ticket_escalated'
      AND n.user_id = b.escalated_to_user_id
      AND n.created_at BETWEEN b.escalated_at - interval '5 minutes' AND b.escalated_at + interval '5 minutes'
    ORDER BY n.created_at DESC
    LIMIT 1
  ) n ON true
  LEFT JOIN LATERAL (
    SELECT s.id, s.acted_on_at, s.dismissed_at
    FROM public.action_suggestions s
    WHERE s.entity_type = 'ticket'
      AND s.entity_id = b.ticket_id
      AND s.suggestion_type = 'escalate'
      AND s.user_id = b.escalated_to_user_id
      AND s.created_at BETWEEN b.escalated_at - interval '5 minutes' AND b.escalated_at + interval '5 minutes'
    ORDER BY s.created_at DESC
    LIMIT 1
  ) s ON true
  WHERE (p_level IS NULL OR b.escalation_level = p_level)
  ORDER BY b.escalated_at DESC
  LIMIT LEAST(COALESCE(p_limit, 200), 500);
$$;


--
-- Name: ticket_escalation_policies; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ticket_escalation_policies (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    brand_id uuid,
    is_default boolean DEFAULT false NOT NULL,
    level_1_minutes integer DEFAULT 30 NOT NULL,
    level_2_minutes integer DEFAULT 120 NOT NULL,
    level_3_minutes integer DEFAULT 480 NOT NULL,
    level_1_roles public.app_role[] DEFAULT ARRAY['responsabile_callcenter'::public.app_role, 'admin'::public.app_role] NOT NULL,
    level_2_roles public.app_role[] DEFAULT ARRAY['responsabile_callcenter'::public.app_role, 'responsabile_venditori'::public.app_role, 'admin'::public.app_role] NOT NULL,
    level_3_roles public.app_role[] DEFAULT ARRAY['admin'::public.app_role, 'ceo'::public.app_role] NOT NULL,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_by uuid,
    CONSTRAINT ticket_escalation_policies_check CHECK ((level_2_minutes > level_1_minutes)),
    CONSTRAINT ticket_escalation_policies_check1 CHECK ((level_3_minutes > level_2_minutes)),
    CONSTRAINT ticket_escalation_policies_level_1_minutes_check CHECK ((level_1_minutes >= 1))
);


--
-- Name: get_ticket_escalation_policy(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_ticket_escalation_policy(p_brand_id uuid) RETURNS public.ticket_escalation_policies
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT *
  FROM public.ticket_escalation_policies
  WHERE brand_id = p_brand_id
  UNION ALL
  SELECT *
  FROM public.ticket_escalation_policies
  WHERE brand_id IS NULL AND is_default = true
  ORDER BY brand_id NULLS LAST
  LIMIT 1;
$$;


--
-- Name: get_ticket_queue_counts(uuid, uuid, jsonb, text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_ticket_queue_counts(p_brand_id uuid, p_current_user_id uuid DEFAULT NULL::uuid, p_sla_thresholds jsonb DEFAULT NULL::jsonb, p_queue_tab text DEFAULT 'all'::text, p_tag_ids uuid[] DEFAULT NULL::uuid[]) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result json;
  v_active_statuses text[] := ARRAY['open', 'in_progress', 'reopened'];
BEGIN
  WITH base_tickets AS (
    SELECT t.*
    FROM tickets t
    WHERE t.brand_id = p_brand_id
      -- Apply queue tab filter for auto/manual counts context
      AND (
        CASE p_queue_tab
          WHEN 'my_queue' THEN 
            t.assigned_to_user_id = p_current_user_id 
            AND t.status::text = ANY(v_active_statuses)
          WHEN 'unassigned' THEN 
            t.assigned_to_user_id IS NULL 
            AND t.status::text = ANY(v_active_statuses)
          WHEN 'sla_breached' THEN 
            t.status::text = ANY(v_active_statuses)
            AND p_sla_thresholds IS NOT NULL
            AND (
              EXTRACT(EPOCH FROM (now() - t.opened_at)) / 60 > 
              COALESCE((p_sla_thresholds->>t.priority::text)::numeric, 1440)
            )
          ELSE true -- 'all'
        END
      )
      -- Apply tag filter if provided
      AND (p_tag_ids IS NULL OR array_length(p_tag_ids, 1) IS NULL OR t.category_tag_id = ANY(p_tag_ids))
  )
  SELECT json_build_object(
    -- Global queue counts (not affected by filters)
    'all', (
      SELECT COUNT(*) FROM tickets t
      WHERE t.brand_id = p_brand_id
    ),
    'my_queue', (
      SELECT COUNT(*) FROM tickets t
      WHERE t.brand_id = p_brand_id
        AND t.assigned_to_user_id = p_current_user_id
        AND t.status::text = ANY(v_active_statuses)
    ),
    'unassigned', (
      SELECT COUNT(*) FROM tickets t
      WHERE t.brand_id = p_brand_id
        AND t.assigned_to_user_id IS NULL
        AND t.status::text = ANY(v_active_statuses)
    ),
    'sla_breached', (
      SELECT COUNT(*) FROM tickets t
      WHERE t.brand_id = p_brand_id
        AND t.status::text = ANY(v_active_statuses)
        AND p_sla_thresholds IS NOT NULL
        AND (
          EXTRACT(EPOCH FROM (now() - t.opened_at)) / 60 > 
          COALESCE((p_sla_thresholds->>t.priority::text)::numeric, 1440)
        )
    ),
    -- Contextual counts (based on current queue tab + tag filters)
    'auto_count', (
      SELECT COUNT(*) FROM base_tickets bt
      WHERE bt.assigned_at IS NOT NULL AND bt.assigned_by_user_id IS NULL
    ),
    'manual_count', (
      SELECT COUNT(*) FROM base_tickets bt
      WHERE bt.assigned_by_user_id IS NOT NULL
    )
  ) INTO v_result;
  
  RETURN v_result;
END;
$$;


--
-- Name: get_ticket_queue_counts(uuid, uuid[], uuid, text, text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_ticket_queue_counts(p_brand_id uuid DEFAULT NULL::uuid, p_brand_ids uuid[] DEFAULT NULL::uuid[], p_current_user_id uuid DEFAULT NULL::uuid, p_sla_thresholds text DEFAULT NULL::text, p_queue_tab text DEFAULT 'all'::text, p_tag_ids uuid[] DEFAULT NULL::uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_sla JSONB;
  v_active_statuses ticket_status[] := ARRAY['open'::ticket_status, 'in_progress'::ticket_status, 'reopened'::ticket_status];
  v_all_count INT;
  v_my_queue_count INT;
  v_unassigned_count INT;
  v_sla_breached_count INT;
  v_auto_count INT;
  v_manual_count INT;
  v_effective_brand_ids UUID[];
BEGIN
  -- Determine effective brand IDs
  IF p_brand_ids IS NOT NULL AND array_length(p_brand_ids, 1) > 0 THEN
    v_effective_brand_ids := p_brand_ids;
  ELSIF p_brand_id IS NOT NULL THEN
    v_effective_brand_ids := ARRAY[p_brand_id];
  ELSE
    RETURN jsonb_build_object(
      'all', 0,
      'my_queue', 0,
      'unassigned', 0,
      'sla_breached', 0,
      'auto_count', 0,
      'manual_count', 0
    );
  END IF;

  -- Parse SLA thresholds
  IF p_sla_thresholds IS NOT NULL THEN
    v_sla := p_sla_thresholds::jsonb;
  ELSE
    v_sla := '{"1": 30, "2": 60, "3": 240, "4": 480, "5": 1440}'::jsonb;
  END IF;

  -- Count all non-archived tickets
  SELECT COUNT(*) INTO v_all_count
  FROM tickets t
  WHERE t.brand_id = ANY(v_effective_brand_ids) AND t.archived = false;

  -- Count my queue
  SELECT COUNT(*) INTO v_my_queue_count
  FROM tickets t
  WHERE t.brand_id = ANY(v_effective_brand_ids) 
    AND t.archived = false
    AND t.status = ANY(v_active_statuses)
    AND t.assigned_to_user_id = p_current_user_id;

  -- Count unassigned
  SELECT COUNT(*) INTO v_unassigned_count
  FROM tickets t
  WHERE t.brand_id = ANY(v_effective_brand_ids)
    AND t.archived = false
    AND t.status = ANY(v_active_statuses)
    AND t.assigned_to_user_id IS NULL;

  -- Count SLA breached
  SELECT COUNT(*) INTO v_sla_breached_count
  FROM tickets t
  WHERE t.brand_id = ANY(v_effective_brand_ids)
    AND t.archived = false
    AND t.status = ANY(v_active_statuses)
    AND EXTRACT(EPOCH FROM (now() - t.opened_at)) / 60 > 
        COALESCE((v_sla->>t.priority::text)::int, 240);

  -- Count auto-assigned (contextual based on current queue tab)
  WITH filtered AS (
    SELECT t.*
    FROM tickets t
    WHERE t.brand_id = ANY(v_effective_brand_ids)
      AND t.archived = false
      AND (p_tag_ids IS NULL OR t.category_tag_id = ANY(p_tag_ids))
      AND (
        p_queue_tab = 'all'
        OR (p_queue_tab = 'my_queue' AND t.assigned_to_user_id = p_current_user_id AND t.status = ANY(v_active_statuses))
        OR (p_queue_tab = 'unassigned' AND t.assigned_to_user_id IS NULL AND t.status = ANY(v_active_statuses))
        OR (p_queue_tab = 'sla_breached' AND t.status = ANY(v_active_statuses) AND
            EXTRACT(EPOCH FROM (now() - t.opened_at)) / 60 > 
            COALESCE((v_sla->>t.priority::text)::int, 240))
      )
  )
  SELECT 
    COUNT(*) FILTER (WHERE f.assigned_by_user_id IS NULL AND f.assigned_to_user_id IS NOT NULL),
    COUNT(*) FILTER (WHERE f.assigned_by_user_id IS NOT NULL)
  INTO v_auto_count, v_manual_count
  FROM filtered f;

  RETURN jsonb_build_object(
    'all', v_all_count,
    'my_queue', v_my_queue_count,
    'unassigned', v_unassigned_count,
    'sla_breached', v_sla_breached_count,
    'auto_count', v_auto_count,
    'manual_count', v_manual_count
  );
END;
$$;


--
-- Name: get_ticket_trend_dashboard(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_ticket_trend_dashboard(p_brand_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result JSON;
BEGIN
  SELECT json_build_object(
    -- Daily trend: created vs resolved
    'daily_trend', (
      SELECT COALESCE(json_agg(json_build_object(
        'date', day::date,
        'created', created_cnt,
        'resolved', resolved_cnt,
        'closed', closed_cnt
      ) ORDER BY day), '[]'::json)
      FROM (
        SELECT 
          date_trunc('day', opened_at) as day,
          COUNT(*) as created_cnt,
          COUNT(*) FILTER (WHERE resolved_at IS NOT NULL AND resolved_at >= p_from AND resolved_at < p_to) as resolved_cnt,
          COUNT(*) FILTER (WHERE closed_at IS NOT NULL AND closed_at >= p_from AND closed_at < p_to) as closed_cnt
        FROM tickets
        WHERE brand_id = p_brand_id
          AND opened_at >= p_from
          AND opened_at < p_to
        GROUP BY date_trunc('day', opened_at)
      ) t
    ),
    
    -- Backlog over time (cumulative open tickets per day)
    'backlog_trend', (
      SELECT COALESCE(json_agg(json_build_object(
        'date', day::date,
        'backlog', backlog_cnt
      ) ORDER BY day), '[]'::json)
      FROM (
        SELECT 
          d.day,
          (
            SELECT COUNT(*) 
            FROM tickets t 
            WHERE t.brand_id = p_brand_id
              AND t.opened_at <= d.day + interval '1 day'
              AND (t.closed_at IS NULL OR t.closed_at > d.day + interval '1 day')
              AND t.status IN ('open', 'in_progress', 'reopened')
          ) as backlog_cnt
        FROM generate_series(p_from::date, p_to::date, '1 day'::interval) as d(day)
      ) t
    ),
    
    -- Top categories (by tag)
    'top_categories', (
      SELECT COALESCE(json_agg(json_build_object(
        'tag_id', tag_id,
        'tag_name', tag_name,
        'tag_color', tag_color,
        'count', cnt
      ) ORDER BY cnt DESC), '[]'::json)
      FROM (
        SELECT 
          t.category_tag_id as tag_id,
          COALESCE(tg.name, 'Non categorizzato') as tag_name,
          COALESCE(tg.color, '#6b7280') as tag_color,
          COUNT(*) as cnt
        FROM tickets t
        LEFT JOIN tags tg ON tg.id = t.category_tag_id
        WHERE t.brand_id = p_brand_id
          AND t.opened_at >= p_from
          AND t.opened_at < p_to
        GROUP BY t.category_tag_id, tg.name, tg.color
        LIMIT 10
      ) t
    ),
    
    -- Aging buckets for open tickets (current state)
    'aging_buckets', (
      SELECT json_build_object(
        'bucket_0_1h', COUNT(*) FILTER (WHERE age_minutes <= 60),
        'bucket_1_4h', COUNT(*) FILTER (WHERE age_minutes > 60 AND age_minutes <= 240),
        'bucket_4_24h', COUNT(*) FILTER (WHERE age_minutes > 240 AND age_minutes <= 1440),
        'bucket_over_24h', COUNT(*) FILTER (WHERE age_minutes > 1440)
      )
      FROM (
        SELECT EXTRACT(EPOCH FROM (now() - opened_at)) / 60 as age_minutes
        FROM tickets
        WHERE brand_id = p_brand_id
          AND status IN ('open', 'in_progress', 'reopened')
      ) t
    ),
    
    -- Operator breakdown
    'operator_breakdown', (
      SELECT COALESCE(json_agg(json_build_object(
        'user_id', user_id,
        'full_name', full_name,
        'email', email,
        'assigned_count', assigned_cnt,
        'resolved_count', resolved_cnt,
        'avg_resolution_minutes', avg_res_min,
        'current_backlog', backlog_cnt
      ) ORDER BY assigned_cnt DESC), '[]'::json)
      FROM (
        SELECT 
          u.id as user_id,
          u.full_name,
          u.email,
          (
            SELECT COUNT(*)
            FROM tickets t
            WHERE t.brand_id = p_brand_id
              AND t.assigned_to_user_id = u.id
              AND t.assigned_at >= p_from
              AND t.assigned_at < p_to
          ) as assigned_cnt,
          (
            SELECT COUNT(*)
            FROM tickets t
            WHERE t.brand_id = p_brand_id
              AND t.assigned_to_user_id = u.id
              AND t.resolved_at >= p_from
              AND t.resolved_at < p_to
          ) as resolved_cnt,
          (
            SELECT COALESCE(ROUND(AVG(EXTRACT(EPOCH FROM (t.resolved_at - t.assigned_at)) / 60)::numeric, 1), 0)
            FROM tickets t
            WHERE t.brand_id = p_brand_id
              AND t.assigned_to_user_id = u.id
              AND t.resolved_at >= p_from
              AND t.resolved_at < p_to
              AND t.assigned_at IS NOT NULL
          ) as avg_res_min,
          (
            SELECT COUNT(*)
            FROM tickets t
            WHERE t.brand_id = p_brand_id
              AND t.assigned_to_user_id = u.id
              AND t.status IN ('open', 'in_progress', 'reopened')
          ) as backlog_cnt
        FROM users u
        JOIN user_roles ur ON ur.user_id = u.id
        WHERE ur.brand_id = p_brand_id
          AND ur.role IN ('callcenter', 'admin')
      ) t
    ),
    
    -- Summary totals
    'summary', (
      SELECT json_build_object(
        'total_created', COUNT(*) FILTER (WHERE opened_at >= p_from AND opened_at < p_to),
        'total_resolved', COUNT(*) FILTER (WHERE resolved_at >= p_from AND resolved_at < p_to),
        'total_closed', COUNT(*) FILTER (WHERE closed_at >= p_from AND closed_at < p_to),
        'current_backlog', COUNT(*) FILTER (WHERE status IN ('open', 'in_progress', 'reopened')),
        'current_unassigned', COUNT(*) FILTER (WHERE status IN ('open', 'in_progress', 'reopened') AND assigned_to_user_id IS NULL)
      )
      FROM tickets
      WHERE brand_id = p_brand_id
    )
  ) INTO v_result;
  
  RETURN v_result;
END;
$$;


--
-- Name: get_unified_customer_timeline(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_unified_customer_timeline(p_contact_id uuid, p_limit integer DEFAULT 200) RETURNS TABLE(source text, event_id uuid, occurred_at timestamp with time zone, actor_display_name text, action text, entity_type text, entity_id uuid, summary text, metadata jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_brand_id uuid;
BEGIN
  SELECT brand_id INTO v_brand_id FROM public.contacts WHERE id = p_contact_id;
  IF v_brand_id IS NULL THEN
    RETURN;
  END IF;

  IF NOT public.user_belongs_to_brand(public.get_user_id(auth.uid()), v_brand_id) THEN
    RAISE EXCEPTION 'Not authorized for this contact';
  END IF;

  RETURN QUERY
  SELECT
    'audit'::text AS source,
    ae.id AS event_id,
    ae.occurred_at,
    ae.actor_display_name,
    ae.action,
    ae.entity_type,
    ae.entity_id,
    NULL::text AS summary,
    ae.metadata
  FROM public.audit_events ae
  WHERE ae.entity_type = 'contact' AND ae.entity_id = p_contact_id

  UNION ALL
  SELECT
    'audit'::text, ae.id, ae.occurred_at, ae.actor_display_name,
    ae.action, ae.entity_type, ae.entity_id, NULL::text, ae.metadata
  FROM public.audit_events ae
  JOIN public.deals d ON d.id = ae.entity_id
  WHERE ae.entity_type = 'deal' AND d.contact_id = p_contact_id

  UNION ALL
  SELECT
    'audit'::text, ae.id, ae.occurred_at, ae.actor_display_name,
    ae.action, ae.entity_type, ae.entity_id, NULL::text, ae.metadata
  FROM public.audit_events ae
  JOIN public.tickets t ON t.id = ae.entity_id
  WHERE ae.entity_type = 'ticket' AND t.contact_id = p_contact_id

  UNION ALL
  SELECT
    'audit'::text, ae.id, ae.occurred_at, ae.actor_display_name,
    ae.action, ae.entity_type, ae.entity_id, NULL::text, ae.metadata
  FROM public.audit_events ae
  JOIN public.appointments a ON a.id = ae.entity_id
  WHERE ae.entity_type = 'appointment' AND a.contact_id = p_contact_id

  ORDER BY occurred_at DESC
  LIMIT p_limit;
END;
$$;


--
-- Name: get_unread_counts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_unread_counts() RETURNS TABLE(thread_id uuid, unread_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT m.thread_id, COUNT(cm.id) AS unread_count
  FROM chat_thread_members m
  LEFT JOIN thread_read_state rs ON rs.thread_id = m.thread_id AND rs.user_id = m.user_id
  LEFT JOIN chat_messages cm ON cm.thread_id = m.thread_id 
    AND cm.created_at > COALESCE(rs.last_read_at, m.joined_at)
    AND cm.deleted_at IS NULL
    AND cm.sender_user_id IS DISTINCT FROM m.user_id
  WHERE m.user_id = get_user_id(auth.uid()) AND m.left_at IS NULL
  GROUP BY m.thread_id HAVING COUNT(cm.id) > 0;
$$;


--
-- Name: get_unread_notification_count(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_unread_notification_count(p_brand_id uuid DEFAULT NULL::uuid) RETURNS integer
