--
-- Name: get_webhook_delivery(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_webhook_delivery(p_delivery_id uuid) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_brand_id uuid;
  v_result json;
BEGIN
  -- Get brand_id
  SELECT brand_id INTO v_brand_id FROM outbound_webhook_deliveries WHERE id = p_delivery_id;
  
  IF v_brand_id IS NULL THEN
    RETURN NULL;
  END IF;
  
  -- Admin check
  IF NOT has_role_for_brand(get_user_id(auth.uid()), v_brand_id, 'admin') THEN
    RAISE EXCEPTION 'Admin access required';
  END IF;
  
  SELECT json_build_object(
    'id', d.id,
    'webhook_id', d.webhook_id,
    'webhook_name', w.name,
    'webhook_url', w.url,
    'event_type', d.event_type,
    'event_id', d.event_id,
    'status', d.status,
    'attempt_count', d.attempt_count,
    'max_attempts', d.max_attempts,
    'next_attempt_at', d.next_attempt_at,
    'response_status', d.response_status,
    'response_body', LEFT(d.response_body, 5000),
    'last_error', d.last_error,
    'payload', d.payload,
    'created_at', d.created_at,
    'updated_at', d.updated_at
  ) INTO v_result
  FROM outbound_webhook_deliveries d
  JOIN outbound_webhooks w ON w.id = d.webhook_id
  WHERE d.id = p_delivery_id;
  
  RETURN v_result;
END;
$$;


--
-- Name: get_webhook_delivery_health(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_webhook_delivery_health(p_brand_id uuid, p_from_hours integer DEFAULT 24) RETURNS TABLE(destination_id uuid, destination_name text, preset text, is_active boolean, total_attempts bigint, sent_count bigint, failed_count bigint, dead_letter_count bigint, pending_count bigint, success_rate numeric, avg_latency_seconds numeric, p95_latency_seconds numeric, last_success_at timestamp with time zone, last_error text, consecutive_failures integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_internal_user_id uuid;
  v_authorized boolean := false;
  v_from_ts timestamptz;
BEGIN
  IF p_from_hours < 1 OR p_from_hours > 168 THEN
    RAISE EXCEPTION 'from_hours must be between 1 and 168' USING ERRCODE = '22023';
  END IF;

  v_internal_user_id := public.get_user_id(auth.uid());
  IF v_internal_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.user_roles ur
    WHERE ur.user_id = v_internal_user_id
      AND ur.is_active = true
      AND ur.role IN ('admin', 'ceo')
      AND (
        ur.brand_id = p_brand_id
        OR ur.brand_id = '00000000-0000-0000-0000-000000000000'::uuid
      )
  ) INTO v_authorized;

  IF NOT v_authorized THEN
    RAISE EXCEPTION 'Insufficient privileges' USING ERRCODE = '42501';
  END IF;

  v_from_ts := now() - (p_from_hours || ' hours')::interval;

  RETURN QUERY
  WITH outbox_window AS (
    SELECT
      o.destination_id,
      o.status,
      o.attempts,
      o.created_at,
      o.delivered_at,
      o.last_error,
      EXTRACT(EPOCH FROM (o.delivered_at - o.created_at)) AS latency_s
    FROM public.notification_webhook_outbox o
    WHERE o.brand_id = p_brand_id
      AND o.created_at >= v_from_ts
  ),
  agg AS (
    SELECT
      destination_id,
      COUNT(*) AS total_attempts,
      COUNT(*) FILTER (WHERE status = 'sent') AS sent_count,
      COUNT(*) FILTER (WHERE status = 'failed') AS failed_count,
      COUNT(*) FILTER (WHERE status = 'dead_letter') AS dead_letter_count,
      COUNT(*) FILTER (WHERE status = 'pending') AS pending_count,
      ROUND(
        100.0 * COUNT(*) FILTER (WHERE status = 'sent')::numeric
        / NULLIF(COUNT(*), 0),
        1
      ) AS success_rate,
      ROUND(AVG(latency_s) FILTER (WHERE status = 'sent')::numeric, 2) AS avg_latency_seconds,
      ROUND(
        (PERCENTILE_CONT(0.95) WITHIN GROUP (ORDER BY latency_s)
         FILTER (WHERE status = 'sent'))::numeric,
        2
      ) AS p95_latency_seconds
    FROM outbox_window
    GROUP BY destination_id
  )
  SELECT
    d.id,
    d.name,
    d.preset,
    d.is_active,
    COALESCE(a.total_attempts, 0),
    COALESCE(a.sent_count, 0),
    COALESCE(a.failed_count, 0),
    COALESCE(a.dead_letter_count, 0),
    COALESCE(a.pending_count, 0),
    COALESCE(a.success_rate, 0),
    COALESCE(a.avg_latency_seconds, 0),
    COALESCE(a.p95_latency_seconds, 0),
    d.last_success_at,
    d.last_error,
    d.consecutive_failures
  FROM public.notification_webhook_destinations d
  LEFT JOIN agg a ON a.destination_id = d.id
  WHERE d.brand_id = p_brand_id
  ORDER BY COALESCE(a.dead_letter_count, 0) DESC, COALESCE(a.failed_count, 0) DESC, d.created_at DESC;
END;
$$;


--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO public.users (supabase_auth_id, email, full_name)
  VALUES (
    NEW.id,
    NEW.email,
    COALESCE(NEW.raw_user_meta_data->>'full_name', NEW.email)
  );
  RETURN NEW;
END;
$$;


--
-- Name: has_finance_access(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_finance_access(p_user_id uuid, p_brand_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM user_roles
    WHERE user_id = p_user_id
      AND (brand_id = p_brand_id OR role::text IN ('admin', 'ceo'))
      AND role::text IN ('admin', 'ceo', 'amministrazione')
  )
$$;


--
-- Name: has_marketing_access(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_marketing_access(p_user_id uuid, p_brand_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT 
    has_role(p_user_id, 'admin'::app_role) OR
    has_role(p_user_id, 'ceo'::app_role) OR
    has_role_for_brand(p_user_id, p_brand_id, 'amministrazione'::app_role) OR
    has_role_for_brand(p_user_id, p_brand_id, 'responsabile_venditori'::app_role) OR
    has_role_for_brand(p_user_id, p_brand_id, 'responsabile_callcenter'::app_role)
$$;


--
-- Name: has_marketing_write_access(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_marketing_write_access(p_user_id uuid, p_brand_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM user_roles
    WHERE user_id = p_user_id
      AND brand_id = p_brand_id
      AND is_active = true
      AND role::text IN ('admin', 'ceo')
  );
$$;


--
-- Name: has_role(uuid, public.app_role); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
