    SELECT 1 FROM public.user_roles
    WHERE user_id = _user_id AND role = _role
  )
$$;


--
-- Name: has_role_for_brand(uuid, uuid, public.app_role); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_role_for_brand(_user_id uuid, _brand_id uuid, _role public.app_role) RETURNS boolean
