    WHERE user_id = _user_id AND brand_id = _brand_id AND role = _role
  )
$$;


--
-- Name: insert_meta_lead_event(uuid, uuid, text, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.insert_meta_lead_event(p_brand_id uuid, p_source_id uuid, p_leadgen_id text, p_page_id text, p_form_id text, p_ad_id text, p_campaign_id text, p_raw_event jsonb) RETURNS TABLE(event_id uuid, is_duplicate boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_event_id uuid;
  v_is_duplicate boolean := false;
BEGIN
  -- Try to insert, handle unique constraint violation
  INSERT INTO meta_lead_events (
    brand_id, source_id, leadgen_id, page_id, form_id, 
    ad_id, campaign_id, raw_event, status
  )
  VALUES (
    p_brand_id, p_source_id, p_leadgen_id, p_page_id, p_form_id,
    p_ad_id, p_campaign_id, p_raw_event, 'received'
  )
  ON CONFLICT (brand_id, leadgen_id) DO UPDATE
  SET status = 'duplicate'
  RETURNING id, (xmax <> 0) INTO v_event_id, v_is_duplicate;
  
  -- If it was a conflict update, mark as duplicate
  IF v_is_duplicate THEN
    UPDATE meta_lead_events 
    SET status = 'duplicate'
    WHERE id = v_event_id;
  END IF;
  
  RETURN QUERY SELECT v_event_id, v_is_duplicate;
END;
$$;


--
-- Name: is_audit_admin(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_audit_admin(_supabase_auth_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.user_roles ur
    JOIN public.users u ON u.id = ur.user_id
    WHERE u.supabase_auth_id = _supabase_auth_id
      AND ur.role IN ('admin'::app_role, 'ceo'::app_role)
  );
$$;


--
-- Name: is_column_hidden_for_user(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_column_hidden_for_user(p_user_id uuid, p_brand_id uuid, p_table_name text, p_column_key text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_override boolean;
  v_role_hidden boolean;
  v_user_role app_role;
BEGIN
  -- Check for user-specific override first
  SELECT is_hidden INTO v_user_override
  FROM user_hidden_columns
  WHERE user_id = p_user_id
  AND brand_id = p_brand_id
  AND table_name = p_table_name
  AND column_key = p_column_key;
  
  IF v_user_override IS NOT NULL THEN
    RETURN v_user_override;
  END IF;
  
  -- Get user's role for this brand
  SELECT role INTO v_user_role
  FROM user_roles
  WHERE user_id = p_user_id
  AND brand_id = p_brand_id
  LIMIT 1;
  
  -- Admin and CEO can see everything
  IF v_user_role IN ('admin'::app_role, 'ceo'::app_role) THEN
    RETURN false;
  END IF;
  
  -- Check role-based hidden column
  SELECT is_hidden INTO v_role_hidden
  FROM role_hidden_columns
  WHERE brand_id = p_brand_id
  AND role = v_user_role::text
  AND table_name = p_table_name
  AND column_key = p_column_key;
  
  -- If no explicit setting, default to visible (not hidden)
  RETURN COALESCE(v_role_hidden, false);
END;
$$;


--
-- Name: is_thread_member(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_thread_member(p_user_id uuid, p_thread_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM chat_thread_members
    WHERE user_id = p_user_id 
      AND thread_id = p_thread_id 
      AND left_at IS NULL
  );
$$;


--
-- Name: is_thread_owner_or_moderator(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_thread_owner_or_moderator(_user_id uuid, _thread_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM chat_thread_members
    WHERE thread_id = _thread_id
    AND user_id = _user_id
    AND role IN ('owner', 'moderator')
    AND left_at IS NULL
  )
$$;


--
-- Name: issue_mcp_token(text, text, text[], timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.issue_mcp_token(p_name text, p_kind text DEFAULT 'user'::text, p_scopes text[] DEFAULT ARRAY['crm.read'::text], p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_brand_id uuid DEFAULT NULL::uuid) RETURNS TABLE(token text, token_id uuid, prefix text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_raw TEXT;
  v_hash TEXT;
  v_prefix TEXT;
  v_id UUID;
BEGIN
  v_user_id := public.get_user_id(auth.uid());
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501';
  END IF;

  IF p_kind = 'service' AND NOT public.has_role(v_user_id, 'admin'::public.app_role) THEN
    RAISE EXCEPTION 'service tokens require admin' USING ERRCODE = '42501';
  END IF;

  v_raw := 'mcp_' || encode(gen_random_bytes(36), 'base64');
  v_raw := replace(replace(replace(v_raw, '+', '-'), '/', '_'), '=', '');
  v_prefix := substr(v_raw, 1, 12);
  v_hash := encode(digest(v_raw, 'sha256'), 'hex');

  INSERT INTO public.mcp_access_tokens(
    token_hash, token_prefix, name, kind, user_id, brand_id, scopes, expires_at, created_by
  ) VALUES (
    v_hash, v_prefix, p_name, p_kind,
    CASE WHEN p_kind = 'user' THEN v_user_id ELSE NULL END,
    p_brand_id, p_scopes, p_expires_at, v_user_id
  )
  RETURNING id INTO v_id;

  RETURN QUERY SELECT v_raw, v_id, v_prefix;
END;
$$;


--
-- Name: list_backup_archives(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_backup_archives(p_brand_id uuid, p_limit integer DEFAULT 100) RETURNS TABLE(run_id uuid, brand_id uuid, scope text, storage_path text, storage_uploaded_at timestamp with time zone, size_bytes bigint, total_rows integer, status text, expires_at timestamp with time zone, scheduled boolean, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT (
    public.has_role(public.get_user_id(auth.uid()), 'admin'::app_role)
    OR public.has_role(public.get_user_id(auth.uid()), 'ceo'::app_role)
  ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT r.id, r.brand_id, r.scope, r.storage_path, r.storage_uploaded_at,
         r.size_bytes, r.total_rows, r.status, r.expires_at,
         (r.schedule_id IS NOT NULL) AS scheduled,
         r.created_at
  FROM public.backup_runs r
  WHERE r.brand_id = p_brand_id
    AND r.storage_path IS NOT NULL
  ORDER BY r.storage_uploaded_at DESC NULLS LAST
  LIMIT LEAST(GREATEST(p_limit, 1), 500);
END;
$$;


--
-- Name: list_capi_events(uuid[], timestamp with time zone, timestamp with time zone, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_capi_events(p_brand_ids uuid[], p_from timestamp with time zone DEFAULT (now() - '7 days'::interval), p_to timestamp with time zone DEFAULT now(), p_status text DEFAULT NULL::text, p_event_name text DEFAULT NULL::text, p_limit integer DEFAULT 200) RETURNS TABLE(id uuid, brand_id uuid, event_name text, event_id text, event_time timestamp with time zone, contact_id uuid, deal_id uuid, lead_event_id uuid, consent_snapshot boolean, status text, attempts integer, max_attempts integer, last_error text, sent_at timestamp with time zone, created_at timestamp with time zone, contact_name text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    q.id,
    q.brand_id,
    q.event_name,
    q.event_id,
    q.event_time,
    q.contact_id,
    q.deal_id,
    q.lead_event_id,
    q.consent_snapshot,
    q.status::text,
    q.attempts,
    q.max_attempts,
    q.last_error,
    q.sent_at,
    q.created_at,
    COALESCE(c.first_name || ' ' || c.last_name, c.first_name, c.last_name, 'N/A') AS contact_name
  FROM meta_capi_event_queue q
  LEFT JOIN contacts c ON c.id = q.contact_id
  WHERE q.brand_id = ANY(p_brand_ids)
    AND q.created_at >= p_from
    AND q.created_at <= p_to
    AND (p_status IS NULL OR q.status::text = p_status)
    AND (p_event_name IS NULL OR q.event_name = p_event_name)
  ORDER BY q.created_at DESC
  LIMIT p_limit;
$$;


--
-- Name: list_compliance_reports(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_compliance_reports(p_brand_id uuid, p_report_type text DEFAULT NULL::text, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_results JSONB;
BEGIN
  IF NOT public.is_audit_admin(auth.uid()) THEN
    RAISE EXCEPTION 'access denied';
  END IF;

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', id,
      'report_type', report_type,
      'period_start', period_start,
      'period_end', period_end,
      'generated_at', generated_at,
      'generated_by', generated_by,
      'checksum', checksum,
      'notes', notes,
      'total_events', summary->'total_events'
    )
    ORDER BY generated_at DESC
  ), '[]'::jsonb)
  INTO v_results
  FROM (
    SELECT *
    FROM public.audit_compliance_reports
    WHERE brand_id = p_brand_id
      AND (p_report_type IS NULL OR report_type = p_report_type)
    ORDER BY generated_at DESC
    LIMIT LEAST(p_limit, 200)
  ) r;

  RETURN v_results;
END;
$$;


--
-- Name: list_contact_lead_events(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_contact_lead_events(p_contact_id uuid, p_include_archived boolean DEFAULT false) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_brand_id uuid;
  v_user_role app_role;
  v_result json;
BEGIN
  -- Resolve app user
  v_user_id := get_user_id(auth.uid());
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  -- Get contact's brand_id
  SELECT brand_id INTO v_brand_id
  FROM public.contacts
  WHERE id = p_contact_id;

  IF v_brand_id IS NULL THEN
    RAISE EXCEPTION 'Contact not found';
  END IF;

  -- Brand access check
  IF NOT user_belongs_to_brand(v_user_id, v_brand_id) THEN
    RAISE EXCEPTION 'Forbidden: no access to brand';
  END IF;

  -- Role check for archived visibility
  IF COALESCE(p_include_archived, FALSE) = TRUE THEN
    SELECT ur.role INTO v_user_role
    FROM public.user_roles ur
    WHERE ur.user_id = v_user_id AND ur.brand_id = v_brand_id
    LIMIT 1;

    IF v_user_role IS NULL OR v_user_role NOT IN ('admin', 'ceo') THEN
      RAISE EXCEPTION 'Forbidden: include_archived requires admin/ceo';
    END IF;
  END IF;

  -- Fetch events with clinical topics
  SELECT json_agg(
    json_build_object(
      'id', le.id,
      'source', le.source,
      'source_name', le.source_name,
      'occurred_at', le.occurred_at,
      'received_at', le.received_at,
      'ai_priority', le.ai_priority,
      'lead_type', le.lead_type,
      'lead_source_channel', le.lead_source_channel,
      'contact_channel', le.contact_channel,
      'pacemaker_status', le.pacemaker_status,
      'customer_sentiment', le.customer_sentiment,
      'decision_status', le.decision_status,
      'objection_type', le.objection_type,
      'booking_notes', le.booking_notes,
      'logistics_notes', le.logistics_notes,
      'ai_conversation_summary', le.ai_conversation_summary,
      'archived', le.archived,
      'clinical_topics', COALESCE(
        (
          SELECT json_agg(json_build_object(
            'id', ct.id,
            'canonical_name', ct.canonical_name,
            'needs_review', ct.needs_review
          ))
          FROM public.lead_event_clinical_topics lect
          JOIN public.clinical_topics ct ON ct.id = lect.topic_id
          WHERE lect.lead_event_id = le.id
        ),
        '[]'::json
      )
    )
    ORDER BY le.received_at DESC
  )
  INTO v_result
  FROM public.lead_events le
  WHERE le.contact_id = p_contact_id
    AND (p_include_archived = TRUE OR le.archived = FALSE);

  RETURN COALESCE(v_result, '[]'::json);
END;
$$;


--
-- Name: list_outbound_webhooks(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_outbound_webhooks(p_brand_id uuid) RETURNS TABLE(id uuid, name text, url text, is_active boolean, event_types public.webhook_event_type[], payload_format text, payload_mapping jsonb, custom_url_params jsonb, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
BEGIN
  -- Get the internal user_id from the supabase_auth_id
  SELECT u.id INTO v_user_id 
  FROM users u 
  WHERE u.supabase_auth_id = auth.uid();

  -- Verify user has admin or ceo role for this brand
  IF NOT EXISTS (
    SELECT 1 FROM user_roles
    WHERE user_id = v_user_id
    AND brand_id = p_brand_id
    AND role IN ('admin', 'ceo')
  ) THEN
    RAISE EXCEPTION 'Access denied: admin or ceo role required';
  END IF;

  RETURN QUERY
  SELECT 
    w.id, w.name, w.url, w.is_active, w.event_types,
    w.payload_format, w.payload_mapping, w.custom_url_params,
    w.created_at, w.updated_at
  FROM outbound_webhooks w
  WHERE w.brand_id = p_brand_id
  ORDER BY w.created_at DESC;
END;
$$;


--
-- Name: list_team_members(uuid, public.app_role, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_team_members(p_brand_id uuid, p_role_filter public.app_role DEFAULT NULL::public.app_role, p_active_only boolean DEFAULT true) RETURNS TABLE(membership_id uuid, user_id uuid, email text, full_name text, role public.app_role, is_active boolean, created_at timestamp with time zone, can_edit boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller_role app_role;
BEGIN
  SELECT ur.role INTO v_caller_role
  FROM user_roles ur
  WHERE ur.user_id = get_user_id(auth.uid())
    AND ur.brand_id = p_brand_id
    AND ur.is_active = true
  ORDER BY get_role_level(ur.role) DESC
  LIMIT 1;

  IF v_caller_role IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT 
    ur.id AS membership_id,
    ur.user_id,
    u.email,
    u.full_name,
    ur.role,
    ur.is_active,
    ur.created_at,
    can_manage_role(v_caller_role, ur.role) AS can_edit
  FROM user_roles ur
  JOIN users u ON u.id = ur.user_id
  WHERE ur.brand_id = p_brand_id
    AND (p_role_filter IS NULL OR ur.role = p_role_filter)
    AND (NOT p_active_only OR ur.is_active = true)
    AND (
      v_caller_role IN ('admin', 'ceo')
      OR can_manage_role(v_caller_role, ur.role)
      OR ur.user_id = get_user_id(auth.uid())
    )
  ORDER BY get_role_level(ur.role) DESC, u.full_name;
END;
$$;


--
-- Name: list_webhook_deliveries(uuid, uuid, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_webhook_deliveries(p_brand_id uuid, p_webhook_id uuid DEFAULT NULL::uuid, p_status text DEFAULT NULL::text, p_event_type text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_brand_ids uuid[];
  v_result json;
  v_total bigint;
BEGIN
  IF p_brand_id = '00000000-0000-0000-0000-000000000000' THEN
    SELECT array_agg(ur.brand_id)
    INTO v_brand_ids
    FROM user_roles ur
    WHERE ur.user_id = (
      SELECT u.id FROM users u WHERE u.supabase_auth_id = auth.uid()
    )
    AND ur.is_active = true
    AND ur.brand_id != '00000000-0000-0000-0000-000000000000';
  ELSE
    v_brand_ids := ARRAY[p_brand_id];
  END IF;

  IF v_brand_ids IS NULL OR array_length(v_brand_ids, 1) IS NULL THEN
    RETURN json_build_object(
      'deliveries', '[]'::json,
      'total_count', 0,
      'limit', p_limit,
      'offset', p_offset
    );
  END IF;

  SELECT count(*)
  INTO v_total
  FROM outbound_webhook_deliveries wd
  JOIN outbound_webhooks ow ON ow.id = wd.webhook_id
  WHERE ow.brand_id = ANY(v_brand_ids)
    AND (p_webhook_id IS NULL OR wd.webhook_id = p_webhook_id)
    AND (p_status IS NULL OR wd.status::text = p_status)
    AND (p_event_type IS NULL OR wd.event_type::text = p_event_type);

  SELECT json_build_object(
    'deliveries', COALESCE(json_agg(row_to_json(t)), '[]'::json),
    'total_count', v_total,
    'limit', p_limit,
    'offset', p_offset
  )
  INTO v_result
  FROM (
    SELECT
      wd.id,
      wd.webhook_id,
      ow.name AS webhook_name,
      wd.event_type::text AS event_type,
      wd.event_id,
      wd.status::text AS status,
      wd.attempt_count,
      wd.max_attempts,
      wd.next_attempt_at,
      wd.response_status,
      wd.last_error,
      wd.created_at,
      wd.updated_at
    FROM outbound_webhook_deliveries wd
    JOIN outbound_webhooks ow ON ow.id = wd.webhook_id
    WHERE ow.brand_id = ANY(v_brand_ids)
      AND (p_webhook_id IS NULL OR wd.webhook_id = p_webhook_id)
      AND (p_status IS NULL OR wd.status::text = p_status)
      AND (p_event_type IS NULL OR wd.event_type::text = p_event_type)
    ORDER BY wd.created_at DESC
    LIMIT p_limit
    OFFSET p_offset
  ) t;

  RETURN v_result;
END;
$$;


--
-- Name: log_audit_access(uuid, text, jsonb, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_audit_access(p_brand_id uuid, p_access_type text, p_filters jsonb DEFAULT '{}'::jsonb, p_result_count integer DEFAULT NULL::integer, p_reason text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_display_name text;
  v_id uuid;
BEGIN
  v_user_id := public.get_user_id(auth.uid());
  IF v_user_id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT COALESCE(full_name, email) INTO v_display_name
  FROM public.users WHERE id = v_user_id;

  INSERT INTO public.audit_access_log (
    brand_id, accessed_by, accessed_by_display_name,
    access_type, filters, result_count, reason, user_agent
  ) VALUES (
    p_brand_id, v_user_id, v_display_name,
    p_access_type, COALESCE(p_filters, '{}'::jsonb),
    p_result_count, p_reason, p_user_agent
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: log_ticket_changes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_ticket_changes() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
BEGIN
  -- Try to get current user (may be null for system operations)
  SELECT get_user_id(auth.uid()) INTO v_user_id;

  IF TG_OP = 'INSERT' THEN
    -- Log ticket creation
    INSERT INTO ticket_audit_logs (brand_id, ticket_id, user_id, action_type, new_value, metadata)
    VALUES (
      NEW.brand_id,
      NEW.id,
      v_user_id,
      'created',
      jsonb_build_object(
        'status', NEW.status,
        'priority', NEW.priority,
        'category_tag_id', NEW.category_tag_id,
        'assigned_to_user_id', NEW.assigned_to_user_id
      ),
      jsonb_build_object('created_by', NEW.created_by)
    );
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    -- Log status change
    IF OLD.status IS DISTINCT FROM NEW.status THEN
      INSERT INTO ticket_audit_logs (brand_id, ticket_id, user_id, action_type, old_value, new_value)
      VALUES (
        NEW.brand_id,
        NEW.id,
        v_user_id,
        'status_change',
        jsonb_build_object('status', OLD.status),
        jsonb_build_object('status', NEW.status)
      );
    END IF;

    -- Log assignment change
    IF OLD.assigned_to_user_id IS DISTINCT FROM NEW.assigned_to_user_id THEN
      INSERT INTO ticket_audit_logs (brand_id, ticket_id, user_id, action_type, old_value, new_value, metadata)
      VALUES (
        NEW.brand_id,
        NEW.id,
        v_user_id,
        'assignment_change',
        jsonb_build_object('assigned_to_user_id', OLD.assigned_to_user_id),
        jsonb_build_object('assigned_to_user_id', NEW.assigned_to_user_id),
        jsonb_build_object(
          'assigned_by_user_id', NEW.assigned_by_user_id,
          'is_auto', NEW.assigned_by_user_id IS NULL AND NEW.assigned_to_user_id IS NOT NULL
        )
      );
    END IF;

    -- Log priority change
    IF OLD.priority IS DISTINCT FROM NEW.priority THEN
      INSERT INTO ticket_audit_logs (brand_id, ticket_id, user_id, action_type, old_value, new_value)
      VALUES (
        NEW.brand_id,
        NEW.id,
        v_user_id,
        'priority_change',
        jsonb_build_object('priority', OLD.priority),
        jsonb_build_object('priority', NEW.priority)
      );
    END IF;

    -- Log category change
    IF OLD.category_tag_id IS DISTINCT FROM NEW.category_tag_id THEN
      INSERT INTO ticket_audit_logs (brand_id, ticket_id, user_id, action_type, old_value, new_value)
      VALUES (
        NEW.brand_id,
        NEW.id,
        v_user_id,
        'category_change',
        jsonb_build_object('category_tag_id', OLD.category_tag_id),
        jsonb_build_object('category_tag_id', NEW.category_tag_id)
      );
    END IF;

    RETURN NEW;
  END IF;

  RETURN NULL;
END;
$$;


--
-- Name: log_ticket_comment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_ticket_comment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO ticket_audit_logs (brand_id, ticket_id, user_id, action_type, new_value)
  VALUES (
    NEW.brand_id,
    NEW.ticket_id,
    NEW.author_user_id,
    'comment_added',
    jsonb_build_object('comment_id', NEW.id)
  );
  RETURN NEW;
END;
$$;


--
-- Name: map_stage_to_contact_status(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.map_stage_to_contact_status(p_stage_name text) RETURNS public.contact_status
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_stage_lower TEXT;
BEGIN
  v_stage_lower := lower(p_stage_name);
  
  -- Semantic matching based on common patterns
  -- "Nuovo" stages -> new
  IF v_stage_lower LIKE '%nuovo%' OR v_stage_lower LIKE '%new%' OR v_stage_lower LIKE '%lead%' THEN
    RETURN 'new'::contact_status;
  END IF;
  
  -- "In Lavorazione", "Contattato", "Working" stages -> active
  IF v_stage_lower LIKE '%lavorazione%' OR v_stage_lower LIKE '%contatt%' OR 
     v_stage_lower LIKE '%working%' OR v_stage_lower LIKE '%progress%' OR
     v_stage_lower LIKE '%trattativa%' OR v_stage_lower LIKE '%negoziazione%' THEN
    RETURN 'active'::contact_status;
  END IF;
  
  -- "Qualificato", "Qualified", "Hot" stages -> qualified  
  IF v_stage_lower LIKE '%qualificat%' OR v_stage_lower LIKE '%qualified%' OR 
     v_stage_lower LIKE '%hot%' OR v_stage_lower LIKE '%pronto%' OR
     v_stage_lower LIKE '%chiusura%' OR v_stage_lower LIKE '%closing%' THEN
    RETURN 'qualified'::contact_status;
  END IF;
  
  -- "KO", "Perso", "Lost", "Non interessato" stages -> unqualified
  IF v_stage_lower LIKE '%ko%' OR v_stage_lower LIKE '%perso%' OR 
     v_stage_lower LIKE '%lost%' OR v_stage_lower LIKE '%non interessat%' OR
     v_stage_lower LIKE '%rifiut%' OR v_stage_lower LIKE '%rejected%' THEN
    RETURN 'unqualified'::contact_status;
  END IF;
  
  -- "Archiviato", "Chiuso", "Archived" stages -> archived (but only for closed deals)
  IF v_stage_lower LIKE '%archiviat%' OR v_stage_lower LIKE '%archived%' THEN
    RETURN 'archived'::contact_status;
  END IF;
  
  -- Default: keep as active if already in pipeline
  RETURN 'active'::contact_status;
END;
$$;


--
-- Name: mark_all_notifications_read(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_all_notifications_read(p_brand_id uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_count INTEGER;
BEGIN
  SELECT u.id INTO v_user_id FROM public.users u WHERE u.supabase_auth_id = auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  UPDATE notifications
  SET read_at = now()
  WHERE user_id = v_user_id
    AND read_at IS NULL
    AND (p_brand_id IS NULL OR brand_id = p_brand_id);

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


--
-- Name: mark_notification_webhook_result(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_notification_webhook_result(p_outbox_id uuid, p_success boolean, p_error text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row RECORD;
  v_retry_max integer;
  v_backoff_seconds integer;
BEGIN
  SELECT o.*, d.retry_max
    INTO v_row
  FROM public.notification_webhook_outbox o
  JOIN public.notification_webhook_destinations d ON d.id = o.destination_id
  WHERE o.id = p_outbox_id;

  IF NOT FOUND THEN RETURN; END IF;
  v_retry_max := v_row.retry_max;

  IF p_success THEN
    UPDATE public.notification_webhook_outbox
    SET status = 'sent', delivered_at = now(), last_error = NULL
    WHERE id = p_outbox_id;

    UPDATE public.notification_webhook_destinations
    SET consecutive_failures = 0,
        last_success_at = now(),
        last_error = NULL,
        updated_at = now()
    WHERE id = v_row.destination_id;
  ELSE
    v_backoff_seconds := LEAST(3600, 30 * (2 ^ v_row.attempts)::integer);

    IF v_row.attempts >= v_retry_max THEN
      UPDATE public.notification_webhook_outbox
      SET status = 'dead_letter', last_error = p_error
      WHERE id = p_outbox_id;
    ELSE
      UPDATE public.notification_webhook_outbox
      SET status = 'pending',
          next_retry_at = now() + (v_backoff_seconds || ' seconds')::interval,
          last_error = p_error
      WHERE id = p_outbox_id;
    END IF;

    UPDATE public.notification_webhook_destinations
    SET consecutive_failures = consecutive_failures + 1,
        last_error = p_error,
        updated_at = now()
    WHERE id = v_row.destination_id;
  END IF;
END;
$$;


--
-- Name: mark_notifications_read(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_notifications_read(p_notification_ids uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_count int;
BEGIN
  v_user_id := get_user_id(auth.uid());
  
  WITH updated AS (
    UPDATE notifications
    SET read_at = now()
    WHERE id = ANY(p_notification_ids) 
      AND user_id = v_user_id 
      AND read_at IS NULL
    RETURNING id
  )
  SELECT COUNT(*) INTO v_count FROM updated;
  
  RETURN v_count;
END;
$$;


--
-- Name: mark_siem_export_result(uuid, boolean, timestamp with time zone, integer, integer, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_siem_export_result(_destination_id uuid, _success boolean, _last_event_at timestamp with time zone, _events_count integer, _http_status integer DEFAULT NULL::integer, _error_message text DEFAULT NULL::text, _latency_ms integer DEFAULT NULL::integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _brand_id UUID;
  _from_cursor TIMESTAMPTZ;
BEGIN
  SELECT brand_id, last_exported_at INTO _brand_id, _from_cursor
  FROM public.siem_destinations
  WHERE id = _destination_id;

  IF _success THEN
    UPDATE public.siem_destinations
    SET last_exported_at = COALESCE(_last_event_at, last_exported_at),
        last_success_at = now(),
        last_error = NULL,
        consecutive_failures = 0,
        updated_at = now()
    WHERE id = _destination_id;
  ELSE
    UPDATE public.siem_destinations
    SET last_error = _error_message,
        consecutive_failures = consecutive_failures + 1,
        updated_at = now()
    WHERE id = _destination_id;
  END IF;

  INSERT INTO public.siem_export_log (
    destination_id, brand_id, events_count, status, http_status,
    error_message, latency_ms, exported_from, exported_to
  ) VALUES (
    _destination_id, _brand_id, _events_count,
    CASE WHEN _success THEN 'success' ELSE 'failed' END,
    _http_status, _error_message, _latency_ms,
    _from_cursor, _last_event_at
  );
END;
$$;


--
-- Name: mark_thread_read(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_thread_read(p_thread_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_user_id UUID;
BEGIN
  v_user_id := get_user_id(auth.uid());
  INSERT INTO thread_read_state (user_id, thread_id, last_read_at) VALUES (v_user_id, p_thread_id, now())
  ON CONFLICT (user_id, thread_id) DO UPDATE SET last_read_at = now();
END; $$;


--
-- Name: mcp_acknowledge_alert(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mcp_acknowledge_alert(p_alert_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT (public.has_role(auth.uid(), 'admin'::app_role) OR public.has_role(auth.uid(), 'ceo'::app_role)) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  UPDATE public.mcp_slo_alerts
  SET acknowledged_at = now(),
      acknowledged_by = auth.uid()
  WHERE id = p_alert_id
    AND acknowledged_at IS NULL;

  RETURN FOUND;
END;
$$;


--
-- Name: mcp_active_tokens(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mcp_active_tokens() RETURNS TABLE(id uuid, name text, kind text, user_id uuid, scopes text[], rate_limit_per_min integer, created_at timestamp with time zone, expires_at timestamp with time zone, last_used_at timestamp with time zone, requests_24h integer, errors_24h integer, avg_latency_ms integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT (has_role(get_user_id(auth.uid()), 'admin'::app_role)
       OR has_role(get_user_id(auth.uid()), 'ceo'::app_role)) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  RETURN QUERY
  SELECT t.id, t.name, t.kind, t.user_id, t.scopes, t.rate_limit_per_min,
         t.created_at, t.expires_at, t.last_used_at,
         coalesce(s.calls, 0)::int,
         coalesce(s.errors, 0)::int,
         coalesce(s.avg_latency, 0)::int
  FROM public.mcp_access_tokens t
  LEFT JOIN (
    SELECT token_id,
           count(*) AS calls,
           count(*) FILTER (WHERE status_code >= 400) AS errors,
           avg(duration_ms) AS avg_latency
    FROM public.mcp_request_log
    WHERE created_at > now() - interval '24 hours'
    GROUP BY token_id
  ) s ON s.token_id = t.id
  WHERE t.revoked_at IS NULL
  ORDER BY coalesce(s.calls, 0) DESC, t.created_at DESC
  LIMIT 200;
END;
$$;


--
-- Name: mcp_check_rate_limit(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mcp_check_rate_limit(p_token_id uuid) RETURNS TABLE(allowed boolean, used integer, max_per_min integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_max integer;
  v_used integer;
BEGIN
  SELECT rate_limit_per_min INTO v_max
  FROM public.mcp_access_tokens
  WHERE id = p_token_id AND revoked_at IS NULL;

  IF v_max IS NULL THEN
    RETURN QUERY SELECT false, 0, 0;
    RETURN;
  END IF;

  SELECT count(*)::int INTO v_used
  FROM public.mcp_request_log
  WHERE token_id = p_token_id
    AND created_at > now() - interval '1 minute';

  RETURN QUERY SELECT (v_used < v_max), v_used, v_max;
END;
$$;


--
-- Name: mcp_cleanup_resource_changes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mcp_cleanup_resource_changes() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_count int;
BEGIN
  DELETE FROM public.mcp_resource_changes
   WHERE occurred_at < now() - interval '7 days';
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


--
-- Name: mcp_emit_resource_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mcp_emit_resource_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uri text;
  v_type text := TG_ARGV[0];
  v_id text;
  v_brand uuid;
  v_change text;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_change := 'deleted';
    v_id := COALESCE(OLD.id::text, '');
    BEGIN v_brand := OLD.brand_id; EXCEPTION WHEN undefined_column THEN v_brand := NULL; END;
  ELSIF TG_OP = 'INSERT' THEN
    v_change := 'created';
    v_id := COALESCE(NEW.id::text, '');
    BEGIN v_brand := NEW.brand_id; EXCEPTION WHEN undefined_column THEN v_brand := NULL; END;
  ELSE
    v_change := 'updated';
    v_id := COALESCE(NEW.id::text, '');
    BEGIN v_brand := NEW.brand_id; EXCEPTION WHEN undefined_column THEN v_brand := NULL; END;
  END IF;

  v_uri := 'crm://' || v_type || '/' || v_id;

  INSERT INTO public.mcp_resource_changes
    (uri, resource_type, resource_id, brand_id, change_type)
  VALUES
    (v_uri, v_type, v_id, v_brand, v_change);

  RETURN COALESCE(NEW, OLD);
EXCEPTION WHEN OTHERS THEN
  -- never break business writes if change feed fails
  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: mcp_evaluate_slo_alerts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mcp_evaluate_slo_alerts() RETURNS TABLE(alert_type text, inserted boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_window_start timestamptz := date_trunc('minute', now()) - interval '5 minutes';
  v_window_end   timestamptz := date_trunc('minute', now());
  v_total int;
  v_errors int;
  v_auth_failures int;
  v_rate_limited int;
  v_p95 numeric;
  v_kill_switch boolean;
BEGIN
  -- Aggregate the last 5-minute window
  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE COALESCE(error_code, '') <> '' AND error_code <> 'OK'),
    COUNT(*) FILTER (WHERE error_code = 'AUTH_INVALID' OR error_code = 'AUTH_MISSING'),
    COUNT(*) FILTER (WHERE error_code = 'RATE_LIMITED'),
    COALESCE(percentile_cont(0.95) WITHIN GROUP (ORDER BY latency_ms), 0)
  INTO v_total, v_errors, v_auth_failures, v_rate_limited, v_p95
  FROM public.mcp_request_log
  WHERE created_at >= v_window_start AND created_at < v_window_end;

  -- Kill-switch state
  SELECT bool_or(kill_switch) INTO v_kill_switch
  FROM public.mcp_servers
  WHERE name = 'ralph-crm-mcp';

  -- Latency p95 > 5000 ms (critical) / > 3000 ms (warning) — only if traffic
  IF v_total >= 10 AND v_p95 > 3000 THEN
    INSERT INTO public.mcp_slo_alerts (alert_type, severity, window_start, window_end, metric_value, threshold, details)
    VALUES ('latency_p95',
            CASE WHEN v_p95 > 5000 THEN 'critical' ELSE 'warning' END,
            v_window_start, v_window_end, v_p95, 3000,
            jsonb_build_object('total_requests', v_total))
    ON CONFLICT (alert_type, window_start) DO NOTHING;
    RETURN QUERY SELECT 'latency_p95'::text, true;
  END IF;

  -- Error rate > 5% critical / > 2% warning
  IF v_total >= 20 AND (v_errors::numeric / v_total) > 0.02 THEN
    INSERT INTO public.mcp_slo_alerts (alert_type, severity, window_start, window_end, metric_value, threshold, details)
    VALUES ('error_rate',
            CASE WHEN (v_errors::numeric / v_total) > 0.05 THEN 'critical' ELSE 'warning' END,
            v_window_start, v_window_end,
            ROUND((v_errors::numeric / v_total)::numeric, 4), 0.02,
            jsonb_build_object('errors', v_errors, 'total', v_total))
    ON CONFLICT (alert_type, window_start) DO NOTHING;
    RETURN QUERY SELECT 'error_rate'::text, true;
  END IF;

  -- Auth failure storm: > 50 in 5 min
  IF v_auth_failures > 50 THEN
    INSERT INTO public.mcp_slo_alerts (alert_type, severity, window_start, window_end, metric_value, threshold, details)
    VALUES ('auth_failure_storm', 'critical', v_window_start, v_window_end, v_auth_failures, 50,
            jsonb_build_object('hint', 'possible brute force; review request_log for ip pattern'))
    ON CONFLICT (alert_type, window_start) DO NOTHING;
    RETURN QUERY SELECT 'auth_failure_storm'::text, true;
  END IF;

  -- Rate limit storm: > 100 hits in 5 min
  IF v_rate_limited > 100 THEN
    INSERT INTO public.mcp_slo_alerts (alert_type, severity, window_start, window_end, metric_value, threshold, details)
    VALUES ('rate_limit_storm', 'warning', v_window_start, v_window_end, v_rate_limited, 100,
            jsonb_build_object('hint', 'consider raising rate_limit_per_min for legitimate tokens'))
    ON CONFLICT (alert_type, window_start) DO NOTHING;
    RETURN QUERY SELECT 'rate_limit_storm'::text, true;
  END IF;

  -- Kill-switch active: emit info alert per window
  IF v_kill_switch THEN
    INSERT INTO public.mcp_slo_alerts (alert_type, severity, window_start, window_end, metric_value, threshold, details)
    VALUES ('kill_switch_activated', 'info', v_window_start, v_window_end, 1, 0,
            jsonb_build_object('message', 'kill switch is currently ON'))
    ON CONFLICT (alert_type, window_start) DO NOTHING;
    RETURN QUERY SELECT 'kill_switch_activated'::text, true;
  END IF;

  RETURN;
END;
$$;


--
-- Name: mcp_list_resources_for_scopes(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mcp_list_resources_for_scopes(p_scopes text[]) RETURNS TABLE(name text, uri_template text, description text, schema_json jsonb, data_classification text, required_scope text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT r.name, r.uri_template, r.description, r.schema_json,
         r.data_classification, r.required_scope
  FROM public.mcp_resources r
  JOIN public.mcp_servers s ON s.id = r.server_id
  WHERE r.enabled = true
    AND s.kill_switch = false
    AND s.status = 'active'::mcp_server_status
    AND (
      '*' = ANY(p_scopes)
      OR r.required_scope = ANY(p_scopes)
      OR EXISTS (
        SELECT 1 FROM unnest(p_scopes) sc
        WHERE sc LIKE '%*'
          AND r.required_scope LIKE replace(sc, '*', '%')
      )
    )
  ORDER BY r.name
  LIMIT 500;
$$;


--
-- Name: mcp_list_tools_for_scopes(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mcp_list_tools_for_scopes(p_scopes text[]) RETURNS TABLE(name text, description text, input_schema_json jsonb, category public.mcp_tool_category, requires_approval boolean, rate_limit_per_min integer, data_classification text, max_timeout_ms integer, required_scope text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT t.name, t.description, t.input_schema_json, t.category,
         t.requires_approval, t.rate_limit_per_min,
         t.data_classification, t.max_timeout_ms, t.required_scope
  FROM public.mcp_tools t
  JOIN public.mcp_servers s ON s.id = t.server_id
  WHERE t.enabled = true
    AND s.kill_switch = false
    AND s.status = 'active'::mcp_server_status
    AND (
      '*' = ANY(p_scopes)
      OR t.required_scope = ANY(p_scopes)
      OR EXISTS (
        SELECT 1 FROM unnest(p_scopes) sc
        WHERE sc LIKE '%*'
          AND t.required_scope LIKE replace(sc, '*', '%')
      )
    )
  ORDER BY t.name
  LIMIT 500;
$$;


--
-- Name: mcp_poll_changes(uuid, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mcp_poll_changes(p_token_id uuid, p_since timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 100) RETURNS TABLE(uri text, resource_type text, change_type text, occurred_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_since timestamptz;
BEGIN
  v_since := COALESCE(p_since, now() - interval '5 minutes');

  RETURN QUERY
  SELECT DISTINCT ON (c.uri)
    c.uri, c.resource_type, c.change_type, c.occurred_at
  FROM public.mcp_resource_changes c
  WHERE c.occurred_at > v_since
    AND (
      -- exact uri match
      EXISTS (
        SELECT 1 FROM public.mcp_subscriptions s
        WHERE s.token_id = p_token_id AND s.uri = c.uri
      )
      OR
      -- collection-level subscription crm://<type> or crm://<type>/*
      EXISTS (
        SELECT 1 FROM public.mcp_subscriptions s
        WHERE s.token_id = p_token_id
          AND (
            s.uri = 'crm://' || c.resource_type
            OR s.uri = 'crm://' || c.resource_type || '/*'
            OR s.uri = 'crm://*'
          )
      )
    )
  ORDER BY c.uri, c.occurred_at DESC
  LIMIT LEAST(GREATEST(p_limit, 1), 500);

  -- Touch last_notified_at
  UPDATE public.mcp_subscriptions
     SET last_notified_at = now()
   WHERE token_id = p_token_id
     AND last_notified_at IS DISTINCT FROM now();
END;
$$;


--
-- Name: mcp_slo_alerts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.mcp_slo_alerts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    alert_type text NOT NULL,
    severity text DEFAULT 'warning'::text NOT NULL,
    window_start timestamp with time zone NOT NULL,
    window_end timestamp with time zone NOT NULL,
    metric_value numeric,
    threshold numeric,
    details jsonb DEFAULT '{}'::jsonb NOT NULL,
    acknowledged_at timestamp with time zone,
    acknowledged_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: mcp_recent_alerts(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mcp_recent_alerts(p_limit integer DEFAULT 50) RETURNS SETOF public.mcp_slo_alerts
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT *
  FROM public.mcp_slo_alerts
  WHERE
    public.has_role(auth.uid(), 'admin'::app_role)
    OR public.has_role(auth.uid(), 'ceo'::app_role)
  ORDER BY created_at DESC
  LIMIT LEAST(GREATEST(COALESCE(p_limit, 50), 1), 500);
$$;


--
-- Name: mcp_server_kpi(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mcp_server_kpi(p_window_hours integer DEFAULT 24) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_since timestamptz := now() - (p_window_hours || ' hours')::interval;
  v_total integer;
  v_errors integer;
  v_auth_fail integer;
  v_p50 integer;
  v_p95 integer;
  v_top_tools jsonb;
  v_top_errors jsonb;
  v_kill boolean;
  v_active_tokens integer;
BEGIN
  IF NOT (has_role(get_user_id(auth.uid()), 'admin'::app_role)
       OR has_role(get_user_id(auth.uid()), 'ceo'::app_role)) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  SELECT count(*)::int,
         count(*) FILTER (WHERE status_code >= 400)::int,
         count(*) FILTER (WHERE error_code = 'AUTH')::int,
         coalesce(percentile_disc(0.5) WITHIN GROUP (ORDER BY duration_ms), 0)::int,
         coalesce(percentile_disc(0.95) WITHIN GROUP (ORDER BY duration_ms), 0)::int
    INTO v_total, v_errors, v_auth_fail, v_p50, v_p95
  FROM public.mcp_request_log
  WHERE created_at >= v_since;

  SELECT coalesce(jsonb_agg(t), '[]'::jsonb)
    INTO v_top_tools
  FROM (
    SELECT tool_name AS name, count(*)::int AS calls,
           coalesce(percentile_disc(0.95) WITHIN GROUP (ORDER BY duration_ms), 0)::int AS p95_ms,
           count(*) FILTER (WHERE status_code >= 400)::int AS errors
    FROM public.mcp_request_log
    WHERE created_at >= v_since AND tool_name IS NOT NULL
    GROUP BY tool_name
    ORDER BY calls DESC
    LIMIT 10
  ) t;

  SELECT coalesce(jsonb_agg(e), '[]'::jsonb)
    INTO v_top_errors
  FROM (
    SELECT error_code AS code, count(*)::int AS occurrences
    FROM public.mcp_request_log
    WHERE created_at >= v_since AND error_code IS NOT NULL
    GROUP BY error_code
    ORDER BY occurrences DESC
    LIMIT 10
  ) e;

  SELECT count(*)::int INTO v_active_tokens
  FROM public.mcp_access_tokens
  WHERE revoked_at IS NULL
    AND (expires_at IS NULL OR expires_at > now());

  SELECT kill_switch INTO v_kill
  FROM public.mcp_servers
  WHERE name = 'ralph-crm-mcp'
  ORDER BY created_at DESC
  LIMIT 1;

  RETURN jsonb_build_object(
    'window_hours', p_window_hours,
    'total_requests', v_total,
    'error_count', v_errors,
    'auth_failures', v_auth_fail,
    'error_rate', CASE WHEN v_total > 0 THEN round((v_errors::numeric / v_total) * 100, 2) ELSE 0 END,
    'latency_p50_ms', v_p50,
    'latency_p95_ms', v_p95,
    'top_tools', v_top_tools,
    'top_errors', v_top_errors,
    'active_tokens', v_active_tokens,
    'kill_switch_active', coalesce(v_kill, false)
  );
END;
$$;


--
-- Name: mcp_subscribe_resource(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mcp_subscribe_resource(p_token_id uuid, p_uri text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id uuid;
  v_type text;
BEGIN
  IF p_token_id IS NULL OR p_uri IS NULL OR length(p_uri) = 0 THEN
    RAISE EXCEPTION 'invalid_args';
  END IF;

  -- Extract resource type from uri prefix crm://<type>/...
  v_type := split_part(replace(p_uri, 'crm://', ''), '/', 1);

  INSERT INTO public.mcp_subscriptions (token_id, uri, resource_type)
  VALUES (p_token_id, p_uri, v_type)
  ON CONFLICT (token_id, uri) DO UPDATE
    SET resource_type = EXCLUDED.resource_type
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: mcp_toggle_server_kill_switch(boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mcp_toggle_server_kill_switch(p_enabled boolean) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT has_role(get_user_id(auth.uid()), 'admin'::app_role) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  UPDATE public.mcp_servers
     SET kill_switch = p_enabled,
         updated_at = now()
   WHERE name = 'ralph-crm-mcp';

  RETURN p_enabled;
END;
$$;


--
-- Name: mcp_unsubscribe_resource(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mcp_unsubscribe_resource(p_token_id uuid, p_uri text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_count int;
BEGIN
  DELETE FROM public.mcp_subscriptions
   WHERE token_id = p_token_id AND uri = p_uri;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count > 0;
END;
$$;


--
-- Name: move_to_dlq(text, text, bigint, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.move_to_dlq(source_queue text, dlq_name text, message_id bigint, payload jsonb) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE new_id BIGINT;
BEGIN
  SELECT pgmq.send(dlq_name, payload) INTO new_id;
  PERFORM pgmq.delete(source_queue, message_id);
  RETURN new_id;
EXCEPTION WHEN undefined_table THEN
  BEGIN
    PERFORM pgmq.create(dlq_name);
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;
  SELECT pgmq.send(dlq_name, payload) INTO new_id;
  BEGIN
    PERFORM pgmq.delete(source_queue, message_id);
  EXCEPTION WHEN undefined_table THEN
    NULL;
  END;
  RETURN new_id;
END;
$$;


--
-- Name: normalize_alias_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_alias_trigger() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  NEW.alias_text := normalize_topic_text(NEW.alias_text);
  RETURN NEW;
END;
$$;


--
-- Name: normalize_topic_text(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_topic_text(p_text text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT lower(
    trim(
      regexp_replace(
        regexp_replace(p_text, '[[:punct:]]', ' ', 'g'),
        '\s+', ' ', 'g'
      )
    )
  )
$$;


--
-- Name: notify_high_risk_appointments(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_high_risk_appointments() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_inserted int := 0;
  v_skipped int := 0;
  r RECORD;
  v_recipient_ids uuid[];
  v_recipient uuid;
BEGIN
  FOR r IN
    SELECT a.id, a.brand_id, a.contact_id, a.scheduled_at, a.assigned_sales_user_id,
           a.risk_score,
           c.first_name, c.last_name
    FROM public.appointments a
    LEFT JOIN public.contacts c ON c.id = a.contact_id
    WHERE a.risk_score >= 60
      AND a.scheduled_at >= now()
      AND a.scheduled_at < now() + interval '24 hours'
      AND a.status NOT IN ('cancelled', 'visited', 'completed', 'no_show')
    ORDER BY a.scheduled_at ASC
    LIMIT 200
  LOOP
    -- Dedup: skip if a risk alert for this appointment was issued in the last 12h
    IF EXISTS (
      SELECT 1 FROM public.notifications
      WHERE entity_type = 'appointment'
        AND entity_id = r.id
        AND type = 'appointment_risk_alert'
        AND created_at > now() - interval '12 hours'
      LIMIT 1
    ) THEN
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;

    -- Determine recipients
    IF r.assigned_sales_user_id IS NOT NULL THEN
      v_recipient_ids := ARRAY[r.assigned_sales_user_id];
    ELSE
      -- Fallback: brand admins/managers
      SELECT COALESCE(array_agg(DISTINCT ur.user_id), ARRAY[]::uuid[])
      INTO v_recipient_ids
      FROM public.user_roles ur
      WHERE ur.brand_id = r.brand_id
        AND ur.is_active = true
        AND ur.role IN ('admin', 'responsabile_venditori', 'responsabile_callcenter');
    END IF;

    -- Insert one notification per recipient
    FOREACH v_recipient IN ARRAY v_recipient_ids LOOP
      INSERT INTO public.notifications (
        brand_id, user_id, type, title, body, entity_type, entity_id
      )
      VALUES (
        r.brand_id,
        v_recipient,
        'appointment_risk_alert',
        format(
          'Appuntamento a rischio: %s',
          COALESCE(NULLIF(trim(concat_ws(' ', r.first_name, r.last_name)), ''), 'Contatto')
        ),
        format(
          'Risk score %s/100 · previsto %s',
          ROUND(r.risk_score)::text,
          to_char(r.scheduled_at AT TIME ZONE 'Europe/Rome', 'DD/MM HH24:MI')
        ),
        'appointment',
        r.id
      );
      v_inserted := v_inserted + 1;
    END LOOP;
  END LOOP;

  RETURN jsonb_build_object(
    'inserted', v_inserted,
    'skipped_duplicates', v_skipped,
    'executed_at', now()
  );
END;
$$;


--
-- Name: notify_sheets_new_lead(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_sheets_new_lead() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _url text;
  _anon_key text;
BEGIN
  -- Skip duplicates and opted-out contacts
  IF NEW.archived THEN
    RETURN NEW;
  END IF;

  _url := 'https://qmqcjtmcxfqahhubpaea.supabase.co/functions/v1/sheets-leads-export';

  SELECT decrypted_secret INTO _anon_key
  FROM vault.decrypted_secrets
  WHERE name = 'supabase_anon_key'
  LIMIT 1;

  PERFORM net.http_post(
    url := _url,
    body := jsonb_build_object('lead_event_id', NEW.id),
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || COALESCE(_anon_key, ''),
      'apikey', COALESCE(_anon_key, '')
    )
  );

  RETURN NEW;
END;
$$;


--
-- Name: override_ai_decision(uuid, integer, text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.override_ai_decision(p_lead_event_id uuid, p_new_priority integer DEFAULT NULL::integer, p_new_lead_type text DEFAULT NULL::text, p_new_should_create_ticket boolean DEFAULT NULL::boolean, p_override_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_brand_id uuid;
  v_decision_log ai_decision_logs%ROWTYPE;
  v_lead_event lead_events%ROWTYPE;
  v_original_decision jsonb;
BEGIN
  -- Get user id
  v_user_id := get_user_id(auth.uid());
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Get lead event and validate brand access
  SELECT * INTO v_lead_event
  FROM lead_events
  WHERE id = p_lead_event_id
  FOR UPDATE;

  IF v_lead_event.id IS NULL THEN
    RAISE EXCEPTION 'Lead event not found';
  END IF;

  v_brand_id := v_lead_event.brand_id;

  IF NOT user_belongs_to_brand(v_user_id, v_brand_id) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  -- Capture original values
  v_original_decision := jsonb_build_object(
    'lead_type', v_lead_event.lead_type,
    'priority', v_lead_event.ai_priority,
    'should_create_ticket', v_lead_event.should_create_ticket,
    'rationale', v_lead_event.ai_rationale
  );

  -- Update lead_event with overrides
  UPDATE lead_events
  SET
    ai_priority = COALESCE(p_new_priority, ai_priority),
    lead_type = COALESCE(p_new_lead_type::lead_type, lead_type),
    should_create_ticket = COALESCE(p_new_should_create_ticket, should_create_ticket)
  WHERE id = p_lead_event_id;

  -- Update or create decision log entry
  SELECT * INTO v_decision_log
  FROM ai_decision_logs
  WHERE lead_event_id = p_lead_event_id
  ORDER BY created_at DESC
  LIMIT 1;

  IF v_decision_log.id IS NOT NULL AND NOT v_decision_log.was_overridden THEN
    -- Update existing log
    UPDATE ai_decision_logs
    SET
      was_overridden = true,
      overridden_by_user_id = v_user_id,
      overridden_at = now(),
      override_reason = p_override_reason,
      original_decision = v_original_decision
    WHERE id = v_decision_log.id;
  ELSE
    -- Create new override log entry
    INSERT INTO ai_decision_logs (
      brand_id,
      lead_event_id,
      lead_type,
      priority,
      should_create_ticket,
      rationale,
      model_version,
      prompt_version,
      was_overridden,
      overridden_by_user_id,
      overridden_at,
      override_reason,
      original_decision
    ) VALUES (
      v_brand_id,
      p_lead_event_id,
      COALESCE(p_new_lead_type, v_lead_event.lead_type::text, 'generic'),
      COALESCE(p_new_priority, v_lead_event.ai_priority, 3),
      COALESCE(p_new_should_create_ticket, v_lead_event.should_create_ticket, false),
      'Override manuale',
      'human',
      'manual',
      true,
      v_user_id,
      now(),
      p_override_reason,
      v_original_decision
    );
  END IF;

  -- Audit log
  INSERT INTO audit_log (brand_id, entity_type, entity_id, action, actor_user_id, old_value, new_value, metadata)
  VALUES (
    v_brand_id,
    'lead_event',
    p_lead_event_id,
    'ai_decision_overridden',
    v_user_id,
    v_original_decision,
    jsonb_build_object(
      'lead_type', COALESCE(p_new_lead_type, v_lead_event.lead_type::text),
      'priority', COALESCE(p_new_priority, v_lead_event.ai_priority),
      'should_create_ticket', COALESCE(p_new_should_create_ticket, v_lead_event.should_create_ticket)
    ),
    jsonb_build_object('reason', p_override_reason)
  );

  RETURN jsonb_build_object(
    'success', true,
    'lead_event_id', p_lead_event_id,
    'changes', jsonb_build_object(
      'priority', COALESCE(p_new_priority, v_lead_event.ai_priority),
      'lead_type', COALESCE(p_new_lead_type, v_lead_event.lead_type::text),
      'should_create_ticket', COALESCE(p_new_should_create_ticket, v_lead_event.should_create_ticket)
    )
  );
END;
$$;


--
-- Name: override_ai_decision(uuid, integer, text, boolean, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.override_ai_decision(p_lead_event_id uuid, p_new_priority integer DEFAULT NULL::integer, p_new_lead_type text DEFAULT NULL::text, p_new_should_create_ticket boolean DEFAULT NULL::boolean, p_override_reason text DEFAULT NULL::text, p_override_category text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_decision_id uuid;
  v_user_id uuid;
  v_result jsonb;
  v_category public.override_reason_category;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Cast category if provided
  IF p_override_category IS NOT NULL AND p_override_category <> '' THEN
    v_category := p_override_category::public.override_reason_category;
  END IF;

  -- Find the most recent decision for this lead event
  SELECT id INTO v_decision_id
  FROM ai_decision_logs
  WHERE lead_event_id = p_lead_event_id
  ORDER BY created_at DESC
  LIMIT 1
  FOR UPDATE;

  IF v_decision_id IS NULL THEN
    RAISE EXCEPTION 'No AI decision found for lead event %', p_lead_event_id;
  END IF;

  -- Save original decision before override
  UPDATE ai_decision_logs SET
    original_decision = CASE
      WHEN original_decision IS NULL THEN
        jsonb_build_object(
          'priority', priority,
          'lead_type', lead_type,
          'should_create_ticket', should_create_ticket
        )
      ELSE original_decision
    END,
    priority = COALESCE(p_new_priority, priority),
    lead_type = COALESCE(p_new_lead_type, lead_type),
    should_create_ticket = COALESCE(p_new_should_create_ticket, should_create_ticket),
    was_overridden = true,
    overridden_at = NOW(),
    overridden_by_user_id = v_user_id,
    override_reason = COALESCE(p_override_reason, override_reason),
    override_reason_category = COALESCE(v_category, override_reason_category)
  WHERE id = v_decision_id;

  SELECT jsonb_build_object(
    'success', true,
    'lead_event_id', p_lead_event_id,
    'changes', jsonb_build_object(
      'priority', COALESCE(p_new_priority, priority),
      'lead_type', COALESCE(p_new_lead_type, lead_type),
      'should_create_ticket', COALESCE(p_new_should_create_ticket, should_create_ticket)
    )
  ) INTO v_result
  FROM ai_decision_logs
  WHERE id = v_decision_id;

  RETURN v_result;
END;
$$;


