--
-- Name: queue_capi_lead_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.queue_capi_lead_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_meta_app_id uuid;
  v_consent boolean;
  v_custom_data jsonb;
  v_user_data jsonb;
  v_lead_id text;
BEGIN
  -- Skip archived
  IF NEW.archived THEN
    RETURN NEW;
  END IF;

  -- Skip if no contact (can't build CAPI user_data)
  IF NEW.contact_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT id INTO v_meta_app_id
  FROM meta_apps
  WHERE brand_id = NEW.brand_id
    AND is_active = true
    AND capi_enabled = true
  LIMIT 1;

  IF v_meta_app_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT COALESCE(marketing_consent, false) INTO v_consent
  FROM contacts
  WHERE id = NEW.contact_id;

  -- Safety: if contact somehow not found, default to false
  IF v_consent IS NULL THEN
    v_consent := false;
  END IF;

  v_custom_data := jsonb_build_object(
    'event_source', 'crm',
    'lead_event_source', 'CRM Gruppo Benessere'
  );

  SELECT mle.leadgen_id::text INTO v_lead_id
  FROM meta_lead_events mle
  WHERE mle.contact_id = NEW.contact_id
  ORDER BY mle.received_at DESC
  LIMIT 1;

  v_user_data := '{}'::jsonb;
  IF v_lead_id IS NOT NULL THEN
    v_user_data := jsonb_build_object('lead_id', v_lead_id);
  END IF;

  INSERT INTO meta_capi_event_queue (
    brand_id, meta_app_id, event_name, event_id, event_time,
    action_source, contact_id, lead_event_id,
    custom_data, user_data, consent_snapshot
  ) VALUES (
    NEW.brand_id,
    v_meta_app_id,
    'Lead',
    'lead_' || NEW.id::text,
    now(),
    'system_generated',
    NEW.contact_id,
    NEW.id,
    v_custom_data,
    v_user_data,
    v_consent
  )
  ON CONFLICT (brand_id, event_id) DO NOTHING;

  RETURN NEW;
END;
$$;


--
-- Name: queue_capi_purchase_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.queue_capi_purchase_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_meta_app_id uuid;
  v_contact_id uuid;
  v_consent boolean;
  v_deal_value numeric;
  v_custom_data jsonb;
  v_user_data jsonb;
  v_lead_id text;
  v_stage_name text;
BEGIN
  -- Look up the stage name from pipeline_stages
  IF NEW.current_stage_id IS NOT NULL THEN
    SELECT name INTO v_stage_name FROM pipeline_stages WHERE id = NEW.current_stage_id;
  END IF;

  -- Only fire when stage changes to a "won" equivalent, or deal status becomes 'won'
  -- Original logic checked stage_name = 'Vinta', but we should use deal status instead
  IF NEW.status IS DISTINCT FROM 'won' THEN
    RETURN NEW;
  END IF;
  IF OLD IS NOT NULL AND OLD.status = 'won' THEN
    RETURN NEW;
  END IF;

  IF NEW.contact_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT id INTO v_meta_app_id
  FROM meta_apps
  WHERE brand_id = NEW.brand_id
    AND is_active = true
    AND capi_enabled = true
  LIMIT 1;

  IF v_meta_app_id IS NULL THEN
    RETURN NEW;
  END IF;

  v_contact_id := NEW.contact_id;

  SELECT COALESCE(marketing_consent, false) INTO v_consent
  FROM contacts
  WHERE id = v_contact_id;

  v_deal_value := COALESCE(NEW.value, 0);

  v_custom_data := jsonb_build_object(
    'event_source', 'crm',
    'lead_event_source', 'CRM Gruppo Benessere',
    'value', v_deal_value,
    'currency', 'EUR'
  );

  SELECT mle.leadgen_id::text INTO v_lead_id
  FROM meta_lead_events mle
  WHERE mle.contact_id = v_contact_id
  ORDER BY mle.received_at DESC
  LIMIT 1;

  v_user_data := '{}'::jsonb;
  IF v_lead_id IS NOT NULL THEN
    v_user_data := jsonb_build_object('lead_id', v_lead_id);
  END IF;

  INSERT INTO meta_capi_event_queue (
    brand_id, meta_app_id, event_name, event_id, event_time,
    action_source, contact_id, deal_id,
    custom_data, user_data, consent_snapshot
  ) VALUES (
    NEW.brand_id,
    v_meta_app_id,
    'Purchase',
    'purchase_' || NEW.id::text,
    now(),
    'system_generated',
    v_contact_id,
    NEW.id,
    v_custom_data,
    v_user_data,
    v_consent
  )
  ON CONFLICT (brand_id, event_id) DO NOTHING;

  RETURN NEW;
END;
$$;


--
-- Name: reactivate_pipeline_stage(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reactivate_pipeline_stage(p_stage_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_stage_name TEXT;
  v_max_order INT;
BEGIN
  v_user_id := get_user_id(auth.uid());
  
  -- Check if user is admin or CEO
  IF NOT (has_role(v_user_id, 'admin'::app_role) OR has_role(v_user_id, 'ceo'::app_role)) THEN
    RAISE EXCEPTION 'Solo admin e CEO possono riattivare fasi pipeline';
  END IF;
  
  -- Get stage name
  SELECT name INTO v_stage_name FROM pipeline_stages WHERE id = p_stage_id;
  
  IF v_stage_name IS NULL THEN
    RAISE EXCEPTION 'Fase non trovata';
  END IF;
  
  -- Get max order for active stages
  SELECT COALESCE(MAX(order_index), -1) INTO v_max_order
  FROM pipeline_stages
  WHERE is_active = true;
  
  -- Reactivate the stage
  UPDATE pipeline_stages
  SET is_active = true,
      order_index = v_max_order + 1,
      updated_at = NOW()
  WHERE id = p_stage_id;
  
  RETURN jsonb_build_object(
    'success', true,
    'stage_name', v_stage_name
  );
END;
$$;


--
-- Name: read_email_batch(text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_email_batch(queue_name text, batch_size integer, vt integer) RETURNS TABLE(msg_id bigint, read_ct integer, message jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY SELECT r.msg_id, r.read_ct, r.message FROM pgmq.read(queue_name, vt, batch_size) r;
EXCEPTION WHEN undefined_table THEN
  PERFORM pgmq.create(queue_name);
  RETURN;
END;
$$;


--
-- Name: rebuild_contact_search_index(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rebuild_contact_search_index() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE 
  v_count INTEGER := 0;
BEGIN
  DELETE FROM contact_search_index;
  
  INSERT INTO contact_search_index (contact_id, brand_id, search_text, search_vector, updated_at)
  SELECT 
    c.id, 
    c.brand_id, 
    public.build_contact_search_text(c.id),
    to_tsvector('simple', public.build_contact_search_text(c.id)),
    now()
  FROM contacts c;
  
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END; 
$$;


--
-- Name: recalculate_order_totals(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalculate_order_totals() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order_id uuid;
  v_subtotal numeric;
  v_tax_amount numeric;
  v_total_amount numeric;
BEGIN
  -- Get the order_id from the affected row
  IF TG_OP = 'DELETE' THEN
    v_order_id := OLD.order_id;
  ELSE
    v_order_id := NEW.order_id;
  END IF;
  
  -- Calculate new subtotal from all line items
  SELECT COALESCE(SUM(line_total), 0)
  INTO v_subtotal
  FROM public.sales_order_items
  WHERE order_id = v_order_id;
  
  -- Calculate tax (assuming VAT is applied per-item, avg 22% for simplicity)
  -- Actually, we'll compute it properly from each item's vat_rate
  SELECT COALESCE(SUM(line_total * vat_rate / 100), 0)
  INTO v_tax_amount
  FROM public.sales_order_items
  WHERE order_id = v_order_id;
  
  -- Get existing discount_amount from order
  DECLARE
    v_discount_amount numeric;
  BEGIN
    SELECT COALESCE(discount_amount, 0)
    INTO v_discount_amount
    FROM public.sales_orders
    WHERE id = v_order_id;
    
    v_total_amount := v_subtotal - v_discount_amount + v_tax_amount;
  END;
  
  -- Update the order totals
  UPDATE public.sales_orders
  SET subtotal = v_subtotal,
      tax_amount = v_tax_amount,
      total_amount = v_total_amount,
      updated_at = now()
  WHERE id = v_order_id;
  
  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: reclaim_stale_capi_events(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reclaim_stale_capi_events() RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  affected integer;
BEGIN
  -- Events stuck in 'processing' for >5 min AND exhausted max_attempts → mark as failed
  UPDATE public.meta_capi_event_queue
  SET 
    status = 'failed',
    last_error = 'Exhausted max_attempts while stuck in processing (auto-DLQ)',
    processing_at = NULL,
    processing_by = NULL
  WHERE status = 'processing'
    AND processing_at < NOW() - INTERVAL '5 minutes'
    AND attempts >= max_attempts;
  
  GET DIAGNOSTICS affected = ROW_COUNT;
  RETURN affected;
END;
$$;


--
-- Name: record_appointment_outcome(uuid, public.appointment_outcome_code, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_appointment_outcome(p_appointment_id uuid, p_outcome_code public.appointment_outcome_code, p_outcome_notes text DEFAULT NULL::text, p_reschedule_reason text DEFAULT NULL::text, p_next_action text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_brand uuid;
  v_user uuid;
  v_outcome_id uuid;
  v_new_status public.appointment_status;
BEGIN
  SELECT brand_id INTO v_brand FROM public.appointments WHERE id = p_appointment_id;
  IF v_brand IS NULL THEN
    RAISE EXCEPTION 'appointment_not_found' USING ERRCODE = 'P0002';
  END IF;

  BEGIN
    v_user := public.get_user_id(auth.uid());
  EXCEPTION WHEN OTHERS THEN
    v_user := NULL;
  END;

  INSERT INTO public.appointment_outcomes(
    appointment_id, brand_id, outcome_code, outcome_notes,
    reschedule_reason, next_action, recorded_by_user_id, metadata
  ) VALUES (
    p_appointment_id, v_brand, p_outcome_code, p_outcome_notes,
    p_reschedule_reason, p_next_action, v_user, COALESCE(p_metadata, '{}'::jsonb)
  )
  RETURNING id INTO v_outcome_id;

  -- Map outcome → status (additive, only forward transitions)
  v_new_status := CASE p_outcome_code
    WHEN 'executed' THEN 'completed'::public.appointment_status
    WHEN 'no_show_client' THEN 'no_show'::public.appointment_status
    WHEN 'no_show_operator' THEN 'no_show'::public.appointment_status
    WHEN 'cancelled_client' THEN 'cancelled'::public.appointment_status
    WHEN 'cancelled_operator' THEN 'cancelled'::public.appointment_status
    WHEN 'rescheduled' THEN 'rescheduled'::public.appointment_status
    ELSE NULL
  END;

  UPDATE public.appointments
  SET last_outcome_code = p_outcome_code,
      last_outcome_at = now(),
      reschedule_reason = COALESCE(p_reschedule_reason, reschedule_reason),
      reschedule_count = CASE WHEN p_outcome_code = 'rescheduled'
                              THEN reschedule_count + 1 ELSE reschedule_count END,
      status = COALESCE(v_new_status, status),
      updated_at = now()
  WHERE id = p_appointment_id;

  RETURN v_outcome_id;
END;
$$;


--
-- Name: record_audit_anomaly(uuid, text, text, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_audit_anomaly(_brand_id uuid, _anomaly_type text, _severity text, _title text, _description text DEFAULT NULL::text, _actor_user_id uuid DEFAULT NULL::uuid, _details jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _id UUID;
BEGIN
  INSERT INTO public.audit_anomalies (
    brand_id, anomaly_type, severity, title, description, actor_user_id, details
  ) VALUES (
