    _anomaly_type, _severity, _title, _description, _actor_user_id, COALESCE(_details, '{}'::jsonb)
  ) RETURNING id INTO _id;
  RETURN _id;
END;
$$;


--
-- Name: record_delivery_result(uuid, boolean, integer, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_delivery_result(p_delivery_id uuid, p_success boolean, p_response_status integer DEFAULT NULL::integer, p_response_body text DEFAULT NULL::text, p_error text DEFAULT NULL::text, p_duration_ms integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_delivery RECORD;
  v_new_status webhook_delivery_status;
  v_next_attempt TIMESTAMP WITH TIME ZONE;
  v_is_dead BOOLEAN := FALSE;
  
  -- Exponential backoff intervals (in minutes): 1, 5, 15, 60, 360, 1440 (24h)
  v_backoff_minutes INTEGER[] := ARRAY[1, 5, 15, 60, 360, 1440];
  v_backoff_index INTEGER;
BEGIN
  -- Fetch current delivery state
  SELECT * INTO v_delivery 
  FROM outbound_webhook_deliveries 
  WHERE id = p_delivery_id 
  FOR UPDATE;
  
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'delivery_not_found');
  END IF;

  IF p_success THEN
    -- SUCCESS: Mark as delivered
    v_new_status := 'success';
    v_next_attempt := NULL;
  ELSE
    -- FAILURE: Check if we've exhausted retries
    IF v_delivery.attempt_count + 1 >= v_delivery.max_attempts THEN
      -- DEAD: Maximum attempts reached
      v_new_status := 'dead';
      v_is_dead := TRUE;
      v_next_attempt := NULL;
    ELSE
      -- RETRYING: Calculate next attempt with exponential backoff + jitter
      v_new_status := 'failed';
      v_backoff_index := LEAST(v_delivery.attempt_count + 1, array_length(v_backoff_minutes, 1));
      v_next_attempt := NOW() + 
        (v_backoff_minutes[v_backoff_index] * INTERVAL '1 minute') +
        (random() * INTERVAL '30 seconds'); -- Add jitter
    END IF;
  END IF;

  -- Update delivery record
  UPDATE outbound_webhook_deliveries SET
    status = v_new_status,
    attempt_count = attempt_count + 1,
    response_status = p_response_status,
    response_body = p_response_body,
    last_error = p_error,
    duration_ms = p_duration_ms,
    next_attempt_at = COALESCE(v_next_attempt, next_attempt_at),
    dead_at = CASE WHEN v_is_dead THEN NOW() ELSE dead_at END,
    updated_at = NOW()
  WHERE id = p_delivery_id;

  RETURN jsonb_build_object(
    'status', v_new_status::text,
    'attempt', v_delivery.attempt_count + 1,
    'max_attempts', v_delivery.max_attempts,
    'is_dead', v_is_dead,
    'next_attempt_at', v_next_attempt
  );
END;
$$;


--
-- Name: record_slo_snapshot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_slo_snapshot() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_slo RECORD;
  v_good BIGINT;
  v_total BIGINT;
  v_count INTEGER := 0;
  v_calc RECORD;
BEGIN
  FOR v_slo IN SELECT * FROM public.slo_definitions WHERE is_active = true LOOP
    -- Default: derive from trace_events for last 5 minutes
    SELECT 
      COUNT(*) FILTER (WHERE status_code = 'ok'),
      COUNT(*)
    INTO v_good, v_total
    FROM public.trace_events
    WHERE service_name = v_slo.service_name
      AND started_at >= now() - interval '5 minutes';

    INSERT INTO public.slo_measurements(slo_id, good_events, total_events)
    VALUES (v_slo.id, COALESCE(v_good, 0), COALESCE(v_total, 0));

    SELECT * INTO v_calc FROM public.calculate_slo_burn_rate(v_slo.id);
    UPDATE public.slo_measurements
    SET current_sli = v_calc.current_sli,
        error_budget_remaining = v_calc.error_budget_remaining,
        burn_rate_1h = v_calc.burn_rate_1h,
        burn_rate_6h = v_calc.burn_rate_6h,
        burn_rate_24h = v_calc.burn_rate_24h
    WHERE slo_id = v_slo.id
      AND id = (SELECT id FROM public.slo_measurements WHERE slo_id = v_slo.id ORDER BY measured_at DESC LIMIT 1);

    v_count := v_count + 1;
  END LOOP;
  RETURN v_count;
END;
$$;


--
-- Name: refresh_anomaly_baselines(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_anomaly_baselines() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_count int := 0;
BEGIN
  INSERT INTO public.anomaly_baselines (metric_name, window_hours, mean_value, stddev_value, sample_count)
  SELECT metric_name, 24, avg(metric_value), coalesce(stddev_pop(metric_value), 0), count(*)::int
  FROM public.capacity_snapshots
  WHERE captured_at > now() - interval '14 days'
  GROUP BY metric_name
  HAVING count(*) >= 5
  ON CONFLICT (metric_name, brand_id, window_hours) DO UPDATE
    SET mean_value = EXCLUDED.mean_value,
        stddev_value = EXCLUDED.stddev_value,
        sample_count = EXCLUDED.sample_count,
        computed_at = now();
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN jsonb_build_object('baselines_refreshed', v_count);
END;
$$;


--
-- Name: remove_group_member(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remove_group_member(p_thread_id uuid, p_target_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_user_id UUID; v_actor_role TEXT; v_target_role TEXT;
BEGIN
  v_user_id := get_user_id(auth.uid());
  IF v_user_id = p_target_user_id THEN
    UPDATE chat_thread_members SET left_at = now() WHERE thread_id = p_thread_id AND user_id = p_target_user_id AND left_at IS NULL;
    RETURN;
  END IF;
  SELECT role INTO v_actor_role FROM chat_thread_members WHERE thread_id = p_thread_id AND user_id = v_user_id AND left_at IS NULL;
  SELECT role INTO v_target_role FROM chat_thread_members WHERE thread_id = p_thread_id AND user_id = p_target_user_id AND left_at IS NULL;
  IF v_actor_role IS NULL OR v_actor_role = 'member' THEN RAISE EXCEPTION 'Only owners and moderators can remove members'; END IF;
  IF v_actor_role = 'moderator' AND v_target_role IN ('owner', 'moderator') THEN RAISE EXCEPTION 'Moderators cannot remove owners or other moderators'; END IF;
  IF v_target_role = 'owner' AND (SELECT COUNT(*) FROM chat_thread_members WHERE thread_id = p_thread_id AND role = 'owner' AND left_at IS NULL) <= 1 THEN
    RAISE EXCEPTION 'Cannot remove the last owner';
  END IF;
  UPDATE chat_thread_members SET left_at = now() WHERE thread_id = p_thread_id AND user_id = p_target_user_id AND left_at IS NULL;
END; $$;


--
-- Name: rename_group_thread(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rename_group_thread(p_thread_id uuid, p_new_title text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_user_id UUID; v_role TEXT;
BEGIN
  v_user_id := get_user_id(auth.uid());
  SELECT role INTO v_role FROM chat_thread_members WHERE thread_id = p_thread_id AND user_id = v_user_id AND left_at IS NULL;
  IF v_role IS NULL OR v_role = 'member' THEN RAISE EXCEPTION 'Only owners and moderators can rename groups'; END IF;
  UPDATE chat_threads SET title = p_new_title, updated_at = now() WHERE id = p_thread_id AND type = 'group';
END; $$;


--
-- Name: reorder_pipeline_stages(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reorder_pipeline_stages(p_stage_ids uuid[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  i INT;
BEGIN
  v_user_id := get_user_id(auth.uid());
  
  -- Check if user is admin or CEO
  IF NOT (has_role(v_user_id, 'admin'::app_role) OR has_role(v_user_id, 'ceo'::app_role)) THEN
    RAISE EXCEPTION 'Solo admin e CEO possono riordinare le fasi pipeline';
  END IF;
  
  -- Update order_index for each stage
  FOR i IN 1..array_length(p_stage_ids, 1) LOOP
    UPDATE pipeline_stages
    SET order_index = i - 1,
        updated_at = NOW()
    WHERE id = p_stage_ids[i];
  END LOOP;
END;
$$;


--
-- Name: replay_ingest_dlq(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.replay_ingest_dlq(p_request_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_request RECORD;
    v_user_id UUID;
BEGIN
    -- Get current user
    v_user_id := get_user_id(auth.uid());
    
    -- Get the DLQ entry
    SELECT * INTO v_request
    FROM incoming_requests
    WHERE id = p_request_id;
    
    IF NOT FOUND THEN
        RETURN json_build_object('success', false, 'error', 'not_found');
    END IF;
    
    -- Verify admin access
    IF NOT has_role_for_brand(v_user_id, v_request.brand_id, 'admin') THEN
        RETURN json_build_object('success', false, 'error', 'unauthorized');
    END IF;
    
    -- Reset status to pending for reprocessing
    UPDATE incoming_requests
    SET 
        status = 'pending',
        processed = false,
        error_message = NULL,
        dlq_reason = NULL
    WHERE id = p_request_id;
    
    RETURN json_build_object(
        'success', true, 
        'message', 'Entry reset to pending for reprocessing',
        'request_id', p_request_id
    );
END;
$$;


--
-- Name: replay_outbound_dlq(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.replay_outbound_dlq(p_delivery_id uuid, p_override_url text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_delivery RECORD;
    v_user_id UUID;
BEGIN
    -- Get current user
    v_user_id := get_user_id(auth.uid());
    
    -- Get the dead delivery
    SELECT * INTO v_delivery
    FROM outbound_webhook_deliveries
    WHERE id = p_delivery_id;
    
    IF NOT FOUND THEN
        RETURN json_build_object('success', false, 'error', 'not_found');
    END IF;
    
    -- Verify admin access
    IF NOT has_role_for_brand(v_user_id, v_delivery.brand_id, 'admin') THEN
        RETURN json_build_object('success', false, 'error', 'unauthorized');
    END IF;
    
    -- Reset to pending for redelivery
    UPDATE outbound_webhook_deliveries
    SET 
        status = 'pending',
        attempt_count = 0,
        next_attempt_at = NOW(),
        dead_at = NULL,
        last_error = CASE 
            WHEN p_override_url IS NOT NULL THEN 'replayed_with_override: ' || p_override_url
            ELSE 'replayed_by_admin'
        END
    WHERE id = p_delivery_id;
    
    -- If override URL provided, store in payload metadata
    IF p_override_url IS NOT NULL THEN
        UPDATE outbound_webhook_deliveries
        SET payload = payload || jsonb_build_object('_override_url', p_override_url)
        WHERE id = p_delivery_id;
    END IF;
    
    RETURN json_build_object(
        'success', true, 
        'message', 'Delivery reset to pending',
        'delivery_id', p_delivery_id,
        'override_url', p_override_url
    );
END;
$$;


--
-- Name: replay_outbound_webhook_delivery(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.replay_outbound_webhook_delivery(p_delivery_id uuid, p_force_new_event_id boolean DEFAULT false) RETURNS TABLE(delivery_id uuid, event_id uuid, reused boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_internal_user_id uuid;
  v_brand_id uuid;
  v_webhook_id uuid;
  v_event_type webhook_event_type;
  v_event_id uuid;
  v_payload jsonb;
  v_new_event_id uuid;
  v_new_delivery_id uuid;
BEGIN
  v_internal_user_id := public.get_user_id(auth.uid());
  IF v_internal_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  SELECT d.brand_id, d.webhook_id, d.event_type, d.event_id, d.payload
    INTO v_brand_id, v_webhook_id, v_event_type, v_event_id, v_payload
  FROM public.outbound_webhook_deliveries d
  WHERE d.id = p_delivery_id;

  IF v_brand_id IS NULL THEN
    RAISE EXCEPTION 'Delivery not found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT public.has_role_for_brand(v_internal_user_id, v_brand_id, 'admin'::app_role) THEN
    RAISE EXCEPTION 'Admin access required' USING ERRCODE = '42501';
  END IF;

  IF p_force_new_event_id THEN
    -- Rare case: admin wants the receiver to treat this as a brand-new event.
    v_new_event_id := gen_random_uuid();
    INSERT INTO public.outbound_webhook_deliveries (
      webhook_id, brand_id, event_type, event_id, payload, status, next_attempt_at, attempt_count
    ) VALUES (
      v_webhook_id, v_brand_id, v_event_type, v_new_event_id, v_payload, 'pending', now(), 0
    )
    RETURNING id INTO v_new_delivery_id;

    RETURN QUERY SELECT v_new_delivery_id, v_new_event_id, false;
  ELSE
    -- Default: idempotent replay — keep event_id stable so the receiver
    -- recognizes the retry via Idempotency-Key.
    UPDATE public.outbound_webhook_deliveries
    SET status = 'pending',
        attempt_count = 0,
        next_attempt_at = now(),
        last_error = NULL,
        response_status = NULL,
        response_body = NULL,
        dead_at = NULL
    WHERE id = p_delivery_id;

    RETURN QUERY SELECT p_delivery_id, v_event_id, true;
  END IF;
END;
$$;


--
-- Name: replay_webhook_dead_letter(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.replay_webhook_dead_letter(p_outbox_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_internal_user_id uuid;
  v_authorized boolean := false;
  v_brand_id uuid;
  v_status text;
BEGIN
  v_internal_user_id := public.get_user_id(auth.uid());
  IF v_internal_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  SELECT brand_id, status INTO v_brand_id, v_status
  FROM public.notification_webhook_outbox
  WHERE id = p_outbox_id;

  IF v_brand_id IS NULL THEN
    RETURN false;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.user_roles ur
    WHERE ur.user_id = v_internal_user_id
      AND ur.is_active = true
      AND ur.role IN ('admin', 'ceo')
      AND (
        ur.brand_id = v_brand_id
        OR ur.brand_id = '00000000-0000-0000-0000-000000000000'::uuid
      )
  ) INTO v_authorized;

  IF NOT v_authorized THEN
    RAISE EXCEPTION 'Insufficient privileges' USING ERRCODE = '42501';
  END IF;

  IF v_status NOT IN ('dead_letter', 'failed') THEN
    RETURN false;
  END IF;

  UPDATE public.notification_webhook_outbox
  SET status = 'pending',
      attempts = 0,
      next_retry_at = now(),
      last_error = NULL
  WHERE id = p_outbox_id;

  RETURN true;
END;
$$;


--
-- Name: resolve_lead_campaign_attribution(uuid, uuid, text, uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_lead_campaign_attribution(p_lead_event_id uuid, p_brand_id uuid, p_source_name text DEFAULT NULL::text, p_campaign_id uuid DEFAULT NULL::uuid, p_tags text[] DEFAULT '{}'::text[]) RETURNS TABLE(match_type text, campaign_id uuid, group_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_group RECORD;
  v_rules JSONB;
  v_source_match BOOLEAN;
  v_tag_match BOOLEAN;
BEGIN
  -- Priority 1: Exact match via campaign_id
  IF p_campaign_id IS NOT NULL THEN
    IF EXISTS (
      SELECT 1 FROM marketing_campaigns mc
      WHERE mc.id = p_campaign_id AND mc.brand_id = p_brand_id
    ) THEN
      RETURN QUERY SELECT 'exact'::TEXT, p_campaign_id, NULL::UUID;
      RETURN;
    END IF;
  END IF;

  -- Priority 2: Group rules, ordered by priority DESC
  FOR v_group IN
    SELECT mcg.id AS gid, mcg.match_rules, mcg.campaign_ids
    FROM marketing_campaign_groups mcg
    WHERE mcg.brand_id = p_brand_id AND mcg.is_active = true
    ORDER BY mcg.priority DESC, mcg.created_at ASC
  LOOP
    v_rules := v_group.match_rules;
    v_source_match := FALSE;
    v_tag_match := FALSE;

    IF v_rules ? 'source_names' AND jsonb_array_length(v_rules->'source_names') > 0 THEN
      IF p_source_name IS NOT NULL AND p_source_name = ANY(
        SELECT jsonb_array_elements_text(v_rules->'source_names')
      ) THEN
        v_source_match := TRUE;
      END IF;
    ELSE
      v_source_match := TRUE;
    END IF;

    IF v_rules ? 'tags' AND jsonb_array_length(v_rules->'tags') > 0 THEN
      IF p_tags IS NOT NULL AND array_length(p_tags, 1) > 0 THEN
        IF p_tags && ARRAY(SELECT jsonb_array_elements_text(v_rules->'tags')) THEN
          v_tag_match := TRUE;
        END IF;
      END IF;
    ELSE
      v_tag_match := TRUE;
    END IF;

    IF v_source_match AND v_tag_match THEN
      RETURN QUERY SELECT
        'group'::TEXT,
        CASE WHEN array_length(v_group.campaign_ids, 1) > 0
             THEN v_group.campaign_ids[1]
             ELSE NULL::UUID
        END,
        v_group.gid;
      RETURN;
    END IF;
  END LOOP;

  -- Priority 3: Unmapped
  RETURN QUERY SELECT 'unmapped'::TEXT, NULL::UUID, NULL::UUID;
  RETURN;
END;
$$;


--
-- Name: revoke_mcp_token(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_mcp_token(p_token_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
BEGIN
  v_user_id := public.get_user_id(auth.uid());
  IF v_user_id IS NULL THEN RETURN FALSE; END IF;

  UPDATE public.mcp_access_tokens
  SET revoked_at = now()
  WHERE id = p_token_id
    AND revoked_at IS NULL
    AND (
      user_id = v_user_id
      OR public.has_role(v_user_id, 'admin'::public.app_role)
    );

  RETURN FOUND;
END;
$$;


--
-- Name: rotate_outbound_webhook_secret(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rotate_outbound_webhook_secret(p_id uuid, p_new_secret text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_brand_id uuid;
BEGIN
  -- Get brand_id
  SELECT brand_id INTO v_brand_id FROM outbound_webhooks WHERE id = p_id;
  
  IF v_brand_id IS NULL THEN
    RAISE EXCEPTION 'Webhook not found';
  END IF;
  
  -- Admin check
  IF NOT has_role_for_brand(get_user_id(auth.uid()), v_brand_id, 'admin') THEN
    RAISE EXCEPTION 'Admin access required';
  END IF;
  
  -- Validate secret length
  IF length(p_new_secret) < 32 THEN
    RAISE EXCEPTION 'Secret must be at least 32 characters';
  END IF;
  
  -- Update secret
  UPDATE outbound_webhooks
  SET secret = p_new_secret, updated_at = now()
  WHERE id = p_id;
  
  RETURN p_new_secret;
END;
$$;


--
-- Name: run_audit_retention(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.run_audit_retention(p_brand_id uuid DEFAULT NULL::uuid, p_dry_run boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_policy record;
  v_cutoff timestamptz;
  v_archived integer;
  v_purged integer;
  v_results jsonb := '[]'::jsonb;
  v_brand_result jsonb;
BEGIN
  -- Only audit admins can invoke manually; cron uses service role bypass
  IF auth.uid() IS NOT NULL AND NOT public.is_audit_admin(auth.uid()) THEN
    RAISE EXCEPTION 'access denied: requires audit admin role';
  END IF;

  FOR v_policy IN
    SELECT * FROM public.audit_retention_policies
    WHERE (p_brand_id IS NULL OR brand_id = p_brand_id)
  LOOP
    v_cutoff := now() - (v_policy.retention_months || ' months')::interval;
    v_archived := 0;
    v_purged := 0;

    IF v_policy.archive_enabled AND NOT p_dry_run THEN
      WITH moved AS (
        INSERT INTO public.audit_events_archive (
          id, brand_id, entity_type, entity_id, action, actor_user_id,
          actor_type, actor_display_name, source, old_value, new_value,
          changed_fields, metadata, correlation_id, occurred_at, created_at
        )
        SELECT id, brand_id, entity_type, entity_id, action, actor_user_id,
               actor_type, actor_display_name, source, old_value, new_value,
               changed_fields, metadata, correlation_id, occurred_at, created_at
        FROM public.audit_events
        WHERE brand_id = v_policy.brand_id
          AND occurred_at < v_cutoff
        ON CONFLICT (id) DO NOTHING
        RETURNING 1
      )
      SELECT count(*) INTO v_archived FROM moved;
    ELSIF v_policy.archive_enabled AND p_dry_run THEN
      SELECT count(*) INTO v_archived
      FROM public.audit_events
      WHERE brand_id = v_policy.brand_id AND occurred_at < v_cutoff;
    END IF;

    IF NOT p_dry_run THEN
      WITH deleted AS (
        DELETE FROM public.audit_events
        WHERE brand_id = v_policy.brand_id
          AND occurred_at < v_cutoff
        RETURNING 1
      )
      SELECT count(*) INTO v_purged FROM deleted;

      UPDATE public.audit_retention_policies
      SET last_purge_at = now(),
          last_archived_count = v_archived,
          last_purged_count = v_purged
      WHERE id = v_policy.id;
    ELSE
      SELECT count(*) INTO v_purged
      FROM public.audit_events
      WHERE brand_id = v_policy.brand_id AND occurred_at < v_cutoff;
    END IF;

    v_brand_result := jsonb_build_object(
      'brand_id', v_policy.brand_id,
      'retention_months', v_policy.retention_months,
      'cutoff', v_cutoff,
      'archive_enabled', v_policy.archive_enabled,
      'archived', v_archived,
      'purged', v_purged,
      'dry_run', p_dry_run
    );
    v_results := v_results || v_brand_result;
  END LOOP;

  RETURN jsonb_build_object('executed_at', now(), 'results', v_results);
END;
$$;


--
-- Name: search_appointments(uuid, timestamp with time zone, timestamp with time zone, public.appointment_status, uuid, uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_appointments(p_brand_id uuid, p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_status public.appointment_status DEFAULT NULL::public.appointment_status, p_sales_user_id uuid DEFAULT NULL::uuid, p_contact_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result json;
  v_total bigint;
BEGIN
  SELECT COUNT(*) INTO v_total
  FROM appointments a
  WHERE a.brand_id = p_brand_id
    AND (p_date_from IS NULL OR a.scheduled_at >= p_date_from)
    AND (p_date_to IS NULL OR a.scheduled_at <= p_date_to)
    AND (p_status IS NULL OR a.status = p_status)
    AND (p_sales_user_id IS NULL OR a.assigned_sales_user_id = p_sales_user_id)
    AND (p_contact_id IS NULL OR a.contact_id = p_contact_id);

  SELECT json_build_object(
    'total', v_total,
    'limit', p_limit,
    'offset', p_offset,
    'appointments', COALESCE((
      SELECT json_agg(row_to_json(t))
      FROM (
        SELECT 
          a.id,
          a.brand_id,
          b.name AS brand_name,
          a.contact_id,
          a.deal_id,
          a.scheduled_at,
          a.duration_minutes,
          a.address,
          a.city,
          a.cap,
          a.notes,
          a.status,
          a.appointment_type,
          a.appointment_order,
          a.parent_appointment_id,
          a.assigned_sales_user_id,
          a.created_at,
          a.updated_at,
          json_build_object(
            'id', c.id,
            'first_name', c.first_name,
            'last_name', c.last_name,
            'email', c.email,
            'primary_phone', (SELECT cp.phone_raw FROM contact_phones cp WHERE cp.contact_id = c.id AND cp.is_primary LIMIT 1)
          ) AS contact,
          CASE WHEN a.assigned_sales_user_id IS NOT NULL THEN
            json_build_object(
              'id', u.id,
              'full_name', u.full_name,
              'email', u.email
            )
          ELSE NULL END AS sales_user
        FROM appointments a
        JOIN brands b ON b.id = a.brand_id
        JOIN contacts c ON c.id = a.contact_id
        LEFT JOIN users u ON u.id = a.assigned_sales_user_id
        WHERE a.brand_id = p_brand_id
          AND (p_date_from IS NULL OR a.scheduled_at >= p_date_from)
          AND (p_date_to IS NULL OR a.scheduled_at <= p_date_to)
          AND (p_status IS NULL OR a.status = p_status)
          AND (p_sales_user_id IS NULL OR a.assigned_sales_user_id = p_sales_user_id)
          AND (p_contact_id IS NULL OR a.contact_id = p_contact_id)
        ORDER BY a.scheduled_at ASC
        LIMIT p_limit
        OFFSET p_offset
      ) t
    ), '[]'::json)
  ) INTO v_result;

  RETURN v_result;
END;
$$;


--
-- Name: search_audit_events(uuid, text, text, text, uuid, timestamp with time zone, timestamp with time zone, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_audit_events(p_brand_id uuid, p_search text, p_entity_type text DEFAULT NULL::text, p_action text DEFAULT NULL::text, p_actor_user_id uuid DEFAULT NULL::uuid, p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, brand_id uuid, entity_type text, entity_id uuid, action text, actor_user_id uuid, actor_type text, actor_display_name text, source text, old_value jsonb, new_value jsonb, changed_fields text[], metadata jsonb, correlation_id text, occurred_at timestamp with time zone, created_at timestamp with time zone, total_count bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_search text;
  v_safe_limit int;
BEGIN
  IF NOT (public.user_belongs_to_brand(public.get_user_id(auth.uid()), p_brand_id)
          AND public.can_view_audit(auth.uid())) THEN
    RAISE EXCEPTION 'Not authorized to view audit events for this brand'
      USING ERRCODE = '42501';
  END IF;

  v_search := lower(trim(coalesce(p_search, '')));
  v_search := substring(v_search FROM 1 FOR 200);
  v_search := replace(replace(v_search, '%', ''), '_', '');

  v_safe_limit := least(greatest(coalesce(p_limit, 50), 1), 500);

  RETURN QUERY
  WITH filtered AS (
    SELECT ae.*
    FROM public.audit_events ae
    WHERE ae.brand_id = p_brand_id
      AND (v_search = '' OR ae.search_text ILIKE '%' || v_search || '%')
      AND (p_entity_type IS NULL OR ae.entity_type = p_entity_type)
      AND (p_action IS NULL OR ae.action = p_action)
      AND (p_actor_user_id IS NULL OR ae.actor_user_id = p_actor_user_id)
      AND (p_date_from IS NULL OR ae.occurred_at >= p_date_from)
      AND (p_date_to IS NULL OR ae.occurred_at <= p_date_to)
  ),
  counted AS (
    SELECT COUNT(*)::bigint AS total FROM filtered
  )
  SELECT
    f.id, f.brand_id, f.entity_type, f.entity_id, f.action,
    f.actor_user_id, f.actor_type, f.actor_display_name, f.source,
    f.old_value, f.new_value, f.changed_fields, f.metadata,
    f.correlation_id, f.occurred_at, f.created_at,
    c.total AS total_count
  FROM filtered f
  CROSS JOIN counted c
  ORDER BY f.occurred_at DESC
  LIMIT v_safe_limit
  OFFSET greatest(coalesce(p_offset, 0), 0);
END;
$$;


--
-- Name: search_contacts(uuid, text, uuid[], boolean, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_contacts(p_brand_id uuid DEFAULT NULL::uuid, p_query text DEFAULT NULL::text, p_tag_ids uuid[] DEFAULT NULL::uuid[], p_match_all_tags boolean DEFAULT false, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_result json;
  v_tag_count int := COALESCE(array_length(p_tag_ids, 1), 0);
  v_clean_query text;
BEGIN
  -- Authentication
  SELECT u.id INTO v_user_id FROM public.users u WHERE u.supabase_auth_id = auth.uid();
  IF v_user_id IS NULL THEN 
    RAISE EXCEPTION 'Unauthorized'; 
  END IF;
  
  -- Brand access validation
  IF p_brand_id IS NOT NULL AND NOT user_belongs_to_brand(v_user_id, p_brand_id) THEN
    RAISE EXCEPTION 'Forbidden: no access to brand';
  END IF;
  
  -- Input validation
  IF p_query IS NOT NULL AND length(p_query) > 200 THEN
    RAISE EXCEPTION 'Query too long: max 200 characters';
  END IF;
  
  p_limit := LEAST(p_limit, 500);
  p_offset := GREATEST(p_offset, 0);
  v_clean_query := NULLIF(TRIM(p_query), '');

  WITH user_brands AS (
    SELECT ur.brand_id FROM user_roles ur WHERE ur.user_id = v_user_id
  ),
  filtered AS (
    SELECT 
      c.id, c.brand_id, c.first_name, c.last_name, c.email, c.city, c.status,
      c.created_at, c.updated_at,
      (
        SELECT json_agg(json_build_object(
          'id', cp.id,
          'phone_normalized', cp.phone_normalized,
          'is_primary', cp.is_primary
        ) ORDER BY cp.is_primary DESC, cp.created_at)
        FROM contact_phones cp 
        WHERE cp.contact_id = c.id AND cp.is_active
      ) AS phones
    FROM contacts c
    JOIN contact_search_index csi ON csi.contact_id = c.id
    WHERE 
      -- Brand filter: multi-brand or single brand
      (
        (p_brand_id IS NULL AND csi.brand_id IN (SELECT brand_id FROM user_brands))
        OR (p_brand_id IS NOT NULL AND c.brand_id = p_brand_id)
      )
      -- Full-text search using the index
      AND (
        v_clean_query IS NULL
        OR csi.search_text ILIKE '%' || v_clean_query || '%'
      )
      -- Tag filter
      AND (
        v_tag_count = 0 
        OR (
          p_match_all_tags = FALSE AND EXISTS (
            SELECT 1 FROM tag_assignments ta 
            WHERE ta.contact_id = c.id AND ta.tag_id = ANY(p_tag_ids)
          )
        )
        OR (
          p_match_all_tags = TRUE AND (
            SELECT COUNT(DISTINCT ta.tag_id) 
            FROM tag_assignments ta 
            WHERE ta.contact_id = c.id AND ta.tag_id = ANY(p_tag_ids)
          ) = v_tag_count
        )
      )
    ORDER BY c.updated_at DESC
    LIMIT p_limit OFFSET p_offset
  ),
  total_count AS (
    SELECT COUNT(*) as cnt
    FROM contacts c
    JOIN contact_search_index csi ON csi.contact_id = c.id
    WHERE 
      (
        (p_brand_id IS NULL AND csi.brand_id IN (SELECT brand_id FROM user_brands))
        OR (p_brand_id IS NOT NULL AND c.brand_id = p_brand_id)
      )
      AND (
        v_clean_query IS NULL
        OR csi.search_text ILIKE '%' || v_clean_query || '%'
      )
      AND (
        v_tag_count = 0 
        OR (
          p_match_all_tags = FALSE AND EXISTS (
            SELECT 1 FROM tag_assignments ta 
            WHERE ta.contact_id = c.id AND ta.tag_id = ANY(p_tag_ids)
          )
        )
        OR (
          p_match_all_tags = TRUE AND (
            SELECT COUNT(DISTINCT ta.tag_id) 
            FROM tag_assignments ta 
            WHERE ta.contact_id = c.id AND ta.tag_id = ANY(p_tag_ids)
          ) = v_tag_count
        )
      )
  )
  SELECT json_build_object(
    'contacts', COALESCE((SELECT json_agg(row_to_json(filtered)) FROM filtered), '[]'::json),
    'total', (SELECT cnt FROM total_count),
    'limit', p_limit,
    'offset', p_offset
  ) INTO v_result;
  
  RETURN v_result;
END;
$$;


--
-- Name: search_deals(uuid, text, uuid[], uuid[], boolean, timestamp with time zone, timestamp with time zone, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_deals(p_brand_id uuid, p_status text DEFAULT 'open'::text, p_stage_ids uuid[] DEFAULT NULL::uuid[], p_tag_ids uuid[] DEFAULT NULL::uuid[], p_match_all_tags boolean DEFAULT false, p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 500, p_offset integer DEFAULT 0) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result JSON;
  v_tag_count INTEGER;
BEGIN
  v_tag_count := COALESCE(array_length(p_tag_ids, 1), 0);
  
  WITH filtered_deals AS (
    SELECT 
      d.id,
      d.brand_id,
      d.contact_id,
      d.current_stage_id,
      d.status,
      d.value,
      d.notes,
      d.created_at,
      d.updated_at,
      d.closed_at,
      -- Contact snapshot
      jsonb_build_object(
        'id', c.id,
        'first_name', c.first_name,
        'last_name', c.last_name,
        'email', c.email
      ) AS contact,
      -- Tags for this deal
      COALESCE(
        (
          SELECT jsonb_agg(
            jsonb_build_object(
              'id', t.id,
              'name', t.name,
              'color', t.color
            )
          )
          FROM tag_assignments ta
          JOIN tags t ON t.id = ta.tag_id
          WHERE ta.deal_id = d.id
        ),
        '[]'::jsonb
      ) AS tags
    FROM deals d
    LEFT JOIN contacts c ON c.id = d.contact_id
    WHERE d.brand_id = p_brand_id
      -- Status filter
      AND (p_status IS NULL OR d.status::text = p_status)
      -- Stage filter
      AND (p_stage_ids IS NULL OR array_length(p_stage_ids, 1) IS NULL OR d.current_stage_id = ANY(p_stage_ids))
      -- Date filters
      AND (p_date_from IS NULL OR d.created_at >= p_date_from)
      AND (p_date_to IS NULL OR d.created_at <= p_date_to)
      -- Tag filter
      AND (
        v_tag_count = 0 
        OR (
          p_match_all_tags = FALSE AND EXISTS (
            SELECT 1 FROM tag_assignments ta
            WHERE ta.deal_id = d.id AND ta.tag_id = ANY(p_tag_ids)
          )
        )
        OR (
          p_match_all_tags = TRUE AND (
            SELECT COUNT(DISTINCT ta.tag_id) 
            FROM tag_assignments ta
            WHERE ta.deal_id = d.id AND ta.tag_id = ANY(p_tag_ids)
          ) = v_tag_count
        )
      )
    ORDER BY d.updated_at DESC
  ),
  counted AS (
    SELECT COUNT(*) as total FROM filtered_deals
  ),
  paginated AS (
    SELECT * FROM filtered_deals
    LIMIT p_limit OFFSET p_offset
  )
  SELECT 
    jsonb_build_object(
      'total', (SELECT total FROM counted),
      'limit', p_limit,
      'offset', p_offset,
      'deals', COALESCE((SELECT jsonb_agg(row_to_json(p.*)) FROM paginated p), '[]'::jsonb)
    )::json
  INTO v_result;
  
  RETURN v_result;
END;
$$;


--
-- Name: search_lead_events(uuid, timestamp with time zone, timestamp with time zone, text, text, boolean, uuid[], boolean, integer, integer, uuid[], boolean, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_lead_events(p_brand_id uuid, p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_source text DEFAULT NULL::text, p_source_name text DEFAULT NULL::text, p_include_archived boolean DEFAULT false, p_tag_ids uuid[] DEFAULT NULL::uuid[], p_match_all_tags boolean DEFAULT false, p_priority_min integer DEFAULT NULL::integer, p_priority_max integer DEFAULT NULL::integer, p_clinical_topic_ids uuid[] DEFAULT NULL::uuid[], p_match_all_topics boolean DEFAULT false, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_user_role app_role;
  v_result json;
  v_tag_count int := COALESCE(array_length(p_tag_ids, 1), 0);
  v_topic_count int := COALESCE(array_length(p_clinical_topic_ids, 1), 0);
  v_is_system_brand boolean;
  v_accessible_brand_ids uuid[];
BEGIN
  -- Resolve app user from auth
  SELECT u.id INTO v_user_id
  FROM public.users u
  WHERE u.supabase_auth_id = auth.uid();

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  -- Check if this is the system brand (for cross-brand aggregation)
  SELECT (p_brand_id = '00000000-0000-0000-0000-000000000000' OR b.is_system = TRUE)
  INTO v_is_system_brand
  FROM public.brands b
  WHERE b.id = p_brand_id;

  -- Brand access check
  IF NOT user_belongs_to_brand(v_user_id, p_brand_id) THEN
    RAISE EXCEPTION 'Forbidden: no access to brand';
  END IF;

  -- For system brand, get all accessible brand IDs (excluding system brand itself)
  IF v_is_system_brand THEN
    SELECT array_agg(ur.brand_id)
    INTO v_accessible_brand_ids
    FROM public.user_roles ur
    JOIN public.brands b ON b.id = ur.brand_id
    WHERE ur.user_id = v_user_id
      AND ur.is_active = TRUE
      AND b.is_system IS NOT TRUE
      AND b.id != '00000000-0000-0000-0000-000000000000';
  ELSE
    v_accessible_brand_ids := ARRAY[p_brand_id];
  END IF;

  -- Role check for include_archived (must be admin/ceo in at least one brand)
  IF p_include_archived = TRUE THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.user_roles ur
      WHERE ur.user_id = v_user_id
        AND ur.brand_id = ANY(v_accessible_brand_ids)
        AND ur.role IN ('admin', 'ceo')
    ) THEN
      RAISE EXCEPTION 'Forbidden: include_archived requires admin/ceo';
    END IF;
  END IF;

  -- Main query with all filters
  WITH filtered_events AS (
    SELECT
      le.id,
      le.brand_id,
      le.contact_id,
      le.deal_id,
      le.source,
      le.source_name,
      le.occurred_at,
      le.received_at,
      le.ai_priority,
      le.ai_confidence,
      le.ai_rationale,
      le.lead_type,
      le.archived,
      le.raw_payload,
      le.created_at,
      le.lead_source_channel,
      le.contact_channel,
      le.pacemaker_status,
      le.customer_sentiment,
      le.decision_status,
      le.objection_type,
      le.booking_notes,
      le.logistics_notes,
      le.ai_conversation_summary
    FROM public.lead_events le
    WHERE le.brand_id = ANY(v_accessible_brand_ids)
      -- Archived filter
      AND (p_include_archived = TRUE OR le.archived = FALSE)
      -- Date filters
      AND (p_date_from IS NULL OR le.received_at >= p_date_from)
      AND (p_date_to IS NULL OR le.received_at <= p_date_to)
      -- Source filters
      AND (p_source IS NULL OR le.source::text = p_source)
      AND (p_source_name IS NULL OR le.source_name ILIKE '%' || p_source_name || '%')
      -- Priority filters
      AND (p_priority_min IS NULL OR le.ai_priority >= p_priority_min)
      AND (p_priority_max IS NULL OR le.ai_priority <= p_priority_max)
      -- Tag filter (ANY mode)
      AND (
        v_tag_count = 0
        OR (
          p_match_all_tags = FALSE
          AND EXISTS (
            SELECT 1 FROM public.tag_assignments ta
            WHERE ta.lead_event_id = le.id
              AND ta.tag_id = ANY(p_tag_ids)
          )
        )
        OR (
          p_match_all_tags = TRUE
          AND (
            SELECT COUNT(DISTINCT ta.tag_id)
            FROM public.tag_assignments ta
            WHERE ta.lead_event_id = le.id
              AND ta.tag_id = ANY(p_tag_ids)
          ) = v_tag_count
        )
      )
      -- Clinical topics filter
      AND (
        v_topic_count = 0
        OR (
          p_match_all_topics = FALSE
          AND EXISTS (
            SELECT 1 FROM public.lead_event_clinical_topics lect
            WHERE lect.lead_event_id = le.id
              AND lect.topic_id = ANY(p_clinical_topic_ids)
          )
        )
        OR (
          p_match_all_topics = TRUE
          AND (
            SELECT COUNT(DISTINCT lect.topic_id)
            FROM public.lead_event_clinical_topics lect
            WHERE lect.lead_event_id = le.id
              AND lect.topic_id = ANY(p_clinical_topic_ids)
          ) = v_topic_count
        )
      )
  ),
  counted AS (
    SELECT COUNT(*) AS total FROM filtered_events
  ),
  paginated AS (
    SELECT fe.*
    FROM filtered_events fe
    ORDER BY fe.received_at DESC
    LIMIT p_limit OFFSET p_offset
  ),
  with_relations AS (
    SELECT
      p.id,
      p.brand_id,
      p.contact_id,
      p.deal_id,
      p.source,
      p.source_name,
      p.occurred_at,
      p.received_at,
      p.ai_priority,
      p.ai_confidence,
      p.ai_rationale,
      p.lead_type,
      p.archived,
      p.raw_payload,
      p.created_at,
      p.lead_source_channel,
      p.contact_channel,
      p.pacemaker_status,
      p.customer_sentiment,
      p.decision_status,
      p.objection_type,
      p.booking_notes,
      p.logistics_notes,
      p.ai_conversation_summary,
      -- Contact snapshot
      jsonb_build_object(
        'id', c.id,
        'first_name', c.first_name,
        'last_name', c.last_name,
        'email', c.email,
        'status', c.status,
        'primary_phone', (
          SELECT cp.phone_normalized
          FROM public.contact_phones cp
          WHERE cp.contact_id = c.id AND cp.is_primary = TRUE
          LIMIT 1
        )
      ) AS contact,
      -- Tags array
      COALESCE(
        (
          SELECT jsonb_agg(
            jsonb_build_object(
              'id', t.id,
              'name', t.name,
              'color', t.color,
              'scope', t.scope
            )
          )
          FROM public.tag_assignments ta
          JOIN public.tags t ON t.id = ta.tag_id
          WHERE ta.lead_event_id = p.id
        ),
        '[]'::jsonb
      ) AS tags,
      -- Clinical topics array
      COALESCE(
        (
          SELECT jsonb_agg(
            jsonb_build_object(
              'id', ct.id,
              'canonical_name', ct.canonical_name,
              'slug', ct.slug
            )
          )
          FROM public.lead_event_clinical_topics lect
          JOIN public.clinical_topics ct ON ct.id = lect.topic_id
          WHERE lect.lead_event_id = p.id
        ),
        '[]'::jsonb
      ) AS clinical_topics
    FROM paginated p
    LEFT JOIN public.contacts c ON c.id = p.contact_id
  )
  SELECT json_build_object(
    'total', (SELECT total FROM counted),
    'limit', p_limit,
    'offset', p_offset,
    'events', COALESCE(
      (SELECT json_agg(row_to_json(wr)) FROM with_relations wr),
      '[]'::json
    )
  ) INTO v_result;

  RETURN v_result;
END;
$$;


--
-- Name: search_tickets_v1(uuid, text, uuid, text, uuid[], text, text[], jsonb, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_tickets_v1(p_brand_id uuid, p_queue_tab text DEFAULT 'all'::text, p_current_user_id uuid DEFAULT NULL::uuid, p_search_query text DEFAULT NULL::text, p_tag_ids uuid[] DEFAULT NULL::uuid[], p_assignment_type text DEFAULT 'all'::text, p_statuses text[] DEFAULT NULL::text[], p_sla_thresholds jsonb DEFAULT NULL::jsonb, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result json;
  v_total_count integer;
  v_active_statuses text[] := ARRAY['open', 'in_progress', 'reopened'];
BEGIN
  -- Build the result with tickets and metadata
  WITH filtered_tickets AS (
    SELECT 
      t.id,
      t.brand_id,
      t.contact_id,
      t.deal_id,
      t.status,
      t.priority,
      t.title,
      t.description,
      t.category_tag_id,
      t.assigned_to_user_id,
      t.assigned_by_user_id,
      t.assigned_at,
      t.created_by,
      t.source_event_id,
      t.opened_at,
      t.resolved_at,
      t.closed_at,
      t.created_at,
      t.updated_at,
      -- Calculate age in minutes for SLA check
      EXTRACT(EPOCH FROM (now() - t.opened_at)) / 60 AS age_minutes
    FROM tickets t
    WHERE t.brand_id = p_brand_id
      -- Queue tab filtering
      AND (
        CASE p_queue_tab
          WHEN 'my_queue' THEN 
            t.assigned_to_user_id = p_current_user_id 
            AND t.status::text = ANY(v_active_statuses)
          WHEN 'unassigned' THEN 
            t.assigned_to_user_id IS NULL 
            AND t.status::text = ANY(v_active_statuses)
          WHEN 'sla_breached' THEN 
            t.status::text = ANY(v_active_statuses)
            AND p_sla_thresholds IS NOT NULL
            AND (
              EXTRACT(EPOCH FROM (now() - t.opened_at)) / 60 > 
              COALESCE((p_sla_thresholds->>t.priority::text)::numeric, 1440)
            )
          ELSE true -- 'all'
        END
      )
      -- Status filter (optional)
      AND (p_statuses IS NULL OR t.status::text = ANY(p_statuses))
      -- Tag/Category filter
      AND (p_tag_ids IS NULL OR array_length(p_tag_ids, 1) IS NULL OR t.category_tag_id = ANY(p_tag_ids))
      -- Assignment type filter
      AND (
        CASE p_assignment_type
          WHEN 'auto' THEN t.assigned_at IS NOT NULL AND t.assigned_by_user_id IS NULL
          WHEN 'manual' THEN t.assigned_by_user_id IS NOT NULL
          ELSE true -- 'all'
        END
      )
      -- Search query (contact name, email, phone, ticket title/description)
      AND (
        p_search_query IS NULL 
        OR p_search_query = ''
        OR EXISTS (
          SELECT 1 FROM contacts c
          WHERE c.id = t.contact_id
          AND (
            c.first_name ILIKE '%' || p_search_query || '%'
            OR c.last_name ILIKE '%' || p_search_query || '%'
            OR (c.first_name || ' ' || c.last_name) ILIKE '%' || p_search_query || '%'
            OR c.email ILIKE '%' || p_search_query || '%'
          )
        )
        OR EXISTS (
          SELECT 1 FROM contact_phones cp
          WHERE cp.contact_id = t.contact_id
          AND cp.phone_normalized LIKE regexp_replace(p_search_query, '[^0-9]', '', 'g') || '%'
        )
        OR t.title ILIKE '%' || p_search_query || '%'
        OR t.description ILIKE '%' || p_search_query || '%'
      )
  ),
  counted AS (
    SELECT COUNT(*) AS total FROM filtered_tickets
  ),
  paginated AS (
    SELECT ft.*
    FROM filtered_tickets ft
    -- Smart sorting: Priority ASC (P1 first), then oldest first (aging)
    ORDER BY ft.priority ASC, ft.opened_at ASC
    LIMIT p_limit
    OFFSET p_offset
  ),
  with_relations AS (
    SELECT 
      p.*,
      -- Contact data
      json_build_object(
        'id', c.id,
        'first_name', c.first_name,
        'last_name', c.last_name,
        'email', c.email,
        'contact_phones', COALESCE(
          (SELECT json_agg(json_build_object('phone_raw', cp.phone_raw, 'is_primary', cp.is_primary))
           FROM contact_phones cp WHERE cp.contact_id = c.id AND cp.is_active = true),
          '[]'::json
        )
      ) AS contacts,
      -- Category tag data
      CASE WHEN tg.id IS NOT NULL THEN
        json_build_object('id', tg.id, 'name', tg.name, 'color', tg.color)
      ELSE NULL END AS tags,
      -- Assigned user data
      CASE WHEN u.id IS NOT NULL THEN
        json_build_object('id', u.id, 'full_name', u.full_name, 'email', u.email)
      ELSE NULL END AS users,
      -- Assigned by user data
      CASE WHEN ab.id IS NOT NULL THEN
        json_build_object('id', ab.id, 'full_name', ab.full_name, 'email', ab.email)
      ELSE NULL END AS assigned_by
    FROM paginated p
    LEFT JOIN contacts c ON c.id = p.contact_id
    LEFT JOIN tags tg ON tg.id = p.category_tag_id
    LEFT JOIN users u ON u.id = p.assigned_to_user_id
    LEFT JOIN users ab ON ab.id = p.assigned_by_user_id
    ORDER BY p.priority ASC, p.opened_at ASC
  )
  SELECT json_build_object(
    'tickets', COALESCE((SELECT json_agg(row_to_json(wr)) FROM with_relations wr), '[]'::json),
    'total_count', (SELECT total FROM counted),
    'limit', p_limit,
    'offset', p_offset,
    'has_more', (SELECT total FROM counted) > (p_offset + p_limit)
  ) INTO v_result;
  
  RETURN v_result;
END;
$$;


--
-- Name: search_tickets_v2(uuid, text, uuid, text, uuid[], text, text[], jsonb, integer, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_tickets_v2(p_brand_id uuid, p_queue_tab text DEFAULT 'all'::text, p_current_user_id uuid DEFAULT NULL::uuid, p_search_query text DEFAULT NULL::text, p_tag_ids uuid[] DEFAULT NULL::uuid[], p_assignment_type text DEFAULT 'all'::text, p_statuses text[] DEFAULT NULL::text[], p_sla_thresholds jsonb DEFAULT NULL::jsonb, p_limit integer DEFAULT 50, p_cursor jsonb DEFAULT NULL::jsonb, p_direction text DEFAULT 'next'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_limit int := GREATEST(1, LEAST(COALESCE(p_limit, 50), 200));
  v_dir text := COALESCE(p_direction, 'next');
  v_cursor_priority int;
  v_cursor_opened_at timestamptz;
  v_cursor_id uuid;
  v_active_statuses text[] := ARRAY['open', 'in_progress', 'reopened'];
  v_total_count int := 0;
  v_has_next boolean := false;
  v_has_prev boolean := false;
  v_next_cursor jsonb := null;
  v_prev_cursor jsonb := null;
  v_rows jsonb := '[]'::jsonb;
  v_first_cursor jsonb := null;
  v_last_cursor jsonb := null;
  v_ordered_count int := 0;
BEGIN
  -- Parse cursor if present
  IF p_cursor IS NOT NULL THEN
    v_cursor_priority := (p_cursor->>'priority')::int;
    v_cursor_opened_at := (p_cursor->>'opened_at')::timestamptz;
    v_cursor_id := (p_cursor->>'id')::uuid;
  END IF;

  -- Get total count and paginated results
  WITH base AS (
    SELECT 
      t.id,
      t.brand_id,
      t.contact_id,
      t.deal_id,
      t.status,
      t.priority,
      t.title,
      t.description,
      t.category_tag_id,
      t.assigned_to_user_id,
      t.assigned_by_user_id,
      t.assigned_at,
      t.created_by,
      t.source_event_id,
      t.opened_at,
      t.resolved_at,
      t.closed_at,
      t.created_at,
      t.updated_at,
      t.sla_breached_at  -- Added sla_breached_at
    FROM tickets t
    WHERE t.brand_id = p_brand_id
      -- Queue tab filtering
      AND (
        CASE p_queue_tab
          WHEN 'my_queue' THEN 
            t.assigned_to_user_id = p_current_user_id 
            AND t.status::text = ANY(v_active_statuses)
          WHEN 'unassigned' THEN 
            t.assigned_to_user_id IS NULL 
            AND t.status::text = ANY(v_active_statuses)
          WHEN 'sla_breached' THEN 
            t.status::text = ANY(v_active_statuses)
            AND p_sla_thresholds IS NOT NULL
            AND (
              EXTRACT(EPOCH FROM (now() - t.opened_at)) / 60 > 
              COALESCE((p_sla_thresholds->>t.priority::text)::numeric, 1440)
            )
          ELSE true -- 'all'
        END
      )
      -- Status filter (optional)
      AND (p_statuses IS NULL OR t.status::text = ANY(p_statuses))
      -- Tag/Category filter
      AND (p_tag_ids IS NULL OR array_length(p_tag_ids, 1) IS NULL OR t.category_tag_id = ANY(p_tag_ids))
      -- Assignment type filter
      AND (
        CASE p_assignment_type
          WHEN 'auto' THEN t.assigned_at IS NOT NULL AND t.assigned_by_user_id IS NULL
          WHEN 'manual' THEN t.assigned_by_user_id IS NOT NULL
          ELSE true -- 'all'
        END
      )
      -- Search query (contact name, email, phone, ticket title/description)
      AND (
        p_search_query IS NULL 
        OR p_search_query = ''
        OR EXISTS (
          SELECT 1 FROM contacts c
          WHERE c.id = t.contact_id
          AND (
            c.first_name ILIKE '%' || p_search_query || '%'
            OR c.last_name ILIKE '%' || p_search_query || '%'
            OR (c.first_name || ' ' || c.last_name) ILIKE '%' || p_search_query || '%'
            OR c.email ILIKE '%' || p_search_query || '%'
          )
        )
        OR EXISTS (
          SELECT 1 FROM contact_phones cp
          WHERE cp.contact_id = t.contact_id
          AND cp.phone_normalized LIKE regexp_replace(p_search_query, '[^0-9]', '', 'g') || '%'
        )
        OR t.title ILIKE '%' || p_search_query || '%'
        OR t.description ILIKE '%' || p_search_query || '%'
      )
  ),
  total AS (
    SELECT COUNT(*)::int AS c FROM base
  ),
  -- Apply cursor windowing
  windowed AS (
    SELECT *
    FROM base b
    WHERE
      -- If no cursor, don't filter
      (p_cursor IS NULL)
      OR
      (
        -- NEXT: greater than cursor (priority ASC, opened_at ASC, id ASC)
        v_dir = 'next' AND (
          (b.priority > v_cursor_priority)
          OR (b.priority = v_cursor_priority AND b.opened_at > v_cursor_opened_at)
          OR (b.priority = v_cursor_priority AND b.opened_at = v_cursor_opened_at AND b.id > v_cursor_id)
        )
      )
      OR
      (
        -- PREV: less than cursor (priority ASC, opened_at ASC, id ASC)
        v_dir = 'prev' AND (
          (b.priority < v_cursor_priority)
          OR (b.priority = v_cursor_priority AND b.opened_at < v_cursor_opened_at)
          OR (b.priority = v_cursor_priority AND b.opened_at = v_cursor_opened_at AND b.id < v_cursor_id)
        )
      )
  ),
  -- Order depending on direction (fetch limit+1 to detect has_more)
  ordered AS (
    SELECT *
    FROM windowed
    ORDER BY
      CASE WHEN v_dir = 'prev' THEN priority END DESC,
      CASE WHEN v_dir = 'prev' THEN opened_at END DESC,
      CASE WHEN v_dir = 'prev' THEN id END DESC,
      CASE WHEN v_dir <> 'prev' THEN priority END ASC,
      CASE WHEN v_dir <> 'prev' THEN opened_at END ASC,
      CASE WHEN v_dir <> 'prev' THEN id END ASC
    LIMIT v_limit + 1
  ),
  -- Trim to actual limit
  trimmed AS (
    SELECT * FROM ordered LIMIT v_limit
  ),
  -- Always return in canonical order (priority ASC, opened_at ASC, id ASC)
  final_rows AS (
    SELECT * FROM trimmed
    ORDER BY priority ASC, opened_at ASC, id ASC
  ),
  -- Build relations for each ticket
  with_relations AS (
    SELECT 
      fr.*,
      -- Contact data
      json_build_object(
        'id', c.id,
        'first_name', c.first_name,
        'last_name', c.last_name,
        'email', c.email,
        'contact_phones', COALESCE(
          (SELECT json_agg(json_build_object('phone_raw', cp.phone_raw, 'is_primary', cp.is_primary))
           FROM contact_phones cp WHERE cp.contact_id = c.id AND cp.is_active = true),
          '[]'::json
        )
      ) AS contacts,
      -- Category tag data
      CASE WHEN tg.id IS NOT NULL THEN
        json_build_object('id', tg.id, 'name', tg.name, 'color', tg.color)
      ELSE NULL END AS tags,
      -- Assigned user data
      CASE WHEN u.id IS NOT NULL THEN
        json_build_object('id', u.id, 'full_name', u.full_name, 'email', u.email)
      ELSE NULL END AS users,
      -- Assigned by user data
      CASE WHEN ab.id IS NOT NULL THEN
        json_build_object('id', ab.id, 'full_name', ab.full_name, 'email', ab.email)
      ELSE NULL END AS assigned_by
    FROM final_rows fr
    LEFT JOIN contacts c ON c.id = fr.contact_id
    LEFT JOIN tags tg ON tg.id = fr.category_tag_id
    LEFT JOIN users u ON u.id = fr.assigned_to_user_id
    LEFT JOIN users ab ON ab.id = fr.assigned_by_user_id
    ORDER BY fr.priority ASC, fr.opened_at ASC, fr.id ASC
  )
  SELECT
    (SELECT c FROM total),
    (SELECT COUNT(*) FROM ordered),
    (SELECT jsonb_agg(row_to_json(wr)) FROM with_relations wr),
    (SELECT jsonb_build_object('priority', priority, 'opened_at', opened_at, 'id', id)
     FROM final_rows ORDER BY priority ASC, opened_at ASC, id ASC LIMIT 1),
    (SELECT jsonb_build_object('priority', priority, 'opened_at', opened_at, 'id', id)
     FROM final_rows ORDER BY priority DESC, opened_at DESC, id DESC LIMIT 1)
  INTO
    v_total_count,
    v_ordered_count,
    v_rows,
    v_first_cursor,
    v_last_cursor;

  -- Determine has_next: if we fetched more than limit, there are more records
  v_has_next := v_ordered_count > v_limit;
  
  -- Set cursors for navigation
  v_next_cursor := v_last_cursor;
  v_prev_cursor := v_first_cursor;

  -- Determine has_prev: check if any records exist before the first cursor
  IF v_first_cursor IS NOT NULL AND (p_cursor IS NOT NULL OR v_dir = 'prev') THEN
    PERFORM 1
    FROM tickets t
    WHERE t.brand_id = p_brand_id
      -- Same base filters
      AND (
        CASE p_queue_tab
          WHEN 'my_queue' THEN 
            t.assigned_to_user_id = p_current_user_id 
            AND t.status::text = ANY(v_active_statuses)
          WHEN 'unassigned' THEN 
            t.assigned_to_user_id IS NULL 
            AND t.status::text = ANY(v_active_statuses)
          WHEN 'sla_breached' THEN 
            t.status::text = ANY(v_active_statuses)
            AND p_sla_thresholds IS NOT NULL
            AND (
              EXTRACT(EPOCH FROM (now() - t.opened_at)) / 60 > 
              COALESCE((p_sla_thresholds->>t.priority::text)::numeric, 1440)
            )
          ELSE true
        END
      )
      AND (p_statuses IS NULL OR t.status::text = ANY(p_statuses))
      AND (p_tag_ids IS NULL OR array_length(p_tag_ids, 1) IS NULL OR t.category_tag_id = ANY(p_tag_ids))
      AND (
        CASE p_assignment_type
          WHEN 'auto' THEN t.assigned_at IS NOT NULL AND t.assigned_by_user_id IS NULL
          WHEN 'manual' THEN t.assigned_by_user_id IS NOT NULL
          ELSE true
        END
      )
      AND (
        p_search_query IS NULL 
        OR p_search_query = ''
        OR EXISTS (
          SELECT 1 FROM contacts c
          WHERE c.id = t.contact_id
          AND (
            c.first_name ILIKE '%' || p_search_query || '%'
            OR c.last_name ILIKE '%' || p_search_query || '%'
            OR (c.first_name || ' ' || c.last_name) ILIKE '%' || p_search_query || '%'
            OR c.email ILIKE '%' || p_search_query || '%'
          )
        )
        OR EXISTS (
          SELECT 1 FROM contact_phones cp
          WHERE cp.contact_id = t.contact_id
          AND cp.phone_normalized LIKE regexp_replace(p_search_query, '[^0-9]', '', 'g') || '%'
        )
        OR t.title ILIKE '%' || p_search_query || '%'
        OR t.description ILIKE '%' || p_search_query || '%'
      )
      -- Records before first cursor
      AND (
        (t.priority < (v_first_cursor->>'priority')::int)
        OR (t.priority = (v_first_cursor->>'priority')::int AND t.opened_at < (v_first_cursor->>'opened_at')::timestamptz)
        OR (t.priority = (v_first_cursor->>'priority')::int AND t.opened_at = (v_first_cursor->>'opened_at')::timestamptz AND t.id < (v_first_cursor->>'id')::uuid)
      )
    LIMIT 1;
    v_has_prev := FOUND;
  ELSE
    v_has_prev := false;
  END IF;

  RETURN jsonb_build_object(
    'tickets', COALESCE(v_rows, '[]'::jsonb),
    'total_count', v_total_count,
    'limit', v_limit,
    'has_next', COALESCE(v_has_next, false),
    'has_prev', COALESCE(v_has_prev, false),
    'next_cursor', v_next_cursor,
    'prev_cursor', v_prev_cursor
  );
END;
$$;


--
-- Name: search_tickets_v2(uuid, uuid[], text, uuid, text, uuid[], text, text[], text, integer, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_tickets_v2(p_brand_id uuid DEFAULT NULL::uuid, p_brand_ids uuid[] DEFAULT NULL::uuid[], p_queue_tab text DEFAULT 'all'::text, p_current_user_id uuid DEFAULT NULL::uuid, p_search_query text DEFAULT NULL::text, p_tag_ids uuid[] DEFAULT NULL::uuid[], p_assignment_type text DEFAULT 'all'::text, p_statuses text[] DEFAULT NULL::text[], p_sla_thresholds text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_cursor jsonb DEFAULT NULL::jsonb, p_direction text DEFAULT 'next'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tickets JSONB;
  v_total_count INT;
  v_result JSONB;
  v_sla JSONB;
  v_active_statuses ticket_status[] := ARRAY['open'::ticket_status, 'in_progress'::ticket_status, 'reopened'::ticket_status];
  v_effective_brand_ids UUID[];
BEGIN
  -- Determine effective brand IDs
  IF p_brand_ids IS NOT NULL AND array_length(p_brand_ids, 1) > 0 THEN
    v_effective_brand_ids := p_brand_ids;
  ELSIF p_brand_id IS NOT NULL THEN
    v_effective_brand_ids := ARRAY[p_brand_id];
  ELSE
    RETURN jsonb_build_object(
      'tickets', '[]'::jsonb,
      'total_count', 0,
      'limit', p_limit,
      'has_next', false,
      'has_prev', false,
      'next_cursor', null,
      'prev_cursor', null
    );
  END IF;

  -- Parse SLA thresholds
  IF p_sla_thresholds IS NOT NULL THEN
    v_sla := p_sla_thresholds::jsonb;
  ELSE
    v_sla := '{"1": 30, "2": 60, "3": 240, "4": 480, "5": 1440}'::jsonb;
  END IF;

  -- Build main query with filters
  WITH filtered_tickets AS (
    SELECT t.*
    FROM tickets t
    WHERE t.brand_id = ANY(v_effective_brand_ids)
      AND t.archived = false
      -- Queue tab filters
      AND (
        p_queue_tab = 'all'
        OR (p_queue_tab = 'my_queue' AND t.assigned_to_user_id = p_current_user_id AND t.status = ANY(v_active_statuses))
        OR (p_queue_tab = 'unassigned' AND t.assigned_to_user_id IS NULL AND t.status = ANY(v_active_statuses))
        OR (p_queue_tab = 'sla_breached' AND t.status = ANY(v_active_statuses) AND
            EXTRACT(EPOCH FROM (now() - t.opened_at)) / 60 > 
            COALESCE((v_sla->>t.priority::text)::int, 240))
      )
      -- Search filter
      AND (
        p_search_query IS NULL 
        OR t.title ILIKE '%' || p_search_query || '%'
        OR t.description ILIKE '%' || p_search_query || '%'
        OR EXISTS (
          SELECT 1 FROM contacts c 
          WHERE c.id = t.contact_id 
          AND (
            c.first_name ILIKE '%' || p_search_query || '%'
            OR c.last_name ILIKE '%' || p_search_query || '%'
            OR c.email ILIKE '%' || p_search_query || '%'
          )
        )
      )
      -- Tag filter
      AND (p_tag_ids IS NULL OR t.category_tag_id = ANY(p_tag_ids))
      -- Assignment type filter
      AND (
        p_assignment_type = 'all'
        OR (p_assignment_type = 'auto' AND t.assigned_by_user_id IS NULL AND t.assigned_to_user_id IS NOT NULL)
        OR (p_assignment_type = 'manual' AND t.assigned_by_user_id IS NOT NULL)
      )
      -- Status filter
      AND (p_statuses IS NULL OR t.status = ANY(ARRAY(SELECT unnest(p_statuses)::ticket_status)))
  ),
  counted AS (
    SELECT COUNT(*) as cnt FROM filtered_tickets
  ),
  paginated AS (
    SELECT ft.*
    FROM filtered_tickets ft
    WHERE (
      p_cursor IS NULL
      OR (
        p_direction = 'next' AND (
          ft.priority > (p_cursor->>'priority')::int
          OR (ft.priority = (p_cursor->>'priority')::int AND ft.opened_at > (p_cursor->>'opened_at')::timestamptz)
          OR (ft.priority = (p_cursor->>'priority')::int AND ft.opened_at = (p_cursor->>'opened_at')::timestamptz AND ft.id > (p_cursor->>'id')::uuid)
        )
      )
      OR (
        p_direction = 'prev' AND (
          ft.priority < (p_cursor->>'priority')::int
          OR (ft.priority = (p_cursor->>'priority')::int AND ft.opened_at < (p_cursor->>'opened_at')::timestamptz)
          OR (ft.priority = (p_cursor->>'priority')::int AND ft.opened_at = (p_cursor->>'opened_at')::timestamptz AND ft.id < (p_cursor->>'id')::uuid)
        )
      )
    )
    ORDER BY 
      CASE WHEN p_direction = 'prev' THEN ft.priority END DESC,
      CASE WHEN p_direction = 'prev' THEN ft.opened_at END DESC,
      CASE WHEN p_direction = 'prev' THEN ft.id END DESC,
      CASE WHEN p_direction = 'next' OR p_direction IS NULL THEN ft.priority END ASC,
      CASE WHEN p_direction = 'next' OR p_direction IS NULL THEN ft.opened_at END ASC,
      CASE WHEN p_direction = 'next' OR p_direction IS NULL THEN ft.id END ASC
    LIMIT p_limit + 1
  ),
  with_relations AS (
    SELECT 
      p.id, p.brand_id, p.contact_id, p.deal_id, p.status, p.priority,
      p.title, p.description, p.category_tag_id, p.assigned_to_user_id,
      p.assigned_by_user_id, p.assigned_at, p.created_by, p.source_event_id,
      p.opened_at, p.resolved_at, p.closed_at, p.sla_breached_at,
      p.created_at, p.updated_at, p.archived, p.archived_at, p.archived_by_user_id,
      jsonb_build_object(
        'id', c.id,
        'first_name', c.first_name,
        'last_name', c.last_name,
        'email', c.email,
        'contact_phones', COALESCE((
          SELECT jsonb_agg(jsonb_build_object('phone_raw', cp.phone_raw, 'is_primary', cp.is_primary))
          FROM contact_phones cp WHERE cp.contact_id = c.id
        ), '[]'::jsonb)
      ) as contacts,
      CASE WHEN tg.id IS NOT NULL THEN jsonb_build_object('id', tg.id, 'name', tg.name, 'color', tg.color) ELSE NULL END as tags,
      CASE WHEN u.id IS NOT NULL THEN jsonb_build_object('id', u.id, 'full_name', u.full_name, 'email', u.email) ELSE NULL END as users,
      CASE WHEN ab.id IS NOT NULL THEN jsonb_build_object('id', ab.id, 'full_name', ab.full_name, 'email', ab.email) ELSE NULL END as assigned_by
    FROM paginated p
    LEFT JOIN contacts c ON c.id = p.contact_id
    LEFT JOIN tags tg ON tg.id = p.category_tag_id
    LEFT JOIN users u ON u.id = p.assigned_to_user_id
    LEFT JOIN users ab ON ab.id = p.assigned_by_user_id
  )
  SELECT 
    (SELECT cnt FROM counted),
    COALESCE(jsonb_agg(to_jsonb(wr.*) ORDER BY wr.priority ASC, wr.opened_at ASC, wr.id ASC), '[]'::jsonb)
  INTO v_total_count, v_tickets
  FROM with_relations wr;

  -- If direction is prev, reverse the results
  IF p_direction = 'prev' THEN
    SELECT jsonb_agg(elem ORDER BY (elem->>'priority')::int ASC, (elem->>'opened_at') ASC, elem->>'id' ASC)
    INTO v_tickets
    FROM jsonb_array_elements(v_tickets) elem;
  END IF;

  -- Build result with pagination info
  v_result := jsonb_build_object(
    'tickets', CASE 
      WHEN jsonb_array_length(v_tickets) > p_limit 
      THEN v_tickets - (jsonb_array_length(v_tickets) - 1)
      ELSE v_tickets 
    END,
    'total_count', v_total_count,
    'limit', p_limit,
    'has_next', jsonb_array_length(v_tickets) > p_limit,
    'has_prev', p_cursor IS NOT NULL,
    'next_cursor', CASE 
      WHEN jsonb_array_length(v_tickets) > p_limit THEN
        jsonb_build_object(
          'priority', (v_tickets->(p_limit - 1)->>'priority')::int,
          'opened_at', v_tickets->(p_limit - 1)->>'opened_at',
          'id', v_tickets->(p_limit - 1)->>'id'
        )
      ELSE NULL 
    END,
    'prev_cursor', CASE 
      WHEN jsonb_array_length(v_tickets) > 0 THEN
        jsonb_build_object(
          'priority', (v_tickets->0->>'priority')::int,
          'opened_at', v_tickets->0->>'opened_at',
          'id', v_tickets->0->>'id'
        )
      ELSE NULL 
    END
  );

  RETURN v_result;
END;
$$;


--
-- Name: send_chat_message(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_chat_message(p_thread_id uuid, p_message_text text, p_attachments jsonb DEFAULT '[]'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_brand_id uuid;
  v_message_id uuid;
BEGIN
  v_user_id := get_user_id(auth.uid());
  
  -- Get thread and check membership
  SELECT brand_id INTO v_brand_id
  FROM chat_threads
  WHERE id = p_thread_id;
  
  IF v_brand_id IS NULL THEN
    RAISE EXCEPTION 'Thread not found';
  END IF;
  
  IF NOT is_thread_member(v_user_id, p_thread_id) THEN
    RAISE EXCEPTION 'Not a member of this thread';
  END IF;
  
  -- Insert message
  INSERT INTO chat_messages (thread_id, brand_id, sender_user_id, sender_type, message_text, attachments)
  VALUES (p_thread_id, v_brand_id, v_user_id, 'user', p_message_text, p_attachments)
  RETURNING id INTO v_message_id;
  
  -- Update thread timestamp
  UPDATE chat_threads SET updated_at = now() WHERE id = p_thread_id;
  
  -- Auto-mark as read by sender
  INSERT INTO chat_message_reads (message_id, user_id)
  VALUES (v_message_id, v_user_id);
  
  RETURN v_message_id;
END;
$$;


--
-- Name: set_appointment_status(uuid, public.appointment_status); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_appointment_status(p_appointment_id uuid, p_status public.appointment_status) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_user_role app_role;
  v_brand_id uuid;
  v_old_value jsonb;
BEGIN
  SELECT u.id INTO v_user_id
  FROM public.users u
  WHERE u.supabase_auth_id = auth.uid();

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  SELECT brand_id INTO v_brand_id
  FROM public.appointments
  WHERE id = p_appointment_id;

  IF v_brand_id IS NULL THEN
    RAISE EXCEPTION 'Not found';
  END IF;

  SELECT ur.role INTO v_user_role
  FROM public.user_roles ur
  WHERE ur.user_id = v_user_id AND ur.brand_id = v_brand_id
  LIMIT 1;

  -- Sales can only set visited/no_show, admin/ceo/callcenter can set any
  IF v_user_role = 'sales' THEN
    IF p_status NOT IN ('visited', 'no_show') THEN
      RAISE EXCEPTION 'Forbidden: sales can only set visited or no_show status';
    END IF;
  ELSIF v_user_role NOT IN ('admin', 'ceo', 'callcenter') THEN
    RAISE EXCEPTION 'Forbidden';
  END IF;

  -- Capture old state
  SELECT row_to_json(a.*)::jsonb INTO v_old_value
  FROM public.appointments a WHERE a.id = p_appointment_id;

  UPDATE public.appointments
  SET status = p_status
  WHERE id = p_appointment_id;

  -- AUDIT
  INSERT INTO public.audit_log (
    brand_id, entity_type, entity_id, action, actor_user_id, old_value, new_value,
    metadata
  )
  SELECT 
    v_brand_id, 
    'appointment', 
    p_appointment_id, 
    'status_change',
    v_user_id,
    v_old_value,
    row_to_json(a.*)::jsonb,
    jsonb_build_object('new_status', p_status::text)
  FROM public.appointments a WHERE a.id = p_appointment_id;
END;
$$;


--
-- Name: set_audit_context(uuid, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_audit_context(p_actor_user_id uuid DEFAULT NULL::uuid, p_actor_type text DEFAULT 'user'::text, p_actor_display_name text DEFAULT NULL::text, p_source text DEFAULT 'ui'::text, p_correlation_id text DEFAULT NULL::text, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM set_config('app.audit_actor_user_id', COALESCE(p_actor_user_id::text, ''), true);
  PERFORM set_config('app.audit_actor_type', COALESCE(p_actor_type, 'user'), true);
  PERFORM set_config('app.audit_actor_display_name', COALESCE(p_actor_display_name, ''), true);
  PERFORM set_config('app.audit_source', COALESCE(p_source, 'ui'), true);
  PERFORM set_config('app.audit_correlation_id', COALESCE(p_correlation_id, ''), true);
  PERFORM set_config('app.audit_reason', COALESCE(p_reason, ''), true);
END;
$$;


--
-- Name: set_deal_closed_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_deal_closed_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  -- If status changed to won, lost, or closed and closed_at is NULL
  IF NEW.status IN ('won', 'lost', 'closed') 
     AND (OLD.status IS DISTINCT FROM NEW.status)
     AND NEW.closed_at IS NULL THEN
    NEW.closed_at = now();
  END IF;
  
  -- If status changed back to open, clear closed_at
  IF NEW.status = 'open' AND OLD.status IN ('won', 'lost', 'closed') THEN
    NEW.closed_at = NULL;
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: set_lead_event_archived(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_lead_event_archived(p_event_id uuid, p_archived boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_user_role app_role;
  v_brand_id uuid;
BEGIN
  -- Get current user
  SELECT u.id INTO v_user_id
  FROM public.users u
  WHERE u.supabase_auth_id = auth.uid();

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Unauthorized: no application user found';
  END IF;

  -- Get event brand_id
  SELECT brand_id INTO v_brand_id
  FROM public.lead_events
  WHERE id = p_event_id;

  IF v_brand_id IS NULL THEN
    RAISE EXCEPTION 'Not found: event does not exist';
  END IF;

  -- Get user role for this brand
  SELECT ur.role INTO v_user_role
  FROM public.user_roles ur
  WHERE ur.user_id = v_user_id AND ur.brand_id = v_brand_id
  LIMIT 1;

  -- Only admin, ceo, callcenter can archive
  IF v_user_role IS NULL OR v_user_role NOT IN ('admin', 'ceo', 'callcenter') THEN
    RAISE EXCEPTION 'Forbidden: archiving requires admin, ceo, or callcenter role';
  END IF;

  -- Perform the update
  UPDATE public.lead_events
  SET archived = p_archived
  WHERE id = p_event_id;

END;
$$;


--
-- Name: set_lead_event_clinical_topics(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_lead_event_clinical_topics(p_event_id uuid, p_topic_ids uuid[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_brand_id uuid;
  v_old_topic_ids uuid[];
BEGIN
  v_user_id := get_user_id(auth.uid());
  
  -- Lock the lead event row and get brand_id
  SELECT brand_id INTO v_brand_id
  FROM lead_events
  WHERE id = p_event_id
  FOR UPDATE;
  
  IF v_brand_id IS NULL THEN
    RAISE EXCEPTION 'Lead event not found';
  END IF;
  
  -- Check permissions
  IF v_user_id IS NOT NULL AND NOT (
    has_role_for_brand(v_user_id, v_brand_id, 'admin') OR
    has_role_for_brand(v_user_id, v_brand_id, 'callcenter') OR
    has_role(v_user_id, 'ceo')
  ) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;
  
  -- Get old topic IDs for audit
  SELECT array_agg(topic_id) INTO v_old_topic_ids
  FROM lead_event_clinical_topics
  WHERE lead_event_id = p_event_id;
  
  -- Replace all: delete existing, insert new
  DELETE FROM lead_event_clinical_topics WHERE lead_event_id = p_event_id;
  
  IF p_topic_ids IS NOT NULL AND array_length(p_topic_ids, 1) > 0 THEN
    INSERT INTO lead_event_clinical_topics (lead_event_id, topic_id)
    SELECT p_event_id, unnest(p_topic_ids)
    ON CONFLICT DO NOTHING;
  END IF;
  
  -- Audit log
  INSERT INTO audit_log (brand_id, entity_type, entity_id, action, actor_user_id, old_value, new_value)
  VALUES (
    v_brand_id,
    'lead_event',
    p_event_id,
    'topics_updated',
    v_user_id,
    to_jsonb(v_old_topic_ids),
    to_jsonb(p_topic_ids)
  );
END;
$$;


--
-- Name: set_order_number(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_order_number() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
