  NEW.updated_at = now();
  RETURN NEW;
END;
$$;


--
-- Name: severity_meets_threshold(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.severity_meets_threshold(_severity text, _threshold text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE _severity
    WHEN 'critical' THEN 4 WHEN 'high' THEN 3 WHEN 'medium' THEN 2 WHEN 'low' THEN 1 ELSE 0
  END >= CASE _threshold
    WHEN 'critical' THEN 4 WHEN 'high' THEN 3 WHEN 'medium' THEN 2 WHEN 'low' THEN 1 ELSE 0
  END;
$$;


--
-- Name: simulate_ticket_escalation_policy(uuid, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.simulate_ticket_escalation_policy(p_brand_id uuid, p_level_1_minutes integer, p_level_2_minutes integer, p_level_3_minutes integer, p_from_days integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_internal_user_id uuid;
  v_authorized boolean := false;
  v_from_ts timestamptz;
  v_result jsonb;
  v_simulated jsonb;
  v_actual jsonb;
  v_total_tickets integer;
  v_avg_resolution_minutes numeric;
BEGIN
  -- Validate inputs
  IF p_level_1_minutes <= 0 OR p_level_2_minutes <= 0 OR p_level_3_minutes <= 0 THEN
    RAISE EXCEPTION 'Level minutes must be positive' USING ERRCODE = '22023';
  END IF;
  IF p_level_1_minutes >= p_level_2_minutes OR p_level_2_minutes >= p_level_3_minutes THEN
    RAISE EXCEPTION 'Levels must be strictly increasing (L1 < L2 < L3)' USING ERRCODE = '22023';
  END IF;
  IF p_from_days < 1 OR p_from_days > 180 THEN
    RAISE EXCEPTION 'from_days must be between 1 and 180' USING ERRCODE = '22023';
  END IF;

  -- Auth: get internal user id
  v_internal_user_id := public.get_user_id(auth.uid());
  IF v_internal_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  -- Authorization: admin/ceo on the specific brand OR system admin
  SELECT EXISTS (
    SELECT 1
    FROM public.user_roles ur
    WHERE ur.user_id = v_internal_user_id
      AND ur.is_active = true
      AND ur.role IN ('admin', 'ceo')
      AND (
        ur.brand_id = p_brand_id
        OR ur.brand_id = '00000000-0000-0000-0000-000000000000'::uuid
      )
  ) INTO v_authorized;

  IF NOT v_authorized THEN
    RAISE EXCEPTION 'Insufficient privileges' USING ERRCODE = '42501';
  END IF;

  v_from_ts := now() - (p_from_days || ' days')::interval;

  -- Build per-ticket simulated level on tickets with SLA breach in window
  WITH base AS (
    SELECT
      t.id,
      t.escalation_level AS actual_level,
      t.sla_breached_at,
      COALESCE(t.resolved_at, t.closed_at, now()) AS effective_end,
      EXTRACT(EPOCH FROM (COALESCE(t.resolved_at, t.closed_at, now()) - t.sla_breached_at)) / 60.0 AS minutes_after_breach
    FROM public.tickets t
    WHERE t.brand_id = p_brand_id
      AND t.sla_breached_at IS NOT NULL
      AND t.sla_breached_at >= v_from_ts
      AND t.archived = false
  ),
  scored AS (
    SELECT
      id,
      actual_level,
      CASE
        WHEN minutes_after_breach >= p_level_3_minutes THEN 3
        WHEN minutes_after_breach >= p_level_2_minutes THEN 2
        WHEN minutes_after_breach >= p_level_1_minutes THEN 1
        ELSE 0
      END AS simulated_level,
      minutes_after_breach
    FROM base
  )
  SELECT
    jsonb_build_object(
      'level_0', COUNT(*) FILTER (WHERE simulated_level = 0),
      'level_1', COUNT(*) FILTER (WHERE simulated_level = 1),
      'level_2', COUNT(*) FILTER (WHERE simulated_level = 2),
      'level_3', COUNT(*) FILTER (WHERE simulated_level = 3)
    ),
    jsonb_build_object(
      'level_0', COUNT(*) FILTER (WHERE actual_level = 0),
      'level_1', COUNT(*) FILTER (WHERE actual_level = 1),
      'level_2', COUNT(*) FILTER (WHERE actual_level = 2),
      'level_3', COUNT(*) FILTER (WHERE actual_level >= 3)
    ),
    COUNT(*),
    ROUND(AVG(minutes_after_breach)::numeric, 1)
  INTO v_simulated, v_actual, v_total_tickets, v_avg_resolution_minutes
  FROM scored;

  v_result := jsonb_build_object(
    'simulated', COALESCE(v_simulated, '{}'::jsonb),
    'actual', COALESCE(v_actual, '{}'::jsonb),
    'total_tickets', COALESCE(v_total_tickets, 0),
    'avg_minutes_after_breach', COALESCE(v_avg_resolution_minutes, 0),
    'thresholds', jsonb_build_object(
      'level_1_minutes', p_level_1_minutes,
      'level_2_minutes', p_level_2_minutes,
      'level_3_minutes', p_level_3_minutes
    ),
    'from_days', p_from_days,
    'brand_id', p_brand_id,
    'computed_at', now()
  );

  RETURN v_result;
END;
$$;


--
-- Name: sync_contact_status_on_deal_create(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_contact_status_on_deal_create() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_stage_name TEXT;
  v_new_status contact_status;
BEGIN
  IF NEW.current_stage_id IS NOT NULL AND NEW.contact_id IS NOT NULL THEN
    SELECT name INTO v_stage_name
    FROM pipeline_stages
    WHERE id = NEW.current_stage_id;
    
    IF v_stage_name IS NOT NULL THEN
      v_new_status := map_stage_to_contact_status(v_stage_name);
      
      UPDATE contacts
      SET status = v_new_status,
          updated_at = now()
      WHERE id = NEW.contact_id
        AND status IS DISTINCT FROM v_new_status;
    END IF;
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: sync_contact_status_on_deal_stage_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_contact_status_on_deal_stage_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_stage_name TEXT;
  v_new_status contact_status;
  v_deal_status TEXT;
BEGIN
  -- Only process if current_stage_id actually changed
  IF OLD.current_stage_id IS DISTINCT FROM NEW.current_stage_id THEN
    -- Get the new stage name
    SELECT name INTO v_stage_name
    FROM pipeline_stages
    WHERE id = NEW.current_stage_id;
    
    IF v_stage_name IS NOT NULL THEN
      -- Also consider deal status (won/lost/closed override stage-based logic)
      v_deal_status := NEW.status;
      
      IF v_deal_status = 'won' THEN
        -- Won deals -> contact becomes qualified (successful conversion)
        v_new_status := 'qualified'::contact_status;
      ELSIF v_deal_status IN ('lost', 'closed') THEN
        -- Lost/closed deals -> contact becomes unqualified or archived
        v_new_status := 'unqualified'::contact_status;
      ELSE
        -- Active deals -> use stage-based mapping
        v_new_status := map_stage_to_contact_status(v_stage_name);
      END IF;
      
      -- Update the contact status
      UPDATE contacts
      SET status = v_new_status,
          updated_at = now()
      WHERE id = NEW.contact_id
        AND status IS DISTINCT FROM v_new_status;
    END IF;
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: sync_deal_value_from_orders(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_deal_value_from_orders() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_deal_id uuid;
  v_new_value numeric;
BEGIN
  -- Get the deal_id from the affected row
  IF TG_OP = 'DELETE' THEN
    v_deal_id := OLD.deal_id;
  ELSE
    v_deal_id := NEW.deal_id;
  END IF;
  
  -- If no deal_id, nothing to sync
  IF v_deal_id IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;
  
  -- Calculate total value from all non-cancelled orders for this deal
  SELECT COALESCE(SUM(total_amount), 0)
  INTO v_new_value
  FROM public.sales_orders
  WHERE deal_id = v_deal_id
    AND status != 'cancelled';
  
  -- Update the deal value
  UPDATE public.deals
  SET value = NULLIF(v_new_value, 0),
      updated_at = now()
  WHERE id = v_deal_id;
  
  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: test_webhook(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.test_webhook(p_webhook_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_brand_id uuid;
  v_is_active boolean;
  v_event_id uuid := gen_random_uuid();
  v_delivery_id uuid;
  v_payload jsonb;
BEGIN
  -- Get brand_id, is_active and check webhook exists
  SELECT brand_id, is_active INTO v_brand_id, v_is_active 
  FROM outbound_webhooks WHERE id = p_webhook_id;
  
  IF v_brand_id IS NULL THEN
    RAISE EXCEPTION 'Webhook not found';
  END IF;
  
  -- Admin check
  IF NOT has_role_for_brand(get_user_id(auth.uid()), v_brand_id, 'admin') THEN
    RAISE EXCEPTION 'Admin access required';
  END IF;
  
  -- Build test payload (include expected error if webhook is inactive)
  v_payload := jsonb_build_object(
    'schema_version', 1,
    'event_type', 'webhook.test',
    'event_id', v_event_id,
    'occurred_at', now(),
    'brand_id', v_brand_id,
    'webhook_id', p_webhook_id,
    'data', jsonb_build_object(
      'ping', 'pong', 
      'timestamp', extract(epoch from now()),
      'webhook_active', v_is_active
    )
  );
  
  -- Insert delivery directly (bypass trigger since this is manual)
  INSERT INTO outbound_webhook_deliveries (
    webhook_id, brand_id, event_type, event_id, payload, status, next_attempt_at
  ) VALUES (
    p_webhook_id, v_brand_id, 'webhook.test', v_event_id, v_payload, 'pending', now()
  )
  RETURNING id INTO v_delivery_id;
  
  RETURN v_delivery_id;
END;
$$;


