--
-- Name: update_appointment(uuid, timestamp with time zone, integer, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_appointment(p_appointment_id uuid, p_scheduled_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_duration_minutes integer DEFAULT NULL::integer, p_address text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_cap text DEFAULT NULL::text, p_notes text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_user_role app_role;
  v_brand_id uuid;
  v_old_value jsonb;
BEGIN
  SELECT u.id INTO v_user_id
  FROM public.users u
  WHERE u.supabase_auth_id = auth.uid();

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  SELECT brand_id INTO v_brand_id
  FROM public.appointments
  WHERE id = p_appointment_id;

  IF v_brand_id IS NULL THEN
    RAISE EXCEPTION 'Not found';
  END IF;

  SELECT ur.role INTO v_user_role
  FROM public.user_roles ur
  WHERE ur.user_id = v_user_id AND ur.brand_id = v_brand_id
  LIMIT 1;

  IF v_user_role NOT IN ('admin', 'ceo', 'callcenter') THEN
    RAISE EXCEPTION 'Forbidden';
  END IF;

  -- Capture old state
  SELECT row_to_json(a.*)::jsonb INTO v_old_value
  FROM public.appointments a WHERE a.id = p_appointment_id;

  UPDATE public.appointments SET
    scheduled_at = COALESCE(p_scheduled_at, scheduled_at),
    duration_minutes = COALESCE(p_duration_minutes, duration_minutes),
    address = COALESCE(p_address, address),
    city = COALESCE(p_city, city),
    cap = COALESCE(p_cap, cap),
    notes = COALESCE(p_notes, notes)
  WHERE id = p_appointment_id;

  -- AUDIT
  INSERT INTO public.audit_log (
    brand_id, entity_type, entity_id, action, actor_user_id, old_value, new_value
  )
  SELECT 
    v_brand_id, 
    'appointment', 
    p_appointment_id, 
    'update',
    v_user_id,
    v_old_value,
    row_to_json(a.*)::jsonb
  FROM public.appointments a WHERE a.id = p_appointment_id;
END;
$$;


--
-- Name: update_capi_event_status(uuid, public.meta_capi_status, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_capi_event_status(p_event_id uuid, p_status public.meta_capi_status, p_error text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE public.meta_capi_event_queue
  SET 
    status = p_status,
    attempts = attempts + 1,
    last_error = p_error,
    sent_at = CASE WHEN p_status = 'sent' THEN NOW() ELSE sent_at END,
    processing_at = NULL,
    processing_by = NULL
  WHERE id = p_event_id;
END;
$$;


--
-- Name: update_contact_last_interaction(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_contact_last_interaction() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_contact_id uuid;
  v_interaction_at timestamptz;
BEGIN
  -- Determine contact_id and interaction timestamp based on table
  IF TG_TABLE_NAME = 'lead_events' THEN
    v_contact_id := COALESCE(NEW.contact_id, OLD.contact_id);
    v_interaction_at := NEW.received_at;
  ELSIF TG_TABLE_NAME = 'call_logs' THEN
    v_contact_id := COALESCE(NEW.contact_id, OLD.contact_id);
    v_interaction_at := NEW.started_at;
  ELSIF TG_TABLE_NAME = 'appointments' THEN
    v_contact_id := COALESCE(NEW.contact_id, OLD.contact_id);
    v_interaction_at := NEW.scheduled_at;
  END IF;

  IF v_contact_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Only update if this interaction is more recent
  UPDATE public.contacts
  SET last_interaction_at = v_interaction_at
  WHERE id = v_contact_id
    AND (last_interaction_at IS NULL OR last_interaction_at < v_interaction_at);

  RETURN NEW;
END;
$$;


--
-- Name: update_contact_search_index(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_contact_search_index(p_contact_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_brand_id UUID; v_search_text TEXT;
BEGIN
  SELECT brand_id INTO v_brand_id FROM contacts WHERE id = p_contact_id;
  IF v_brand_id IS NULL THEN RETURN; END IF;
  v_search_text := public.build_contact_search_text(p_contact_id);
  INSERT INTO contact_search_index (contact_id, brand_id, search_text, search_vector, updated_at)
  VALUES (p_contact_id, v_brand_id, v_search_text, to_tsvector('simple', v_search_text), now())
  ON CONFLICT (contact_id) DO UPDATE SET brand_id = EXCLUDED.brand_id, search_text = EXCLUDED.search_text, search_vector = EXCLUDED.search_vector, updated_at = now();
END;
$$;


