--
-- Name: update_lead_event_qualification(uuid, public.lead_source_channel, public.contact_channel, public.pacemaker_status, public.customer_sentiment, public.decision_status, public.objection_type, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_lead_event_qualification(p_event_id uuid, p_lead_source_channel public.lead_source_channel DEFAULT NULL::public.lead_source_channel, p_contact_channel public.contact_channel DEFAULT NULL::public.contact_channel, p_pacemaker_status public.pacemaker_status DEFAULT NULL::public.pacemaker_status, p_customer_sentiment public.customer_sentiment DEFAULT NULL::public.customer_sentiment, p_decision_status public.decision_status DEFAULT NULL::public.decision_status, p_objection_type public.objection_type DEFAULT NULL::public.objection_type, p_booking_notes text DEFAULT NULL::text, p_logistics_notes text DEFAULT NULL::text, p_ai_conversation_summary text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_brand_id uuid;
  v_old_values jsonb;
BEGIN
  -- Resolve app user
  v_user_id := get_user_id(auth.uid());
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  -- Get event's brand_id and verify it exists
  SELECT brand_id INTO v_brand_id
  FROM public.lead_events
  WHERE id = p_event_id;

  IF v_brand_id IS NULL THEN
    RAISE EXCEPTION 'Lead event not found';
  END IF;

  -- Brand access check
  IF NOT user_belongs_to_brand(v_user_id, v_brand_id) THEN
    RAISE EXCEPTION 'Forbidden: no access to brand';
  END IF;

  -- Capture old values for audit
  SELECT jsonb_build_object(
    'lead_source_channel', lead_source_channel,
    'contact_channel', contact_channel,
    'pacemaker_status', pacemaker_status,
    'customer_sentiment', customer_sentiment,
    'decision_status', decision_status,
    'objection_type', objection_type,
    'booking_notes', booking_notes,
    'logistics_notes', logistics_notes,
    'ai_conversation_summary', ai_conversation_summary
  ) INTO v_old_values
  FROM public.lead_events
  WHERE id = p_event_id;

  -- Update the lead_event with new qualification values
  -- Using COALESCE to only update non-null parameters (preserves existing values)
  UPDATE public.lead_events SET
    lead_source_channel = COALESCE(p_lead_source_channel, lead_source_channel),
    contact_channel = COALESCE(p_contact_channel, contact_channel),
    pacemaker_status = COALESCE(p_pacemaker_status, pacemaker_status),
    customer_sentiment = COALESCE(p_customer_sentiment, customer_sentiment),
    decision_status = COALESCE(p_decision_status, decision_status),
    objection_type = COALESCE(p_objection_type, objection_type),
    booking_notes = COALESCE(p_booking_notes, booking_notes),
    logistics_notes = COALESCE(p_logistics_notes, logistics_notes),
    ai_conversation_summary = COALESCE(p_ai_conversation_summary, ai_conversation_summary)
  WHERE id = p_event_id;

  -- Audit log
  INSERT INTO public.audit_log (
    brand_id,
    entity_type,
    entity_id,
    action,
    actor_user_id,
    old_value,
    new_value
  ) VALUES (
    v_brand_id,
    'lead_event',
    p_event_id,
    'update_qualification',
    v_user_id,
    v_old_values,
    jsonb_build_object(
      'lead_source_channel', p_lead_source_channel,
      'contact_channel', p_contact_channel,
      'pacemaker_status', p_pacemaker_status,
      'customer_sentiment', p_customer_sentiment,
      'decision_status', p_decision_status,
      'objection_type', p_objection_type,
      'booking_notes', p_booking_notes,
      'logistics_notes', p_logistics_notes,
      'ai_conversation_summary', p_ai_conversation_summary
    )
  );
END;
$$;


--
-- Name: update_meta_lead_event_status(uuid, public.meta_lead_status, jsonb, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_meta_lead_event_status(p_event_id uuid, p_status public.meta_lead_status, p_fetched_payload jsonb DEFAULT NULL::jsonb, p_lead_event_id uuid DEFAULT NULL::uuid, p_contact_id uuid DEFAULT NULL::uuid, p_error text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE meta_lead_events
  SET 
    status = p_status,
    fetched_payload = COALESCE(p_fetched_payload, fetched_payload),
    lead_event_id = COALESCE(p_lead_event_id, lead_event_id),
    contact_id = COALESCE(p_contact_id, contact_id),
    error = p_error,
    processed_at = CASE WHEN p_status IN ('ingested', 'error') THEN now() ELSE processed_at END
  WHERE id = p_event_id;
END;
$$;


--
-- Name: update_order_payment_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_order_payment_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_total_paid NUMERIC(12,2);
  v_order_total NUMERIC(12,2);
  v_order_id UUID;
  v_new_status sales_order_status;
  v_current_status sales_order_status;
BEGIN
  v_order_id := COALESCE(NEW.order_id, OLD.order_id);
  
  SELECT COALESCE(SUM(amount), 0)
  INTO v_total_paid
  FROM payments
  WHERE order_id = v_order_id AND status = 'completed';
  
  SELECT total_amount, status INTO v_order_total, v_current_status
  FROM sales_orders WHERE id = v_order_id;
  
  -- Determina nuovo status solo se ordine è confirmed o successivo
  IF v_current_status NOT IN ('draft', 'cancelled', 'refunded') THEN
    IF v_total_paid >= v_order_total THEN
      v_new_status := 'paid';
    ELSIF v_total_paid > 0 THEN
      v_new_status := 'partially_paid';
    ELSE
      v_new_status := v_current_status;
    END IF;
    
    UPDATE sales_orders
    SET 
      paid_amount = v_total_paid,
      status = v_new_status,
      paid_at = CASE WHEN v_new_status = 'paid' THEN now() ELSE paid_at END,
      updated_at = now()
    WHERE id = v_order_id;
  ELSE
    UPDATE sales_orders
    SET paid_amount = v_total_paid, updated_at = now()
    WHERE id = v_order_id;
  END IF;
  
  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: update_outbound_webhook(uuid, text, text, text[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_outbound_webhook(p_id uuid, p_name text DEFAULT NULL::text, p_url text DEFAULT NULL::text, p_event_types text[] DEFAULT NULL::text[], p_is_active boolean DEFAULT NULL::boolean) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_brand_id uuid;
  v_valid_events text[] := ARRAY[
    'ticket.created', 'ticket.updated', 'ticket.assigned', 
    'ticket.status_changed', 'ticket.priority_changed', 
    'ticket.sla_breached', 'ticket.resolved', 'ticket.closed',
    'contact.created', 'contact.updated',
    'deal.created', 'deal.stage_changed', 'deal.closed',
    'webhook.test'
  ];
BEGIN
  -- Get brand_id and check exists
  SELECT brand_id INTO v_brand_id FROM outbound_webhooks WHERE id = p_id;
  
  IF v_brand_id IS NULL THEN
    RAISE EXCEPTION 'Webhook not found';
  END IF;
  
  -- Admin check
  IF NOT has_role_for_brand(get_user_id(auth.uid()), v_brand_id, 'admin') THEN
    RAISE EXCEPTION 'Admin access required';
  END IF;
  
  -- Validate URL if provided: HTTPS required, no exceptions
  IF p_url IS NOT NULL AND NOT (p_url LIKE 'https://%') THEN
    RAISE EXCEPTION 'URL must use HTTPS';
  END IF;
  
  -- Validate event types if provided
  IF p_event_types IS NOT NULL AND NOT (p_event_types <@ v_valid_events) THEN
    RAISE EXCEPTION 'Invalid event type(s) specified';
  END IF;
  
  -- Update
  UPDATE outbound_webhooks SET
    name = COALESCE(p_name, name),
    url = COALESCE(p_url, url),
    event_types = COALESCE(p_event_types::webhook_event_type[], event_types),
    is_active = COALESCE(p_is_active, is_active),
    updated_at = now()
  WHERE id = p_id;
  
  RETURN true;
END;
$$;


--
-- Name: update_outbound_webhook(uuid, text, text, text[], boolean, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_outbound_webhook(p_id uuid, p_name text DEFAULT NULL::text, p_url text DEFAULT NULL::text, p_event_types text[] DEFAULT NULL::text[], p_is_active boolean DEFAULT NULL::boolean, p_payload_format text DEFAULT NULL::text, p_payload_mapping jsonb DEFAULT NULL::jsonb, p_custom_url_params jsonb DEFAULT NULL::jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_brand_id uuid;
  v_user_id uuid;
BEGIN
  -- Get the internal user_id from the supabase_auth_id
  SELECT u.id INTO v_user_id 
  FROM users u 
  WHERE u.supabase_auth_id = auth.uid();

  -- Get brand_id for this webhook
  SELECT brand_id INTO v_brand_id FROM outbound_webhooks WHERE id = p_id;
  
  IF v_brand_id IS NULL THEN
    RAISE EXCEPTION 'Webhook not found';
  END IF;

  -- Verify user has admin or ceo role for this brand
  IF NOT EXISTS (
    SELECT 1 FROM user_roles
    WHERE user_id = v_user_id
    AND brand_id = v_brand_id
    AND role IN ('admin', 'ceo')
  ) THEN
    RAISE EXCEPTION 'Access denied: admin or ceo role required';
  END IF;

  -- Update the webhook
  UPDATE outbound_webhooks
  SET
    name = COALESCE(p_name, name),
    url = COALESCE(p_url, url),
    event_types = COALESCE(p_event_types, event_types),
    is_active = COALESCE(p_is_active, is_active),
    payload_format = COALESCE(p_payload_format, payload_format),
    payload_mapping = CASE WHEN p_payload_mapping IS NOT NULL THEN p_payload_mapping ELSE payload_mapping END,
    custom_url_params = CASE WHEN p_custom_url_params IS NOT NULL THEN p_custom_url_params ELSE custom_url_params END,
    updated_at = now()
  WHERE id = p_id;

  RETURN true;
END;
$$;


--
-- Name: update_outbound_webhook(uuid, text, text, public.webhook_event_type[], boolean, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_outbound_webhook(p_id uuid, p_name text DEFAULT NULL::text, p_url text DEFAULT NULL::text, p_event_types public.webhook_event_type[] DEFAULT NULL::public.webhook_event_type[], p_is_active boolean DEFAULT NULL::boolean, p_payload_format text DEFAULT NULL::text, p_payload_mapping jsonb DEFAULT NULL::jsonb, p_custom_url_params jsonb DEFAULT NULL::jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_brand_id UUID;
BEGIN
  -- Get webhook's brand_id
  SELECT brand_id INTO v_brand_id FROM outbound_webhooks WHERE id = p_id;
  
  IF v_brand_id IS NULL THEN
    RAISE EXCEPTION 'Webhook not found';
  END IF;

  -- Verify user has admin role for this brand
  IF NOT EXISTS (
    SELECT 1 FROM user_brand_roles
    WHERE user_id = auth.uid()
    AND brand_id = v_brand_id
    AND role = 'admin'
  ) THEN
    RAISE EXCEPTION 'Access denied: admin role required';
  END IF;

  -- Validate payload_format if provided
  IF p_payload_format IS NOT NULL AND p_payload_format NOT IN ('json', 'form_urlencoded') THEN
    RAISE EXCEPTION 'Invalid payload_format. Must be json or form_urlencoded';
  END IF;

  -- Update webhook
  UPDATE outbound_webhooks
  SET
    name = COALESCE(p_name, name),
    url = COALESCE(p_url, url),
    event_types = COALESCE(p_event_types, event_types),
    is_active = COALESCE(p_is_active, is_active),
    payload_format = COALESCE(p_payload_format, payload_format),
    payload_mapping = CASE WHEN p_payload_mapping IS NULL THEN payload_mapping ELSE p_payload_mapping END,
    custom_url_params = CASE WHEN p_custom_url_params IS NULL THEN custom_url_params ELSE p_custom_url_params END,
    updated_at = now()
  WHERE id = p_id;

  RETURN TRUE;
END;
$$;


--
-- Name: update_pipeline_stage(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_pipeline_stage(p_stage_id uuid, p_name text DEFAULT NULL::text, p_color text DEFAULT NULL::text, p_description text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
BEGIN
  v_user_id := get_user_id(auth.uid());
  
  -- Check if user is admin or CEO
  IF NOT (has_role(v_user_id, 'admin'::app_role) OR has_role(v_user_id, 'ceo'::app_role)) THEN
    RAISE EXCEPTION 'Solo admin e CEO possono modificare fasi pipeline';
  END IF;
  
  UPDATE pipeline_stages
  SET 
    name = COALESCE(p_name, name),
    color = COALESCE(p_color, color),
    description = COALESCE(p_description, description),
    updated_at = NOW()
  WHERE id = p_stage_id;
END;
$$;


--
-- Name: update_team_member(uuid, public.app_role, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_team_member(p_membership_id uuid, p_new_role public.app_role DEFAULT NULL::public.app_role, p_is_active boolean DEFAULT NULL::boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_brand_id uuid;
  v_current_role app_role;
  v_caller_role app_role;
BEGIN
  -- Get current membership info
  SELECT brand_id, role INTO v_brand_id, v_current_role
  FROM user_roles WHERE id = p_membership_id;

  IF v_brand_id IS NULL THEN
    RAISE EXCEPTION 'Membership not found';
  END IF;

  -- Get caller's role
  SELECT ur.role INTO v_caller_role
  FROM user_roles ur
  WHERE ur.user_id = get_user_id(auth.uid())
    AND ur.brand_id = v_brand_id
    AND ur.is_active = true
  ORDER BY get_role_level(ur.role) DESC
  LIMIT 1;

  -- Check caller can manage current role
  IF NOT can_manage_role(v_caller_role, v_current_role) THEN
    RAISE EXCEPTION 'Non autorizzato a gestire questo membro';
  END IF;

  -- If changing role, check can manage new role too
  IF p_new_role IS NOT NULL AND NOT can_manage_role(v_caller_role, p_new_role) THEN
    RAISE EXCEPTION 'Non autorizzato ad assegnare questo ruolo';
  END IF;

  -- Prevent self-demotion for protection
  IF (SELECT user_id FROM user_roles WHERE id = p_membership_id) = get_user_id(auth.uid()) 
     AND p_new_role IS NOT NULL 
     AND get_role_level(p_new_role) < get_role_level(v_current_role) THEN
    RAISE EXCEPTION 'Non puoi demotare te stesso';
  END IF;

  -- Update
  UPDATE user_roles SET
    role = COALESCE(p_new_role, role),
    is_active = COALESCE(p_is_active, is_active)
  WHERE id = p_membership_id;
END;
$$;


