--
-- Name: audit_retention_policies; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.audit_retention_policies (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    brand_id uuid NOT NULL,
    retention_months integer DEFAULT 24 NOT NULL,
    archive_enabled boolean DEFAULT true NOT NULL,
    last_purge_at timestamp with time zone,
    last_archived_count integer DEFAULT 0,
    last_purged_count integer DEFAULT 0,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT audit_retention_policies_retention_months_check CHECK (((retention_months >= 1) AND (retention_months <= 120)))
);


--
-- Name: upsert_audit_retention_policy(uuid, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_audit_retention_policy(p_brand_id uuid, p_retention_months integer, p_archive_enabled boolean) RETURNS public.audit_retention_policies
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row public.audit_retention_policies;
BEGIN
  IF NOT public.is_audit_admin(auth.uid()) THEN
    RAISE EXCEPTION 'access denied';
  END IF;

  INSERT INTO public.audit_retention_policies (brand_id, retention_months, archive_enabled)
  VALUES (p_brand_id, p_retention_months, p_archive_enabled)
  ON CONFLICT (brand_id) DO UPDATE
    SET retention_months = EXCLUDED.retention_months,
        archive_enabled = EXCLUDED.archive_enabled,
        updated_at = now()
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$$;


--
-- Name: upsert_backup_schedule(uuid, text, text, integer, integer, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_backup_schedule(p_brand_id uuid, p_scope text, p_frequency text, p_hour_utc integer, p_day_of_week integer, p_retention_days integer, p_enabled boolean) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_id UUID;
BEGIN
  v_user_id := public.get_user_id(auth.uid());
  IF NOT (
    public.has_role(v_user_id, 'admin'::app_role)
    OR public.has_role(v_user_id, 'ceo'::app_role)
  ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.backup_schedules (
    brand_id, scope, frequency, hour_utc, day_of_week,
    retention_days, enabled, created_by_user_id
  ) VALUES (
    p_brand_id, p_scope, p_frequency, p_hour_utc, p_day_of_week,
    p_retention_days, p_enabled, v_user_id
  )
  ON CONFLICT (brand_id) DO UPDATE SET
    scope = EXCLUDED.scope,
    frequency = EXCLUDED.frequency,
    hour_utc = EXCLUDED.hour_utc,
    day_of_week = EXCLUDED.day_of_week,
    retention_days = EXCLUDED.retention_days,
    enabled = EXCLUDED.enabled,
    updated_at = now()
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: upsert_clinical_topics_from_strings(uuid, text[], public.topic_created_by); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_clinical_topics_from_strings(p_brand_id uuid, p_strings text[], p_created_by public.topic_created_by DEFAULT 'user'::public.topic_created_by) RETURNS uuid[]
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_result uuid[] := '{}';
  v_string text;
  v_normalized text;
  v_topic_id uuid;
  v_canonical text;
BEGIN
  -- Validate caller has access to brand
  v_user_id := get_user_id(auth.uid());
  IF v_user_id IS NULL AND current_setting('role', true) != 'service_role' THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  
  IF v_user_id IS NOT NULL AND NOT user_belongs_to_brand(v_user_id, p_brand_id) THEN
    RAISE EXCEPTION 'Access denied to brand';
  END IF;

  FOREACH v_string IN ARRAY p_strings LOOP
    v_normalized := normalize_topic_text(v_string);
    
    IF v_normalized = '' OR v_normalized IS NULL THEN
      CONTINUE;
    END IF;
    
    -- Check if alias already exists
    SELECT cta.topic_id INTO v_topic_id
    FROM clinical_topic_aliases cta
    WHERE cta.brand_id = p_brand_id AND cta.alias_text = v_normalized;
    
    IF v_topic_id IS NULL THEN
      -- Create new topic with Title Case canonical name
      v_canonical := initcap(v_string);
      
      INSERT INTO clinical_topics (brand_id, canonical_name, slug, created_by, needs_review)
      VALUES (p_brand_id, v_canonical, v_normalized, p_created_by, true)
      ON CONFLICT (brand_id, slug) DO UPDATE SET updated_at = now()
      RETURNING id INTO v_topic_id;
      
      -- Create alias for the new topic
      INSERT INTO clinical_topic_aliases (brand_id, topic_id, alias_text, created_by)
      VALUES (p_brand_id, v_topic_id, v_normalized, p_created_by)
      ON CONFLICT (brand_id, alias_text) DO NOTHING;
    END IF;
    
    v_result := array_append(v_result, v_topic_id);
  END LOOP;
  
  RETURN v_result;
END;
$$;


--
-- Name: upsert_contact_field_values(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_contact_field_values(p_contact_id uuid, p_brand_id uuid, p_values jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_item JSONB;
  v_field_def RECORD;
  v_count INTEGER := 0;
BEGIN
  FOR v_item IN SELECT * FROM jsonb_array_elements(p_values)
  LOOP
    SELECT * INTO v_field_def
    FROM contact_field_definitions
    WHERE id = (v_item->>'field_definition_id')::uuid
      AND is_active = true;
    
    IF v_field_def IS NULL THEN
      CONTINUE;
    END IF;
    
    INSERT INTO contact_field_values (
      contact_id, brand_id, field_definition_id,
      value_text, value_number, value_bool, value_date, value_json,
      updated_by_user_id
    )
    VALUES (
      p_contact_id,
      p_brand_id,
      v_field_def.id,
      CASE WHEN v_field_def.field_type IN ('text', 'email', 'phone', 'url', 'textarea', 'select') 
           THEN v_item->>'value' END,
      CASE WHEN v_field_def.field_type = 'number' 
           THEN (v_item->>'value')::numeric END,
      CASE WHEN v_field_def.field_type = 'bool' 
           THEN (v_item->>'value')::boolean END,
      CASE WHEN v_field_def.field_type = 'date' 
           THEN (v_item->>'value')::date END,
      CASE WHEN v_field_def.field_type = 'multiselect' 
           THEN v_item->'value' END,
      auth.uid()
    )
    ON CONFLICT (contact_id, field_definition_id) DO UPDATE SET
      value_text = EXCLUDED.value_text,
      value_number = EXCLUDED.value_number,
      value_bool = EXCLUDED.value_bool,
      value_date = EXCLUDED.value_date,
      value_json = EXCLUDED.value_json,
      updated_at = now(),
      updated_by_user_id = auth.uid();
    
    v_count := v_count + 1;
  END LOOP;
  
  RETURN jsonb_build_object('updated', v_count);
END;
$$;


--
-- Name: upsert_contact_field_values_by_key(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_contact_field_values_by_key(p_contact_id uuid, p_brand_id uuid, p_field_values jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_item JSONB;
  v_field_def RECORD;
  v_count INTEGER := 0;
BEGIN
  FOR v_item IN SELECT * FROM jsonb_array_elements(p_field_values)
  LOOP
    SELECT * INTO v_field_def
    FROM contact_field_definitions
    WHERE key = (v_item->>'field_key')
      AND is_active = true
      AND (brand_id IS NULL OR brand_id = p_brand_id)
    ORDER BY brand_id NULLS LAST
    LIMIT 1;
    
    IF v_field_def IS NULL THEN
      CONTINUE;
    END IF;
    
    INSERT INTO contact_field_values (
      contact_id, brand_id, field_definition_id,
      value_text, updated_by_user_id
    )
    VALUES (
      p_contact_id,
      p_brand_id,
      v_field_def.id,
      v_item->>'value',
      NULL
    )
    ON CONFLICT (contact_id, field_definition_id) DO UPDATE SET
      value_text = EXCLUDED.value_text,
      updated_at = now();
    
    v_count := v_count + 1;
  END LOOP;
  
  RETURN jsonb_build_object('updated', v_count);
END;
$$;


--
-- Name: upsert_notification_preference(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_notification_preference(p_brand_id uuid, p_notification_type text, p_enabled boolean) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_result json;
BEGIN
  SELECT u.id INTO v_user_id FROM public.users u WHERE u.supabase_auth_id = auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  IF NOT user_belongs_to_brand(v_user_id, p_brand_id) THEN
    RAISE EXCEPTION 'Forbidden: no access to brand';
  END IF;

  INSERT INTO notification_preferences (user_id, brand_id, notification_type, enabled)
  VALUES (v_user_id, p_brand_id, p_notification_type::notification_type, p_enabled)
  ON CONFLICT (user_id, brand_id, notification_type)
  DO UPDATE SET enabled = EXCLUDED.enabled
  RETURNING json_build_object(
    'id', id,
    'user_id', user_id,
    'brand_id', brand_id,
    'notification_type', notification_type,
    'enabled', enabled
  ) INTO v_result;

  RETURN v_result;
END;
$$;


--
-- Name: user_belongs_to_brand(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.user_belongs_to_brand(_user_id uuid, _brand_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.user_roles ur
    WHERE ur.user_id = _user_id
      AND ur.brand_id = _brand_id
  )
$$;


--
-- Name: user_can_access_brand(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.user_can_access_brand(p_user_id uuid, p_brand_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_internal_id uuid;
BEGIN
  -- Resolve auth UUID to internal user ID
  SELECT id INTO v_internal_id FROM public.users WHERE supabase_auth_id = p_user_id LIMIT 1;
  IF v_internal_id IS NULL THEN
    RETURN false;
  END IF;

  -- Direct access
  IF EXISTS (
    SELECT 1 FROM user_roles ur
    WHERE ur.user_id = v_internal_id AND ur.brand_id = p_brand_id
  ) THEN
    RETURN true;
  END IF;
  
  -- Check if user has parent brand with can_access_children
  RETURN EXISTS (
    SELECT 1 
    FROM user_roles ur
    JOIN brands b ON b.parent_brand_id = ur.brand_id
    WHERE ur.user_id = v_internal_id
      AND ur.can_access_children = true
      AND b.id = p_brand_id
  );
END;
$$;


--
-- Name: user_can_access_page(uuid, uuid, public.app_page); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.user_can_access_page(p_user_id uuid, p_brand_id uuid, p_page public.app_page) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_override boolean;
  v_role_permission boolean;
  v_user_role app_role;
BEGIN
  -- Check for user-specific override first
  SELECT can_access INTO v_user_override
  FROM user_page_permissions
  WHERE user_id = p_user_id
  AND brand_id = p_brand_id
  AND page = p_page;
  
  IF v_user_override IS NOT NULL THEN
    RETURN v_user_override;
  END IF;
  
  -- Get user's role for this brand
  SELECT role INTO v_user_role
  FROM user_roles
  WHERE user_id = p_user_id
  AND brand_id = p_brand_id
  LIMIT 1;
  
  -- Admin and CEO always have access to everything
  IF v_user_role IN ('admin'::app_role, 'ceo'::app_role) THEN
    RETURN true;
  END IF;
  
  -- Check role-based permission
  SELECT can_access INTO v_role_permission
  FROM role_page_permissions
  WHERE brand_id = p_brand_id
  AND role = v_user_role::text
  AND page = p_page;
  
  -- If no explicit permission set, default to true (allow)
  RETURN COALESCE(v_role_permission, true);
END;
$$;


--
-- Name: validate_mcp_token(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_mcp_token(p_raw_token text) RETURNS TABLE(token_id uuid, user_id uuid, kind text, brand_id uuid, scopes text[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_hash TEXT;
BEGIN
  IF p_raw_token IS NULL OR length(p_raw_token) < 16 THEN RETURN; END IF;
  v_hash := encode(digest(p_raw_token, 'sha256'), 'hex');

  RETURN QUERY
  UPDATE public.mcp_access_tokens t
  SET last_used_at = now()
  WHERE t.token_hash = v_hash
    AND t.revoked_at IS NULL
    AND (t.expires_at IS NULL OR t.expires_at > now())
  RETURNING t.id, t.user_id, t.kind, t.brand_id, t.scopes;
END;
$$;


--
-- Name: validate_payment_plan_details(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_payment_plan_details() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  -- installment requires: num_installments, installment_amount
  IF NEW.method = 'installment' THEN
    IF NEW.plan_details IS NULL 
       OR (NEW.plan_details->>'num_installments') IS NULL
       OR (NEW.plan_details->>'installment_amount') IS NULL THEN
      RAISE EXCEPTION 'Installment payments require plan_details with num_installments and installment_amount';
    END IF;
    IF (NEW.plan_details->>'num_installments')::int < 2 THEN
      RAISE EXCEPTION 'num_installments must be >= 2';
    END IF;
  END IF;

  -- rental requires: monthly_fee, duration_months, start_date
  IF NEW.method = 'rental' THEN
    IF NEW.plan_details IS NULL
       OR (NEW.plan_details->>'monthly_fee') IS NULL
       OR (NEW.plan_details->>'duration_months') IS NULL
       OR (NEW.plan_details->>'start_date') IS NULL THEN
      RAISE EXCEPTION 'Rental payments require plan_details with monthly_fee, duration_months, and start_date';
    END IF;
    IF (NEW.plan_details->>'duration_months')::int < 1 THEN
      RAISE EXCEPTION 'duration_months must be >= 1';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: webhook_metrics_24h(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.webhook_metrics_24h(p_brand_id uuid) RETURNS json
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH user_brands AS (
    SELECT CASE 
      WHEN p_brand_id = '00000000-0000-0000-0000-000000000000' THEN ur.brand_id
      ELSE p_brand_id
    END AS bid
    FROM user_roles ur
    WHERE ur.user_id = get_user_id(auth.uid())
      AND (p_brand_id != '00000000-0000-0000-0000-000000000000' OR ur.brand_id != '00000000-0000-0000-0000-000000000000')
    GROUP BY 1
  ),
  recent_deliveries AS (
    SELECT 
      status,
      duration_ms,
      attempt_count
    FROM outbound_webhook_deliveries
    WHERE brand_id IN (SELECT bid FROM user_brands)
      AND created_at >= now() - interval '24 hours'
  ),
  agg AS (
    SELECT
      COUNT(*) FILTER (WHERE TRUE) AS total_deliveries,
      COUNT(*) FILTER (WHERE status = 'success') AS success_count,
      COUNT(*) FILTER (WHERE status = 'failed') AS failed_count,
      COUNT(*) FILTER (WHERE status = 'pending') AS pending_count,
      COUNT(*) FILTER (WHERE status = 'sending') AS sending_count,
      ROUND(AVG(attempt_count)::numeric, 2) AS avg_attempts,
      ROUND(AVG(duration_ms) FILTER (WHERE status = 'success' AND duration_ms IS NOT NULL)::numeric, 0) AS avg_latency_ms
    FROM recent_deliveries
  ),
  percentiles AS (
    SELECT
      ROUND(percentile_cont(0.50) WITHIN GROUP (ORDER BY duration_ms)::numeric, 0) AS p50_latency_ms,
      ROUND(percentile_cont(0.95) WITHIN GROUP (ORDER BY duration_ms)::numeric, 0) AS p95_latency_ms,
      ROUND(percentile_cont(0.99) WITHIN GROUP (ORDER BY duration_ms)::numeric, 0) AS p99_latency_ms
    FROM recent_deliveries
    WHERE status = 'success' AND duration_ms IS NOT NULL
  )
  SELECT json_build_object(
    'total_deliveries', COALESCE(agg.total_deliveries, 0),
    'success_count', COALESCE(agg.success_count, 0),
    'failed_count', COALESCE(agg.failed_count, 0),
    'pending_count', COALESCE(agg.pending_count, 0),
    'sending_count', COALESCE(agg.sending_count, 0),
    'avg_attempts', COALESCE(agg.avg_attempts, 0),
    'avg_latency_ms', agg.avg_latency_ms,
    'p50_latency_ms', percentiles.p50_latency_ms,
    'p95_latency_ms', percentiles.p95_latency_ms,
    'p99_latency_ms', percentiles.p99_latency_ms,
    'computed_at', now()
  )
  FROM agg, percentiles;
$$;


--
-- Name: webhook_timeseries_24h(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.webhook_timeseries_24h(p_brand_id uuid, p_bucket_minutes integer DEFAULT 15) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result json;
  v_cutoff timestamptz := now() - interval '24 hours';
  v_bucket_interval interval;
BEGIN
  -- Admin check
  IF NOT has_role_for_brand(get_user_id(auth.uid()), p_brand_id, 'admin') THEN
    RAISE EXCEPTION 'Admin access required';
  END IF;

  -- Clamp bucket to reasonable values
  p_bucket_minutes := GREATEST(5, LEAST(60, p_bucket_minutes));
  v_bucket_interval := (p_bucket_minutes || ' minutes')::interval;

  SELECT COALESCE(json_agg(json_build_object(
    'bucket', bucket,
    'success_count', success_count,
    'failed_count', failed_count,
    'pending_count', pending_count,
    'total_count', total_count
  ) ORDER BY bucket), '[]'::json)
  INTO v_result
  FROM (
    SELECT 
      date_trunc('hour', created_at) + 
        (floor(extract(minute from created_at) / p_bucket_minutes) * v_bucket_interval) AS bucket,
      COUNT(*) FILTER (WHERE status = 'success') AS success_count,
      COUNT(*) FILTER (WHERE status = 'failed') AS failed_count,
      COUNT(*) FILTER (WHERE status = 'pending') AS pending_count,
      COUNT(*) AS total_count
    FROM outbound_webhook_deliveries
    WHERE brand_id = p_brand_id
      AND created_at >= v_cutoff
    GROUP BY bucket
  ) t;

  RETURN v_result;
END;
$$;


--
-- Name: webhook_top_errors_24h(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.webhook_top_errors_24h(p_brand_id uuid, p_limit integer DEFAULT 10) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result json;
  v_cutoff timestamptz := now() - interval '24 hours';
BEGIN
  -- Admin check
  IF NOT has_role_for_brand(get_user_id(auth.uid()), p_brand_id, 'admin') THEN
    RAISE EXCEPTION 'Admin access required';
  END IF;

  SELECT COALESCE(json_agg(json_build_object(
    'error', COALESCE(
      CASE 
        WHEN last_error ILIKE '%timeout%' THEN 'Timeout'
        WHEN last_error ILIKE '%connection%refused%' THEN 'Connection Refused'
        WHEN last_error ILIKE '%dns%' OR last_error ILIKE '%resolve%' THEN 'DNS Error'
        WHEN last_error ILIKE '%ssl%' OR last_error ILIKE '%certificate%' THEN 'SSL/TLS Error'
        WHEN last_error ILIKE '%rate%limit%' THEN 'Rate Limited'
        WHEN last_error ILIKE '%unauthorized%' OR last_error ILIKE '%401%' THEN 'Unauthorized'
        WHEN last_error ILIKE '%forbidden%' OR last_error ILIKE '%403%' THEN 'Forbidden'
        WHEN last_error ILIKE '%not%found%' OR last_error ILIKE '%404%' THEN 'Not Found'
        WHEN last_error ILIKE '%500%' OR last_error ILIKE '%internal%server%' THEN 'Server Error (5xx)'
        ELSE LEFT(last_error, 80)
      END,
      'Unknown Error'
    ),
    'raw_error', LEFT(last_error, 200),
    'count', cnt,
    'last_occurrence', last_at
  ) ORDER BY cnt DESC), '[]'::json)
  INTO v_result
  FROM (
    SELECT 
      last_error,
      COUNT(*) AS cnt,
      MAX(created_at) AS last_at
    FROM outbound_webhook_deliveries
    WHERE brand_id = p_brand_id
      AND status = 'failed'
      AND created_at >= v_cutoff
      AND last_error IS NOT NULL
    GROUP BY last_error
    ORDER BY cnt DESC
    LIMIT p_limit
  ) t;

  RETURN v_result;
END;
$$;


--
-- Name: webhook_top_event_types_24h(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.webhook_top_event_types_24h(p_brand_id uuid, p_limit integer DEFAULT 10) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result json;
  v_cutoff timestamptz := now() - interval '24 hours';
BEGIN
  -- Admin check
  IF NOT has_role_for_brand(get_user_id(auth.uid()), p_brand_id, 'admin') THEN
    RAISE EXCEPTION 'Admin access required';
  END IF;

  SELECT COALESCE(json_agg(json_build_object(
    'event_type', event_type,
    'total_count', total_count,
    'success_count', success_count,
    'failed_count', failed_count,
    'success_rate', CASE WHEN total_count > 0 
      THEN ROUND((success_count::numeric / total_count) * 100, 1) 
      ELSE 0 
    END
  ) ORDER BY total_count DESC), '[]'::json)
  INTO v_result
  FROM (
    SELECT 
      event_type::text,
      COUNT(*) AS total_count,
      COUNT(*) FILTER (WHERE status = 'success') AS success_count,
      COUNT(*) FILTER (WHERE status = 'failed') AS failed_count
    FROM outbound_webhook_deliveries
    WHERE brand_id = p_brand_id
      AND created_at >= v_cutoff
    GROUP BY event_type
    ORDER BY total_count DESC
    LIMIT p_limit
  ) t;

  RETURN v_result;
END;
$$;


--
-- Name: webhook_top_webhooks_24h(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.webhook_top_webhooks_24h(p_brand_id uuid, p_limit integer DEFAULT 10) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result json;
  v_cutoff timestamptz := now() - interval '24 hours';
BEGIN
  -- Admin check
  IF NOT has_role_for_brand(get_user_id(auth.uid()), p_brand_id, 'admin') THEN
    RAISE EXCEPTION 'Admin access required';
  END IF;

  SELECT COALESCE(json_agg(json_build_object(
    'webhook_id', webhook_id,
    'webhook_name', webhook_name,
    'webhook_url', webhook_url,
    'total_count', total_count,
    'success_count', success_count,
    'failed_count', failed_count,
    'pending_count', pending_count,
    'fail_rate', CASE WHEN total_count > 0 
      THEN ROUND((failed_count::numeric / total_count) * 100, 1) 
      ELSE 0 
    END,
    'avg_attempts', avg_attempts
  ) ORDER BY fail_rate DESC, total_count DESC), '[]'::json)
  INTO v_result
  FROM (
    SELECT 
      d.webhook_id,
      w.name AS webhook_name,
      w.url AS webhook_url,
      COUNT(*) AS total_count,
      COUNT(*) FILTER (WHERE d.status = 'success') AS success_count,
      COUNT(*) FILTER (WHERE d.status = 'failed') AS failed_count,
      COUNT(*) FILTER (WHERE d.status = 'pending') AS pending_count,
      ROUND(AVG(d.attempt_count)::numeric, 2) AS avg_attempts
    FROM outbound_webhook_deliveries d
    JOIN outbound_webhooks w ON w.id = d.webhook_id
    WHERE d.brand_id = p_brand_id
      AND d.created_at >= v_cutoff
    GROUP BY d.webhook_id, w.name, w.url
    ORDER BY total_count DESC
    LIMIT p_limit
  ) t;

  RETURN v_result;
END;
$$;


--
-- Name: write_audit_event(uuid, text, uuid, text, jsonb, jsonb, text[], jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.write_audit_event(p_brand_id uuid, p_entity_type text, p_entity_id uuid, p_action text, p_old_value jsonb DEFAULT NULL::jsonb, p_new_value jsonb DEFAULT NULL::jsonb, p_changed_fields text[] DEFAULT NULL::text[], p_metadata jsonb DEFAULT '{}'::jsonb, p_idempotency_key text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor_user_id uuid;
  v_actor_type text;
  v_actor_display_name text;
  v_source text;
  v_correlation_id text;
  v_reason text;
  v_event_id uuid;
  v_final_metadata jsonb;
BEGIN
  BEGIN
    v_actor_user_id := NULLIF(current_setting('app.audit_actor_user_id', true), '')::uuid;
  EXCEPTION WHEN OTHERS THEN
    v_actor_user_id := NULL;
  END;

  v_actor_type := COALESCE(NULLIF(current_setting('app.audit_actor_type', true), ''), 'system');
  v_actor_display_name := NULLIF(current_setting('app.audit_actor_display_name', true), '');
  v_source := COALESCE(NULLIF(current_setting('app.audit_source', true), ''), 'trigger');
  v_correlation_id := NULLIF(current_setting('app.audit_correlation_id', true), '');
  v_reason := NULLIF(current_setting('app.audit_reason', true), '');

  IF v_actor_user_id IS NULL THEN
    BEGIN
      SELECT id, COALESCE(first_name || ' ' || last_name, email)
        INTO v_actor_user_id, v_actor_display_name
        FROM public.users
       WHERE supabase_auth_id = auth.uid()
       LIMIT 1;
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END IF;

  IF v_actor_display_name IS NULL AND v_actor_user_id IS NOT NULL THEN
    SELECT COALESCE(first_name || ' ' || last_name, email)
      INTO v_actor_display_name
      FROM public.users
     WHERE id = v_actor_user_id
     LIMIT 1;
  END IF;

  v_final_metadata := COALESCE(p_metadata, '{}'::jsonb);
  IF v_reason IS NOT NULL THEN
    v_final_metadata := v_final_metadata || jsonb_build_object('reason', v_reason);
  END IF;

  INSERT INTO public.audit_events (
    brand_id, entity_type, entity_id, action,
    actor_user_id, actor_type, actor_display_name, source,
    old_value, new_value, changed_fields,
    metadata, correlation_id, idempotency_key
  ) VALUES (
    p_brand_id, p_entity_type, p_entity_id, p_action,
    v_actor_user_id, v_actor_type, v_actor_display_name, v_source,
    p_old_value, p_new_value, p_changed_fields,
    v_final_metadata, v_correlation_id, p_idempotency_key
  )
  ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL
  DO NOTHING
  RETURNING id INTO v_event_id;

  RETURN v_event_id;
END;
$$;


