    assigned_at timestamp with time zone DEFAULT now() NOT NULL,
    assigned_by_user_id uuid,
    confidence numeric(3,2),
    CONSTRAINT exactly_one_entity CHECK ((((
CASE
    WHEN (contact_id IS NOT NULL) THEN 1
    ELSE 0
END +
CASE
    WHEN (lead_event_id IS NOT NULL) THEN 1
    ELSE 0
END) +
CASE
    WHEN (deal_id IS NOT NULL) THEN 1
    ELSE 0
END) = 1))
);


