--
-- Name: v_ai_override_rate_30d; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_ai_override_rate_30d WITH (security_invoker='true') AS
 SELECT brand_id,
    (date_trunc('day'::text, created_at))::date AS day,
    count(*) AS total_decisions,
    count(*) FILTER (WHERE was_overridden) AS overridden_decisions,
    round(((100.0 * (count(*) FILTER (WHERE was_overridden))::numeric) / (NULLIF(count(*), 0))::numeric), 2) AS override_rate_pct,
    round(avg(confidence), 3) AS avg_confidence,
    round(avg(confidence) FILTER (WHERE was_overridden), 3) AS avg_confidence_when_overridden
   FROM public.ai_decision_logs
  WHERE (created_at >= (now() - '30 days'::interval))
  GROUP BY brand_id, (date_trunc('day'::text, created_at))
  ORDER BY ((date_trunc('day'::text, created_at))::date) DESC;


--
-- Name: v_ai_proposal_outcomes_30d; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_ai_proposal_outcomes_30d WITH (security_invoker='true') AS
 SELECT brand_id,
    (date_trunc('day'::text, decided_at))::date AS day,
    decision,
    count(*) AS cnt
   FROM public.ai_call_action_decisions d
  WHERE (decided_at >= (now() - '30 days'::interval))
  GROUP BY brand_id, (date_trunc('day'::text, decided_at)), decision
  ORDER BY ((date_trunc('day'::text, decided_at))::date) DESC;


