--

CREATE POLICY "Admin/CEO can manage role_hidden_columns" ON public.role_hidden_columns USING ((EXISTS ( SELECT 1
   FROM (public.user_roles ur
     JOIN public.users u ON ((u.id = ur.user_id)))
  WHERE ((u.supabase_auth_id = auth.uid()) AND (ur.brand_id = role_hidden_columns.brand_id) AND (ur.role = ANY (ARRAY['admin'::public.app_role, 'ceo'::public.app_role]))))));


